  1→/* ==========================================================================
  2→   WARP ENGINE — GAME.CSS
  3→   Theme: Dark Sci-Fi / Bronze & Copper
  4→   Dependencies: base/style.css, puzzles.css
  5→   ========================================================================== */
  6→
  7→/* --- 1. FONTS & TYPOGRAPHY --- */
  8→
  9→@font-face {
 10→  font-family: 'Inconsolata';
 11→  src: url('assets/fonts/Inconsolata.woff2') format('woff2');
 12→  font-weight: 400; font-style: normal; font-display: swap;
 13→}
 14→
 15→@font-face {
 16→  font-family: 'Handelsonsix';
 17→  src: url('assets/fonts/handelsonsix.woff2') format('woff2');
 18→  font-weight: 400; font-style: normal; font-display: swap;
 19→}
 20→
 21→:root {
 22→  /* Palette */
 23→  --we-bg:            #0e0f12;
 24→  --we-surface:       #14161c;
 25→  --we-panel:         rgba(26, 29, 37, 0.95);
 26→  --we-text:          #ece9e0;
 27→  --we-muted:         #bdb8ac;
 28→  --we-accent:        #b8956a; /* Bronze */
 29→  --we-accent-glow:   rgba(184, 149, 106, 0.4);
 30→  --we-success:       #58c59a;
 31→  --we-danger:        #ff6b6b;
 32→  --we-focus:         #8dc8ff; /* Sci-fi Blue for interactions */
 33→  --we-shadow:        rgba(0, 0, 0, 0.6);
 34→
 35→  /* Overrides for puzzles.css variables to match theme */
 36→  --pz-text-color:    var(--we-text);
 37→
 38→  /* FIX TOKENY: Návrat k tvému odstínu (Dark Slate), mírně vyšší opacita pro čitelnost */
 39→  --pz-token-bg:      rgba(39, 51, 54, 0.85);
 40→  --pz-token-border:  rgba(184, 149, 106, 0.3);
 41→
 42→  --pz-selected-bg:   rgba(141, 200, 255, 0.1);
 43→  --pz-selected-border: var(--we-focus);
 44→
 45→  /* Červená pro chybu */
 46→  --pz-wrong-bg:      rgba(220, 40, 40, 0.4);
 47→  --pz-wrong-border:  rgba(220, 40, 40, 0.8);
 48→}
 49→
 50→/* GLOBAL LAYOUT & VIEWPORT FIXES */
 51→html {
 52→  overflow-y: auto; /* Povolit scroll pro odstrčení lišt na tabletu */
 53→  height: 100%;
 54→  overscroll-behavior-y: none;
 55→}
 56→
 57→body {
 58→  font-family: 'Inconsolata', monospace, system-ui;
 59→  background-color: var(--we-bg);
 60→  color: var(--we-text);
 61→
 62→  margin: 0;
 63→  min-height: 100%; /* Umožní obsahu roztáhnout se */
 64→  overflow-y: auto; /* CRITICAL pro tablety */
 65→  -webkit-tap-highlight-color: transparent;
 66→}
 67→
 68→#gameRoot {
 69→  width: 100%;
 70→  max-width: 1200px;
 71→  margin: 0 auto;
 72→  min-height: 100vh;
 73→  display: flex;
 74→  flex-direction: column;
 75→}
 76→
 77→/* Headers */
 78→.topbar .title,
 79→.scene-title,
 80→.pz-title,
 81→.puzzle .title {
 82→  font-family: 'Handelsonsix', sans-serif;
 83→  letter-spacing: 0.8px;
 84→  text-transform: uppercase;
 85→  text-shadow: 0 2px 4px var(--we-shadow);
 86→}
 87→
 88→.topbar .title { font-size: 1.5em; color: var(--we-accent); }
 89→.pz-title { font-size: 1.4em; margin-bottom: 0.5em; }
 90→
 91→/* --- 2. UI COMPONENTS --- */
 92→
 93→/* Buttons (Global Sci-Fi Style) */
 94→.btn, button, .ui-button, .pz-btn {
 95→  background: linear-gradient(180deg, #2b2f38, #232731);
 96→  color: var(--we-text);
 97→  border: 1px solid rgba(184, 149, 106, 0.3);
 98→  border-radius: 8px;
 99→  padding: 8px 16px;
100→  font-family: 'Inconsolata', monospace;
101→  cursor: pointer;
102→  transition: all 0.2s ease;
103→  box-shadow: 0 4px 6px rgba(0,0,0,0.3);
104→}
105→
106→.btn:hover, button:hover, .pz-btn:hover {
107→  border-color: var(--we-accent);
108→  box-shadow: 0 0 10px var(--we-accent-glow);
109→  transform: translateY(-1px);
110→}
111→
112→.btn:active { transform: translateY(1px); }
113→
114→/* Inventory */
115→.inventory {
116→  background: linear-gradient(180deg, rgba(20,22,28,0.95), rgba(15,16,20,0.98));
117→  border-top: 1px solid var(--we-accent);
118→  backdrop-filter: blur(4px);
119→  position: relative;
120→  z-index: 50;
121→}
122→
123→.item {
124→  background: rgba(255, 255, 255, 0.05);
125→  border: 1px solid rgba(255, 255, 255, 0.1);
126→  border-radius: 6px;
127→  transition: all 0.2s ease;
128→
129→  /* FIX PRO TABLETY: Okamžitá reakce na dotyk (žádné čekání na double-tap/scroll) */
130→  touch-action: manipulation;
131→  user-select: none;
132→  -webkit-user-select: none;
133→  cursor: pointer;
134→  position: relative;
135→  z-index: 10;
136→}
137→
138→.item:active {
139→  transform: scale(0.96);
140→  background: rgba(255, 255, 255, 0.15);
141→}
142→
143→.inventory .item:hover, .inventory .item.selected {
144→  border-color: var(--we-focus);
145→  background: rgba(141, 200, 255, 0.1);
146→  box-shadow: 0 0 8px rgba(141, 200, 255, 0.3);
147→}
148→
149→/* Dialogs */
150→.dialog-window, .dlg-panel {
151→  background: var(--we-panel);
152→  border: 1px solid var(--we-accent);
153→  box-shadow: 0 -10px 40px black;
154→  border-radius: 12px;
155→}
156→
157→.dlg-nameplate {
158→  background: var(--we-bg);
159→  border: 1px solid var(--we-accent);
160→  color: var(--we-accent);
161→  font-family: 'Handelsonsix', sans-serif;
162→  text-transform: uppercase;
163→}
164→
165→/* DIALOG CHARACTER VISUALS */
166→.dlg-char {
167→  display: flex;
168→  align-items: flex-end;
169→  justify-content: center;
170→  height: 100%;
171→  bottom: 0;
172→  width: min(42vw, 380px);
173→
174→  /* FIX PERFORMANCE: Animujeme pouze transformaci, ne filtr (stín), to sekalo iPad */
175→  transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
176→
177→  /* FIX SAFARI VRSTVY: Vynucení 3D kontextu, aby ::after (záře) nezmizela pod pozadím */
178→  transform-style: preserve-3d;
179→  z-index: 1;
180→}
181→
182→.dlg-compact .dlg-char {
183→  width: min(36vw, 300px);
184→}
185→
186→@media (max-width: 720px) {
187→  .dlg-char {
188→    width: min(46vw, 300px);
189→  }
190→}
191→
192→.dlg-char-img {
193→  width: 100%;
194→  height: auto;
195→  max-height: calc(100% - 20px);
196→
197→  object-fit: contain;
198→  /* Statický stín je OK, ale nebudeme ho animovat */
199→  filter: drop-shadow(0 5px 15px rgba(0,0,0,0.5));
200→
201→  /* FIX SAFARI DUCHOVÉ: */
202→  will-change: transform;
203→
204→  color: transparent;
205→  text-indent: -10000px;
206→
207→  /* Musí být v popředí před září */
208→  position: relative;
209→  z-index: 5;
210→}
211→
212→.dlg-choice {
213→  border-radius: 20px;
214→  background: rgba(255,255,255,0.05);
215→}
216→
217→/* FIX: Blur efekt pro dialog overlay (specificky pro tuto hru) */
218→.dlg-overlay::before {
219→  content: '';
220→  position: absolute;
221→  inset: 0;
222→  background: rgba(0, 0, 0, 0.55);
223→  backdrop-filter: blur(2px); /* Zde je požadovaný blur */
224→  pointer-events: auto; /* Blokuje hotspoty pod dialogem */
225→  z-index: 1099;
226→}
227→
228→/* --- SPEAKER HIGHLIGHT (Cross-Platform Glow) --- */
229→
230→/* 1. STANDARD (PC, Android, Chrome) - Tvůj původní design */
231→
232→/* Aktivní mluvčí - Zvýraznění */
233→.dlg-char.speaking {
234→    /* translateZ(0) zapíná GPU akceleraci, ale nemění hloubku */
235→    transform: translateY(-6px) scale(1.05) translateZ(0);
236→    z-index: 10;
237→
238→    -webkit-filter: drop-shadow(0 0 25px rgba(184, 149, 106, 0.6)) brightness(1.1);
239→    filter: drop-shadow(0 0 25px rgba(184, 149, 106, 0.6)) brightness(1.1);
240→}
241→
242→/* Atmosférická záře za postavou */
243→.dlg-char.speaking::after {
244→    content: '';
245→    position: absolute;
246→    bottom: 0;
247→    left: 50%;
248→
249→    /* Centrování */
250→    transform: translateX(-50%);
251→
252→    width: 120%;
253→    height: 70%;
254→
255→    background: radial-gradient(ellipse at center, rgba(184, 149, 106, 0.2) 0%, transparent 70%);
256→    z-index: -1;
257→
258→    /* Animace */
259→    animation: speaker-pulse 2.5s infinite ease-in-out;
260→    pointer-events: none;
261→
262→    will-change: opacity, transform;
263→    -webkit-mask-image: -webkit-radial-gradient(white, black);
264→}
265→
266→@keyframes speaker-pulse {
267→    0%, 100% { opacity: 0.3; transform: translateX(-50%) scale(0.95); }
268→    50% { opacity: 0.6; transform: translateX(-50%) scale(1.05); }
269→}
270→
271→
272→/* 2. SAFARI / iOS PATCH (Fix mizejícího efektu) */
273→/* Detekce WebKit jádra */
274→@supports (-webkit-touch-callout: none) {
275→
276→    /* Kontejner musí mít explicitní 3D kontext */
277→    .dlg-char {
278→        transform-style: preserve-3d;
279→        /* Klíčový hack pro Safari: donutí ho překreslit filtry */
280→        -webkit-perspective: 1000px;
281→        perspective: 1000px;
282→    }
283→
284→    .dlg-char.speaking {
285→        /* Na Safari použijeme translate3d pro vynucení GPU */
286→        transform: translate3d(0, -6px, 10px) scale(1.05);
287→
288→        /* Vypneme filtr na rodiči, pokud způsobuje problémy s ::after */
289→        /* Místo toho ho můžeme aplikovat přímo na img níže, pokud je třeba */
290→        filter: none;
291→        -webkit-filter: none;
292→    }
293→
294→    /* Fix pro obrázek uvnitř (aby nebyl máznutý) */
295→    .dlg-char.speaking .dlg-char-img {
296→        /* Zde aplikujeme jas jen na obrázek */
297→        filter: brightness(1.1);
298→        -webkit-filter: brightness(1.1);
299→    }
300→
301→    /* Fix pro záři (::after) */
302→    .dlg-char.speaking::after {
303→        /* Vypnout animaci, která způsobuje blikání na iPadu */
304→        animation: none;
305→
306→        /* Nastavit statickou, bezpečnou viditelnost */
307→        opacity: 0.6;
308→
309→        /* FYZICKÝ POSUN DOZADU - jediné spolehlivé řešení pro z-index v Safari */
310→        /* translateZ(-1px) strčí vrstvu "za" rodiče v 3D prostoru */
311→        transform: translateX(-50%) translateZ(-1px) scale(1.0);
312→
313→        /* Hack proti mizení: */
314→        -webkit-backface-visibility: hidden;
315→        backface-visibility: hidden;
316→
317→        /* Zjednodušený gradient pro Safari, který se lépe renderuje */
318→        background: radial-gradient(closest-side, rgba(184, 149, 106, 0.5), transparent);
319→    }
320→}
321→
322→/* --- 3. PUZZLE SYSTEM (Overrides) --- */
323→
324→.pz__window {
325→  /* Sci-fi panel look for puzzles */
326→  background: rgba(14, 15, 18, 0.85);
327→  border: 1px solid var(--we-accent);
328→  border-radius: 12px;
329→  box-shadow: 0 0 30px rgba(0,0,0,0.8);
330→  backdrop-filter: blur(5px);
331→}
332→
333→/* --- 4. PUZZLE KIND: MATCH --- */
334→
335→.pz-kind-match {
336→  --pz-token-gap: 12px;
337→}
338→
339→/* Layout: Image + Text side-by-side */
340→.pz-match-column .pz-token {
341→  display: flex;
342→  flex-direction: row;
343→  align-items: center;
344→  gap: 12px;
345→  text-align: left;
346→  justify-content: flex-start;
347→  min-height: 70px;
348→  padding: 8px 12px;
349→
350→  /* Použijeme var(--pz-token-bg), která je teď nastavena dle tvého přání */
351→  background: var(--pz-token-bg);
352→
353→  border: 1px solid rgba(255, 255, 255, 0.15);
354→  transition: transform 0.1s, box-shadow 0.2s;
355→}
356→
357→/* Red flash pro chybu */
358→.pz-match-column .pz-token.is-wrong,
359→.pz-match-column .pz-token.wrong {
360→  background: var(--pz-wrong-bg) !important;
361→  border-color: var(--pz-wrong-border) !important;
362→}
363→
364→/* Selection State: Glow border only */
365→.pz-match-column .pz-token.is-selected,
366→.pz-match-column .pz-token.selected {
367→  background: rgba(141, 200, 255, 0.05) !important;
368→  border-color: var(--we-focus) !important;
369→  box-shadow: 0 0 0 1px var(--we-focus), 0 0 15px rgba(141, 200, 255, 0.3) !important;
370→  z-index: 5;
371→  transform: scale(1.02);
372→}
373→
374→/* Token Images */
375→.pz-token-image {
376→  flex: 0 0 auto;
377→  width: auto;
378→  height: 64px;
379→  max-width: 140px;
380→  object-fit: contain;
381→  background: rgba(0,0,0,0.3);
382→  border-radius: 4px;
383→  border: 1px solid rgba(255,255,255,0.05);
384→}
385→
386→@media (max-width: 600px) {
387→  .pz-match-column .pz-token {
388→    flex-direction: column;
389→    text-align: center;
390→    padding: 10px;
391→  }
392→  .pz-token-image {
393→    max-width: 100%;
394→    height: auto;
395→    max-height: 100px;
396→    margin-bottom: 8px;
397→  }
398→}
399→
400→/* --- 5. PUZZLE KIND: CLOZE --- */
401→
402→/* Dragging Mechanics */
403→.pz-cloze-tokens-area .pz-token,
404→.pz-cloze-gap .pz-token {
405→  touch-action: none;       /* CRITICAL for tablets */
406→  user-select: none;
407→  cursor: grab;
408→  background: var(--pz-token-bg);
409→  border: 1px solid var(--pz-token-border);
410→  padding: 6px 12px;
411→  border-radius: 6px;
412→  color: var(--we-text);
413→  font-weight: 500;
414→}
415→
416→/* The "Ghost" element */
417→.pz-cloze-ghost {
418→  pointer-events: none !important;
419→  z-index: 9999;
420→  box-shadow: 0 15px 30px rgba(0,0,0,0.6);
421→  opacity: 0.95;
422→  transform: scale(1.1);
423→  border-color: var(--we-accent);
424→}
425→
426→/* Drop Zones (Gaps) */
427→.pz-cloze-gap {
428→  background: rgba(0,0,0,0.3);
429→
430→  /* FIX: Sjednocení rámečku - 1px dashed po celém obvodu v barvě tématu */
431→  border: 1px dashed rgba(184, 149, 106, 0.5);
432→
433→  border-radius: 4px;
434→  min-width: 80px;
435→  display: inline-block;
436→  vertical-align: middle;
437→  margin: 0 4px;
438→  transition: all 0.2s;
439→}
440→
441→.pz-cloze-gap.drag-over {
442→  background: rgba(141, 200, 255, 0.2);
443→  border-color: var(--we-focus);
444→  box-shadow: 0 0 10px rgba(141, 200, 255, 0.3);
445→}
446→
447→.pz-cloze-gap.filled {
448→  border: none;
449→  background: transparent;
450→}
451→
452→/* --- 6. PUZZLE KIND: GROUP & ORDER --- */
453→
454→/* Buckets/Slots */
455→.pz-group-bucket,
456→.pz-order-slot {
457→  background: rgba(20, 22, 25, 0.8);
458→  border: 1px dashed rgba(184, 149, 106, 0.4);
459→  border-radius: 10px;
460→}
461→
462→.pz-group-label {
463→  color: var(--we-accent);
464→  font-family: 'Handelsonsix', sans-serif;
465→  letter-spacing: 1px;
466→}
467→
468→/* --- FIX: Vynucení barvy tokenů pro Group a Order puzzle --- */
469→
470→/* 1. ZÁKLADNÍ STAV (Dark Slate) */
471→.pz-kind-group .pz-token,
472→.pz-kind-order .pz-token {
473→  background: rgba(39, 51, 54, 0.9) !important;
474→  border: 1px solid rgba(184, 149, 106, 0.3) !important;
475→  color: #ece9e0 !important;
476→  backdrop-filter: blur(4px);
477→  font-weight: 500;
478→  transition: background 0.2s, transform 0.1s;
479→}
480→
481→/* 2. HOVER EFEKT */
482→.pz-kind-group .pz-token:hover,
483→.pz-kind-order .pz-token:hover {
484→  background: rgba(39, 51, 54, 1) !important;
485→  border-color: var(--we-focus) !important;
486→  box-shadow: 0 0 8px rgba(141, 200, 255, 0.3) !important;
487→  transform: translateY(-1px);
488→}
489→
490→/* 3. CHYBOVÝ STAV (Červená) - TOTO ZAJISTÍ ZČERVENÁNÍ */
491→/* Musí být definováno AŽ PO základním stavu a musí mít !important */
492→.pz-kind-group .pz-token.wrong,
493→.pz-kind-group .pz-token.is-wrong,
494→.pz-kind-order .pz-token.wrong,
495→.pz-kind-order .pz-token.is-wrong {
496→  background: var(--pz-wrong-bg) !important;       /* Červené pozadí */
497→  border-color: var(--pz-wrong-border) !important; /* Červený rámeček */
498→  box-shadow: 0 0 15px rgba(255, 60, 60, 0.4) !important;
499→  animation: shake 0.4s ease-in-out; /* Ujistíme se, že animace třesení funguje */
500→}
501→
502→@keyframes shake {
503→  0%, 100% { transform: translateX(0); }
504→  25% { transform: translateX(-5px); }
505→  75% { transform: translateX(5px); }
506→}
507→
508→/* --- 7. SCENE SPECIFIC: WARP CORE --- */
509→
510→/* Overrides handled in style.css via states */
511→
512→/* --- 8. ANIMATIONS & FX --- */
513→
514→@keyframes titleScan {
515→  0%   { transform: translateX(-120%); }
516→  100% { transform: translateX(120%); }
517→}
518→
519→.title-scan::after {
520→  content: "";
521→  position: absolute; inset: 0;
522→  background: linear-gradient(120deg, transparent 0%, rgba(184, 149, 106, 0.1) 50%, transparent 100%);
523→  animation: titleScan 3s ease-in-out infinite;
524→  pointer-events: none;
525→}
526→
527→.toast {
528→  background: var(--we-panel);
529→  border: 1px solid var(--we-accent);
530→  color: var(--we-text);
531→  box-shadow: 0 10px 30px rgba(0,0,0,0.8);
532→  font-family: 'Inconsolata', monospace;
533→}
534→
535→/* --- EPIC HIGHLIGHT GLOW (Pro hotspoty) --- */
536→
537→/* Přepisujeme defaultní styl ze style.css pro tuto hru */
538→.hs-glow {
539→  /* Pozicování a vrstvy - musí být nahoře! */
540→  position: absolute !important;
541→  z-index: 9000 !important;
542→  pointer-events: none;
543→
544→  /* Vizuál */
545→  background: radial-gradient(ellipse at center, rgba(88, 197, 154, 0.0) 0%, rgba(88, 197, 154, 0.3) 60%, transparent 80%);
546→  border: 3px solid rgba(88, 197, 154, 0.9);
547→  box-shadow: 0 0 40px rgba(88, 197, 154, 0.8), inset 0 0 20px rgba(88, 197, 154, 0.5);
548→  border-radius: 12px;
549→
550→  /* Animace - začínáme viditelně! */
551→  opacity: 0.6;
552→  animation: epic-pulse 1.8s infinite ease-in-out;
553→}
554→
555→@keyframes epic-pulse {
556→  0%   { transform: scale(0.95); opacity: 0.6; border-color: rgba(88, 197, 154, 0.7); }
557→  50%  { transform: scale(1.05); opacity: 1.0; border-color: rgba(88, 197, 154, 1.0); box-shadow: 0 0 60px rgba(88, 197, 154, 1); }
558→  100% { transform: scale(0.95); opacity: 0.6; border-color: rgba(88, 197, 154, 0.7); }
559→}
