  1→// engine/engine.js
  2→// Game engine core: scenes, i18n, dialogs, hero profile, inventory, puzzles, events.
  3→
  4→import {createPuzzleRunner, openListModal} from './puzzles/index.js';
  5→import {DialogUI} from './dialogs.js';
  6→
  7→export class Game {
  8→    constructor(opts) {
  9→        // DOM refs
 10→        this.sceneImage = opts.sceneImage;
 11→        this.hotspotLayer = opts.hotspotLayer;
 12→        this.inventoryRoot = opts.inventoryRoot;
 13→        this.messageBox = opts.messageBox;
 14→        this.modalRoot = opts.modalRoot;
 15→        this.modalTitle = opts.modalTitle;
 16→        this.modalBody = opts.modalBody;
 17→        this.modalCancel = opts.modalCancel;
 18→        this.modalOk = opts.modalOk;
 19→
 20→        // Data sources
 21→        this.baseUrl = opts.baseUrl || './';
 22→        this.scenesUrl = opts.scenesUrl;          // already prefixed by caller
 23→        this.dialogsUrl = opts.dialogsUrl || null; // ./games/<id>/dialogs.json (optional)
 24→        this.lang = (opts.lang || 'cs').toLowerCase();
 25→        this.i18n = opts.i18n || {engine: {}, game: {}};
 26→
 27→        // State
 28→        this.data = null;
 29→        this.meta = {};
 30→        this.dialogsData = null;
 31→        this.state = null;
 32→        this.currentScene = null;
 33→        this._modalResolve = null;
 34→        this._pendingHighlights = {};
 35→
 36→        // Toast container
 37→        this.toastRoot = document.createElement('div');
 38→        this.toastRoot.className = 'toast-container';
 39→        document.body.appendChild(this.toastRoot);
 40→
 41→        // Dialog UI
 42→        this.dialogUI = new DialogUI(this);
 43→
 44→        // Modal events
 45→        this.modalCancel.addEventListener('click', () => this._closeModal(false));
 46→        this.modalOk.addEventListener('click', () => this._closeModal(true));
 47→
 48→        // ESC = exit use-mode
 49→        document.addEventListener('keydown', (e) => {
 50→            if (e.key === 'Escape' && this.state?.useItemId) {
 51→                this.exitUseMode();
 52→                e.preventDefault();
 53→            }
 54→        });
 55→    }
 56→
 57→    // --- debug toggles ----------------------------------------------------------
 58→
 59→    _debugOn() {
 60→        try {
 61→            return new URLSearchParams(location.search).get('debug') === '1';
 62→        } catch {
 63→            return false;
 64→        }
 65→    }
 66→
 67→    _dbg(...args) {
 68→        if (this._debugOn()) console.debug('[GAME]', ...args);
 69→    }
 70→
 71→    // --- version signature for safe restore ------------------------------------
 72→
 73→    _signature() {
 74→        const gid = this.meta?.id || 'unknown';
 75→        const gver = this.meta?.version || '0';
 76→        const lang = this.lang || 'cs';
 77→        return `${gid}|${gver}|${lang}`;
 78→    }
 79→
 80→    // --- i18n helpers -----------------------------------------------------------
 81→
 82→    _fmt(str, params) {
 83→        if (!params) return str;
 84→        return String(str).replace(/\{(\w+)}/g, (_, k) => (params[k] ?? `{${k}}`));
 85→    }
