 282→    _isItemApplicableHere(itemId) {
 283→        // Fail-safe: if currentScene is not loaded, return null to indicate uncertainty
 284→        if (!this.currentScene) {
 285→            this._dbg('[GUARD] _isItemApplicableHere: currentScene is null/undefined, returning null (fail-safe)');
 286→            return null;
 287→        }
 288→
 289→        const hs = this.currentScene.hotspots || [];
 290→
 291→        // If scene has no hotspots at all, we can definitively say item is not usable here
 292→        if (hs.length === 0) {
 293→            return false;
 294→        }
 295→
 296→        return hs.some(h => {
 297→            if (!h || !Array.isArray(h.acceptItems)) return false;
 298→
 299→            const accepts = h.acceptItems.map(x => typeof x === 'string' ? { id: x } : x);
 300→            if (!accepts.some(a => a?.id === itemId)) return false;
 301→
 302→            if (h.requireItems && !this._hasAll(h.requireItems)) return false;
 303→            if (h.requireFlags && !this._hasAllFlags(h.requireFlags)) return false;
 304→
 305→            return true;
 306→        });
 307→    }
