 311→    _renderHotspots() {
 312→        this.hotspotLayer.innerHTML = '';
 313→        const hotspots = this.currentScene.hotspots || [];
 314→
 315→        hotspots.forEach((h, idx) => {
 316→            const el = document.createElement('button');
 317→            el.className = 'hotspot';
 318→
 319→            // Default render rectangle (can be overridden by state)
 320→            let visualRect = h.rect;
 321→
 322→            // STATE LOGIC: Find the first matching state (Priority List)
 323→            // The engine checks states from top to bottom. The first one with satisfied requireFlags wins.
 324→            let activeState = null;
 325→            if (h.states && Array.isArray(h.states)) {
 326→                activeState = h.states.find(s => {
 327→                    // If no flags required, it's a default/fallback state
 328→                    if (!s.requireFlags) return true;
 329→                    // Otherwise check if all flags are present
 330→                    return this._hasAllFlags(s.requireFlags);
 331→                });
 332→            }
 333→
 334→            // APPLY ACTIVE STATE
 335→            if (activeState) {
 336→                // 1. CSS Class (e.g., "state-success", "state-locked")
 337→                if (activeState.cssClass) {
 338→                    el.classList.add(activeState.cssClass);
 339→                }
 340→
 341→                // 2. Content (text label, icon, symbol)
 342→                if (activeState.content) {
 343→                    const span = document.createElement('span');
 344→                    span.className = 'hs-content';
 345→                    span.textContent = this._text(activeState.content);
 346→                    el.appendChild(span);
 347→                }
 348→
 349→                // 3. Image Overlay (e.g., specific item graphic)
 350→                if (activeState.image) {
 351→                    const img = document.createElement('img');
 352→                    img.src = this._resolveAsset(activeState.image);
 353→                    img.className = 'hs-image';
 354→                    el.appendChild(img);
 355→                }
 356→
 357→                // 4. Rect Override (if the visual state has different dimensions than the hit area)
 358→                if (activeState.rect) {
 359→                    visualRect = activeState.rect;
 360→                }
 361→
 362→                // 5. Interactivity (disable clicking if the state is final/passive)
 363→                if (activeState.clickable === false) {
 364→                    el.style.pointerEvents = 'none';
 365→                    el.tabIndex = -1;
 366→                }
 367→            }
 368→
 369→            // Apply calculated geometry
 370→            el.style.left = visualRect.x + '%';
 371→            el.style.top = visualRect.y + '%';
 372→            el.style.width = visualRect.w + '%';
 373→            el.style.height = visualRect.h + '%';
 374→
 375→            // Bind interactions (only if not disabled by state)
 376→            if (!activeState || activeState.clickable !== false) {
 377→                el.setAttribute('data-index', String(idx));
 378→
 379→                // Tooltip: prefer state label, fallback to hotspot label
 380→                const label = (activeState && activeState.label) || h.label;
 381→                if (label) el.title = this._text(label);
 382→
 383→                el.addEventListener('click', (e) => {
 384→                    // Editor guard
 385→                    if (document.body.classList.contains('editor-on')) {
 386→                        e.preventDefault(); e.stopPropagation(); return;
 387→                    }
 388→                    e.preventDefault();
 389→                    this._activateHotspot(h).catch(err => this._msg(String(err)));
 390→                });
 391→
 392→                // --- Drop handling for item drag & drop ---
 393→                if (h.acceptItems && Array.isArray(h.acceptItems)) {
 394→                    this._setupHotspotDropHandlers(el, h, idx);
 395→                }
 396→            }
 397→
 398→            this.hotspotLayer.appendChild(el);
 399→        });
 400→    }
