 593→    async _ensurePuzzlesLoaded() {
 594→        // pokud už jsou v this.data.puzzles ve formátu mapy, hotovo
 595→        if (this.data?.puzzles && typeof this.data.puzzles === 'object' && !Array.isArray(this.data.puzzles)) {
 596→            return;
 597→        }
 598→
 599→        const url = this._resolveAsset('puzzles.json');
 600→        let json = {};
 601→        try {
 602→            const r = await fetch(url, {cache: 'no-cache'});
 603→            if (r.ok) json = await r.json();
 604→        } catch {
 605→            // ignore
 606→        }
 607→
 608→        // 1) { byId: { ... } }
 609→        if (json && typeof json === 'object' && json.byId && typeof json.byId === 'object') {
 610→            this.data.puzzles = json.byId;
 611→            return;
 612→        }
 613→        // 2) [ { id, kind, ... }, ... ]
 614→        if (Array.isArray(json)) {
 615→            this.data.puzzles = Object.fromEntries(json.filter(p => p?.id).map(p => [p.id, p]));
 616→            return;
 617→        }
 618→        // 3) { id1:{...}, id2:{...} }
 619→        if (json && typeof json === 'object') {
 620→            this.data.puzzles = json;
 621→            return;
 622→        }
 623→
 624→        // fallback, empty map
 625→        this.data.puzzles = {};
 626→    }
