 845→    /**
 846→     * Sets up drag & drop handlers for an inventory item element.
 847→     * @param {HTMLElement} el - The item button element.
 848→     * @param {object} item - The item data object.
 849→     */
 850→    _setupItemDragDrop(el, item) {
 851→        // HTML5 Drag API
 852→        el.addEventListener('dragstart', (e) => {
 853→            e.dataTransfer.setData('text/plain', item.id);
 854→            e.dataTransfer.effectAllowed = 'move';
 855→            el.classList.add('is-dragging');
 856→            document.body.classList.add('item-dragging');
 857→
 858→            // Create custom drag image
 859→            if (item.icon) {
 860→                const dragImg = new Image();
 861→                dragImg.src = this._resolveAsset(item.icon);
 862→                // Use small offset so cursor is on the image
 863→                e.dataTransfer.setDragImage(dragImg, 24, 24);
 864→            }
 865→
 866→            this._dbg('[DRAG] Started dragging item:', item.id);
 867→        });
 868→
 869→        el.addEventListener('dragend', (e) => {
 870→            el.classList.remove('is-dragging');
 871→            document.body.classList.remove('item-dragging');
 872→            this._clearHotspotDropHighlights();
 873→            this._dbg('[DRAG] Ended dragging item:', item.id);
 874→        });
 875→
 876→        // Touch-based drag for mobile (pointer events fallback)
 877→        this._setupTouchDrag(el, item);
 878→    }
 879→
 880→    /**
 881→     * Sets up touch-based drag for mobile devices where HTML5 drag doesn't work well.
 882→     * @param {HTMLElement} el - The item element.
 883→     * @param {object} item - The item data object.
 884→     */
 885→    _setupTouchDrag(el, item) {
 886→        let touchStartTime = 0;
 887→        let touchStartX = 0;
 888→        let touchStartY = 0;
 889→        let ghost = null;
 890→        let isDragging = false;
 891→        const DRAG_THRESHOLD = 10; // pixels
 892→        const HOLD_TIME = 200; // ms to distinguish from tap
 893→
 894→        const createGhost = () => {
 895→            ghost = document.createElement('div');
 896→            ghost.className = 'item-drag-ghost';
 897→            if (item.icon) {
 898→                const img = document.createElement('img');
 899→                img.src = this._resolveAsset(item.icon);
 900→                ghost.appendChild(img);
 901→            }
 902→            const label = document.createElement('span');
 903→            label.textContent = this._text(item.label) || item.id;
 904→            ghost.appendChild(label);
 905→            document.body.appendChild(ghost);
 906→        };
 907→
 908→        const moveGhost = (x, y) => {
 909→            if (!ghost) return;
 910→            ghost.style.left = (x - 30) + 'px';
 911→            ghost.style.top = (y - 30) + 'px';
 912→        };
 913→
 914→        const removeGhost = () => {
 915→            if (ghost && ghost.parentNode) {
 916→                ghost.parentNode.removeChild(ghost);
 917→            }
 918→            ghost = null;
 919→        };
 920→
 921→        const getHotspotUnderPoint = (x, y) => {
 922→            const elements = document.elementsFromPoint(x, y);
 923→            for (const elem of elements) {
 924→                if (elem.classList.contains('hotspot') && elem.dataset.acceptsItems) {
 925→                    return elem;
 926→                }
 927→            }
 928→            return null;
 929→        };
 930→
 931→        el.addEventListener('touchstart', (e) => {
 932→            touchStartTime = Date.now();
 933→            const touch = e.touches[0];
 934→            touchStartX = touch.clientX;
 935→            touchStartY = touch.clientY;
 936→            isDragging = false;
 937→        }, { passive: true });
 938→
 939→        el.addEventListener('touchmove', (e) => {
 940→            const touch = e.touches[0];
 941→            const dx = touch.clientX - touchStartX;
 942→            const dy = touch.clientY - touchStartY;
 943→            const distance = Math.sqrt(dx * dx + dy * dy);
 944→            const elapsed = Date.now() - touchStartTime;
 945→
 946→            // Start drag if moved enough or held long enough while moving
 947→            if (!isDragging && (distance > DRAG_THRESHOLD || (elapsed > HOLD_TIME && distance > 5))) {
 948→                isDragging = true;
 949→                createGhost();
 950→                el.classList.add('is-dragging');
 951→                document.body.classList.add('item-dragging');
 952→                this._highlightAcceptingHotspots(item.id);
 953→            }
 954→
 955→            if (isDragging) {
 956→                e.preventDefault(); // Prevent scroll while dragging
 957→                moveGhost(touch.clientX, touch.clientY);
 958→
 959→                // Highlight hotspot under touch
 960→                const hotspot = getHotspotUnderPoint(touch.clientX, touch.clientY);
 961→                this._updateHotspotDropHighlight(hotspot);
 962→            }
 963→        }, { passive: false });
 964→
 965→        el.addEventListener('touchend', (e) => {
 966→            if (isDragging) {
 967→                const touch = e.changedTouches[0];
 968→                const hotspot = getHotspotUnderPoint(touch.clientX, touch.clientY);
 969→
 970→                if (hotspot) {
 971→                    const hotspotIndex = parseInt(hotspot.dataset.index, 10);
 972→                    const hs = this.currentScene?.hotspots?.[hotspotIndex];
 973→                    if (hs) {
 974→                        this._handleItemDropOnHotspot(item.id, hs);
 975→                    }
 976→                }
 977→
 978→                removeGhost();
 979→                el.classList.remove('is-dragging');
 980→                document.body.classList.remove('item-dragging');
 981→                this._clearHotspotDropHighlights();
 982→                isDragging = false;
 983→            }
 984→        });
 985→
 986→        el.addEventListener('touchcancel', () => {
 987→            if (isDragging) {
 988→                removeGhost();
 989→                el.classList.remove('is-dragging');
 990→                document.body.classList.remove('item-dragging');
 991→                this._clearHotspotDropHighlights();
 992→                isDragging = false;
 993→            }
 994→        });
 995→    }
 996→
 997→    /**
 998→     * Highlights hotspots that accept the given item.
 999→     * @param {string} itemId - The item ID being dragged.
1000→     */
1001→    _highlightAcceptingHotspots(itemId) {
1002→        const hotspots = this.hotspotLayer.querySelectorAll('.hotspot');
