1075→    /**
1076→     * Open the "Inspect Item" modal.
1077→     * Final UX:
1078→     * - No OK/Cancel footer at all.
1079→     * - A top-right close (×) icon that reddens on hover.
1080→     * - Inside body: single blue "Use" button (adventure style).
1081→     * - Title/word/description are localized via _text/_t.
1082→     *
1083→     * No global modal API changes required — we defensively hide any footer if present.
1084→     *
1085→     * @param {{id:string, icon?:string, label?:string|object, meta?:{word?:string|object, description?:string|object}}} item
1086→     * @returns {Promise<void>}
1087→     */
1088→    async _inspectItem(item) {
1089→        // Build modal body
1090→        const body = document.createElement('div');
1091→        body.className = 'modal-body item-inspect';
1092→
1093→        if (item.icon) {
1094→            const img = document.createElement('img');
1095→            img.src = this._resolveAsset(item.icon);
1096→            img.alt = this._text(item.label) || item.id;
1097→            img.className = 'modal-img';
1098→            body.appendChild(img);
1099→        }
1100→
1101→        if (item.meta?.word) {
1102→            const w = document.createElement('div');
1103→            w.className = 'modal-word';
1104→            const wordValue = this._text(item.meta.word);
1105→            w.textContent = (wordValue && String(wordValue)) || String(item.meta.word);
1106→            body.appendChild(w);
1107→        }
1108→
1109→        if (item.meta?.description) {
1110→            const d = document.createElement('div');
1111→            d.className = 'modal-desc';
1112→            const descValue = this._text(item.meta.description);
1113→            d.textContent = (descValue && String(descValue)) || String(item.meta.description);
1114→            body.appendChild(d);
1115→        }
1116→
1117→        // Inline action dock (only "Use")
1118→        const ops = document.createElement('div');
1119→        ops.className = 'item-ops';
1120→
1121→        const btnUse = document.createElement('button');
1122→        btnUse.type = 'button';
1123→        btnUse.className = 'btn btn--action';
1124→        btnUse.textContent = this._t('engine.use.button', 'Použít');
1125→
1126→        const policy = this._getUseGuardPolicy();
1127→        if (policy !== 'off') {
1128→            const allowed = this._isItemApplicableHere(item.id);
1129→            // FAIL-SAFE: If allowed is null (cannot determine), show the button anyway
1130→            // This prevents edge cases where button disappears due to race conditions
1131→            const shouldHide = policy === 'hide' && allowed === false;
1132→            const shouldDisable = policy === 'disable' && allowed === false;
1133→
1134→            if (shouldHide) {
1135→                // Button is intentionally not placed in the panel
1136→                this._dbg('[ITEM] Use button hidden: policy=hide, allowed=false');
1137→            } else {
1138→                if (shouldDisable) {
1139→                    btnUse.disabled = true;
1140→                    btnUse.title = this._t('engine.use.disabledHere', 'Na této scéně teď nemáš kde použít.');
1141→                    btnUse.classList.add('is-disabled');
1142→                }
1143→                btnUse.addEventListener('click', () => {
1144→                    if (btnUse.disabled) return;
1145→                    this.enterUseMode(item.id);
1146→                    this._closeModal(true);
1147→                });
1148→                ops.appendChild(btnUse);
1149→            }
1150→        } else {
1151→            btnUse.addEventListener('click', () => {
1152→                this.enterUseMode(item.id);
1153→                this._closeModal(true);
1154→            });
1155→            ops.appendChild(btnUse);
1156→        }
1157→
1158→        body.appendChild(ops);
1159→
1160→        // Open modal WITHOUT footer labels (try to suppress buttons).
1161→        // If the modal implementation still renders a footer, we hide it below.
1162→        const p = this.openModal({
1163→            title: this._text(item.label) || item.id,
1164→            body,
1165→            okLabel: '',          // suppress OK
1166→            cancelLabel: ''       // suppress Cancel
1167→        });
1168→
1169→        // Tune modal DOM after it mounts: add header close icon; hide any footer.
1170→        const tune = () => {
1171→            const overlay = document.getElementById('modal');
1172→            if (!overlay) return;
1173→            const content = overlay.querySelector('.modal-content');
1174→            if (!content) return;
1175→
1176→            content.classList.add('modal--item');
1177→
1178→            // Header with title + close icon (×)
1179→            let header = content.querySelector('.modal-header');
1180→            if (!header) {
1181→                header = document.createElement('div');
1182→                header.className = 'modal-header';
1183→
1184→                const titleEl = document.createElement('div');
1185→                titleEl.className = 'modal-title';
1186→                titleEl.textContent = this._text(item.label) || item.id;
1187→
1188→                const closeBtn = document.createElement('button');
1189→                closeBtn.type = 'button';
1190→                closeBtn.className = 'modal-close';
1191→                closeBtn.setAttribute('aria-label', this._t('engine.modal.close', 'Close'));
1192→                closeBtn.innerHTML = '&times;'; // ×
1193→                closeBtn.addEventListener('click', () => this._closeModal(false));
1194→
1195→                header.appendChild(titleEl);
1196→                header.appendChild(closeBtn);
1197→
1198→                // Remove any plain .modal-title block if present and insert header at the top
1199→                const oldTitle = content.querySelector('.modal-title');
1200→                if (oldTitle && oldTitle.parentElement === content) oldTitle.remove();
1201→                content.insertBefore(header, content.firstChild);
1202→            }
1203→
1204→            // Hide any footer/actions row defensively (if openModal created it)
1205→            const candidates = Array.from(content.children).slice(-3); // last few blocks
1206→            candidates.forEach(node => {
1207→                if (node.classList.contains('item-ops')) return; // keep our Use dock
1208→                const btns = node.querySelectorAll('button');
1209→                if (btns.length && (node === content.lastElementChild || /ok|cancel|zavř|close/i.test(node.textContent || ''))) {
1210→                    node.style.display = 'none';
1211→                    node.classList.add('modal-footer-hidden');
1212→                }
1213→            });
1214→        };
1215→
1216→        // Run after layout tick to ensure modal DOM exists
1217→        setTimeout(tune, 0);
1218→
1219→        await p;
1220→    }
