1321→    /**
1322→     * Process game events based on a trigger.
1323→     * @param {{on: string, scene?: string}} trigger - The event trigger context.
1324→     */
1325→    async _processEvents(trigger) {
1326→        const events = this.data.events || [];
1327→        for (const ev of events) {
1328→            if (!ev || !ev.id) continue;
1329→
1330→            // 1. Check if already fired (for one-time events)
1331→            if (ev.once && this.state.eventsFired?.[ev.id]) continue;
1332→
1333→            const w = ev.when || {};
1334→
1335→            // 2. Check Conditions
1336→            // a) Trigger type match
1337→            if (w.on && w.on !== trigger.on) continue;
1338→
1339→            // b) Scene match (current scene or specified scene)
1340→            if (w.scene && w.scene !== (trigger.scene || this.state.scene)) continue;
1341→
1342→            // c) Inventory requirements
1343→            if (w.requireItems && !this._hasAll(w.requireItems)) continue;
1344→
1345→            // d) Flag requirements
1346→            if (w.requireFlags && !this._hasAllFlags(w.requireFlags)) continue;
1347→
1348→            // e) Missing items check
1349→            if (w.missingItems && (w.missingItems.some(x => this.state.inventory.includes(x)))) continue;
1350→
1351→            // --- MATCH FOUND ---
1352→
1353→            // Mark event as fired IMMEDIATELY before executing actions.
1354→            // This prevents recursion loops if an action (like a dialog) triggers
1355→            // a state change that would otherwise re-evaluate and re-trigger this
1356→            // same event while it is still pending/awaiting.
1357→            if (ev.once) {
1358→                this.state.eventsFired = this.state.eventsFired || {};
1359→                this.state.eventsFired[ev.id] = true;
1360→                this._saveState();
1361→            }
1362→
1363→            const act = ev.then || {};
1364→
1365→            // 3. Execute Actions
1366→
1367→            // Show Toast
1368→            if (act.toast?.text) {
1369→                this.toast(this._text(act.toast.text), act.toast.ms ?? 5000);
1370→            }
1371→
1372→            // Change Scene Image
1373→            if (act.setSceneImage?.sceneId && act.setSceneImage?.image) {
1374→                const sc = this.data.scenes.find(s => s.id === act.setSceneImage.sceneId);
1375→                if (sc) {
1376→                    sc.image = this._resolveAsset(act.setSceneImage.image);
1377→                    // If we are currently in this scene, update the DOM immediately
1378→                    if (this.currentScene?.id === sc.id) {
1379→                        this.sceneImage.src = sc.image;
1380→                        await new Promise(res => {
1381→                            if (this.sceneImage.complete && this.sceneImage.naturalWidth) res();
1382→                            else this.sceneImage.onload = () => res();
1383→                        });
1384→                    }
1385→                }
1386→            }
1387→
1388→            // Open Dialog (Blocking)
1389→            // The engine waits here until the dialog is fully closed by the user.
1390→            if (act.openDialog) {
1391→                await this.openDialog(act.openDialog);
1392→            }
1393→
1394→            // Highlight Hotspot
1395→            // Executed after the dialog closes (if any).
1396→            if (act.highlightHotspot?.rect) {
1397→                const h = act.highlightHotspot;
1398→                this._enqueueOrShowHighlight({
1399→                    sceneId: h.sceneId || (w.scene || this.state.scene),
1400→                    rect: h.rect,
1401→                    ms: h.ms ?? 3500,
1402→                    outline: !!h.outline
1403→                });
1404→            }
1405→
1406→            // Play Video (Blocking)
1407→            // Engine waits until the video ends or is skipped
1408→            if (act.playVideo?.src) {
1409→                await this._playVideo(act.playVideo);
1410→                if (act.playVideo.onEnd) {
1411→                    await this._applyActions(act.playVideo.onEnd);
1412→                }
1413→            }
1414→
1415→            // Open Puzzle
1416→            if (act.openPuzzle) {
1417→                const ap = act.openPuzzle;
1418→                const res = await this._openPuzzleByRef({
1419→                    ref: ap.ref,
1420→                    rect: ap.rect || {x: 0, y: 0, w: 100, h: 100},
1421→                    options: ap.options || {},
1422→                    background: ap.background || null
1423→                });
1424→
1425→                if (ap.options?.aggregateOnly) {
1426→                    this._appendPuzzleResult({ref: ap.ref, ok: !!res?.ok, detail: res?.detail || null});
1427→                } else {
1428→                    if (res?.ok) {
1429→                        if (ap.onSuccess) await this._applyActions(ap.onSuccess);
1430→                    } else {
1431→                        if (ap.onFail) await this._applyActions(ap.onFail);
1432→                    }
1433→                }
1434→            }
1435→
1436→            // Open Puzzle List
1437→            if (act.openPuzzleList) {
1438→                const apl = act.openPuzzleList;
1439→                const ok = await openListModal(this, {
1440→                    items: apl.items || [],
1441→                    rect: apl.rect || {x: 0, y: 0, w: 100, h: 100},
1442→                    background: apl.background || null,
1443→                    aggregateOnly: !!apl.aggregateOnly,
1444→                    blockUntilSolved: !!apl.blockUntilSolved,
1445→                    puzzlesById: this.data.puzzles
1446→                });
1447→                if (ok) {
1448→                    if (apl.onSuccess) await this._applyActions(apl.onSuccess);
1449→                } else {
1450→                    if (apl.onFail) await this._applyActions(apl.onFail);
1451→                }
1452→            }
1453→
1454→            // Set Flags
1455→            if (act.setFlags) {
1456→                let changed = false;
1457→                if (Array.isArray(act.setFlags)) {
1458→                    for (const f of act.setFlags) {
1459→                        if (!this.state.flags[f]) {
1460→                            this.state.flags[f] = true;
1461→                            changed = true;
1462→                        }
1463→                    }
1464→                } else {
1465→                    for (const [k, v] of Object.entries(act.setFlags)) {
1466→                        if (!!this.state.flags[k] !== !!v) {
1467→                            this.state.flags[k] = !!v;
1468→                            changed = true;
1469→                        }
1470→                    }
1471→                }
1472→                if (changed) this._saveState();
1473→            }
1474→        }
1475→    }
