 13→// ============================================================================
 14→// PUZZLE KINDS REGISTRY
 15→// ============================================================================
 16→// Centrální mapa všech dostupných puzzle typů.
 17→// Pro přidání nového typu stačí přidat import výše a záznam do této mapy.
 18→// ============================================================================
 19→
 20→const PUZZLE_KINDS = {
 21→    phrase: PhrasePuzzle,
 22→    code: CodePuzzle,
 23→    quiz: QuizPuzzle,
 24→    order: OrderPuzzle,
 25→    match: MatchPuzzle,
 26→    group: GroupPuzzle,
 27→    choice: ChoicePuzzle,
 28→    list: ListPuzzle,
 29→    cloze: ClozePuzzle
 30→};
 31→
 32→const _registry = new Map();
 33→
 34→export function registerKind(kind, clazz) {
 35→    _registry.set(kind, clazz);
 36→}
 37→
 38→export function getKind(kind) {
 39→    return _registry.get(kind) || BasePuzzle;
 40→}
 41→
 42→// Automatická registrace všech puzzle kinds z mapy
 43→for (const [kind, clazz] of Object.entries(PUZZLE_KINDS)) {
 44→    registerKind(kind, clazz);
 45→}
 46→
 47→/** Create and run a single puzzle instance inside a container overlay. */
 48→export function createPuzzleRunner(args) {
 49→    const cfg = args.config || (args.ref ? args.puzzlesById?.[args.ref] : null);
 50→    if (!cfg) throw new Error(`Puzzle config not found (ref='${args.ref || ''}')`);
 51→
 52→    const Clazz = getKind(cfg.kind);
 53→    const i18nFn = args.i18n || ((k, def = '') => (
 54→        args.engine?._t?.(k, def) ??
 55→        args.engine?.i18n?.game?.[k] ??
 56→        args.engine?.i18n?.engine?.[k] ??
 57→        def
 58→    ));
 59→
 60→    const puzzle = new Clazz({
 61→        id: args.ref || cfg.id || 'inline',
 62→        kind: cfg.kind,
 63→        config: cfg,
 64→        i18n: i18nFn,
 65→        engine: args.engine,
 66→        instanceOptions: args.instanceOptions || {}
 67→    });
 68→
 69→    // single-shot guard
 70→    let __resolved = false;
 71→    puzzle.resolveOk = (detail) => {
 72→        if (!__resolved) {
 73→            __resolved = true;
 74→            args.onResolve?.({ok: true, detail});
 75→        }
 76→    };
 77→    puzzle.resolveFail = (reason, extra) => {
 78→        if (!__resolved) {
 79→            __resolved = true;
 80→            args.onResolve?.({ok: false, detail: {reason, ...(extra || {})}});
 81→        }
 82→    };
 83→
 84→    const _origOnOk = puzzle.onOk?.bind(puzzle);
 85→    puzzle.onOk = () => {
 86→        const res = _origOnOk ? _origOnOk() : puzzle.evaluate?.();
 87→        return Promise.resolve(res).then((r) => {
 88→            if (__resolved) return;
 89→            if (r && (r.hold === true || r === 'hold')) return; // keep open
 90→            const ok = !!(r && r.ok);
 91→            __resolved = true;
 92→            args.onResolve?.({ok, detail: r?.detail});
 93→        });
 94→    };
 95→
 96→    const containerRect = (args.instanceOptions && args.instanceOptions.overrideContainerRect === true && args.rect) ? args.rect : {
 97→        x: 0,
 98→        y: 0,
 99→        w: 100,
100→        h: 100
101→    };
102→
103→    const container = document.createElement('div');
104→    container.className = 'pz-container';
105→    Object.assign(container.style, {
106→        position: 'absolute',
107→        pointerEvents: 'auto',
108→        zIndex: '8000',
109→        ...rectToStyle(containerRect)
110→    });
111→
112→    // host modal hardly stopped
113→    const hostModal = args.engine?.modalRoot;
114→    let prevDisplay = '';
115→    if (hostModal) {
116→        prevDisplay = hostModal.style.display;
117→        hostModal.style.display = 'none';
118→    }
119→
120→    function mountInto(rootEl) {
121→        rootEl.appendChild(container);
122→
123→        const workRect = cfg.rect || {x: 10, y: 10, w: 80, h: 80};
124→
125→        // Resolve background: args.background (from list step) OR cfg.background (from puzzle config)
126→        const resolvedBackground = args.background ||
127→                                   (cfg.background ? (args.engine?._resolveAsset?.(cfg.background) || cfg.background) : undefined);
128→
129→        console.log('[PZ] runner mountInto:', {
130→            id: puzzle.id,
131→            kind: puzzle.kind,
132→            argsRect: args.rect,
133→            cfgRect: cfg.rect,
134→            containerRect,
135→            workRect,
136→            'args.background': args.background,
137→            'cfg.background': cfg.background,
138→            'resolvedBackground': resolvedBackground
139→        });
140→
141→        if (/\bdebug=1\b/.test(window.location.search)) {
142→            console.debug('[PZ] runner mountInto:', {
143→                id: puzzle.id,
144→                kind: puzzle.kind,
145→                'args.rect (hotspot)': args.rect,
146→                'cfg.rect (puzzle config)': cfg.rect,
147→                'containerRect (used)': containerRect,
148→                'workRect (used)': workRect,
149→                containerStyle: container.style.cssText
150→            });
151→        }
152→
153→        puzzle.mount(container, workRect, resolvedBackground);
154→        puzzle.render?.();
155→    }
156→
157→    function unmount() {
158→        try {
159→            puzzle.unmount();
160→        } catch {
161→        }
162→        if (container.parentNode) container.parentNode.removeChild(container);
163→        if (hostModal) hostModal.style.display = prevDisplay || '';
164→    }
165→
166→    puzzle.onRequestClose = ({reason}) => {
167→        if (__resolved) return;
168→        __resolved = true;
169→        args.onResolve?.({ok: false, detail: {reason: reason || 'cancel'}});
170→    };
171→
172→    return {puzzle, mountInto, unmount};
173→}
174→
175→/** Open list/sequence of puzzles. */
176→export function openListModal(engine, cfg) {
177→    const mountRoot = engine.hotspotLayer;
178→    const i18n = (k, def = '') => engine._t?.(k, def) || def;
179→
180→    let puzzlesById = cfg.puzzlesById;
181→    if (!puzzlesById) {
182→        const raw = engine.data?.puzzles || engine.data?.puzzlesById || {};
183→        puzzlesById = Array.isArray(raw) ? Object.fromEntries(raw.map(p => [p.id, p])) : raw;
184→    }
185→
186→    const listItems = (cfg.items || []).map(it => ({
187→        ...it,
188→        background: it.background ? engine._resolveAsset(it.background) : undefined
189→    }));
190→
191→    return new Promise((resolve) => {
192→        runPuzzleList({
193→            items: listItems,
194→            rect: cfg.rect || {x: 0, y: 0, w: 100, h: 100},
195→            background: cfg.background ? engine._resolveAsset(cfg.background) : undefined,
196→            aggregateOnly: !!cfg.aggregateOnly,
197→            blockUntilSolved: !!cfg.blockUntilSolved,
198→            summary: cfg.summary || {show: true},
199→            puzzlesById,
200→            i18n,
201→            engine,
202→            mountRoot,
203→            onDone: (res) => resolve(!!res.ok)
204→        });
205→    });
206→}
