  6→/**
  7→ * Base class for all puzzles – container, theming, buttons, wiring.
  8→ * Provides common infrastructure: mount, layout, i18n, token styling, etc.
  9→ */
 10→export class BasePuzzle {
 11→    /**
 12→     * @param {{
 13→     *   id: string,
 14→     *   kind: string,
 15→     *   config: any,
 16→     *   i18n?: (key:string, fallback?:string)=>string,
 17→     *   engine: any,
 18→     *   instanceOptions?: any
 19→     * }} ctx
 20→     */
 21→    constructor(ctx) {
 22→        this.id = ctx.id;
 23→        this.kind = ctx.kind;
 24→        this.config = ctx.config || {};
 25→
 26→        this.instanceOptions = {...(ctx.instanceOptions || {}), ...(this.config.options || {})};
 27→
 28→        // I18n centralized through i18n-helpers.js
 29→        this.engine = ctx.engine || {};
 30→        const i18nDict = {
 31→            engine: this.engine?.i18n?.engine || {},
 32→            game: this.engine?.i18n?.game || {}
 33→        };
 34→
 35→        // Wrapper pro i18n helpers
 36→        this.t = (val, fallback = '') => i18nText(i18nDict, val, fallback);
 37→        this.tKey = (key, fallback = '') => i18nT(i18nDict, key, fallback);
 38→
 39→        this.root = null;
 40→        this.windowEl = null;
 41→        this.flowEl = null;
 42→        this.okBtn = null;
 43→        this.cancelBtn = null;
 44→        this.onRequestClose = null;
 45→        this.resolveOk = null;
 46→        this.resolveFail = null;
 47→
 48→        if (DBG()) console.debug('[PZ] constructor', {id: this.id, kind: this.kind});
 49→    }
 50→
 51→    /** Create root DOM, apply layout and theme. */
 52→    mount(container, workRect, backgroundUrl) {
 53→        const root = document.createElement('div');
 54→        root.className = `pz pz--kind-${this.kind} pz--id-${this.id}`;
 55→
 56→        // Root vždy vyplní container (workRect se NEaplikuje na root)
 57→        Object.assign(root.style, {
 58→            position: 'absolute',
 59→            inset: '0',
 60→            width: '100%',
 61→            height: '100%'
 62→        });
 63→        container.appendChild(root);
 64→        this.root = root;
 65→
 66→        const win = document.createElement('div');
 67→        win.className = 'pz__window';
 68→        this.windowEl = win;
 69→        Object.assign(win.style, {
 70→            position: 'absolute',
 71→            left: (workRect?.x ?? 10) + '%',
 72→            top: (workRect?.y ?? 10) + '%',
 73→            width: (workRect?.w ?? 80) + '%',
 74→            height: (workRect?.h ?? 80) + '%'
 75→        });
 76→        root.appendChild(win);
 77→        this.windowEl = win;
 78→
 79→        console.log('[PZ] base.mount window rect (cfg.rect):', workRect, {
 80→            computedWindowRectPx: win.getBoundingClientRect(),
 81→            parentRectPx: container.getBoundingClientRect()
 82→        });
 83→
 84→        // Background overlay (FULL Screen under root)
 85→        if (backgroundUrl) {
 86→            const overlay = document.createElement('div');
 87→            overlay.className = 'pz-overlay';
 88→            overlay.style.background = `url("${backgroundUrl}") center/cover no-repeat`;
 89→            overlay.style.opacity = '1';
 90→            overlay.style.pointerEvents = 'none';
 91→            overlay.style.position = 'absolute';
 92→            overlay.style.inset = '0';
 93→            container.insertBefore(overlay, container.firstChild);
 94→            this._bgOverlay = overlay;
 95→        }
 96→
 97→        // Flow container - NO INLINE Styles!
 98→        const flow = document.createElement('div');
 99→        flow.className = 'pz__flow';
100→        win.appendChild(flow);
101→        this.flowEl = flow;
102→
103→        // Header group (title + prompt up)
104→        const hasHeader = this.config.title || this.config.prompt;
105→        if (hasHeader) {
106→            const headerGroup = document.createElement('div');
107→            headerGroup.className = 'pz-header-group';
108→
109→            if (this.config.title) {
110→                const titleVisible = this.config.theme?.title?.visible !== false;
111→                if (titleVisible) {
112→                    const title = document.createElement('div');
113→                    title.className = 'pz-title';
114→                    title.setAttribute('data-id', 'title');
115→                    const titleText = this.t(this.config.title, '');
116→                    title.textContent = titleText;
117→
118→                    // Apply theme styles
119→                    const titleStyle = this.config.theme?.title || {};
120→                    this.applyStyle(title, titleStyle);
121→
122→                    headerGroup.appendChild(title);
123→                    if (DBG()) console.debug('[PZ] title:', {raw: this.config.title, translated: titleText});
124→                }
125→            }
126→
127→            if (this.config.prompt) {
128→                const promptVisible = this.config.theme?.prompt?.visible !== false;
129→                if (promptVisible) {
130→                    const prompt = document.createElement('div');
131→                    prompt.className = 'pz-prompt';
132→                    prompt.setAttribute('data-id', 'prompt');
133→                    const promptText = this.t(this.config.prompt, '');
134→                    prompt.textContent = promptText;
135→
136→                    // Apply theme styles
137→                    const promptStyle = this.config.theme?.prompt || {};
138→                    this.applyStyle(prompt, promptStyle);
139→
140→                    headerGroup.appendChild(prompt);
141→                    if (DBG()) console.debug('[PZ] prompt:', {raw: this.config.prompt, translated: promptText});
142→                }
143→            }
144→
145→            // Only append header group if it has children
146→            if (headerGroup.children.length > 0) {
147→                flow.appendChild(headerGroup);
148→            }
149→        }
150→
151→        // Buttons (merge z config + instanceOptions)
152→        const mergedButtons = {
153→            ok: {
154→                visible: true,
155→                label: '@btn.ok@OK', ...(this.config.buttons?.ok || {}), ...(this.instanceOptions.buttons?.ok || {})
156→            },
157→            cancel: {
158→                visible: true,
159→                label: '@btn.cancel@Zavřít', ...(this.config.buttons?.cancel || {}), ...(this.instanceOptions.buttons?.cancel || {})
160→            },
161→        };
162→
163→        const footer = document.createElement('div');
164→        footer.className = 'pz-footer';
165→        footer.setAttribute('data-id', 'footer');
166→
167→        if (mergedButtons.ok.visible !== false) {
168→            const ok = document.createElement('button');
169→            ok.type = 'button';
170→            ok.className = 'pz-btn pz-btn--ok';
171→            ok.setAttribute('data-id', 'ok');
172→            ok.textContent = this.t(mergedButtons.ok.label, 'OK');
173→            ok.addEventListener('click', () => this.onOk());
174→            footer.appendChild(ok);
175→            this.okBtn = ok;
176→        }
177→        if (mergedButtons.cancel.visible !== false) {
178→            const c = document.createElement('button');
179→            c.type = 'button';
180→            c.className = 'pz-btn pz-btn--cancel';
181→            c.setAttribute('data-id', 'cancel');
182→            c.textContent = this.t(mergedButtons.cancel.label, 'Zavřít');
183→            c.addEventListener('click', () => this.onCancel());
184→            footer.appendChild(c);
185→            this.cancelBtn = c;
186→        }
187→
188→        flow.appendChild(footer);
189→
190→        // Layout (auto/manual/grid)
191→        const layoutCfg = this.instanceOptions.layout || this.config.layout || this.config.options?.layout || {
192→            mode: 'auto',
193→            direction: 'vertical'
194→        };
195→        applyAutoLayout(root, layoutCfg);
196→        // Manual per-element positioning based on config.elements (percent rects) + visibility
197→        const elementsCfg = this.instanceOptions?.elements || this.config?.elements || this.config?.options?.elements;
198→        if ((layoutCfg?.mode === 'manual') && elementsCfg) {
199→            this.applyManualElements(elementsCfg);
200→        }
201→
202→
203→        this.applyTheme();
204→        if (DBG()) console.debug('[PZ] base.mount ok', {id: this.id, cls: this.root.className, layout: layoutCfg});
205→    }
206→
207→    /**
208→     * Apply manual per-element layout using elements map:
209→     * elements: { "<id>": { rect: {x,y,w,h}, visible?: boolean } }
210→     * Coordinates are percent of .pz__window.
211→     */
212→    applyManualElements(elementsMap = {}) {
213→        const win = this.windowEl || this.root;
214→        if (!win) return;
215→        if (this.flowEl) {
216→            this.flowEl.style.padding = '0';
217→        }
218→        for (const [id, cfg] of Object.entries(elementsMap)) {
219→            const el = win.querySelector(`[data-id="${id}"]`) || this.root.querySelector(`[data-id="${id}"]`);
220→            if (!el) continue;
221→            if (cfg && cfg.visible === false) {
222→                el.style.display = 'none';
223→                el.classList.add('pz-hidden');
224→            } else {
225→                el.classList.remove('pz-hidden');
226→                if (el.style.display === 'none') el.style.removeProperty('display');
227→            }
228→            if (cfg && cfg.rect) {
229→                el.style.position = 'absolute';
230→                el.style.left = (cfg.rect.x ?? 0) + '%';
231→                el.style.top = (cfg.rect.y ?? 0) + '%';
232→                el.style.width = (cfg.rect.w ?? 100) + '%';
233→                el.style.height = (cfg.rect.h ?? 100) + '%';
234→            }
235→        }
236→    }
237→
238→
239→    applyTheme() {
240→        const t1 = this.config.theme || {};
241→        const t2 = (this.instanceOptions && this.instanceOptions.theme) || {};
242→        const vars = {...(t1.vars || {}), ...(t2.vars || {})};
243→        for (const [k, v] of Object.entries(vars)) this.root?.style.setProperty(k, v);
244→        const cls = [t1.class, t2.class].filter(Boolean).join(' ');
245→        if (cls) this.root?.classList.add(...cls.split(/\s+/));
246→        if (this.instanceOptions?.aggregateOnly) this.root?.classList.add('pz--agg');
247→    }
248→
249→    /**
250→     * Apply style object to element (common theming utility).
251→     * Supports: visible, display, bg, color, border, borderColor, borderWidth, borderRadius, fontSize, textAlign, etc.
252→     */
253→    applyStyle(el, style = {}) {
254→        if (!el || !style) return;
255→
256→        // visible (JS API) - has priority over display
257→        if (style.visible === false) {
258→            el.style.display = 'none';
259→        } else if (style.display) {
260→            // display (CSS property) - only if visible is not false
261→            el.style.display = style.display;
262→        }
263→
264→        // Other CSS properties
265→        if (style.bg) el.style.background = style.bg;
266→        if (style.color) el.style.color = style.color;
267→        if (style.border) el.style.border = style.border;
268→        if (style.borderColor) el.style.borderColor = style.borderColor;
269→        if (style.borderWidth) el.style.borderWidth = style.borderWidth;
270→        if (style.borderRadius) el.style.borderRadius = style.borderRadius;
271→        if (style.fontSize) el.style.fontSize = style.fontSize;
272→        if (style.textAlign) el.style.textAlign = style.textAlign;
273→        if (style.fontWeight) el.style.fontWeight = style.fontWeight;
274→        if (style.padding) el.style.padding = style.padding;
275→        if (style.margin) el.style.margin = style.margin;
276→
277→        if (DBG() && Object.keys(style).length > 0) {
278→            console.debug('[PZ] applyStyle:', {el: el.className, style});
279→        }
280→    }
281→
282→    /**
283→     * Create token element with text/image content.
284→     * @param {object} token - { id, label, text, image, style, rect }
285→     * @param {string} baseClass - dodatečná CSS třída (např. 'pz-token-shuffled')
286→     * @returns {HTMLElement}
287→     */
288→    createToken(token, baseClass = '') {
289→        const el = document.createElement('button');
290→        el.type = 'button';
291→        el.className = `pz-token ${baseClass}`.trim();
292→        el.setAttribute('data-id', String(token.id || ''));
293→
294→        // Image
295→        if (token.image) {
296→            const img = document.createElement('img');
297→            img.className = 'pz-token-image';
298→            img.src = token.image;
299→            img.alt = this.t(token.label || token.text || '', '');
300→            el.appendChild(img);
301→        }
302→
303→        // Text/Label
304→        if (token.label || token.text || !token.image) {
305→            const span = document.createElement('span');
306→            span.className = 'pz-token-text';
307→            span.textContent = this.t(token.label || token.text || '', '');
308→            el.appendChild(span);
309→        }
310→
311→        // Apply merged theme: config.theme.token + token.style
312→        const mergedStyle = {
313→            ...(this.config.theme?.token || {}),
314→            ...(token.style || {})
315→        };
316→        this.applyStyle(el, mergedStyle);
317→
318→        // Manual positioning (pokud je rect)
319→        if (token.rect) {
320→            Object.assign(el.style, {
321→                position: 'absolute',
322→                left: (token.rect.x || 0) + '%',
323→                top: (token.rect.y || 0) + '%',
324→                width: (token.rect.w || 0) + '%',
325→                height: (token.rect.h || 0) + '%'
326→            });
327→        }
328→
329→        return el;
330→    }
331→
332→    /**
333→     * Helper: převod array/string na Set<string> pro porovnání řešení
334→     */
335→    toIdSet(arr) {
336→        const s = new Set();
337→        (Array.isArray(arr) ? arr : [arr]).forEach(x => s.add(String(x)));
338→        return s;
339→    }
340→
341→    /**
342→     * Create content area for tokens (respects layout mode).
343→     * @returns {HTMLElement} - area element, ready to append tokens
344→     */
345→    createTokenArea() {
346→        const area = document.createElement('div');
347→        area.className = 'pz-token-area';
348→
349→        const layoutCfg = this.instanceOptions.layout || this.config.layout || {};
350→        const mode = layoutCfg.mode || 'auto';
351→
352→        if (mode === 'manual') {
353→            Object.assign(area.style, {position: 'relative', flex: '1 1 auto'});
354→        } else if (layoutCfg.grid) {
355→            // Grid layout
356→            Object.assign(area.style, {
357→                display: 'grid',
358→                gridTemplateColumns: `repeat(${layoutCfg.grid.cols || 2}, 1fr)`,
359→                gap: layoutCfg.grid.gap || 'var(--pz-token-gap)',
360→                alignContent: 'start'
361→            });
362→        } else {
363→            // Auto flex layout (vertical/horizontal)
364→            const dir = layoutCfg.direction || 'vertical';
365→            Object.assign(area.style, {
366→                display: 'flex',
367→                flexDirection: dir === 'horizontal' ? 'row' : 'column',
368→                flexWrap: 'wrap',
369→                gap: 'var(--pz-token-gap)',
370→                alignItems: 'stretch'
371→            });
372→        }
373→
374→        return area;
375→    }
376→
377→    render() {
378→        // Override in subclasses
379→    }
380→
381→    onOk() {
382→        return this.evaluate?.();
383→    }
384→
385→    onCancel() {
386→        this.resolveFail?.('cancel');
387→        this.onRequestClose?.({reason: 'cancel'});
388→    }
389→
390→    evaluate() {
391→        return {ok: false};
392→    }
393→
394→    unmount() {
395→        if (this._bgOverlay?.parentNode) this._bgOverlay.parentNode.removeChild(this._bgOverlay);
396→        if (this.root?.parentNode) this.root.parentNode.removeChild(this.root);
397→        this.root = null;
398→        this.windowEl = null;
399→        this.flowEl = null;
400→        this.okBtn = null;
401→        this.cancelBtn = null;
402→        this._bgOverlay = null;
403→    }
404→}

