  5→
  6→export default class PhrasePuzzle extends BasePuzzle {
  7→    constructor(args) {
  8→        super(args);
  9→        this._els = {};
 10→    }
 11→
 12→    mount(container, workRect, backgroundUrl) {
 13→        super.mount?.(container, workRect, backgroundUrl);
 14→        const flow = this.flowEl;
 15→        this.root?.classList.add('pz-kind-phrase');
 16→
 17→        const inputWrap = document.createElement('div');
 18→        inputWrap.className = 'pz-input-wrap';
 19→
 20→        const input = document.createElement('input');
 21→        input.setAttribute('data-id', 'input');
 22→        input.className = 'pz-input';
 23→        input.type = 'text';
 24→        const placeholderText = this.t(this.config.placeholder, '…');
 25→        input.placeholder = placeholderText;
 26→        input.autocomplete = 'off';
 27→        input.spellcheck = false;
 28→        input.addEventListener('keydown', (e) => {
 29→            if (e.key === 'Enter') {
 30→                e.preventDefault();
 31→                this.onOk();
 32→            }
 33→            if (e.key === 'Escape') {
 34→                e.preventDefault();
 35→                this.onCancel();
 36→            }
 37→        });
 38→
 39→        if (DBG()) {
 40→            console.debug('[PZ.phrase] placeholder:', {
 41→                raw: this.config.placeholder,
 42→                translated: placeholderText
 43→            });
 44→        }
 45→
 46→        inputWrap.appendChild(input);
 47→
 48→        // CRITICAL: Vložíme input PŘED footer (musí být na stejné řádce v horizontal mode)
 49→        const footer = flow.querySelector('.pz-footer');
 50→        if (footer) {
 51→            flow.insertBefore(inputWrap, footer);
 52→        } else {
 53→            flow.appendChild(inputWrap);
 54→        }
 55→
 56→        this._els.input = input;
 57→        setTimeout(() => input.focus(), 0);
 58→    }
 59→
 60→    _isCorrect(val) {
 61→        const pool = this.config.solutions ?? this.config.solution ?? '';
 62→        const typed = normalizeText(val);
 63→
 64→        // Support both single value and array of values
 65→        const arr = Array.isArray(pool) ? pool : [pool];
 66→
 67→        const result = arr.some(s => {
 68→            const resolved = this.t(s, s);
 69→            return normalizeText(resolved) === typed;
 70→        });
 71→
 72→        if (DBG()) {
 73→            console.debug('[PZ.phrase] validation:', {
 74→                typed,
 75→                solutions: arr.map(s => normalizeText(this.t(s, s))),
 76→                result
 77→            });
 78→        }
 79→
 80→        return result;
 81→    }
 82→
 83→    onOk() {
 84→        const v = this._els.input?.value || '';
 85→        const ok = this._isCorrect(v);
 86→
 87→        if (!ok && this.instanceOptions.blockUntilSolved) {
 88→            this._els.input.classList.add('invalid');
 89→            setTimeout(() => this._els.input.classList.remove('invalid'), 600);
 90→
 91→            // Show toast if enabled (default: true)
 92→            const showToast = this.instanceOptions.showErrorToast ?? this.config.showErrorToast ?? true;
 93→            if (showToast && this.engine?.toast) {
 94→                const msg = this.t(
 95→                    this.config.errorMessage || '@engine.puzzle.incorrect@Puzzle není správně vyřešen.',
 96→                    'Puzzle není správně vyřešen.'
 97→                );
 98→                this.engine.toast(msg, 2500);
 99→            }
100→
101→            return {hold: true};
102→        }
103→
104→        return {ok, detail: {value: v}};
105→    }
106→}

