 66→        const target = this.config.solution || this.config.solutions || '';
 67→        const typed = normalizeText(val);
 68→        const pool = Array.isArray(target) ? target : [target];
 69→
 70→        const result = pool.some(s => {
 71→            const resolved = this.t(s, s);
 72→            return normalizeText(resolved) === typed;
 73→        });
 74→
 75→        if (DBG()) {
 76→            console.debug('[PZ.code] validation:', {
 77→                typed,
 78→                solutions: pool.map(s => normalizeText(this.t(s, s))),
 79→                result
 80→            });
 81→        }
 82→
 83→        return result;
 84→    }
 85→
 86→    onOk() {
 87→        if (this._locked) return {hold: true};
 88→
 89→        const v = this._els.input?.value || '';
 90→        const ok = this._isCorrect(v);
 91→
 92→        if (!ok) {
 93→            // Code: always show strong fail feedback
 94→            this._els.input.classList.add('invalid');
 95→            setTimeout(() => this._els.input.classList.remove('invalid'), 700);
 96→        }
 97→
 98→        if (!ok && this.instanceOptions.blockUntilSolved) {
 99→            return {hold: true};
100→        }
101→
102→        return {ok, detail: {value: v}};
103→    }
104→}
