  1→// engine/puzzles/kinds/quiz.js
  2→// Kind: quiz – selectable tokens (text/image), single/multi-select, auto coloring
  3→
  4→import {BasePuzzle} from '../base.js';
  5→
  6→const DBG = () => (typeof window !== 'undefined' && /\bdebug=1\b/.test(window.location.search));
  7→
  8→export default class QuizPuzzle extends BasePuzzle {
  9→    constructor(args) {
 10→        super(args);
 11→        this._tokenEls = new Map();
 12→        this._selected = new Set();
 13→        this._locked = false;
 14→    }
 15→
 16→    mount(container, workRect, backgroundUrl) {
 17→        super.mount?.(container, workRect, backgroundUrl);
 18→        const flow = this.flowEl;
 19→        this.root?.classList.add('pz-kind-quiz');
 20→
 21→        // Token area (auto layout respects config)
 22→        const area = this.createTokenArea();
 23→
 24→        // For horizontal layout, ensure wrapping
 25→        const layoutCfg = this.instanceOptions.layout || this.config.layout || {};
 26→        if (layoutCfg.direction === 'horizontal') {
 27→            Object.assign(area.style, {
 28→                display: 'flex',
 29→                flexDirection: 'row',
 30→                flexWrap: 'wrap', // IMPORTANT: wrap to next line
 31→                gap: 'var(--pz-token-gap)',
 32→                width: '100%'
 33→            });
 34→        }
 35→
 36→        // Build tokens using base factory
 37→        const tokens = this.config.tokens || [];
 38→        tokens.forEach((t, idx) => {
 39→            const id = String(t.id ?? idx);
 40→            const el = this.createToken(t);
 41→            el.addEventListener('click', () => this._toggleSelect(id));
 42→
 43→            area.appendChild(el);
 44→            this._tokenEls.set(id, el);
 45→        });
 46→
 47→        // Insert area BEFORE footer
 48→        const footer = flow.querySelector('.pz-footer');
 49→        if (footer) {
 50→            flow.insertBefore(area, footer);
 51→        } else {
 52→            flow.appendChild(area);
 53→        }
 54→
 55→        if (DBG()) {
 56→            console.debug('[PZ.quiz] mounted', {
 57→                tokenCount: tokens.length,
 58→                multiSelect: this.instanceOptions.multiSelect,
 59→                direction: layoutCfg.direction
 60→            });
 61→        }
 62→    }
 63→
 64→    _toggleSelect(id) {
 65→        if (this._locked) return;
 66→
 67→        const multi = !!(this.instanceOptions.multiSelect || this.config.multiSelect);
 68→
 69→        if (!multi) {
 70→            // Single select: clear all others
 71→            this._clearSelection();
 72→        }
 73→
 74→        const el = this._tokenEls.get(id);
 75→        if (!el) return;
 76→
 77→        if (this._selected.has(id)) {
 78→            this._selected.delete(id);
 79→            el.classList.remove('selected', 'is-selected');
 80→        } else {
 81→            this._selected.add(id);
 82→            el.classList.add('selected', 'is-selected');
 83→        }
 84→
 85→        if (DBG()) {
 86→            console.debug('[PZ.quiz] toggle:', {id, selected: Array.from(this._selected)});
 87→        }
 88→    }
 89→
 90→    _clearSelection() {
 91→        for (const id of Array.from(this._selected)) {
 92→            this._tokenEls.get(id)?.classList.remove('selected', 'is-selected');
 93→        }
 94→        this._selected.clear();
 95→    }
 96→
 97→    _solutionIds() {
 98→        // Prefer explicit solutionIds, fallback to tokens[].correct === true
 99→        if (Array.isArray(this.config.solutionIds) && this.config.solutionIds.length) {
100→            return this.toIdSet(this.config.solutionIds);
101→        }
102→        if (Array.isArray(this.config.solutions) && this.config.solutions.length) {
103→            return this.toIdSet(this.config.solutions);
104→        }
105→
106→        const s = new Set();
107→        (this.config.tokens || []).forEach((t, idx) => {
108→            const id = String(t.id ?? idx);
109→            if (t.correct) s.add(id);
110→        });
111→        return s;
112→    }
113→
114→    _markCorrectness(showHints = false) {
115→        const sol = this._solutionIds();
116→
117→        for (const [id, el] of this._tokenEls.entries()) {
118→            el.classList.remove('correct', 'wrong', 'hint', 'is-correct', 'is-wrong', 'is-hint');
119→
120→            const isSel = this._selected.has(id);
121→            const isOk = sol.has(id);
122→
123→            if (isSel && isOk) {
124→                el.classList.add('correct', 'is-correct');
125→            } else if (isSel && !isOk) {
126→                el.classList.add('wrong', 'is-wrong');
127→            } else if (!isSel && isOk && showHints) {
128→                el.classList.add('hint', 'is-hint');
129→            }
130→        }
131→
132→        if (DBG()) {
133→            console.debug('[PZ.quiz] marked correctness:', {
134→                selected: Array.from(this._selected),
135→                solution: Array.from(sol),
136→                showHints
137→            });
138→        }
139→    }
140→
141→    onOk() {
142→        if (this._locked) return {hold: true};
143→
144→        const sol = this._solutionIds();
145→        const sel = this.toIdSet(Array.from(this._selected));
146→        const ok = (sel.size === sol.size) && [...sel].every(x => sol.has(x));
147→
148→        const aggregateOnly = !!this.instanceOptions.aggregateOnly;
149→
150→        if (!aggregateOnly) {
151→            // Show visual feedback
152→            this._markCorrectness(true);
153→        }
154→
155→        if (!ok && this.instanceOptions.blockUntilSolved) {
156→            // Add shake animation to wrong selections
157→            for (const [id, el] of this._tokenEls.entries()) {
158→                if (this._selected.has(id) && !sol.has(id)) {
159→                    el.classList.add('invalid');
160→                    setTimeout(() => el.classList.remove('invalid'), 600);
161→                }
162→            }
163→
164→            // Show toast if enabled (default: true)
165→            const showToast = this.instanceOptions.showErrorToast ?? this.config.showErrorToast ?? true;
166→            if (showToast && this.engine?.toast) {
167→                const msg = this.t(
168→                    this.config.errorMessage || '@engine.puzzle.incorrect@Puzzle není správně vyřešen.',
169→                    'Puzzle není správně vyřešen.'
170→                );
171→                this.engine.toast(msg, 2500);
172→            }
173→
174→            // Keep open; optional reset
175→            if (this.instanceOptions.resetOnFail !== false) {
176→                setTimeout(() => {
177→                    this._clearSelection();
178→                    this._markCorrectness(false);
179→                }, 300);
180→            }
181→            return {hold: true};
182→        }
183→
184→        if (DBG()) {
185→            console.debug('[PZ.quiz] onOk result:', {ok, selected: Array.from(sel), solution: Array.from(sol)});
186→        }
187→
188→        return {
189→            ok,
190→            detail: {
191→                selectedIds: Array.from(sel),
192→                solutionIds: Array.from(sol)
193→            }
194→        };
195→    }
196→}
