  1→// engine/puzzles/kinds/order.js
  2→// Kind: order â€“ click tokens to move from shuffled â†’ ordered; verify final sequence
  3→
  4→import {BasePuzzle} from '../base.js';
  5→
  6→const DBG = () => (typeof window !== 'undefined' && /\bdebug=1\b/.test(window.location.search));
  7→
  8→export default class OrderPuzzle extends BasePuzzle {
  9→    constructor(args) {
 10→        super(args);
 11→        this._tokenEls = new Map();
 12→        this._ordered = [];
 13→        this._shuffledIds = [];
 14→    }
 15→
 16→    mount(container, workRect, backgroundUrl) {
 17→        super.mount?.(container, workRect, backgroundUrl);
 18→        const flow = this.flowEl;
 19→        this.root?.classList.add('pz-kind-order');
 20→
 21→        // Container for two areas: shuffled + ordered
 22→        const container2 = document.createElement('div');
 23→        container2.className = 'pz-order-container';
 24→
 25→        const layoutCfg = this.instanceOptions.layout || this.config.layout || {};
 26→        const dir = layoutCfg.direction || 'vertical';
 27→
 28→        // Grid layout: vertical = 2 columns, horizontal = 2 rows
 29→        Object.assign(container2.style, {
 30→            flex: '1 1 auto',
 31→            display: 'grid',
 32→            gap: 'var(--pz-token-gap)',
 33→            gridTemplateColumns: dir === 'horizontal' ? '1fr' : '1fr 1fr',
 34→            gridTemplateRows: dir === 'horizontal' ? '1fr 1fr' : '1fr'
 35→        });
 36→
 37→        // Shuffled area
 38→        const shuffledArea = document.createElement('div');
 39→        shuffledArea.className = 'pz-area pz-area-shuffled';
 40→        Object.assign(shuffledArea.style, {
 41→            display: 'flex',
 42→            flexDirection: dir === 'horizontal' ? 'row' : 'column',
 43→            flexWrap: dir === 'horizontal' ? 'wrap' : 'nowrap',
 44→            justifyContent: dir === 'horizontal' ? 'center' : 'flex-start',
 45→            alignItems: dir === 'horizontal' ? 'center' : 'stretch',
 46→            gap: 'var(--pz-token-gap)',
 47→            padding: '1vh 1vw',
 48→            border: '1px solid rgba(255, 255, 255, 0.15)',
 49→            borderRadius: 'var(--pz-token-radius)',
 50→            background: 'rgba(255, 255, 255, 0.03)',
 51→            backdropFilter: 'blur(2px)'
 52→        });
 53→
 54→        // Ordered area
 55→        const orderedArea = document.createElement('div');
 56→        orderedArea.className = 'pz-area pz-area-ordered';
 57→        Object.assign(orderedArea.style, {
 58→            display: 'flex',
 59→            flexDirection: dir === 'horizontal' ? 'row' : 'column',
 60→            flexWrap: dir === 'horizontal' ? 'wrap' : 'nowrap',
 61→            justifyContent: dir === 'horizontal' ? 'center' : 'flex-start',
 62→            alignItems: dir === 'horizontal' ? 'center' : 'stretch',
 63→            gap: 'var(--pz-token-gap)',
 64→            padding: '1vh 1vw',
 65→            border: '1px solid rgba(255, 255, 255, 0.15)',
 66→            borderRadius: 'var(--pz-token-radius)',
 67→            background: 'rgba(255, 255, 255, 0.03)',
 68→            backdropFilter: 'blur(2px)'
 69→        });
 70→
 71→        container2.appendChild(shuffledArea);
 72→        container2.appendChild(orderedArea);
 73→
 74→        // Create and shuffle tokens
 75→        const tokens = (this.config.tokens || []).map((t, idx) => ({
 76→            id: String(t.id ?? idx),
 77→            ...t
 78→        }));
 79→
 80→        this._shuffledIds = this._shuffle(tokens.map(t => t.id));
 81→
 82→        this._shuffledIds.forEach(id => {
 83→            const token = tokens.find(t => t.id === id);
 84→            if (!token) return;
 85→
 86→            const el = this.createToken(token);
 87→            el.addEventListener('click', () => this._togglePlacement(id));
 88→
 89→            shuffledArea.appendChild(el);
 90→            this._tokenEls.set(id, el);
 91→        });
 92→
 93→        this._shuffledArea = shuffledArea;
 94→        this._orderedArea = orderedArea;
 95→
 96→        // Insert container BEFORE footer
 97→        const footer = flow.querySelector('.pz-footer');
 98→        if (footer) {
 99→            flow.insertBefore(container2, footer);
100→        } else {
101→            flow.appendChild(container2);
102→        }
103→
104→        if (DBG()) {
105→            console.debug('[PZ.order] mounted', {
106→                tokenCount: tokens.length,
107→                shuffled: this._shuffledIds,
108→                direction: dir
109→            });
110→        }
111→    }
112→
113→    _togglePlacement(id) {
114→        const inOrdered = this._ordered.includes(id);
115→        const el = this._tokenEls.get(id);
116→        if (!el) return;
117→
118→        if (inOrdered) {
119→            // Move back to shuffled
120→            this._ordered = this._ordered.filter(x => x !== id);
121→            this._shuffledArea.appendChild(el);
122→        } else {
123→            // Move to ordered (append at end)
124→            this._ordered.push(id);
125→            this._orderedArea.appendChild(el);
126→        }
127→
128→        this._clearMarks();
129→
130→        if (DBG()) {
131→            console.debug('[PZ.order] toggle:', {id, ordered: this._ordered});
132→        }
133→    }
134→
135→    _solution() {
136→        // Prefer explicit array
137→        if (Array.isArray(this.config.solution)) {
138→            return this.config.solution.map(String);
139→        }
140→        if (Array.isArray(this.config.solutionIds)) {
141→            return this.config.solutionIds.map(String);
142→        }
143→        // Fallback: order equals tokens order in config
144→        return (this.config.tokens || []).map((t, idx) => String(t.id ?? idx));
145→    }
146→
147→    _markCorrectness(showHints = false) {
148→        const want = this._solution();
149→        const got = this._ordered;
150→        const n = Math.max(want.length, got.length);
151→
152→        for (let i = 0; i < n; i++) {
153→            const id = got[i];
154→            const el = id ? this._tokenEls.get(id) : null;
155→            if (!el) continue;
156→
157→            el.classList.remove('correct', 'wrong', 'hint', 'is-correct', 'is-wrong', 'is-hint');
158→
159→            if (want[i] === id) {
160→                el.classList.add('correct', 'is-correct');
161→            } else {
162→                el.classList.add('wrong', 'is-wrong');
163→            }
164→        }
165→
166→        if (showHints) {
167→            // Tokens not placed but needed â†’ gentle hint
168→            const missing = new Set(want.filter(id => !got.includes(id)));
169→            for (const id of missing) {
170→                const el = this._tokenEls.get(id);
171→                if (el) el.classList.add('hint', 'is-hint');
172→            }
173→        }
174→
175→        if (DBG()) {
176→            console.debug('[PZ.order] marked correctness:', {got, want, showHints});
177→        }
178→    }
179→
180→    _clearMarks() {
181→        for (const el of this._tokenEls.values()) {
182→            el.classList.remove('correct', 'wrong', 'hint', 'is-correct', 'is-wrong', 'is-hint');
183→        }
184→    }
185→
186→    onOk() {
187→        const want = this._solution();
188→        const ok = (want.length === this._ordered.length) &&
189→            want.every((id, i) => this._ordered[i] === id);
190→
191→        if (!this.instanceOptions.aggregateOnly) {
192→            this._markCorrectness(true);
193→        }
194→
195→        if (!ok && this.instanceOptions.blockUntilSolved) {
196→            return {hold: true};
197→        }
198→
199→        if (DBG()) {
200→            console.debug('[PZ.order] onOk result:', {ok, ordered: this._ordered, solution: want});
201→        }
202→
203→        return {
204→            ok,
205→            detail: {
206→                orderedIds: [...this._ordered],
207→                solution: want
208→            }
209→        };
210→    }
211→
212→    _shuffle(arr) {
213→        const a = arr.slice();
214→        for (let i = a.length - 1; i > 0; i--) {
215→            const j = Math.floor(Math.random() * (i + 1));
216→            [a[i], a[j]] = [a[j], a[i]];
217→        }
218→        return a;
219→    }
220→}

  1→// engine/puzzles/kinds/match.js
  2→// Kind: match – pair matching (columns click mode or dragdrop mode)
  3→
  4→import {BasePuzzle} from '../base.js';
  5→
  6→const DBG = () => (typeof window !== 'undefined' && /\bdebug=1\b/.test(window.location.search));
  7→
  8→/**
  9→ * Pair color palette - Intelligent selection
 10→ * REMOVED: Reds (confusion with error), Light Blues (confusion with selection)
 11→ * KEPT: Distinct, vibrant colors visible on dark backgrounds
 12→ */
 13→const PAIR_COLORS = [
 14→    'rgba(155, 89, 182, 0.35)',  // Amethyst (Purple) - distinct from blue
 15→    'rgba(26, 188, 156, 0.35)',  // Turquoise/Teal - distinct from selection blue
 16→    'rgba(230, 126, 34, 0.35)',  // Carrot (Orange)
 17→    'rgba(241, 196, 15, 0.35)',  // Moon Yellow (Gold)
 18→    'rgba(219, 10, 172, 0.35)',  // Magenta/Deep Pink
 19→    'rgba(46, 204, 113, 0.35)',  // Emerald (Green) - distinct from error red
 20→    'rgba(52, 73, 94, 0.50)',    // Wet Asphalt (Dark Grey-Blue)
 21→    'rgba(166, 219, 10, 0.35)',  // Lime
 22→    'rgba(139, 69, 19, 0.40)',   // Saddle Brown
 23→    'rgba(0, 128, 128, 0.35)',   // Teal
 24→    'rgba(128, 0, 128, 0.35)',   // Purple
 25→    'rgba(255, 20, 147, 0.35)'   // Deep Pink
 26→];
 27→
 28→export default class MatchPuzzle extends BasePuzzle {
 29→    constructor(args) {
 30→        super(args);
 31→        this._tokenEls = new Map();
 32→        this._tokenSides = new Map(); // Track which side each token belongs to
 33→        this._pairs = new Map(); // tokenId -> pairedTokenId
 34→        this._selectedForPair = null; // first token of pair in click mode
 35→        this._mode = (args.config?.mode || 'columns').toLowerCase();
 36→        this._connectionLines = new Map(); // Store SVG connection elements for columns mode
 37→        this._svgContainer = null; // SVG overlay for connection lines
 38→        this._isUpdatingLines = false; // Prevent ResizeObserver infinite loop
 39→        this._resizeTimeout = null; // Debounce resize updates
 40→    }
 41→
 42→    /**
 43→     * Override createToken to fix Image paths and layout
 44→     */
 45→    createToken(data) {
 46→        // 1. Let BasePuzzle create the structure (button > img + span)
 47→        const el = super.createToken(data);
 48→
 49→        // 2. FIX IMAGE PATH: BasePuzzle doesn't resolve assets, we must do it here.
 50→        if (data.image) {
 51→            let img = el.querySelector('.pz-token-image');
 52→
 53→            // Resolve path relative to game root
 54→            const src = this.engine && this.engine._resolveAsset
 55→                ? this.engine._resolveAsset(data.image)
 56→                : data.image;
 57→
 58→            if (img) {
 59→                // Update existing image source created by BasePuzzle
 60→                img.src = src;
 61→            } else {
 62→                // Fallback if BasePuzzle logic changes
 63→                img = document.createElement('img');
 64→                img.src = src;
 65→                img.className = 'pz-token-image';
 66→                img.draggable = false;
 67→                el.prepend(img);
 68→            }
 69→            el.classList.add('has-image');
 70→        }
 71→
 72→        return el;
 73→    }
 74→
 75→    /**
 76→     * Get pair color by index with fallback to random color
 77→     * @param {number} pairIndex - Index of the pair (0-based)
 78→     * @returns {string} RGBA color string
 79→     */
 80→    _getPairColor(pairIndex) {
 81→        if (pairIndex < PAIR_COLORS.length) {
 82→            return PAIR_COLORS[pairIndex];
 83→        }
 84→
 85→        // Fallback: generate random vibrant color (avoiding reds/blues)
 86→        // High Green/Red mix (Yellows/Oranges) or High Red/Blue mix (Purples)
 87→        const r = 50 + Math.floor(Math.random() * 150);
 88→        const g = 100 + Math.floor(Math.random() * 155);
 89→        const b = 50 + Math.floor(Math.random() * 100); // Keep blue low to avoid selection confusion
 90→        return `rgba(${r}, ${g}, ${b}, 0.35)`;
 91→    }
 92→
 93→    /**
 94→     * Finds the lowest available color index not currently used on the board.
 95→     * Prevents color collisions when pairs are removed and new ones added.
 96→     */
 97→    _getNextAvailableColorIndex() {
 98→        const usedIndices = new Set();
 99→
100→        // Scan all tokens to see which indices are currently active
101→        this._tokenEls.forEach(el => {
102→            if (el.dataset.pairIndex !== undefined) {
103→                usedIndices.add(parseInt(el.dataset.pairIndex, 10));
104→            }
105→        });
106→
107→        // Find first gap (0, 1, 2...)
108→        let idx = 0;
109→        while (usedIndices.has(idx)) {
110→            idx++;
111→        }
112→        return idx;
113→    }
114→
115→    /**
116→     * Create SVG overlay for connection lines (columns mode only)
117→     * @param {HTMLElement} container - Parent container element
118→     */
119→    _createSvgContainer(container) {
120→        if (this._svgContainer) return this._svgContainer;
121→
122→        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
123→        svg.setAttribute('class', 'pz-match-connections');
124→        svg.style.cssText = `
125→            position: absolute;
126→            top: 0;
127→            left: 0;
128→            width: 100%;
129→            height: 100%;
130→            pointer-events: none;
131→            z-index: 1;
132→        `;
133→
134→        // Insert SVG before columns (so lines appear behind tokens)
135→        const columnsEl = container.querySelector('.pz-match-columns');
136→        if (columnsEl) {
137→            container.insertBefore(svg, columnsEl);
138→        } else {
139→            container.appendChild(svg);
140→        }
141→
142→        this._svgContainer = svg;
143→        return svg;
144→    }
145→
146→    /**
147→     * Draw connection line between two tokens
148→     * @param {string} id1 - First token ID
149→     * @param {string} id2 - Second token ID
150→     * @param {string} color - Line color
151→     * @param {number} pairIndex - Pair index for tracking
152→     */
153→    _drawConnectionLine(id1, id2, color, pairIndex) {
154→        if (this._mode !== 'columns') return;
155→
156→        const el1 = this._tokenEls.get(id1);
157→        const el2 = this._tokenEls.get(id2);
158→        if (!el1 || !el2 || !this._svgContainer) return;
159→
160→        // Get positions relative to SVG container
161→        const containerRect = this._svgContainer.parentElement.getBoundingClientRect();
162→        const rect1 = el1.getBoundingClientRect();
163→        const rect2 = el2.getBoundingClientRect();
164→
165→        // Calculate center points
166→        const x1 = rect1.left + rect1.width / 2 - containerRect.left;
167→        const y1 = rect1.top + rect1.height / 2 - containerRect.top;
168→        const x2 = rect2.left + rect2.width / 2 - containerRect.left;
169→        const y2 = rect2.top + rect2.height / 2 - containerRect.top;
170→
171→        // Create curved path (Bezier curve for better visual clarity)
172→        const midX = (x1 + x2) / 2;
173→        const controlOffset = Math.abs(x2 - x1) * 0.3; // Control point offset
174→
175→        const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
176→        const d = `M ${x1} ${y1} Q ${midX - controlOffset} ${y1}, ${midX} ${(y1 + y2) / 2} Q ${midX + controlOffset} ${y2}, ${x2} ${y2}`;
177→
178→        path.setAttribute('d', d);
179→        path.setAttribute('stroke', color);
180→        path.setAttribute('stroke-width', '3');
181→        path.setAttribute('fill', 'none');
182→        path.setAttribute('stroke-linecap', 'round');
