203→    /**
204→     * Remove connection line between tokens
205→     * @param {string} id1 - First token ID
206→     * @param {string} id2 - Second token ID
207→     */
208→    _removeConnectionLine(id1, id2) {
209→        const key1 = `${id1}-${id2}`;
210→        const key2 = `${id2}-${id1}`;
211→
212→        const line = this._connectionLines.get(key1) || this._connectionLines.get(key2);
213→        if (line) {
