226→    /**
227→     * Update all connection lines (useful when window resizes)
228→     * Uses debounce and recursion prevention to avoid infinite loops
229→     */
230→    _updateConnectionLines() {
231→        if (this._mode !== 'columns' || !this._svgContainer) return;
232→        if (this._isUpdatingLines) return; // Prevent recursion
233→
234→        this._isUpdatingLines = true;
235→
236→        // Use requestAnimationFrame to batch updates
237→        requestAnimationFrame(() => {
238→            this._connectionLines.forEach((line, key) => {
239→                const id1 = line.getAttribute('data-id1');
240→                const id2 = line.getAttribute('data-id2');
241→                const color = line.getAttribute('stroke');
242→                const pairIndex = parseInt(line.getAttribute('data-pair-index'), 10);
243→
244→                // Remove old line
245→                line.remove();
246→                this._connectionLines.delete(key);
247→
248→                // Redraw with current positions
249→                this._drawConnectionLine(id1, id2, color, pairIndex);
250→            });
251→
252→            // Reset flag after updates complete
253→            this._isUpdatingLines = false;
254→        });
255→    }
