447→    _generateScatteredPositions(count) {
448→        if (count === 0) return [];
449→        const cols = Math.ceil(Math.sqrt(count));
450→        const rows = Math.ceil(count / cols);
451→        const marginX = 12;
452→        const marginY = 12;
453→        const availableWidth = 100 - (2 * marginX);
454→        const availableHeight = 100 - (2 * marginY);
455→        const cellWidth = availableWidth / cols;
456→        const cellHeight = availableHeight / rows;
457→
458→        const positions = [];
459→        for (let i = 0; i < count; i++) {
460→            const col = i % cols;
461→            const row = Math.floor(i / cols);
462→            const centerX = marginX + (col + 0.5) * cellWidth;
463→            const centerY = marginY + (row + 0.5) * cellHeight;
464→            const offsetX = (Math.random() - 0.5) * cellWidth * 0.6;
465→            const offsetY = (Math.random() - 0.5) * cellHeight * 0.6;
466→
467→            positions.push({
468→                x: Math.max(marginX, Math.min(100 - marginX, centerX + offsetX)),
469→                y: Math.max(marginY, Math.min(100 - marginY, centerY + offsetY))
470→            });
471→        }
472→
473→        for (let i = positions.length - 1; i > 0; i--) {
474→            const j = Math.floor(Math.random() * (i + 1));
475→            [positions[i], positions[j]] = [positions[j], positions[i]];
476→        }
477→        return positions;
478→    }
