480→    _onClickToken(id) {
481→        const el = this._tokenEls.get(id);
482→        if (!el) return;
483→
484→        // CRITICAL FIX: Remove validation classes to allow re-selection after onOk
485→        el.classList.remove('correct', 'wrong', 'is-correct', 'is-wrong');
486→
487→        const currentPair = this._pairs.get(id);
488→        if (!currentPair) {
489→            // Only reset bg if not paired (paired tokens have permanent color)
490→            el.style.background = '';
491→            delete el.dataset.pairIndex;
492→        }
493→
494→        // 1. If already paired -> UNPAIR
495→        if (currentPair) {
496→            const otherEl = this._tokenEls.get(currentPair);
497→
498→            // Remove connection line (columns mode)
499→            if (this._mode === 'columns') {
500→                this._removeConnectionLine(id, currentPair);
501→            }
502→
503→            this._pairs.delete(id);
504→            this._pairs.delete(currentPair);
505→
506→            el.style.background = '';
507→            delete el.dataset.pairIndex;
508→            el.classList.remove('selected', 'is-selected');
509→            el.blur();
510→
511→            if (otherEl) {
512→                otherEl.style.background = '';
513→                delete otherEl.dataset.pairIndex;
514→                otherEl.classList.remove('correct', 'wrong', 'is-correct', 'is-wrong', 'selected', 'is-selected');
515→                otherEl.blur();
516→            }
517→
518→            if (DBG()) console.debug('[PZ.match] unpaired:', {id, was: currentPair});
519→            return;
520→        }
521→
522→        // 2. Select First Token
523→        if (!this._selectedForPair) {
524→            this._selectedForPair = id;
525→
526→            // FIX: Don't set background color yet! Just use CSS selection class.
527→            // This prevents the "colors looking like a pair" confusion.
528→            el.classList.add('selected', 'is-selected');
529→            el.blur();
530→
531→            if (DBG()) console.debug('[PZ.match] first selected (waiting for match):', id);
532→
533→            // 3. Deselect Self
534→        } else if (this._selectedForPair === id) {
535→            this._selectedForPair = null;
536→            el.classList.remove('selected', 'is-selected');
537→            el.style.background = '';
538→            el.blur();
539→
540→            if (DBG()) console.debug('[PZ.match] deselected:', id);
541→
542→            // 4. Form Pair
543→        } else {
544→            const first = this._selectedForPair;
545→            const firstSide = this._tokenSides.get(first);
546→            const secondSide = this._tokenSides.get(id);
547→
548→            // Constraint: Different sides only
549→            if (firstSide === secondSide) {
550→                // Switch selection to this new one
551→                const firstEl = this._tokenEls.get(first);
552→                if (firstEl) {
553→                    firstEl.classList.remove('selected', 'is-selected');
554→                    firstEl.style.background = '';
555→                }
556→
557→                this._selectedForPair = id;
558→                el.classList.add('selected', 'is-selected');
559→                el.blur();
560→
561→                if (DBG()) console.debug('[PZ.match] same side - reselecting:', {first, second: id});
562→                return;
563→            }
564→
565→            // Create Pair
566→            this._selectedForPair = null;
567→            this._pairs.set(first, id);
568→            this._pairs.set(id, first);
569→
570→            // FIX: Calculate unique color index to avoid collisions with existing pairs
571→            const pairIndex = this._getNextAvailableColorIndex();
572→            const pairColor = this._getPairColor(pairIndex);
573→
574→            const el1 = this._tokenEls.get(first);
575→            const el2 = this._tokenEls.get(id);
576→
577→            if (el1) {
578→                el1.classList.remove('selected', 'is-selected');
579→                el1.style.background = pairColor;
580→                el1.dataset.pairIndex = pairIndex; // Store index for collision check
581→                el1.blur();
582→            }
583→            if (el2) {
584→                el2.classList.remove('selected', 'is-selected');
585→                el2.style.background = pairColor;
586→                el2.dataset.pairIndex = pairIndex;
587→                el2.blur();
588→            }
589→
590→            // Draw connection line (columns mode only)
591→            if (this._mode === 'columns') {
592→                this._drawConnectionLine(first, id, pairColor, pairIndex);
593→            }
594→
595→            if (DBG()) console.debug('[PZ.match] paired:', {first, second: id, color: pairColor, index: pairIndex});
596→        }
597→    }
