599→    _enableDrag(id, el, board) {
600→        let dragging = false;
601→        let startX = 0, startY = 0;
602→        let offsetX = 0, offsetY = 0;
603→
604→        const onDown = (e) => {
605→            dragging = true;
606→            el.style.cursor = 'grabbing';
607→            el.style.zIndex = '10';
608→            el.classList.add('is-dragging');
609→
610→            const rect = board.getBoundingClientRect();
611→            const ev = e.touches ? e.touches[0] : e;
612→            startX = ev.clientX;
613→            startY = ev.clientY;
614→
615→            const leftPct = parseFloat(el.style.left) || 50;
616→            const topPct = parseFloat(el.style.top) || 50;
617→            offsetX = (leftPct / 100) * rect.width;
618→            offsetY = (topPct / 100) * rect.height;
619→
620→            e.preventDefault();
621→        };
622→
623→        const onMove = (e) => {
624→            if (!dragging) return;
625→
626→            const rect = board.getBoundingClientRect();
627→            const ev = e.touches ? e.touches[0] : e;
628→
629→            const dx = ev.clientX - startX;
630→            const dy = ev.clientY - startY;
631→
632→            const newX = Math.max(0, Math.min(rect.width, offsetX + dx));
633→            const newY = Math.max(0, Math.min(rect.height, offsetY + dy));
634→
635→            el.style.left = (newX / rect.width * 100) + '%';
636→            el.style.top = (newY / rect.height * 100) + '%';
637→
638→            e.preventDefault();
639→        };
640→
641→        const onUp = () => {
642→            if (!dragging) return;
643→            dragging = false;
644→            el.style.cursor = 'grab';
645→            el.style.zIndex = '5';
646→            el.classList.remove('is-dragging');
647→
648→            // CRITICAL: Unpair dragged token FIRST (before checking overlap)
649→            // This ensures token returns to side color even if dropped on empty space
650→                    const existingPairId = this._pairs.get(id);
651→                    if (existingPairId) {
652→                        const existingPairEl = this._tokenEls.get(existingPairId);
653→
654→                        this._pairs.delete(id);
655→                        this._pairs.delete(existingPairId);
656→
657→                // Reset dragged token styles (returns to side color via CSS)
658→                        el.style.background = '';
659→                        delete el.dataset.pairIndex;
660→                        el.classList.remove('correct', 'wrong', 'is-correct', 'is-wrong');
661→
662→                        // Reset old partner token styles (returns to side color via CSS)
663→                        if (existingPairEl) {
664→                            existingPairEl.style.background = '';
665→                            delete existingPairEl.dataset.pairIndex;
666→                            existingPairEl.classList.remove('correct', 'wrong', 'is-correct', 'is-wrong');
667→                        }
668→
669→                if (DBG()) console.debug('[PZ.match] drag unpaired (dropped):', {id, was: existingPairId});
670→            }
671→
672→            // Now check if token was dropped on another token to create new pair
673→            const rect1 = el.getBoundingClientRect();
674→            const cx = (rect1.left + rect1.right) / 2;
675→            const cy = (rect1.top + rect1.bottom) / 2;
676→
677→            for (const [otherId, otherEl] of this._tokenEls.entries()) {
678→                if (otherId === id) continue;
679→
680→                const rect2 = otherEl.getBoundingClientRect();
681→                if (cx >= rect2.left && cx <= rect2.right &&
682→                    cy >= rect2.top && cy <= rect2.bottom) {
683→
684→                    // If target token is already paired, unpair it first
685→                    const otherExistingPairId = this._pairs.get(otherId);
686→                    if (otherExistingPairId) {
687→                        const otherExistingPairEl = this._tokenEls.get(otherExistingPairId);
688→
689→                        this._pairs.delete(otherId);
690→                        this._pairs.delete(otherExistingPairId);
691→
692→                        // Reset target token styles (will be set to new pair color below)
693→                        otherEl.style.background = '';
694→                        delete otherEl.dataset.pairIndex;
695→                        otherEl.classList.remove('correct', 'wrong', 'is-correct', 'is-wrong');
696→
697→                        // Reset old partner token styles (returns to side color via CSS)
698→                        if (otherExistingPairEl) {
699→                            otherExistingPairEl.style.background = '';
700→                            delete otherExistingPairEl.dataset.pairIndex;
701→                            otherExistingPairEl.classList.remove('correct', 'wrong', 'is-correct', 'is-wrong');
702→                        }
703→
704→                        if (DBG()) console.debug('[PZ.match] drag unpaired target old pair:', {otherId, was: otherExistingPairId});
705→                    }
706→
707→                    // Create new pair
708→                    this._pairs.set(id, otherId);
709→                    this._pairs.set(otherId, id);
710→
711→                    const idx = this._getNextAvailableColorIndex();
712→                    const pairColor = this._getPairColor(idx);
713→
714→                    el.style.background = pairColor;
715→                    el.dataset.pairIndex = idx;
716→
717→                    otherEl.style.background = pairColor;
718→                    otherEl.dataset.pairIndex = idx;
719→
720→                    if (DBG()) console.debug('[PZ.match] drag paired:', {id, otherId});
721→                    break;
722→                }
723→            }
724→
725→            // If no overlap was found, token remains unpaired with side color (CSS applies automatically)
726→        };
