728→        el.addEventListener('mousedown', onDown);
729→        el.addEventListener('touchstart', onDown, {passive: false});
730→        document.addEventListener('mousemove', onMove);
731→        document.addEventListener('touchmove', onMove, {passive: false});
732→        document.addEventListener('mouseup', onUp);
733→        document.addEventListener('touchend', onUp);
