746→    onOk() {
747→        const sol = this._solutionPairs();
748→        let allOk = true;
749→
750→        const wrongTokens = [];
751→        const wrongAll = [];
752→
753→        for (const [id, el] of this._tokenEls.entries()) {
754→            const pairedWith = this._pairs.get(id);
755→            const expectedPair = sol.get(id);
756→            const good = (pairedWith === expectedPair);
757→
758→            if (!this.instanceOptions.aggregateOnly) {
759→                el.classList.remove('correct', 'wrong', 'is-correct', 'is-wrong');
760→
761→                if (good && pairedWith) {
762→                    el.classList.add('correct', 'is-correct');
763→                } else if (!good) {
764→                    el.classList.add('wrong', 'is-wrong');
765→                    // Reset pair color visually so red is clearly visible
766→                    el.style.background = '';
767→                    wrongAll.push(id);
768→                    if (pairedWith) {
769→                        wrongTokens.push(id);
770→                    }
771→                }
772→            }
773→            if (!good) allOk = false;
774→        }
775→
776→        if (!allOk && this.instanceOptions.blockUntilSolved) {
777→            if (wrongTokens.length > 0 || wrongAll.length > 0) {
778→                setTimeout(() => {
779→                    const alreadyReset = new Set();
780→                    for (const id of wrongTokens) {
781→                        if (alreadyReset.has(id)) continue;
782→
783→                        const el = this._tokenEls.get(id);
784→                        const pairedWith = this._pairs.get(id);
785→                        if (!pairedWith || !el) continue;
786→
787→                        const otherEl = this._tokenEls.get(pairedWith);
788→
789→                        // Remove connection line (columns mode)
790→                        if (this._mode === 'columns') {
791→                            this._removeConnectionLine(id, pairedWith);
792→                        }
793→
794→                        this._pairs.delete(id);
795→                        this._pairs.delete(pairedWith);
796→
797→                        // Clear styles
798→                        el.classList.remove('wrong', 'is-wrong', 'selected', 'is-selected');
799→                        el.style.background = '';
800→                        delete el.dataset.pairIndex; // Free up the color index!
801→
802→                        if (otherEl) {
803→                            otherEl.classList.remove('wrong', 'is-wrong', 'selected', 'is-selected');
804→                            otherEl.style.background = '';
805→                            delete otherEl.dataset.pairIndex;
806→                        }
807→
808→                        alreadyReset.add(id);
809→                        alreadyReset.add(pairedWith);
810→                    }
811→
812→                    // Clear remaining red flashes
813→                    for (const [tid, tel] of this._tokenEls.entries()) {
814→                        if (tel && tel.classList.contains('is-wrong')) {
815→                            tel.classList.remove('wrong', 'is-wrong');
816→                            // Only reset bg if it wasn't a correct pair that somehow got flagged
817→                            // (logic above ensures strictly pairs logic)
818→                            if (!this._pairs.has(tid)) {
819→                                tel.style.background = '';
820→                                delete tel.dataset.pairIndex;
821→                            }
822→                        }
823→                    }
824→                }, 800);
825→            }
826→            return {hold: true};
827→        }
828→
829→        const detail = {};
830→        for (const [id, pairedWith] of this._pairs.entries()) {
831→            detail[id] = pairedWith;
832→        }
833→
834→        return {ok: allOk, detail: {pairs: detail}};
835→    }
836→
837→    /**
838→     * Cleanup when puzzle is unmounted
839→     */
840→    unmount() {
841→        // Disconnect ResizeObserver
842→        if (this._resizeObserver) {
843→            this._resizeObserver.disconnect();
844→            this._resizeObserver = null;
845→        }
846→
847→        // Clear resize timeout
848→        if (this._resizeTimeout) {
849→            clearTimeout(this._resizeTimeout);
850→            this._resizeTimeout = null;
851→        }
852→
853→        // Clear connection lines
854→        this._connectionLines.clear();
855→
856→        // Call parent unmount
857→        super.unmount?.();
858→    }
859→}

  1→// engine/puzzles/kinds/group.js
  2→// Kind: group â€“ drag tokens into correct group areas (grid/manual layout)
  3→
  4→import {BasePuzzle} from '../base.js';
  5→
  6→const DBG = () => (typeof window !== 'undefined' && /\bdebug=1\b/.test(window.location.search));
  7→
  8→export default class GroupPuzzle extends BasePuzzle {
  9→    constructor(args) {
 10→        super(args);
 11→        this._tokenEls = new Map();
 12→        this._tokenInit = new Map(); // id -> {left, top, transform} for reset
 13→        this._inGroup = new Map();   // id -> groupId
 14→        this._groupAreas = new Map(); // groupId -> DOM element
 15→    }
 16→
 17→    mount(container, workRect, backgroundUrl) {
 18→        super.mount?.(container, workRect, backgroundUrl);
 19→        const flow = this.flowEl;
 20→        this.root?.classList.add('pz-kind-group');
 21→
 22→        // Board container for groups + tokens
 23→        const board = document.createElement('div');
 24→        board.className = 'pz-group-board';
 25→        Object.assign(board.style, {
 26→            flex: '1 1 auto',
 27→            position: 'relative',
 28→            minHeight: '220px',
 29→            borderRadius: 'var(--pz-token-radius)'
 30→        });
 31→
 32→        const layoutCfg = this.instanceOptions.layout || this.config.layout || {};
 33→        const mode = layoutCfg.mode || 'auto';
 34→
 35→        // Create group areas
 36→        if (mode === 'manual') {
 37→            // Manual positioning
 38→            (this.config.groups || []).forEach(g => {
 39→                const el = this._makeGroupArea(g);
 40→                Object.assign(el.style, {
 41→                    position: 'absolute',
 42→                    left: (g.rect?.x ?? 0) + '%',
 43→                    top: (g.rect?.y ?? 0) + '%',
 44→                    width: (g.rect?.w ?? 0) + '%',
 45→                    height: (g.rect?.h ?? 0) + '%'
 46→                });
 47→                board.appendChild(el);
 48→            });
 49→        } else {
 50→            // Auto grid layout with dynamic calculation
 51→            const dir = layoutCfg.direction || 'vertical';
 52→            const groupCount = (this.config.groups || []).length;
 53→
 54→            // Calculate optimal grid dimensions
 55→            const {cols, rows} = this._calculateGridDimensions(groupCount, dir);
 56→
 57→            const gap = layoutCfg.gap || '10px';
 58→
 59→            Object.assign(board.style, {
 60→                display: 'grid',
 61→                gridTemplateColumns: `repeat(${cols}, 1fr)`,
 62→                gridTemplateRows: `repeat(${rows}, 1fr)`,
 63→                gap: gap,
 64→                // Center the entire grid in the board
 65→                placeContent: 'center',
 66→                // Horizontal: fill rows first (default), Vertical: fill columns first
 67→                gridAutoFlow: dir === 'horizontal' ? 'row' : 'column'
 68→            });
 69→
 70→            (this.config.groups || []).forEach(g => {
 71→                const el = this._makeGroupArea(g);
 72→                board.appendChild(el);
 73→            });
 74→        }
 75→
 76→        // Create draggable tokens (start at center)
 77→        (this.config.tokens || []).forEach((t, i) => {
 78→            const id = String(t.id ?? i);
 79→            const el = this.createToken(t);
 80→
 81→            Object.assign(el.style, {
 82→                position: 'absolute',
 83→                left: '50%',
 84→                top: '50%',
 85→                transform: 'translate(-50%, -50%)',
 86→                cursor: 'grab',
 87→                zIndex: '5'
 88→            });
 89→
 90→            board.appendChild(el);
 91→            this._tokenEls.set(id, el);
 92→            this._tokenInit.set(id, {
 93→                left: el.style.left,
 94→                top: el.style.top,
 95→                transform: el.style.transform
 96→            });
 97→
 98→            this._enableDrag(id, el, board);
 99→        });
100→
101→        // Insert board BEFORE footer
102→        const footer = flow.querySelector('.pz-footer');
103→        if (footer) {
104→            flow.insertBefore(board, footer);
105→        } else {
106→            flow.appendChild(board);
107→        }
108→
109→        if (DBG()) {
110→            console.debug('[PZ.group] mounted', {
111→                groupCount: this.config.groups?.length || 0,
112→                tokenCount: this.config.tokens?.length || 0,
113→                mode
114→            });
115→        }
116→    }
117→
118→    _makeGroupArea(group) {
119→        const el = document.createElement('div');
120→        el.className = 'pz-group-area';
121→        el.setAttribute('data-group', String(group.id));
122→
123→        Object.assign(el.style, {
124→            border: '1px solid rgba(255, 255, 255, 0.25)',
125→            borderRadius: 'var(--pz-token-radius)',
126→            display: 'flex',
127→            alignItems: 'center',
128→            justifyContent: 'center',
129→            background: group.style?.bg || 'rgba(255, 255, 255, 0.04)',
130→            backdropFilter: 'blur(2px)',
131→            position: 'relative'
132→        });
133→
134→        const label = document.createElement('div');
135→        label.className = 'pz-group-label';
136→        label.textContent = this.t(group.label || '', '');
137→
138→        // Position label at top center, above tokens
139→        Object.assign(label.style, {
140→            position: 'absolute',
141→            top: '8px',
142→            left: '50%',
143→            transform: 'translateX(-50%)',
144→            fontWeight: '600',
145→            opacity: '0.7',
146→            pointerEvents: 'none', // Don't interfere with token drag
147→            zIndex: '1',
148→            whiteSpace: 'nowrap'
149→        });
150→
151→        el.appendChild(label);
152→
153→        this._groupAreas.set(String(group.id), el);
154→        return el;
155→    }
156→
157→    /**
158→     * Calculate optimal grid dimensions based on group count and direction.
159→     * Ensures groups are centered and well-distributed.
160→     */
161→    _calculateGridDimensions(count, direction) {
162→        if (count <= 0) return {cols: 1, rows: 1};
163→
164→        if (direction === 'vertical') {
165→            // Vertical: prefer filling columns first (groups side by side)
166→            // 1-3 groups → single row
167→            // 4+ groups → try to make roughly square grid
168→            if (count <= 3) {
169→                return {cols: count, rows: 1};
170→            }
171→            // For 4+: calculate optimal columns (roughly sqrt, prefer more columns than rows)
172→            const cols = Math.ceil(Math.sqrt(count));
173→            const rows = Math.ceil(count / cols);
174→            return {cols, rows};
175→        } else {
176→            // Horizontal: prefer filling rows first (groups stacked vertically)
177→            // 1-3 groups → single column
178→            // 4+ groups → try to make roughly square grid
179→            if (count <= 3) {
180→                return {cols: 1, rows: count};
181→            }
182→            // For 4+: calculate optimal rows (roughly sqrt, prefer more rows than columns)
183→            const rows = Math.ceil(Math.sqrt(count));
184→            const cols = Math.ceil(count / rows);
185→            return {cols, rows};
186→        }
187→    }
188→
189→    _enableDrag(id, el, board) {
190→        let dragging = false;
191→        let startX = 0, startY = 0;
192→        let offsetX = 0, offsetY = 0;
193→
194→        const onDown = (e) => {
195→            dragging = true;
196→            el.style.cursor = 'grabbing';
197→            el.style.zIndex = '10';
198→
199→            const rect = board.getBoundingClientRect();
200→            const ev = e.touches ? e.touches[0] : e;
201→            startX = ev.clientX;
202→            startY = ev.clientY;
203→
204→            const leftPct = parseFloat(el.style.left) || 50;
205→            const topPct = parseFloat(el.style.top) || 50;
206→            offsetX = (leftPct / 100) * rect.width;
207→            offsetY = (topPct / 100) * rect.height;
208→
209→            e.preventDefault();
210→        };
211→
212→        const onMove = (e) => {
213→            if (!dragging) return;
214→
215→            const rect = board.getBoundingClientRect();
216→            const ev = e.touches ? e.touches[0] : e;
217→
218→            const dx = ev.clientX - startX;
219→            const dy = ev.clientY - startY;
220→
221→            const newX = Math.max(0, Math.min(rect.width, offsetX + dx));
222→            const newY = Math.max(0, Math.min(rect.height, offsetY + dy));
223→
224→            el.style.left = (newX / rect.width * 100) + '%';
225→            el.style.top = (newY / rect.height * 100) + '%';
226→            el.style.transform = 'translate(-50%, -50%)';
227→
228→            e.preventDefault();
229→        };
230→
231→        const onUp = () => {
232→            if (!dragging) return;
233→            dragging = false;
234→            el.style.cursor = 'grab';
235→            el.style.zIndex = '5';
236→
237→            // Find group under center of token
238→            const tokenRect = el.getBoundingClientRect();
239→            const cx = (tokenRect.left + tokenRect.right) / 2;
240→            const cy = (tokenRect.top + tokenRect.bottom) / 2;
241→
242→            let hitGroupId = null;
243→            for (const [gid, area] of this._groupAreas.entries()) {
244→                const areaRect = area.getBoundingClientRect();
245→                if (cx >= areaRect.left && cx <= areaRect.right &&
246→                    cy >= areaRect.top && cy <= areaRect.bottom) {
247→                    hitGroupId = gid;
248→                    break;
249→                }
250→            }
251→
252→            if (hitGroupId) {
253→                this._inGroup.set(id, hitGroupId);
254→            } else {
255→                this._inGroup.delete(id);
256→            }
257→
258→            if (DBG()) {
259→                console.debug('[PZ.group] drag end:', {id, group: hitGroupId});
260→            }
261→        };
262→
263→        el.addEventListener('mousedown', onDown);
264→        el.addEventListener('touchstart', onDown, {passive: false});
265→
266→        document.addEventListener('mousemove', onMove);
267→        document.addEventListener('touchmove', onMove, {passive: false});
268→
269→        document.addEventListener('mouseup', onUp);
270→        document.addEventListener('touchend', onUp);
271→    }
272→
273→    _solutions() {
274→        // Expected: solutions: { [tokenId]: groupId, ... }
275→        return this.config.solutions || this.config.solution || {};
276→    }
277→
278→    onOk() {
279→        const sol = this._solutions();
280→        let allOk = true;
281→
282→        for (const [id, el] of this._tokenEls.entries()) {
283→            const got = this._inGroup.get(id) || null;
284→            const expect = String(sol[id] ?? '');
285→            const good = (String(got ?? '') === expect);
286→
287→            if (!this.instanceOptions.aggregateOnly) {
288→                el.classList.remove('correct', 'wrong', 'is-correct', 'is-wrong');
289→                el.classList.add(good ? 'correct' : 'wrong', good ? 'is-correct' : 'is-wrong');
290→            }
291→
292→            if (!good) allOk = false;
293→        }
294→
295→        if (!allOk && this.instanceOptions.blockUntilSolved) {
296→            // Reset wrong tokens to center
297→            for (const [id, el] of this._tokenEls.entries()) {
298→                const got = this._inGroup.get(id) || null;
299→                const expect = String(sol[id] ?? '');
300→                if (String(got ?? '') !== expect) {
301→                    const init = this._tokenInit.get(id);
302→                    if (init) {
303→                        el.style.left = init.left;
304→                        el.style.top = init.top;
305→                        el.style.transform = init.transform;
306→                    }
307→                    this._inGroup.delete(id);
308→                }
309→            }
310→            return {hold: true};
311→        }
312→
313→        const detail = {};
314→        for (const [id, gid] of this._inGroup.entries()) {
315→            detail[id] = gid;
316→        }
317→
318→        if (DBG()) {
319→            console.debug('[PZ.group] onOk result:', {allOk, groups: detail, solutions: sol});
320→        }
321→
322→        return {
323→            ok: allOk,
324→            detail: {groups: detail}
325→        };
326→    }
327→}

  1→// engine/puzzles/kinds/choice.js
  2→// Kind: choice – text + selectable value (dropdown or editable input)
  3→
  4→import {BasePuzzle} from '../base.js';
  5→
  6→const DBG = () => (typeof window !== 'undefined' && /\bdebug=1\b/.test(window.location.search));
  7→
  8→export default class ChoicePuzzle extends BasePuzzle {
  9→    constructor(args) {
 10→        super(args);
 11→        this._valueMap = new Map(); // tokenId -> selected value
 12→        this._rows = new Map(); // tokenId -> DOM row element
 13→    }
 14→
 15→    mount(container, workRect, backgroundUrl) {
 16→        super.mount?.(container, workRect, backgroundUrl);
 17→        const flow = this.flowEl;
 18→        this.root?.classList.add('pz-kind-choice');
 19→
 20→        // List container for choice rows
 21→        const list = document.createElement('div');
 22→        list.className = 'pz-choice-list';
 23→        Object.assign(list.style, {
 24→            flex: '1 1 auto',
 25→            display: 'flex',
 26→            flexDirection: 'column',
 27→            gap: 'var(--pz-token-gap)',
 28→            overflowY: 'auto'
 29→        });
 30→
 31→        // Create choice rows
 32→        (this.config.tokens || []).forEach((t, i) => {
 33→            const id = String(t.id ?? i);
 34→            const row = this._makeRow(t, id);
 35→            list.appendChild(row);
 36→            this._rows.set(id, row);
 37→        });
 38→
 39→        // Insert list BEFORE footer
 40→        const footer = flow.querySelector('.pz-footer');
 41→        if (footer) {
 42→            flow.insertBefore(list, footer);
 43→        } else {
 44→            flow.appendChild(list);
 45→        }
 46→
 47→        if (DBG()) {
 48→            console.debug('[PZ.choice] mounted', {rowCount: this.config.tokens?.length || 0});
 49→        }
 50→    }
 51→
 52→    _makeRow(token, id) {
 53→        const row = document.createElement('div');
 54→        row.className = 'pz-choice-row';
 55→        row.setAttribute('data-id', id);
 56→        Object.assign(row.style, {
 57→            display: 'grid',
 58→            gridTemplateColumns: '1fr auto',
 59→            gap: 'var(--pz-token-gap)',
 60→            alignItems: 'center'
 61→        });
 62→
 63→        // Text label (left side) - can be hidden via style.visible
 64→        const textEl = document.createElement('div');
 65→        textEl.className = 'pz-choice-text';
 66→        textEl.setAttribute('data-id', `label:${id}`);
 67→        textEl.textContent = this.t(token.label || token.text || '', '');
 68→
 69→        const textStyle = {
 70→            ...(this.config.theme?.text || {}),
 71→            ...(token.textStyle || {})
 72→        };
 73→        this.applyStyle(textEl, textStyle);
 74→
 75→        row.appendChild(textEl);
 76→
 77→        // Choice control (right side) - dropdown or editable input
 78→        const controlWrap = document.createElement('div');
 79→        controlWrap.className = 'pz-choice-control';
 80→        controlWrap.setAttribute('data-id', `control:${id}`);
 81→        controlWrap.style.position = 'relative';
 82→
 83→        const choices = token.choices || [];
 84→        const editable = token.editable || (choices.length === 0);
 85→
 86→        if (editable) {
 87→            // Editable input
 88→            const input = document.createElement('input');
 89→            input.setAttribute('data-id', `input:${id}`);
 90→            input.type = 'text';
 91→            input.className = 'pz-input pz-choice-input';
 92→            input.placeholder = this.t(token.placeholder || '', '');
 93→            input.addEventListener('input', () => {
 94→                this._valueMap.set(id, input.value);
 95→            });
 96→
 97→            const inputStyle = {
 98→                minWidth: '120px',
 99→                ...(this.config.theme?.input || {}),
100→                ...(token.style || {})
101→            };
102→            this.applyStyle(input, inputStyle);
103→
104→            controlWrap.appendChild(input);
105→        } else {
106→            // Dropdown (token-styled button + menu)
107→            const btn = document.createElement('button');
108→            btn.setAttribute('data-id', `button:${id}`);
109→            btn.type = 'button';
110→            btn.className = 'pz-token pz-choice-button';
111→            btn.textContent = this.t(token.placeholder || '@engine.select@Vyberte…', 'Vyberte…');
112→
113→            const btnStyle = {
114→                minWidth: '120px',
115→                cursor: 'pointer',
116→                ...(this.config.theme?.token || {}),
117→                ...(token.style || {})
118→            };
119→            this.applyStyle(btn, btnStyle);
120→
121→            // Dropdown menu
122→            const menu = document.createElement('div');
123→            menu.className = 'pz-dropdown';
124→            menu.setAttribute('data-id', `menu:${id}`);
125→            Object.assign(menu.style, {
126→                position: 'absolute',
127→                top: 'calc(100% + 4px)',
128→                right: '0', // Right-align with button
129→                minWidth: '160px',
130→                maxWidth: '300px',
131→                maxHeight: '200px',
132→                overflowY: 'auto',
133→                background: 'rgba(17, 17, 20, 0.95)',
134→                border: '1px solid rgba(255, 255, 255, 0.2)',
135→                borderRadius: 'var(--pz-token-radius)',
136→                padding: '4px',
137→                display: 'none',
138→                zIndex: '100',
139→                boxShadow: '0 4px 12px rgba(0, 0, 0, 0.4)'
140→            });
141→
142→            choices.forEach(opt => {
143→                const optBtn = document.createElement('button');
144→                optBtn.type = 'button';
145→                optBtn.className = 'pz-token pz-choice-option';
146→                optBtn.textContent = this.t(opt.label || String(opt.value), String(opt.value));
147→                optBtn.style.width = '100%';
148→                optBtn.style.marginBottom = '2px';
149→
150→                optBtn.addEventListener('click', () => {
151→                    const val = String(opt.value ?? opt.label ?? '');
152→                    this._valueMap.set(id, val);
153→                    btn.textContent = this.t(opt.label || val, val);
154→                    menu.style.display = 'none';
155→                });
156→
157→                menu.appendChild(optBtn);
158→            });
159→
160→            btn.addEventListener('click', (e) => {
161→                e.stopPropagation();
162→                const isOpen = menu.style.display === 'block';
163→                // Close all other dropdowns
164→                document.querySelectorAll('.pz-dropdown').forEach(m => m.style.display = 'none');
165→                menu.style.display = isOpen ? 'none' : 'block';
166→            });
167→
168→            // Close on outside click
169→            document.addEventListener('click', () => {
170→                menu.style.display = 'none';
171→            });
172→
173→            controlWrap.appendChild(btn);
174→            controlWrap.appendChild(menu);
175→        }
176→
177→        row.appendChild(controlWrap);
178→        return row;
179→    }
180→
181→    _solutions() {
182→        // Expected: solutions: { [tokenId]: "value" | ["value1", "value2", ...], ... }
183→        // IMPORTANT: Translate solution values (may have @key@fallback format)
184→        const raw = this.config.solutions || {};
185→        const translated = {};
186→
187→        for (const [id, val] of Object.entries(raw)) {
188→            // Support multiple correct answers (array or single value)
189→            if (Array.isArray(val)) {
190→                translated[id] = val.map(v => this.t(v, v));
191→            } else {
192→                translated[id] = [this.t(val, val)];
193→            }
194→        }
195→
196→        // FALLBACK: Check individual tokens for 'solution' property
197→        if (Object.keys(translated).length === 0) {
198→            (this.config.tokens || []).forEach((t, i) => {
199→                const id = String(t.id ?? i);
200→                if (t.solution !== undefined) {
201→                    const sol = t.solution;
202→                    translated[id] = Array.isArray(sol) ? sol.map(s => this.t(s, s)) : [this.t(sol, sol)];
203→                }
204→            });
205→        }
206→
207→        if (DBG()) {
208→            console.debug('[PZ.choice] solutions translated:', {raw, translated});
209→        }
210→
211→        return translated;
212→    }
213→
214→    _isCorrect(id, value, solutions) {
215→        const expectedValues = solutions[id];
216→        if (!expectedValues) return false;
217→        const got = String(value ?? '');
218→        return expectedValues.some(expected => got === String(expected));
219→    }
220→
221→    onOk() {
222→        const sol = this._solutions();
223→        let allOk = true;
224→        const wrongRows = [];
225→
226→        for (const [id, row] of this._rows.entries()) {
227→            const got = this._valueMap.get(id);
228→            const good = this._isCorrect(id, got, sol);
229→
230→            if (!this.instanceOptions.aggregateOnly) {
231→                row.classList.remove('correct', 'wrong', 'is-correct', 'is-wrong', 'invalid');
232→                row.classList.add(good ? 'correct' : 'wrong', good ? 'is-correct' : 'is-wrong');
233→            }
234→
235→            if (!good) {
236→                allOk = false;
237→                wrongRows.push(row);
238→            }
239→        }
240→
241→        if (!allOk && this.instanceOptions.blockUntilSolved) {
242→            // Add visual feedback (shake animation)
243→            wrongRows.forEach(row => {
244→                row.classList.add('invalid');
245→                setTimeout(() => row.classList.remove('invalid'), 600);
246→            });
247→
248→            // Show toast if enabled (default: true)
249→            const showToast = this.instanceOptions.showErrorToast ?? this.config.showErrorToast ?? true;
250→
251→            if (DBG()) {
252→                console.debug('[PZ.choice] Toast check:', {
253→                    showToast,
254→                    hasEngine: !!this.engine,
255→                    hasToastMethod: !!(this.engine?.toast),
256→                    engineType: typeof this.engine,
257→                    engineConstructor: this.engine?.constructor?.name,
258→                    errorMessage: this.config.errorMessage
259→                });
260→            }
261→
262→            if (showToast) {
263→                const msg = this.t(
264→                    this.config.errorMessage || '@engine.puzzle.incorrect@Puzzle není správně vyřešen.',
265→                    'Puzzle není správně vyřešen.'
266→                );
267→
268→                // Try engine.toast first, then fallback to direct call
269→                if (this.engine?.toast) {
270→                    this.engine.toast(msg, 2500);
271→                } else if (typeof window !== 'undefined' && window.game?.toast) {
272→                    window.game.toast(msg, 2500);
273→                } else {
274→                    console.warn('[PZ.choice] Toast method not available:', {
275→                        hasEngine: !!this.engine,
276→                        hasWindowGame: !!(typeof window !== 'undefined' && window.game)
277→                    });
278→                }
279→            }
280→
281→            return {hold: true};
282→        }
283→
284→        const detail = {};
285→        for (const [id, val] of this._valueMap.entries()) {
286→            detail[id] = val;
287→        }
288→
289→        if (DBG()) {
290→            console.debug('[PZ.choice] onOk result:', {allOk, values: detail, solutions: sol});
291→        }
292→
293→        return {
294→            ok: allOk,
295→            detail: {values: detail}
296→        };
297→    }
298→}
299→

  1→// engine/puzzles/kinds/list.js
  2→// Kind: list – sequential puzzle execution with aggregation and summary
  3→
  4→import {BasePuzzle} from '../base.js';
  5→import {createPuzzleRunner} from '../index.js';
  6→
  7→const DBG = () => (typeof window !== 'undefined' && /\bdebug=1\b/.test(window.location.search));
  8→
  9→export default class ListPuzzle extends BasePuzzle {
 10→    constructor(args) {
 11→        super(args);
 12→        this._results = [];
 13→        this._currentIdx = 0;
 14→        this._running = false;
 15→        this._bgOverlay = null;
 16→    }
 17→
 18→    mount(container, workRect, backgroundUrl) {
 19→        // List doesn't use standard BasePuzzle mount - it manages its own sequence
 20→        this.container = container;
 21→        this.workRect = workRect;
 22→        this.backgroundUrl = backgroundUrl;
 23→
 24→        // Shared background for entire list
 25→        if (backgroundUrl) {
 26→            this._bgOverlay = document.createElement('div');
 27→            Object.assign(this._bgOverlay.style, {
 28→                position: 'absolute',
 29→                inset: '0',
 30→                backgroundImage: `url("${backgroundUrl}")`,
 31→                backgroundSize: 'cover',
 32→                backgroundPosition: 'center',
 33→                pointerEvents: 'none',
 34→                zIndex: '7999'
 35→            });
 36→            container.appendChild(this._bgOverlay);
 37→        }
 38→
 39→        if (DBG()) {
 40→            console.debug('[PZ.list] mounted', {
 41→                steps: this.config.steps?.length || 0,
 42→                aggregateOnly: this.instanceOptions.aggregateOnly,
 43→                blockUntilSolved: this.instanceOptions.blockUntilSolved
 44→            });
 45→        }
 46→    }
 47→
 48→    render() {
 49→        if (this._running) return;
 50→        this._running = true;
 51→
 52→        const steps = this.config.steps || this.config.items || [];
 53→
 54→        if (DBG()) {
 55→            console.debug('[PZ.list] starting sequence', {stepCount: steps.length});
 56→        }
 57→
 58→        this._runSequence(steps);
 59→    }
 60→
 61→    _runSequence(steps) {
 62→        if (this._currentIdx >= steps.length) {
 63→            // All done - show summary
 64→            this._showSummary();
 65→            return;
 66→        }
 67→
 68→        const step = steps[this._currentIdx];
 69→        const instOpts = {
 70→            aggregateOnly: this.instanceOptions.aggregateOnly ?? false,
 71→            blockUntilSolved: this.instanceOptions.blockUntilSolved ?? false,
 72→            ...(step.options || {})
 73→        };
 74→
 75→        if (DBG()) {
 76→            console.debug('[PZ.list] starting step', {
 77→                idx: this._currentIdx,
 78→                ref: step.ref,
 79→                options: instOpts
 80→            });
 81→        }
 82→
 83→        // IMPORTANT: Use step.rect if defined, otherwise use full screen (not this.workRect)
 84→        // this.workRect is for the list container itself, not for individual puzzles
 85→        const puzzleRect = step.rect || {x: 0, y: 0, w: 100, h: 100};
 86→
 87→        const runner = createPuzzleRunner({
 88→            ref: step.ref,
 89→            config: step.config,
 90→            rect: puzzleRect,
 91→            background: step.background || undefined,
 92→            instanceOptions: instOpts,
 93→            puzzlesById: this.engine.data?.puzzles || {},
 94→            i18n: (k, def) => this.tKey(k, def),
 95→            engine: this.engine,
 96→            onResolve: (result) => {
 97→                this._results.push({
 98→                    index: this._currentIdx,
 99→                    ref: step.ref || step.config?.id || `#${this._currentIdx}`,
100→                    ok: !!result.ok,
101→                    detail: result.detail
102→                });
103→
104→                if (DBG()) {
105→                    console.debug('[PZ.list] step resolved', {
106→                        idx: this._currentIdx,
107→                        ok: result.ok,
108→                        blockUntilSolved: instOpts.blockUntilSolved
109→                    });
110→                }
111→
112→                // blockUntilSolved takes precedence
113→                if (instOpts.blockUntilSolved && !result.ok) {
114→                    if (DBG()) {
115→                        console.debug('[PZ.list] blocked - must solve correctly');
116→                    }
117→                    return; // Stay on this step
118→                }
119→
120→                // Progress to next
121→                runner.unmount();
122→                this._currentIdx++;
123→                this._runSequence(steps);
124→            }
125→        });
126→
127→        runner.mountInto(this.container);
128→    }
129→
130→    _showSummary() {
131→        const total = this._results.length;
132→        const ok = this._results.filter(r => r.ok).length;
133→        const allOk = ok === total;
134→
135→        if (DBG()) {
136→            console.debug('[PZ.list] summary', {total, ok, allOk});
137→        }
138→
139→        const summary = this.config.summary || {};
140→
141→        if (summary.show === false) {
142→            // No summary - resolve immediately
143→            this._finish(allOk);
144→            return;
145→        }
146→
147→        // Create summary overlay (use CSS classes, minimal inline styles)
148→        const host = document.createElement('div');
149→        host.className = 'pz-list-summary';
150→        Object.assign(host.style, {
151→            left: (this.workRect?.x ?? 10) + '%',
152→            top: (this.workRect?.y ?? 10) + '%',
153→            width: (this.workRect?.w ?? 80) + '%',
154→            height: (this.workRect?.h ?? 80) + '%'
155→        });
156→
157→        // Title
158→        const title = document.createElement('div');
159→        title.textContent = this.t(summary.title || '@list.summary.title@Výsledek série', 'Výsledek série');
160→        Object.assign(title.style, {
161→            fontSize: '1.4em',
162→            fontWeight: '700',
163→            textAlign: 'center',
164→            color: 'rgba(255, 255, 255, 0.95)'
165→        });
166→        host.appendChild(title);
167→
168→        // Score (if enabled)
169→        if (summary.showScore !== false) {
170→            const score = document.createElement('div');
171→            score.textContent = `${ok} / ${total}`;
172→            Object.assign(score.style, {
173→                fontSize: '2.5em',
174→                fontWeight: '700',
175→                color: allOk ? 'rgba(20, 220, 90, 0.9)' : 'rgba(255, 160, 90, 0.9)'
176→            });
177→            host.appendChild(score);
178→        }
179→
180→        // Message
181→        const message = document.createElement('div');
182→        const msgKey = allOk ? 'messageOk' : 'messageFail';
183→        const msgDefault = allOk ? 'Skvělé! Série splněna.' : 'Něco se nepovedlo.';
184→        message.textContent = this.t(summary[msgKey] || msgDefault, msgDefault);
185→        Object.assign(message.style, {
186→            fontSize: '1.1em',
187→            textAlign: 'center',
188→            opacity: '0.9',
189→            color: 'rgba(255, 255, 255, 0.9)',
190→            maxWidth: '80%'
191→        });
192→        host.appendChild(message);
193→
194→        // OK button - MUST use only CSS classes, NO inline background/border styles
195→        const btn = document.createElement('button');
196→        btn.type = 'button';
197→        btn.className = 'pz-btn pz-btn--ok';
198→        btn.textContent = this.t('@engine.modal.ok@OK', 'OK');
199→
200→        // Only layout styles inline, NO background/border (CSS handles those)
201→        Object.assign(btn.style, {
202→            marginTop: '2vh',
203→            minWidth: '120px'
204→        });
205→
206→        btn.addEventListener('click', () => {
207→            if (host.parentNode) {
208→                host.parentNode.removeChild(host);
209→            }
210→            this._finish(allOk);
211→        });
212→        host.appendChild(btn);
213→
214→        this.container.appendChild(host);
215→    }
216→
217→    _finish(allOk) {
218→        if (DBG()) {
219→            console.debug('[PZ.list] finished', {allOk, results: this._results});
220→        }
221→
222→        if (allOk) {
223→            this.resolveOk?.({results: this._results});
224→        } else {
225→            this.resolveFail?.('incomplete', {results: this._results});
226→        }
227→    }
228→
229→    unmount() {
230→        if (this._bgOverlay?.parentNode) {
231→            this._bgOverlay.parentNode.removeChild(this._bgOverlay);
232→        }
233→        this._running = false;
234→
235→        if (DBG()) {
236→            console.debug('[PZ.list] unmount');
237→        }
238→    }
239→
240→    onOk() {
241→        // List manages its own flow - no manual OK
242→        return {hold: true};
243→    }
244→
245→    onCancel() {
246→        this.resolveFail?.('cancel');
247→        this.onRequestClose?.({reason: 'cancel'});
248→    }
249→}

  1→// engine/puzzles/kinds/cloze.js
  2→// Kind: cloze – doplňovačka
  3→// FIX 6: Oprava vizuálu (dashed) a oprava vracení tokenů do banku (bezpečný DOM move).
  4→
  5→import {BasePuzzle} from '../base.js';
  6→
  7→const DBG = () => (typeof window !== 'undefined' && /\bdebug=1\b/.test(window.location.search));
  8→
  9→export default class ClozePuzzle extends BasePuzzle {
 10→    constructor(args) {
 11→        super(args);
 12→        this._tokenEls = new Map();
 13→        this._gapEls = new Map();
 14→        this._placements = new Map();
 15→        this._tokensArea = null;
 16→
 17→        this._dragState = {
 18→            active: false,
 19→            tokenId: null,
 20→            originalEl: null,
 21→            ghostEl: null,
 22→            startX: 0,
 23→            startY: 0,
 24→            offsetX: 0,
 25→            offsetY: 0,
 26→            hoveredGapId: null
 27→        };
 28→
 29→        this._ignoreNextClick = false;
 30→
 31→        this._onPointerMove = this._onPointerMove.bind(this);
 32→        this._onPointerUp = this._onPointerUp.bind(this);
 33→    }
 34→
 35→    mount(container, workRect, backgroundUrl) {
 36→        super.mount?.(container, workRect, backgroundUrl);
 37→        const flow = this.flowEl;
 38→        this.root?.classList.add('pz-kind-cloze');
 39→
 40→        const layoutCfg = this.instanceOptions.layout || this.config.layout || {};
 41→        const direction = layoutCfg.direction || 'vertical';
 42→
 43→        const clozeContainer = document.createElement('div');
 44→        clozeContainer.className = 'pz-cloze-container';
 45→        Object.assign(clozeContainer.style, {
 46→            flex: '1 1 auto',
 47→            display: 'flex',
 48→            flexDirection: direction === 'horizontal' ? 'row' : 'column',
 49→            gap: 'calc(var(--pz-token-gap) * 2)',
 50→            minHeight: '0',
 51→            position: 'relative',
 52→            touchAction: 'none'
 53→        });
 54→
 55→        const textArea = this._createTextArea();
 56→        clozeContainer.appendChild(textArea);
 57→
 58→        const tokensArea = this._createTokensArea();
 59→        this._tokensArea = tokensArea;
 60→        clozeContainer.appendChild(tokensArea);
 61→
 62→        const footer = flow.querySelector('.pz-footer');
 63→        if (footer) {
 64→            flow.insertBefore(clozeContainer, footer);
 65→        } else {
 66→            flow.appendChild(clozeContainer);
 67→        }
 68→    }
 69→
 70→    _createTextArea() {
 71→        const area = document.createElement('div');
 72→        area.className = 'pz-cloze-text-area';
 73→        const text = this.t(this.config.text || '', '');
 74→        const parts = text.split(/(\{gap\d+})/g);
 75→
 76→        parts.forEach(part => {
 77→            if (/^\{gap\d+}$/.test(part)) {
 78→                const gapId = part.slice(1, -1);
 79→                const gap = this._createGap(gapId);
 80→                area.appendChild(gap);
 81→                this._gapEls.set(gapId, gap);
 82→            } else if (part.trim()) {
 83→                const textSpan = document.createElement('span');
 84→                textSpan.textContent = part;
 85→                textSpan.style.whiteSpace = 'pre-wrap';
 86→                area.appendChild(textSpan);
 87→            }
 88→        });
 89→        return area;
 90→    }
 91→
 92→    _createGap(gapId) {
 93→        const gap = document.createElement('span');
 94→        gap.className = 'pz-cloze-gap';
 95→        gap.setAttribute('data-gap-id', gapId);
 96→
 97→        gap.addEventListener('click', (e) => {
 98→            if (this._ignoreNextClick) {
 99→                this._ignoreNextClick = false;
100→                return;
101→            }
102→
103→            // Kliknutím na gap vrátíme token do banku
104→            if (this._placements.has(gapId)) {
105→                this._returnTokenToArea(this._placements.get(gapId));
106→                // Poznámka: _returnTokenToArea se postará o vyčištění placements i gap class
107→            }
108→        });
109→        return gap;
110→    }
111→
112→    _createTokensArea() {
113→        const area = document.createElement('div');
114→        area.className = 'pz-cloze-tokens-area';
115→        const tokens = [...(this.config.tokens || [])];
116→
117→        for (let i = tokens.length - 1; i > 0; i--) {
118→            const j = Math.floor(Math.random() * (i + 1));
119→            [tokens[i], tokens[j]] = [tokens[j], tokens[i]];
120→        }
121→
122→        tokens.forEach(t => {
123→            const id = String(t.id);
124→            const el = this.createToken(t);
125→            el.setAttribute('data-token-id', id);
126→            this._enablePointerDrag(el, id);
127→            this._tokenEls.set(id, el);
128→            area.appendChild(el);
129→        });
130→
131→        return area;
132→    }
133→
134→    // ========================================================================
135→    // POINTER EVENTS
136→    // ========================================================================
137→
138→    _enablePointerDrag(el, tokenId) {
139→        el.style.touchAction = 'none';
140→        el.style.userSelect = 'none';
141→        el.style.cursor = 'grab';
142→
143→        el.addEventListener('pointerdown', (e) => {
144→            if (e.button !== 0) return;
145→            e.preventDefault();
146→            this._startDrag(e, el, tokenId);
147→        });
148→    }
149→
150→    _startDrag(e, el, tokenId) {
151→        if (this._dragState.active) return;
152→
153→        const rect = el.getBoundingClientRect();
154→        const computed = window.getComputedStyle(el);
155→
156→        this._dragState = {
157→            active: true,
158→            tokenId: tokenId,
159→            originalEl: el,
160→            ghostEl: null,
161→            startX: e.clientX,
162→            startY: e.clientY,
163→            offsetX: e.clientX - rect.left,
164→            offsetY: e.clientY - rect.top,
165→            hoveredGapId: null
166→        };
167→
168→        const ghost = el.cloneNode(true);
169→        ghost.className = 'pz-token pz-cloze-ghost';
170→        ghost.style.borderRadius = computed.borderRadius;
171→        ghost.style.backgroundColor = computed.backgroundColor;
172→        ghost.style.border = computed.border;
173→        ghost.style.color = computed.color;
174→        ghost.style.fontFamily = computed.fontFamily;
175→        ghost.style.fontSize = computed.fontSize;
176→        ghost.style.padding = computed.padding;
177→        ghost.style.boxSizing = 'border-box';
178→        ghost.style.margin = '0';
179→
180→        Object.assign(ghost.style, {
181→            position: 'fixed',
182→            left: (rect.left) + 'px',
183→            top: (rect.top) + 'px',
184→            width: rect.width + 'px',
185→            height: rect.height + 'px',
186→            zIndex: '9999',
187→            pointerEvents: 'none',
188→            opacity: '0.95',
189→            transform: 'scale(1.05)',
190→            boxShadow: '0 10px 25px rgba(0,0,0,0.5)',
191→            textAlign: computed.textAlign,
192→            display: 'flex',
193→            alignItems: 'center',
194→            justifyContent: 'center'
195→        });
196→
197→        document.body.appendChild(ghost);
198→        this._dragState.ghostEl = ghost;
199→
200→        el.style.opacity = '0.3';
201→        el.classList.add('dragging');
202→
203→        document.addEventListener('pointermove', this._onPointerMove);
204→        document.addEventListener('pointerup', this._onPointerUp);
205→        document.addEventListener('pointercancel', this._onPointerUp);
206→    }
207→
208→    _onPointerMove(e) {
209→        if (!this._dragState.active || !this._dragState.ghostEl) return;
210→        e.preventDefault();
211→
212→        const x = e.clientX - this._dragState.offsetX;
213→        const y = e.clientY - this._dragState.offsetY;
214→        this._dragState.ghostEl.style.left = x + 'px';
215→        this._dragState.ghostEl.style.top = y + 'px';
216→
217→        this._updateHoveredGap(e.clientX, e.clientY);
218→    }
219→
220→    _updateHoveredGap(x, y) {
221→        this._gapEls.forEach(gap => gap.classList.remove('drag-over'));
222→
223→        const elements = document.elementsFromPoint(x, y);
224→        let foundGapId = null;
225→
226→        for (const el of elements) {
227→            const gap = el.closest('.pz-cloze-gap');
228→            if (gap) {
229→                foundGapId = gap.getAttribute('data-gap-id');
230→                break;
231→            }
232→        }
233→
234→        if (foundGapId) {
235→            this._dragState.hoveredGapId = foundGapId;
236→            const gap = this._gapEls.get(foundGapId);
237→            if (gap) gap.classList.add('drag-over');
238→        } else {
239→            this._dragState.hoveredGapId = null;
240→        }
241→    }
242→
243→    _onPointerUp(e) {
244→        if (!this._dragState.active) return;
245→
246→        document.removeEventListener('pointermove', this._onPointerMove);
247→        document.removeEventListener('pointerup', this._onPointerUp);
248→        document.removeEventListener('pointercancel', this._onPointerUp);
249→
250→        if (this._dragState.ghostEl) {
251→            this._dragState.ghostEl.style.display = 'none';
252→        }
253→
254→        // Detekce cíle (Hybridní: Live + Cache fallback)
255→        let targetGapId = null;
256→        const freshElements = document.elementsFromPoint(e.clientX, e.clientY);
257→        for (const el of freshElements) {
258→            const gap = el.closest('.pz-cloze-gap');
259→            if (gap) {
260→                targetGapId = gap.getAttribute('data-gap-id');
261→                break;
262→            }
263→        }
264→
265→        if (!targetGapId && this._dragState.hoveredGapId) {
266→            targetGapId = this._dragState.hoveredGapId;
267→        }
268→
269→        if (targetGapId) {
270→            this._dropIntoGap(targetGapId);
271→        } else {
272→            this._returnToBank();
273→        }
274→
275→        // Cleanup
276→        if (this._dragState.ghostEl) this._dragState.ghostEl.remove();
277→        if (this._dragState.originalEl) {
278→            this._dragState.originalEl.style.opacity = '1';
279→            this._dragState.originalEl.classList.remove('dragging');
280→            this._dragState.originalEl.style.cursor = 'grab';
281→        }
282→
283→        this._gapEls.forEach(g => g.classList.remove('drag-over'));
284→        this._dragState = { active: false, tokenId: null, originalEl: null, ghostEl: null, hoveredGapId: null };
285→    }
286→
287→    // --- LOGIC HELPERS (OPRAVENÉ) ---
288→
289→    _dropIntoGap(gapId) {
290→        const tokenId = this._dragState.tokenId;
291→        const gap = this._gapEls.get(gapId);
292→
293→        if (!gap) return;
294→
295→        this._ignoreNextClick = true;
296→        setTimeout(() => { this._ignoreNextClick = false; }, 100);
297→
298→        // 1. Pokud je v gapu JINÝ token, vrátíme ho do banku
299→        if (this._placements.has(gapId)) {
300→            const existingTokenId = this._placements.get(gapId);
301→            if (existingTokenId !== tokenId) {
302→                this._returnTokenToArea(existingTokenId);
303→            }
304→        }
305→
306→        // 2. Pokud byl tento token v jiném gapu, uvolníme ten starý gap
307→        for (const [otherGap, placedToken] of this._placements.entries()) {
308→            if (placedToken === tokenId && otherGap !== gapId) {
309→                this._placements.delete(otherGap);
310→                const oldGapEl = this._gapEls.get(otherGap);
311→                if (oldGapEl) {
312→                    oldGapEl.classList.remove('filled');
313→                    // POZOR: Nemazat innerHTML, pokud tam token stále je (on se přesune appendChildem)
314→                }
315→            }
316→        }
317→
318→        // 3. Zaregistrujeme novou pozici
319→        this._placements.set(gapId, tokenId);
320→
321→        // 4. Fyzický přesun v DOMu
322→        const tokenEl = this._dragState.originalEl; // Použijeme originalEl z drag state
323→
324→        // Append přesune element, není třeba volat removeChild
325→        gap.appendChild(tokenEl);
326→
327→        gap.classList.add('filled');
328→        gap.classList.remove('drag-over');
329→
330→        // Styly pro "connected" stav
331→        tokenEl.style.background = 'var(--pz-selected-bg)';
332→        tokenEl.style.borderColor = 'var(--pz-selected-border)';
333→        tokenEl.classList.remove('correct', 'wrong', 'is-correct', 'is-wrong');
334→    }
335→
336→    _returnToBank() {
337→        const tokenId = this._dragState.tokenId;
338→        this._returnTokenToArea(tokenId);
339→    }
340→
341→    _returnTokenToArea(tokenId) {
342→        const tokenEl = this._tokenEls.get(tokenId);
343→        if (!tokenEl || !this._tokensArea) return;
344→
345→        // 1. Najít, zda byl v nějakém gapu, a vyčistit ten gap
346→        for (const [gapId, placedToken] of this._placements.entries()) {
347→            if (placedToken === tokenId) {
348→                this._placements.delete(gapId);
349→                const gap = this._gapEls.get(gapId);
350→                if (gap) {
351→                    gap.classList.remove('filled');
352→                    // Nemusíme dělat gap.innerHTML = '', protože appendChild níže ten element vyjme
353→                }
354→            }
355→        }
356→
357→        // 2. Reset stylů
358→        tokenEl.style.background = '';
359→        tokenEl.style.borderColor = '';
360→        tokenEl.classList.remove('correct', 'wrong', 'is-correct', 'is-wrong');
361→
362→        // 3. Přesunout fyzicky do banku
363→        this._tokensArea.appendChild(tokenEl);
364→    }
365→
366→    // ========================================================================
367→    // EVALUATION
368→    // ========================================================================
369→
370→    onOk() {
371→        const solution = this.config.solution || {};
372→        let allCorrect = true;
373→        const correctGaps = new Set();
374→
375→        for (const [gapId, tokenId] of this._placements.entries()) {
376→            const expectedTokenId = String(solution[gapId] || '');
377→            const isCorrect = (tokenId === expectedTokenId);
378→
379→            if (isCorrect) correctGaps.add(gapId);
380→            else allCorrect = false;
381→
382→            if (!this.instanceOptions.aggregateOnly) {
383→                const tokenEl = this._tokenEls.get(tokenId);
384→                if (tokenEl) {
385→                    tokenEl.classList.remove('correct', 'wrong', 'is-correct', 'is-wrong');
386→                    if (isCorrect) {
387→                        tokenEl.classList.add('correct', 'is-correct');
388→                        tokenEl.style.background = 'var(--pz-correct-bg)';
389→                        tokenEl.style.borderColor = 'var(--pz-correct-border)';
390→                    } else {
391→                        tokenEl.classList.add('wrong', 'is-wrong');
392→                        tokenEl.style.background = 'var(--pz-wrong-bg)';
393→                        tokenEl.style.borderColor = 'var(--pz-wrong-border)';
394→                    }
395→                }
396→            }
397→        }
398→
399→        for (const gapId of Object.keys(solution)) {
400→            if (!this._placements.has(gapId)) allCorrect = false;
401→        }
402→
403→        if (!allCorrect && this.instanceOptions.blockUntilSolved) {
404→            setTimeout(() => {
405→                const wrongPlacements = [];
406→                for (const [gapId, tokenId] of this._placements.entries()) {
407→                    if (!correctGaps.has(gapId)) wrongPlacements.push({gapId, tokenId});
408→                }
409→                wrongPlacements.forEach(({gapId, tokenId}) => {
410→                    this._returnTokenToArea(tokenId);
411→                    // _returnTokenToArea už řeší smazání z _placements a update gap class
412→                });
413→            }, 800);
414→            return {hold: true};
415→        }
416→
417→        return { ok: allCorrect, detail: { placements: Object.fromEntries(this._placements) } };
418→    }
419→}
