 1→/**
 2→ * Compute absolute CSS positioning (in %) for a rect inside the scene.
 3→ * @param {{x:number,y:number,w:number,h:number}} rect
 4→ * @returns {Record<string,string>} style map
 5→ */
 6→export function rectToStyle(rect) {
 7→    return {
 8→        left: rect.x + '%',
 9→        top: rect.y + '%',
10→        width: rect.w + '%',
11→        height: rect.h + '%'
12→    };
13→}
