15→/**
16→ * Apply auto layout onto container element (.pz__flow) for vertical/horizontal/grid.
17→ *
18→ * @param {HTMLElement} root
19→ * @param {{mode:"auto"|"manual", direction?:"vertical"|"horizontal"|"grid", grid?:{cols?:number}}} layout
20→ */
21→export function applyAutoLayout(root, layout) {
22→    const mode = layout?.mode || 'auto';
23→    root.classList.toggle('pz--auto', mode === 'auto');
24→    root.classList.toggle('pz--manual', mode === 'manual');
25→
26→    root.classList.remove('pz--vertical', 'pz--horizontal', 'pz--grid');
27→    if (mode === 'auto') {
28→        const dir = layout?.direction || 'vertical';
29→        if (dir === 'grid') {
30→            root.classList.add('pz--grid');
31→            const cols = layout?.grid?.cols ?? 3;
32→            const flow = root.querySelector('.pz__flow');
33→            if (flow) flow.setAttribute('data-cols', String(cols));
34→        } else if (dir === 'horizontal') {
35→            root.classList.add('pz--horizontal');
36→        } else {
37→            root.classList.add('pz--vertical');
38→        }
39→    }
40→
41→    // Debug (toggle with ?debug=1)
42→    try {
43→        if (typeof window !== 'undefined' && /\bdebug=1\b/.test(window.location.search)) {
44→            console.debug('[PZ] layout classes:', root.className);
45→        }
46→    } catch {
47→    }
48→}
