120→    function mountInto(rootEl) {
121→        rootEl.appendChild(container);
122→
123→        const workRect = cfg.rect || {x: 10, y: 10, w: 80, h: 80};
124→
125→        // Resolve background: args.background (from list step) OR cfg.background (from puzzle config)
126→        const resolvedBackground = args.background ||
127→                                   (cfg.background ? (args.engine?._resolveAsset?.(cfg.background) || cfg.background) : undefined);
128→
129→        console.log('[PZ] runner mountInto:', {
130→            id: puzzle.id,
131→            kind: puzzle.kind,
132→            argsRect: args.rect,
133→            cfgRect: cfg.rect,
134→            containerRect,
135→            workRect,
136→            'args.background': args.background,
137→            'cfg.background': cfg.background,
138→            'resolvedBackground': resolvedBackground
139→        });
140→
141→        if (/\bdebug=1\b/.test(window.location.search)) {
142→            console.debug('[PZ] runner mountInto:', {
143→                id: puzzle.id,
144→                kind: puzzle.kind,
145→                'args.rect (hotspot)': args.rect,
146→                'cfg.rect (puzzle config)': cfg.rect,
147→                'containerRect (used)': containerRect,
148→                'workRect (used)': workRect,
149→                containerStyle: container.style.cssText
150→            });
151→        }
152→
153→        puzzle.mount(container, workRect, resolvedBackground);
154→        puzzle.render?.();
155→    }
