  80→    // --- i18n helpers -----------------------------------------------------------
  81→
  82→    _fmt(str, params) {
  83→        if (!params) return str;
  84→        return String(str).replace(/\{(\w+)}/g, (_, k) => (params[k] ?? `{${k}}`));
  85→    }
  86→
  87→    _t(key, fallback = '', params = null) {
  88→        const g = this.i18n?.game?.[key];
  89→        const e = this.i18n?.engine?.[key];
  90→        const raw = (g != null ? g : (e != null ? e : fallback));
  91→        return this._fmt(raw, params);
