  94→    /**
  95→     * Resolve string | {key} | "@key@fallback".
  96→     */
  97→    _text(val, fallback = '') {
  98→        if (val && typeof val === 'object' && val.key) {
  99→            return this._t(String(val.key), fallback);
 100→        }
 101→        if (typeof val === 'string') {
 102→            const m = val.match(/^@([^@]+)@(.*)$/s);
 103→            if (m) return this._t(m[1].trim(), m[2]);
 104→            return val;
 105→        }
 106→        return (val != null ? String(val) : String(fallback));
