 109→    /** Prefix relative paths with baseUrl. */
 110→    _resolveAsset(path) {
 111→        if (!path) return path;
 112→        const s = String(path);
 113→        if (/^(?:https?:)?\/\//i.test(s)) return s;           // absolute URL
 114→        if (s.startsWith('./') || s.startsWith('/')) return s; // already rooted
 115→        return this.baseUrl.replace(/\/+$/, '/') + s.replace(/^\/+/, '');
