 277→    /**
 278→     * Checks if an item can be used in the current scene.
 279→     * @param {string} itemId - The item ID to check.
 280→     * @returns {boolean|null} - true if usable, false if not usable, null if cannot determine (fail-safe).
 281→     */
 282→    _isItemApplicableHere(itemId) {
 283→        // Fail-safe: if currentScene is not loaded, return null to indicate uncertainty
 284→        if (!this.currentScene) {
 285→            this._dbg('[GUARD] _isItemApplicableHere: currentScene is null/undefined, returning null (fail-safe)');
 286→            return null;
 287→        }
 288→
 289→        const hs = this.currentScene.hotspots || [];
 290→
 291→        // If scene has no hotspots at all, we can definitively say item is not usable here
 292→        if (hs.length === 0) {
 293→            return false;
 294→        }
 295→
 296→        return hs.some(h => {
 297→            if (!h || !Array.isArray(h.acceptItems)) return false;
 298→
 299→            const accepts = h.acceptItems.map(x => typeof x === 'string' ? { id: x } : x);
 300→            if (!accepts.some(a => a?.id === itemId)) return false;
 301→
 302→            if (h.requireItems && !this._hasAll(h.requireItems)) return false;
 303→            if (h.requireFlags && !this._hasAllFlags(h.requireFlags)) return false;
 304→
 305→            return true;
 306→        });
 307→    }
 308→
 309→    // --- renderers --------------------------------------------------------------
 310→
 311→    _renderHotspots() {
 312→        this.hotspotLayer.innerHTML = '';
 313→        const hotspots = this.currentScene.hotspots || [];
 314→
 315→        hotspots.forEach((h, idx) => {
 316→            const el = document.createElement('button');
 317→            el.className = 'hotspot';
 318→
 319→            // Default render rectangle (can be overridden by state)
 320→            let visualRect = h.rect;
 321→
 322→            // STATE LOGIC: Find the first matching state (Priority List)
 323→            // The engine checks states from top to bottom. The first one with satisfied requireFlags wins.
 324→            let activeState = null;
 325→            if (h.states && Array.isArray(h.states)) {
 326→                activeState = h.states.find(s => {
 327→                    // If no flags required, it's a default/fallback state
 328→                    if (!s.requireFlags) return true;
 329→                    // Otherwise check if all flags are present
 330→                    return this._hasAllFlags(s.requireFlags);
 331→                });
 332→            }
 333→
 334→            // APPLY ACTIVE STATE
 335→            if (activeState) {
 336→                // 1. CSS Class (e.g., "state-success", "state-locked")
 337→                if (activeState.cssClass) {
 338→                    el.classList.add(activeState.cssClass);
 339→                }
 340→
 341→                // 2. Content (text label, icon, symbol)
 342→                if (activeState.content) {
 343→                    const span = document.createElement('span');
 344→                    span.className = 'hs-content';
 345→                    span.textContent = this._text(activeState.content);
 346→                    el.appendChild(span);
 347→                }
 348→
 349→                // 3. Image Overlay (e.g., specific item graphic)
 350→                if (activeState.image) {
 351→                    const img = document.createElement('img');
 352→                    img.src = this._resolveAsset(activeState.image);
 353→                    img.className = 'hs-image';
 354→                    el.appendChild(img);
 355→                }
 356→
 357→                // 4. Rect Override (if the visual state has different dimensions than the hit area)
 358→                if (activeState.rect) {
 359→                    visualRect = activeState.rect;
 360→                }
 361→
 362→                // 5. Interactivity (disable clicking if the state is final/passive)
 363→                if (activeState.clickable === false) {
 364→                    el.style.pointerEvents = 'none';
 365→                    el.tabIndex = -1;
 366→                }
 367→            }
 368→
 369→            // Apply calculated geometry
 370→            el.style.left = visualRect.x + '%';
 371→            el.style.top = visualRect.y + '%';
 372→            el.style.width = visualRect.w + '%';
 373→            el.style.height = visualRect.h + '%';
 374→
 375→            // Bind interactions (only if not disabled by state)
 376→            if (!activeState || activeState.clickable !== false) {
 377→                el.setAttribute('data-index', String(idx));
 378→
 379→                // Tooltip: prefer state label, fallback to hotspot label
 380→                const label = (activeState && activeState.label) || h.label;
 381→                if (label) el.title = this._text(label);
 382→
 383→                el.addEventListener('click', (e) => {
 384→                    // Editor guard
 385→                    if (document.body.classList.contains('editor-on')) {
 386→                        e.preventDefault(); e.stopPropagation(); return;
 387→                    }
 388→                    e.preventDefault();
 389→                    this._activateHotspot(h).catch(err => this._msg(String(err)));
 390→                });
 391→
 392→                // --- Drop handling for item drag & drop ---
 393→                if (h.acceptItems && Array.isArray(h.acceptItems)) {
 394→                    this._setupHotspotDropHandlers(el, h, idx);
 395→                }
 396→            }
 397→
 398→            this.hotspotLayer.appendChild(el);
 399→        });
 400→    }
 401→
 402→    /**
 403→     * Sets up drag & drop handlers for a hotspot that accepts items.
 404→     * @param {HTMLElement} el - The hotspot element.
 405→     * @param {object} hs - The hotspot configuration.
 406→     * @param {number} idx - The hotspot index.
 407→     */
 408→    _setupHotspotDropHandlers(el, hs, idx) {
 409→        // HTML5 Drag API - dragover is required to allow drop
 410→        el.addEventListener('dragover', (e) => {
 411→            const itemId = e.dataTransfer.types.includes('text/plain') ? 'pending' : null;
 412→            if (itemId) {
 413→                e.preventDefault();
 414→                e.dataTransfer.dropEffect = 'move';
 415→                el.classList.add('drop-target');
 416→            }
 417→        });
 418→
 419→        el.addEventListener('dragleave', (e) => {
 420→            el.classList.remove('drop-target');
 421→        });
 422→
 423→        el.addEventListener('drop', async (e) => {
 424→            e.preventDefault();
 425→            el.classList.remove('drop-target');
 426→
 427→            const itemId = e.dataTransfer.getData('text/plain');
 428→            if (!itemId) return;
 429→
 430→            this._dbg('[DROP] Item dropped on hotspot:', itemId, hs);
 431→            await this._handleItemDropOnHotspot(itemId, hs);
 432→        });
 433→    }
 434→
 435→    async _activateHotspot(h) {
 436→        console.log('[HOTSPOT] Activation triggered:', h.type, h);
 437→
 438→        // 1. Use-mode guard (pokud držíme předmět a hotspot ho neumí přijmout)
 439→        // Pokud hráč drží předmět, ale klikne na něco, co předměty nebere -> chyba.
 440→        if (this.state.useItemId && !h.acceptItems) {
 441→            this.toast(this._t('engine.use.notApplicable', 'Tento předmět tady nelze použít.'), 2500);
 442→            this.exitUseMode();
 443→            return;
 444→        }
 445→
 446→        // 2. Requirements check (Prerekvizity)
 447→        // Kontrola, zda má hráč potřebné předměty v inventáři (pokud jsou vyžadovány)
 448→        if (h.requireItems && !this._hasAll(h.requireItems)) {
 449→            this._msg(this._t('engine.missingItems', 'Něco ti chybí…'));
 450→            return;
 451→        }
 452→        // Kontrola, zda jsou splněny herní flagy (např. odemčeno)
 453→        if (h.requireFlags && !this._hasAllFlags(h.requireFlags)) {
 454→            this._msg(this._t('engine.needUnlock', 'Nejprve musíš něco odemknout…'));
 455→            return;
 456→        }
 457→
 458→        // 3. Item Usage (Accept items) - Pokud hotspot přijímá předměty
 459→        if (h.acceptItems && Array.isArray(h.acceptItems)) {
 460→            const selected = this.state.useItemId;
 461→            // Normalizace acceptItems (může to být string nebo objekt)
 462→            const accepts = h.acceptItems.map(x => (typeof x === 'string' ? {id: x, consume: false} : x));
 463→
 464→            // Zkusíme najít, zda vybraný předmět je v seznamu povolených
 465→            const match = selected ? accepts.find(a => a.id === selected) : null;
 466→
 467→            if (!match) {
 468→                // Hráč drží předmět, ale ten sem nepatří
 469→                if (selected) {
 470→                    this.toast(this._t('engine.use.notApplicable', 'Tento předmět tady nelze použít.'), 2500);
 471→                    this.exitUseMode();
 472→                    return;
 473→                }
 474→                // Hráč nic nedrží, ale hotspot vyžaduje předmět -> zobrazíme hint?
 475→                const allowHint = (h.showNeedHint !== false) && (this.data?.settings?.hints?.acceptNeed !== false);
 476→                if (allowHint) {
 477→                    const need = accepts.map(a => this._itemLabel(a.id)).filter(Boolean).join(', ');
 478→                    this.toast(this._t('engine.use.needItem', 'Potřebuješ použít: {need}.', {need}), 3500);
 479→                }
 480→                return;
 481→            }
 482→
 483→            // SHODA: Hráč použil správný předmět
 484→            if (match.consume) this._removeItemFromInventory(match.id);
 485→            this.exitUseMode();
 486→
 487→            if (h.onApply) await this._applyActions(h.onApply);
 488→            else this.toast(this._t('engine.use.applied', 'Předmět byl použit.'), 2200);
 489→            return;
 490→        }
 491→
 492→        // 4. Specific Actions (Rozcestník typů hotspotů)
 493→
 494→        // --- NOVÁ ČÁST: Obecná akce Apply (bez předmětu) ---
 495→        // Toto je to, co potřebujeme pro spuštění videa kliknutím na šipku
 496→        if (h.type === 'apply') {
 497→            console.log('[HOTSPOT] Executing Apply actions:', h.onApply);
 498→            if (h.onApply) {
 499→                await this._applyActions(h.onApply);
 500→            }
 501→            return;
 502→        }
 503→        // ---------------------------------------------------
 504→
 505→        if (h.type === 'goTo') {
 506→            await this.goto(h.target);
 507→            return;
 508→        }
 509→
 510→        if (h.type === 'pickup') {
 511→            if (!this.state.inventory.includes(h.itemId)) {
 512→                this.state.inventory.push(h.itemId);
 513→                this._renderInventory();
 514→                this._msg(this._t('engine.pickedUp', 'Sebráno: {name}', {name: this._itemLabel(h.itemId)}));
 515→                await this._stateChanged();
 516→            } else {
 517→                this._msg(this._t('engine.alreadyHave', 'Už máš: {name}', {name: this._itemLabel(h.itemId)}));
 518→            }
 519→            return;
 520→        }
 521→
 522→        if (h.type === 'puzzle') {
 523→            const ref = h.puzzleRef || h.puzzle?.ref;
 524→            if (!ref) {
 525→                console.error('Puzzle hotspot missing puzzleRef');
 526→                return;
 527→            }
 528→
 529→            const options = h.options || h.puzzle?.options || {};
 530→            const background = h.puzzleBackground || h.puzzle?.background || null;
 531→            const solvedKey = 'solved:pz:' + ref;
 532→
 533→            if (this.state.solved[solvedKey]) {
 534→                await this._applyActions(h.onSuccess);
 535→                return;
 536→            }
 537→
 538→            const res = await this._openPuzzleByRef({
 539→                ref,
 540→                rect: h.rect || {x: 0, y: 0, w: 100, h: 100},
 541→                options,
 542→                background
 543→            });
 544→
 545→            if (options.aggregateOnly) {
 546→                this._appendPuzzleResult({ref, ok: !!res?.ok, detail: res?.detail || null});
 547→                if (res?.ok && h.onSuccess) await this._applyActions(h.onSuccess);
 548→                if (!res?.ok && h.onFail) await this._applyActions(h.onFail);
 549→                return;
 550→            }
 551→
 552→            if (res?.ok) {
 553→                this._msg(this._t('engine.solved', 'Vyřešeno!'));
 554→                this.state.solved[solvedKey] = true;
 555→                this._saveState();
 556→                await this._applyActions(h.onSuccess);
 557→            } else {
 558→                if (h.onFail) await this._applyActions(h.onFail);
 559→                else this._msg(this._t('engine.puzzleFailed', 'Puzzle nevyřešeno.'));
 560→            }
 561→            return;
 562→        }
 563→
 564→        if (h.type === 'puzzleList') {
 565→            const ok = await openListModal(this, {
 566→                items: h.items || h.puzzleList?.items || [],
 567→                rect: h.rect || {x: 0, y: 0, w: 100, h: 100},
 568→                background: h.puzzleList?.background || h.background,
 569→                aggregateOnly: !!(h.options?.aggregateOnly),
 570→                blockUntilSolved: !!(h.options?.blockUntilSolved),
 571→                puzzlesById: this.data.puzzles
 572→            });
 573→            if (ok) {
 574→                if (h.onSuccess) await this._applyActions(h.onSuccess);
 575→            } else {
 576→                if (h.onFail) await this._applyActions(h.onFail);
 577→            }
 578→            return;
 579→        }
 580→
 581→        if (h.type === 'dialog') {
 582→            await this.openDialog(h.dialogId);
 583→            return;
 584→        }
 585→
 586→        // Fallback pro neznámé typy
 587→        this._msg('Unknown hotspot type: ' + h.type);
 588→        console.warn('Unknown hotspot type:', h);
 589→    }
