 592→
 593→    async _ensurePuzzlesLoaded() {
 594→        // pokud už jsou v this.data.puzzles ve formátu mapy, hotovo
 595→        if (this.data?.puzzles && typeof this.data.puzzles === 'object' && !Array.isArray(this.data.puzzles)) {
 596→            return;
 597→        }
 598→
 599→        const url = this._resolveAsset('puzzles.json');
 600→        let json = {};
 601→        try {
 602→            const r = await fetch(url, {cache: 'no-cache'});
 603→            if (r.ok) json = await r.json();
 604→        } catch {
 605→            // ignore
 606→        }
 607→
 608→        // 1) { byId: { ... } }
 609→        if (json && typeof json === 'object' && json.byId && typeof json.byId === 'object') {
 610→            this.data.puzzles = json.byId;
 611→            return;
 612→        }
 613→        // 2) [ { id, kind, ... }, ... ]
 614→        if (Array.isArray(json)) {
 615→            this.data.puzzles = Object.fromEntries(json.filter(p => p?.id).map(p => [p.id, p]));
 616→            return;
 617→        }
 618→        // 3) { id1:{...}, id2:{...} }
 619→        if (json && typeof json === 'object') {
 620→            this.data.puzzles = json;
 621→            return;
 622→        }
 623→
 624→        // fallback, empty map
 625→        this.data.puzzles = {};
 626→    }
 627→
 628→    async _openPuzzleByRef({ref, rect, options = {}, background = null}) {
 629→        await this._ensurePuzzlesLoaded();
 630→
 631→        // If background not provided in hotspot, try to get it from puzzle config
 632→        if (!background) {
 633→            const puzzleCfg = this.data.puzzles?.[ref];
 634→            if (puzzleCfg?.background) {
 635→                background = puzzleCfg.background;
 636→            }
 637→        }
 638→
 639→        return await new Promise((resolve) => {
 640→            const runner = createPuzzleRunner({
 641→                ref,
 642→                rect,
 643→                background: background ? this._resolveAsset(background) : null,
 644→                instanceOptions: options,
 645→                puzzlesById: this.data.puzzles || {},
 646→                i18n: (k) => this._t(k, k),
 647→                engine: this,
 648→                onResolve: (result) => {
 649→                    try {
 650→                        runner?.unmount?.();
 651→                    } catch (_) {
 652→                    }
 653→                    resolve(result || {ok: false});
 654→                }
 655→            });
 656→
 657→            runner.mountInto(this.hotspotLayer);
 658→        });
 659→    }
