 669→    // --- apply action bundles (success/fail/shared) -----------------------------
 670→
 671→    /**
 672→     * Executes a bundle of actions (used by Hotspots, Puzzles onSuccess/onFail, Video onEnd).
 673→     * Supports: toast, message, openDialog, highlightHotspot, playVideo, giveItem, setFlags, clearFlags, goTo.
 674→     */
 675→    async _applyActions(actions) {
 676→        if (!actions) return;
 677→
 678→        // 1. Visual Feedback
 679→        if (actions.toast?.text) {
 680→            this.toast(this._text(actions.toast.text), actions.toast.ms ?? 5000);
 681→        }
 682→        if (actions.message) {
 683→            this._msg(this._text(actions.message));
 684→        }
 685→
 686→        // 2. Dialogs (Blocking)
 687→        if (actions.openDialog) {
 688→            await this.openDialog(actions.openDialog);
 689→        }
 690→
 691→        // 3. Highlight Hotspot
 692→        if (actions.highlightHotspot?.rect) {
 693→            const h = actions.highlightHotspot;
 694→            this._enqueueOrShowHighlight({
 695→                sceneId: h.sceneId || this.currentScene?.id,
 696→                rect: h.rect,
 697→                ms: h.ms ?? 3500,
 698→                outline: !!h.outline
 699→            });
 700→        }
 701→
 702→        // 4. Play Video (Blocking)
 703→        if (actions.playVideo?.src) {
 704→            await this._playVideo(actions.playVideo);
 705→
 706→            if (actions.playVideo.onEnd) {
 707→                await this._applyActions(actions.playVideo.onEnd);
 708→            }
 709→        }
 710→
 711→        // 5. Logic (Items / Flags)
 712→        let changed = false;
 713→
 714→        if (actions.giveItem) {
 715→            const give = Array.isArray(actions.giveItem) ? actions.giveItem : [actions.giveItem];
 716→            let added = 0;
 717→            for (const id of give) {
 718→                if (!this.state.inventory.includes(id)) {
 719→                    this.state.inventory.push(id);
 720→                    added++;
 721→                    changed = true;
 722→                }
 723→            }
 724→            if (added) this._renderInventory();
 725→        }
 726→
 727→        if (actions.setFlags) {
 728→            if (Array.isArray(actions.setFlags)) {
 729→                for (const f of actions.setFlags) {
 730→                    if (!this.state.flags[f]) {
 731→                        this.state.flags[f] = true;
 732→                        changed = true;
 733→                    }
 734→                }
 735→            } else {
 736→                for (const [k, v] of Object.entries(actions.setFlags)) {
 737→                    if (!!this.state.flags[k] !== !!v) {
 738→                        this.state.flags[k] = !!v;
 739→                        changed = true;
 740→                    }
 741→                }
 742→            }
 743→        }
 744→
 745→        if (actions.clearFlags && Array.isArray(actions.clearFlags)) {
 746→            for (const f of actions.clearFlags) {
 747→                if (this.state.flags[f]) {
 748→                    delete this.state.flags[f];
 749→                    changed = true;
 750→                }
 751→            }
 752→        }
 753→
 754→        // 6. State & Navigation
 755→        if (changed) {
 756→            this._renderHotspots();
 757→            await this._stateChanged();
 758→            if (this.currentScene) {
 759→                this._drainHighlightsForScene(this.currentScene.id);
 760→            }
 761→        }
 762→
 763→        if (actions.goTo) {
 764→            await this.goto(actions.goTo);
 765→        }
 766→    }
 767→
 768→    // backward compatibility
 769→    async _applyOnSuccess(actions) {
 770→        return this._applyActions(actions);
 771→    }
