 782→    _renderInventory() {
 783→        this.inventoryRoot.innerHTML = '';
 784→        (this.state.inventory || []).forEach(id => {
 785→            const item = this._itemById(id);
 786→            if (!item) return;
 787→
 788→            const wrap = document.createElement('button');
 789→            wrap.type = 'button';
 790→            wrap.className = 'item';
 791→            wrap.draggable = true; // Enable HTML5 drag
 792→            wrap.dataset.itemId = id;
 793→            if (this.state.useItemId === id) wrap.classList.add('selected');
 794→            wrap.title = this._t('engine.item.hint', 'Klikni pro náhled, táhni pro použití');
 795→
 796→            if (item.icon) {
 797→                const img = document.createElement('img');
 798→                img.src = this._resolveAsset(item.icon);
 799→                img.alt = this._text(item.label) || id;
 800→                img.draggable = false; // Prevent image from being dragged separately
 801→                wrap.appendChild(img);
 802→            }
 803→            const span = document.createElement('span');
 804→            span.textContent = this._text(item.label) || id;
 805→            wrap.appendChild(span);
 806→
 807→            // --- Drag & Drop handlers ---
 808→            this._setupItemDragDrop(wrap, item);
 809→
 810→            // --- Click handler (for preview) ---
 811→            // Using pointerup with tracking to differentiate from drag
 812→            let pointerDownTime = 0;
 813→            let pointerMoved = false;
 814→
 815→            wrap.addEventListener('pointerdown', (e) => {
 816→                pointerDownTime = Date.now();
 817→                pointerMoved = false;
 818→            });
 819→
 820→            wrap.addEventListener('pointermove', () => {
 821→                pointerMoved = true;
 822→            });
 823→
 824→            wrap.addEventListener('pointerup', (e) => {
 825→                // Ignore if this was a drag operation
 826→                if (pointerMoved && Date.now() - pointerDownTime > 150) return;
 827→
 828→                // Toggle use mode if already selected
 829→                if (this.state.useItemId === id) {
 830→                    this.exitUseMode();
 831→                    return;
 832→                }
 833→                this._inspectItem(item);
 834→            });
 835→
 836→            // Prevent default click to avoid double-firing
 837→            wrap.addEventListener('click', (e) => {
 838→                e.preventDefault();
 839→            });
 840→
 841→            this.inventoryRoot.appendChild(wrap);
 842→        });
 843→    }
