1013→    /**
1014→     * Updates the visual highlight for the hotspot currently under the drag cursor.
1015→     * @param {HTMLElement|null} hotspotEl - The hotspot element or null.
1016→     */
1017→    _updateHotspotDropHighlight(hotspotEl) {
1018→        const hotspots = this.hotspotLayer.querySelectorAll('.hotspot');
1019→        hotspots.forEach(el => {
1020→            el.classList.toggle('drop-target', el === hotspotEl && el.dataset.acceptsItems === 'true');
1021→        });
1022→    }
