1035→    /**
1036→     * Checks if a hotspot accepts a specific item.
1037→     * @param {object} hs - The hotspot configuration.
1038→     * @param {string} itemId - The item ID to check.
1039→     * @returns {boolean}
1040→     */
1041→    _hotspotAcceptsItem(hs, itemId) {
1042→        if (!hs || !Array.isArray(hs.acceptItems)) return false;
1043→        const accepts = hs.acceptItems.map(x => typeof x === 'string' ? { id: x } : x);
1044→        if (!accepts.some(a => a?.id === itemId)) return false;
1045→        if (hs.requireItems && !this._hasAll(hs.requireItems)) return false;
1046→        if (hs.requireFlags && !this._hasAllFlags(hs.requireFlags)) return false;
1047→        return true;
1048→    }
