1050→    /**
1051→     * Handles dropping an item on a hotspot.
1052→     * @param {string} itemId - The dropped item ID.
1053→     * @param {object} hs - The target hotspot configuration.
1054→     */
1055→    async _handleItemDropOnHotspot(itemId, hs) {
1056→        if (!this._hotspotAcceptsItem(hs, itemId)) {
1057→            this.toast(this._t('engine.use.notApplicable', 'Tento předmět tady nelze použít.'), 2500);
1058→            return;
1059→        }
1060→
1061→        const accepts = hs.acceptItems.map(x => typeof x === 'string' ? { id: x, consume: false } : x);
1062→        const match = accepts.find(a => a.id === itemId);
1063→
1064→        if (match) {
1065→            if (match.consume) this._removeItemFromInventory(itemId);
1066→
1067→            if (hs.onApply) {
1068→                await this._applyActions(hs.onApply);
1069→            } else {
1070→                this.toast(this._t('engine.use.applied', 'Předmět byl použit.'), 2200);
1071→            }
1072→        }
1073→    }
