1284→    _enqueueOrShowHighlight({sceneId, rect, ms = 3500, outline = false}) {
1285→        if (!sceneId || sceneId === this.currentScene?.id) {
1286→            this._showHighlightRect(rect, ms, {outline});
1287→        } else {
1288→            this._pendingHighlights[sceneId] = this._pendingHighlights[sceneId] || [];
1289→            this._pendingHighlights[sceneId].push({rect, ms, outline});
