1477→    // --- video ---------------------------------------------------------------
1478→
1479→    /**
1480→     * Plays a video overlay or embedded video.
1481→     * Returns a Promise that resolves when the video ends or is skipped.
1482→     * @param {object} cfg - { src, mode, rect, delay, allowSkip, onEnd }
1483→     */
1484→    async _playVideo(cfg) {
1485→        const src = this._resolveAsset(cfg.src);
1486→
1487→        // 1. Delay logic (optional wait before showing video)
1488→        if (cfg.delay && cfg.delay > 0) {
1489→            await new Promise(resolve => setTimeout(resolve, cfg.delay));
1490→        }
1491→
1492→        return new Promise((resolve) => {
1493→            // Container setup
1494→            const wrapper = document.createElement('div');
1495→            wrapper.className = 'video-overlay';
1496→
1497→            // Mode handling (fullscreen vs rect)
1498→            if (cfg.mode === 'rect' && cfg.rect) {
1499→                wrapper.classList.add('mode-rect');
1500→                Object.assign(wrapper.style, {
1501→                    left: cfg.rect.x + '%',
1502→                    top: cfg.rect.y + '%',
1503→                    width: cfg.rect.w + '%',
1504→                    height: cfg.rect.h + '%'
1505→                });
1506→            } else {
1507→                wrapper.classList.add('mode-fullscreen');
1508→            }
1509→
1510→            // Video element
1511→            const video = document.createElement('video');
1512→            video.src = src;
1513→            video.autoplay = true;
1514→            video.playsInline = true; // Critical for iOS/Tablets to prevent native fullscreen force
1515→            video.controls = false;   // We handle interaction manually
1516→
1517→            wrapper.appendChild(video);
1518→
1519→            // Skip button (optional)
1520→            if (cfg.allowSkip !== false) {
1521→                const skipBtn = document.createElement('button');
1522→                skipBtn.className = 'video-skip';
1523→                skipBtn.innerHTML = '&times;'; // Close icon
1524→                skipBtn.title = 'Skip Video';
1525→
1526→                // Skip handler
1527→                skipBtn.addEventListener('click', (e) => {
1528→                    e.stopPropagation();
1529→                    finish();
1530→                });
1531→                wrapper.appendChild(skipBtn);
1532→
1533→                // Allow clicking outside/on wrapper to skip (only in fullscreen mode)
1534→                if (cfg.mode !== 'rect') {
1535→                    wrapper.addEventListener('click', finish);
1536→                }
1537→            }
1538→
1539→            // Mount to DOM (highest layer)
1540→            document.body.appendChild(wrapper);
1541→
1542→            // Lifecycle end handler
1543→            let finished = false;
1544→            function finish() {
1545→                if (finished) return;
1546→                finished = true;
1547→
1548→                video.pause();
1549→                if (wrapper.parentNode) wrapper.parentNode.removeChild(wrapper);
1550→
1551→                // Execute follow-up actions (onEnd) if defined
1552→                // Note: We resolve first to unblock the engine, logic happens outside
1553→                resolve();
1554→            }
1555→
1556→            // Event listeners
1557→            video.addEventListener('ended', finish);
1558→
1559→            video.addEventListener('error', (e) => {
1560→                console.error('[VIDEO] Error playing:', src, e);
1561→                finish(); // Don't block the game on error
1562→            });
1563→
1564→            // Start playback with error handling (autoplay policy)
1565→            video.play().catch(err => {
1566→                console.warn('[VIDEO] Autoplay blocked or failed:', err);
1567→                // If autoplay is blocked, we might need a "Click to Play" UI here.
1568→                // For now, we assume user interaction has already happened (dialog click).
1569→            });
1570→        });
1571→    }
