1575→    async _ensureDialogsLoaded() {
1576→        if (this.dialogsData || !this.dialogsUrl) return;
1577→        try {
1578→            this._dbg('_ensureDialogsLoaded(): fetching', this.dialogsUrl);
1579→            const r = await fetch(this.dialogsUrl, {cache: 'no-cache'});
1580→            const json = await r.json();
1581→            this.dialogsData = json || {dialogs: [], characters: []};
1582→            this._dbg('_ensureDialogsLoaded(): fetched OK', {dialogs: this.dialogsData.dialogs?.length ?? 0});
1583→        } catch (err) {
1584→            console.error('[GAME] _ensureDialogsLoaded() failed:', err);
1585→            this.dialogsData = {dialogs: [], characters: []};
1586→        }
1587→    }
1588→
1589→    async openDialog(arg) {
1590→        const id = (typeof arg === 'string') ? arg : (arg && arg.id);
1591→        this._dbg('openDialog() begin →', {id});
1592→        if (!id) {
1593→            console.warn('[GAME] openDialog() called without id');
1594→            return;
1595→        }
1596→        await this._ensureDialogsLoaded();
1597→        if (!this.dialogsData) {
1598→            this._msg('Dialogy nejsou k dispozici.');
1599→            return;
1600→        }
1601→        return await this.dialogUI.open(id);
1602→    }
