1611→    _loadState() {
1612→        try {
1613→            const raw = localStorage.getItem('leeuwenhoek_escape_state');
1614→            return raw ? JSON.parse(raw) : null;
1615→        } catch {
1616→            return null;
1617→        }
1618→    }
