  1→/**
  2→ * engine/dialogs.js
  3→ * Handles the Dialog UI, character portraits, typewriter text effects,
  4→ * and branching conversation flow.
  5→ * * Architecture Note:
  6→ * Portraits are anchored to the dialog panel via .dlg-stage (bottom: 0).
  7→ * The open() method returns a Promise that resolves only when the dialog closes,
  8→ * allowing the main Engine to await the conversation.
  9→ */
 10→
 11→export class DialogUI {
 12→    /**
 13→     * @param {import('./engine.js').Game} game
 14→     */
 15→    constructor(game) {
 16→        this.game = game;
 17→        this.overlay = null; // Root DOM element (.dlg-overlay)
 18→
 19→        /** @type {object|null} Current dialog state { id, dlg, idx, leftChar, rightChar, leftMirror, rightMirror ... } */
 20→        this.active = null;
 21→
 22→        this._typewriterRunning = false;
 23→        this._typewriterSkipped = false;
 24→
 25→        /** @type {Function|null} Resolver for the Promise returned by open() */
 26→        this._closeResolver = null;
 27→
 28→        /** * Input lock to prevent race conditions during async transitions.
 29→         * Prevents "double-click" skipping issues.
 30→         * @type {boolean}
 31→         */
 32→        this._busy = false;
 33→
 34→        this.typewriterConfig = {
 35→            enabled: true,
 36→            speed: 15,        // ms per char
 37→            skipOnClick: true // clicking skips animation to end
 38→        };
 39→    }
 40→
 41→    /**
 42→     * Non-blocking sleep helper.
 43→     * @param {number} ms
 44→     */
 45→    _sleep(ms) {
 46→        return new Promise(resolve => setTimeout(resolve, ms));
 47→    }
 48→
 49→    // --- Visual Effects ---
 50→
 51→    /**
 52→     * Renders text character by character.
 53→     * @param {HTMLElement} element
 54→     * @param {string} text
 55→     */
 56→    async _typewriterText(element, text) {
 57→        if (!element || !text || !this.typewriterConfig.enabled) {
 58→            if (element) element.textContent = text;
 59→            return;
 60→        }
 61→
 62→        this._typewriterRunning = true;
 63→        this._typewriterSkipped = false;
 64→        element.textContent = '';
 65→
 66→        const chars = text.split('');
 67→        for (let i = 0; i < chars.length; i++) {
 68→            if (this._typewriterSkipped) {
 69→                element.textContent = text;
 70→                break;
 71→            }
 72→            element.textContent += chars[i];
 73→            await this._sleep(this.typewriterConfig.speed);
 74→        }
 75→
 76→        this._typewriterRunning = false;
 77→    }
 78→
 79→    _skipTypewriter() {
 80→        if (this._typewriterRunning) {
 81→            this._typewriterSkipped = true;
 82→        }
 83→    }
 84→
 85→    /**
 86→     * Visually highlights the selected choice button briefly before proceeding.
 87→     * @param {HTMLElement} btn
 88→     */
 89→    async _flashChoice(btn) {
 90→        if (!btn || btn.__flashing) return;
 91→        btn.__flashing = true;
 92→        btn.classList.add('dlg-choice--selected');
 93→        btn.setAttribute('disabled', 'disabled');
 94→        try {
 95→            await this._sleep(220);
 96→        } finally {
 97→            btn.classList.remove('dlg-choice--selected');
 98→            btn.removeAttribute('disabled');
 99→            btn.__flashing = false;
100→        }
101→    }
102→
103→    // --- Debugging ---
104→
105→    _dbgOn() {
106→        try { return new URLSearchParams(location.search).get('debug') === '1'; } catch { return false; }
107→    }
108→
109→    _dbg(...a) {
110→        if (this._dbgOn()) console.debug('[DLG]', ...a);
111→    }
112→
113→    // --- DOM Mounting ---
114→
115→    _ensureMounted() {
116→        if (this.overlay) return;
117→
118→        const root = document.createElement('div');
119→        root.className = 'dlg-overlay hidden';
120→        root.innerHTML = `
121→            <div class="dlg-blocker"></div>
122→            <div class="dlg-stage">
123→                <div class="dlg-char left"><img class="dlg-char-img" alt=""></div>
124→                <div class="dlg-char right"><img class="dlg-char-img" alt=""></div>
125→            </div>
126→            <div class="dlg-panel">
127→                <div class="dlg-nameplate"></div>
128→                <div class="dlg-text"></div>
129→                <div class="dlg-choices"></div>
130→                <div class="dlg-continue"></div>
131→            </div>
132→        `;
133→
134→        // I18n for "tap to continue" hint
135→        const cont = root.querySelector('.dlg-continue');
136→        if (cont) cont.textContent = this.game._text('@ui.tapToNext@Klepni pro pokračování');
137→
138→        // Blocker layer to capture clicks outside the panel
139→        const blocker = root.querySelector('.dlg-blocker');
140→        if (blocker) {
141→            Object.assign(blocker.style, {
142→                position: 'absolute',
143→                inset: '0',
144→                zIndex: '1050',
145→                pointerEvents: 'auto',
146→                background: 'transparent'
147→            });
148→
149→            blocker.addEventListener('click', (e) => {
150→                e.stopPropagation();
151→                e.preventDefault();
152→                this._handleInput();
153→            });
154→        }
155→
156→        // Global click handler for advancement
157→        root.addEventListener('click', (e) => {
158→            if (e.target?.closest('.dlg-choices')) return;
159→            this._handleInput();
160→        });
161→
162→        // Mount into scene container or body
163→        const host = this.game?.sceneImage?.closest('#sceneContainer') ||
164→            this.game?.sceneImage?.parentElement ||
165→            document.body;
166→        host.appendChild(root);
167→        this.overlay = root;
168→
169→        // Responsive handling
170→        const onResize = () => {
171→            const compact = window.innerHeight < 560;
172→            this.overlay.classList.toggle('dlg-compact', compact);
173→        };
174→        window.addEventListener('resize', onResize);
175→        onResize();
176→    }
177→
178→    /**
179→     * Centralized input handler. Skips typewriter or advances dialog.
180→     */
181→    _handleInput() {
182→        if (this._busy) return;
183→
184→        if (this._typewriterRunning && this.typewriterConfig.skipOnClick) {
185→            this._skipTypewriter();
186→        } else {
187→            void this.next();
188→        }
189→    }
190→
191→    _show() {
192→        if (!this.overlay) this._ensureMounted();
193→        this.overlay.classList.remove('hidden');
194→    }
195→
196→    _hide() {
197→        if (this.overlay) this.overlay.classList.add('hidden');
198→    }
199→
200→    // --- Core Lifecycle ---
201→
202→    /**
203→     * Opens a dialog sequence.
204→     * Returns a Promise that resolves when the dialog is closed.
205→     * @param {string} dialogId
206→     * @returns {Promise<void>}
207→     */
208→    /**
209→     * Opens a dialog sequence.
210→     * Preloads initial character assets to prevent "flash of old content".
211→     * Returns a Promise that resolves when the dialog is closed.
212→     * @param {string} dialogId
213→     * @returns {Promise<void>}
214→     */
215→    async open(dialogId) {
216→        this._dbg('open() →', dialogId);
217→
218→        const list = Array.isArray(this.game.dialogsData?.dialogs) ? this.game.dialogsData.dialogs : [];
219→
220→        // Resolve ID
221→        let dlg = list.find(d => d?.id === dialogId);
222→        if (!dlg && typeof dialogId === 'string' && dialogId.includes('.')) {
223→            const tail = dialogId.split('.').pop();
224→            dlg = list.find(d => d?.id === tail);
225→        }
226→        if (!dlg) {
227→            this._dbg('open() abort: not found', dialogId);
228→            return;
229→        }
230→
231→        // --- PRELOAD PHASE START ---
232→        const leftCharDef = dlg.left;
233→        const rightCharDef = dlg.right;
234→
235→        const assetsToLoad = [];
236→
237→        if (leftCharDef) {
238→            const char = this._findCharacter(leftCharDef.characterId);
239→            const pose = leftCharDef.defaultPose || 'idle';
240→            if (char && char.poses && char.poses[pose]) {
241→                assetsToLoad.push(this.game._resolveAsset(char.poses[pose]));
242→            }
243→        }
244→        if (rightCharDef) {
245→            const char = this._findCharacter(rightCharDef.characterId);
246→            const pose = rightCharDef.defaultPose || 'idle';
247→            if (char && char.poses && char.poses[pose]) {
248→                assetsToLoad.push(this.game._resolveAsset(char.poses[pose]));
249→            }
250→        }
251→
252→        if (assetsToLoad.length > 0) {
253→            await Promise.all(assetsToLoad.map(src => {
254→                return new Promise(resolve => {
255→                    const img = new Image();
256→                    img.onload = resolve;
257→                    img.onerror = resolve; // Nechceme zaseknout hru, když obrázek chybí
258→                    img.src = src;
259→                });
260→            }));
261→        }
262→        // --- PRELOAD PHASE END ---
263→
264→        this._ensureMounted();
265→        this._show();
266→
267→        const lImg = this.overlay.querySelector('.dlg-char.left .dlg-char-img');
268→        const rImg = this.overlay.querySelector('.dlg-char.right .dlg-char-img');
269→        if (lImg) lImg.src = '';
270→        if (rImg) rImg.src = '';
271→
272→        // Initialize state
273→        this.active = {
274→            id: dialogId,
275→            dlg,
276→            idx: 0,
277→            leftChar: dlg.left ? this._findCharacter(dlg.left.characterId) : null,
278→            rightChar: dlg.right ? this._findCharacter(dlg.right.characterId) : null,
279→            leftPose: dlg.left?.defaultPose || null,
280→            rightPose: dlg.right?.defaultPose || null,
281→            leftDefaultMirror: !!dlg.left?.mirror,
282→            rightDefaultMirror: !!dlg.right?.mirror
283→        };
284→
285→        if (dlg.typewriter !== undefined) {
286→            if (typeof dlg.typewriter === 'boolean') {
287→                this.typewriterConfig.enabled = dlg.typewriter;
288→            } else if (typeof dlg.typewriter === 'object') {
289→                this.typewriterConfig = { ...this.typewriterConfig, ...dlg.typewriter };
290→            }
291→        }
292→
293→        this._renderStep();
294→
295→        return new Promise(resolve => {
296→            this._closeResolver = resolve;
297→        });
298→    }
299→
300→    /**
301→     * Force close the dialog (e.g. on game restart).
302→     * In normal flow, _end() handles the closing logic.
303→     */
304→    async close() {
305→        this.active = null;
306→        this._hide();
307→
308→        if (this._closeResolver) {
309→            this._closeResolver();
310→            this._closeResolver = null;
311→        }
312→    }
313→
314→    refresh() {
315→        if (!this.active) return;
316→        this._renderStep();
317→    }
318→
319→    // --- Character & Asset Resolution ---
320→
321→    _findCharacter(charId) {
322→        const chars = Array.isArray(this.game.dialogsData?.characters) ? this.game.dialogsData.characters : [];
323→
324→        // Special handling for 'hero' placeholder
325→        if (charId === 'hero') {
326→            const hero = this.game.getHero();
327→            const byId = chars.find(c => c?.id === hero.id);
328→            if (byId) return byId;
329→
330→            const tpl = chars.find(c => c?.id === 'hero');
331→            if (!tpl) return null;
332→
333→            // Clone and replace placeholders
334→            const clone = JSON.parse(JSON.stringify(tpl));
335→            clone.name = this.game._text(hero.name) || hero.name || clone.name;
336→            const poses = clone.poses || {};
337→            for (const [k, v] of Object.entries(poses)) {
338→                let p = String(v || '');
339→                p = p.replaceAll('{heroId}', hero.id);
340→                p = p.replaceAll('{heroBase}', hero.assetsBase || '');
341→                p = p.replace(/\/hero\//g, `/${hero.id}/`);
342→                p = p.replace(/\/hero(?=\/|$)/g, `/${hero.id}`);
343→                poses[k] = p;
344→            }
345→            clone.poses = poses;
346→            return clone;
347→        }
348→
349→        return chars.find(c => c?.id === charId) || null;
350→    }
351→
352→    _els(side) {
353→        const wrap = this.overlay?.querySelector(side === 'left' ? '.dlg-char.left' : '.dlg-char.right');
354→        return {wrap, img: wrap?.querySelector('.dlg-char-img')};
355→    }
356→
357→    _setSpeaking(side) {
358→        const L = this.overlay?.querySelector('.dlg-char.left');
359→        const R = this.overlay?.querySelector('.dlg-char.right');
360→        L?.classList.remove('speaking');
361→        R?.classList.remove('speaking');
362→        this.overlay?.classList.remove('speaker-left', 'speaker-right');
363→
364→        if (side === 'left') {
365→            L?.classList.add('speaking');
366→            this.overlay?.classList.add('speaker-left');
367→        }
368→        if (side === 'right') {
369→            R?.classList.add('speaking');
370→            this.overlay?.classList.add('speaker-right');
371→        }
372→    }
373→
374→    /**
375→     * Updates character image.
376→     * @param {string} side - 'left' or 'right'
377→     * @param {string|null} poseOverride - specific pose to use, or null for default
378→     * @param {boolean} mirror - whether to flip the image horizontally
379→     */
380→    _applyPortrait(side, poseOverride = null, mirror = false) {
381→        const {img} = this._els(side);
382→        const actor = (side === 'left') ? this.active?.leftChar : this.active?.rightChar;
383→        const basePose = (side === 'left') ? this.active?.leftPose : this.active?.rightPose;
384→        const pose = poseOverride || basePose;
385→
386→        if (!img) return;
387→
388→        if (!actor) {
389→            img.src = '';
390→            img.style.display = 'none'; // FIX for Safari (hide frame)
391→            return;
392→        }
393→
394→        const poses = actor.poses || {};
395→        const src0 = (pose && poses[pose]) || poses.neutral || Object.values(poses)[0] || '';
396→
397→        if (src0) {
398→            img.src = this.game._resolveAsset(src0);
399→            img.alt = this.game._text(actor.name) || '';
400→            img.style.display = 'block';
401→        } else {
402→            img.src = '';
403→            img.style.display = 'none';
404→        }
405→
406→        // Apply mirror class if requested
407→        if (mirror) {
408→            img.classList.add('is-mirrored');
409→        } else {
410→            img.classList.remove('is-mirrored');
411→        }
412→    }
413→
414→    // --- Rendering ---
415→
416→    _renderStep() {
417→        const step = this.active?.dlg?.sequence?.[this.active?.idx ?? -1];
418→        if (!step) {
419→            // If index is out of bounds, we are done.
420→            void this._end();
421→            return;
422→        }
423→
424→        // Update poses
425→        if (step.leftPose) this.active.leftPose = step.leftPose;
426→        if (step.rightPose) this.active.rightPose = step.rightPose;
427→
428→        // Determine mirroring based on Defaults + Step Override
429→        // 1. Start with defaults defined in dialog config
430→        let mirrorLeft = this.active.leftDefaultMirror;
431→        let mirrorRight = this.active.rightDefaultMirror;
432→
433→        // 2. If step specifies mirror, apply it ONLY to the active speaker
434→        // (This allows transient flipping or overriding defaults)
435→        if (typeof step.mirror === 'boolean') {
436→            if (step.speaker === 'left') mirrorLeft = step.mirror;
437→            if (step.speaker === 'right') mirrorRight = step.mirror;
438→        }
439→
440→        // Visuals
441→        const sp = step.speaker === 'left' ? 'left' : (step.speaker === 'right' ? 'right' : null);
442→        this._setSpeaking(sp);
443→
444→        // Apply portraits with resolved mirror settings
445→        this._applyPortrait(
446→            'left',
447→            (step.pose && step.speaker === 'left') ? step.pose : null,
448→            mirrorLeft
449→        );
450→
451→        this._applyPortrait(
452→            'right',
453→            (step.pose && step.speaker === 'right') ? step.pose : null,
454→            mirrorRight
455→        );
456→
457→        // UI Elements
458→        const nameEl = this.overlay?.querySelector('.dlg-nameplate');
459→        const textEl = this.overlay?.querySelector('.dlg-text');
460→        const choicesEl = this.overlay?.querySelector('.dlg-choices');
461→
462→        if (nameEl) {
463→            let speakerName = '';
464→            if (step.speaker === 'left' && this.active.leftChar) speakerName = this.game._text(this.active.leftChar.name);
465→            if (step.speaker === 'right' && this.active.rightChar) speakerName = this.game._text(this.active.rightChar.name);
466→            nameEl.textContent = speakerName || '';
467→        }
468→        if (textEl) {
469→            const text = this.game._text(step.text || '');
470→            void this._typewriterText(textEl, text);
471→        }
472→
473→        // Choices
474→        if (choicesEl) {
475→            choicesEl.innerHTML = '';
476→            if (Array.isArray(step.choices) && step.choices.length) {
477→                step.choices.forEach(ch => {
478→                    const b = document.createElement('button');
479→                    b.type = 'button';
480→                    b.className = 'dlg-choice';
481→                    b.textContent = this.game._text(ch?.label || '');
482→                    b.addEventListener('click', async (e) => {
483→                        e.stopPropagation();
484→                        await this._flashChoice(b);
485→                        await this._applyChoice(step, ch || {});
486→                    }, {passive: false});
487→                    choicesEl.appendChild(b);
488→                });
489→            }
490→        }
491→    }
492→
493→    // --- Logic & Flow ---
494→
495→    async _applyChoice(step, ch) {
496→        if (this._busy) return;
497→        this._busy = true;
498→
499→        try {
500→            const act = ch?.onChoose || {};
501→            if (act.setFlags) await this._applyFlags(act.setFlags);
502→
503→            if (act.jump) {
504→                const to = (this.active?.dlg?.sequence || []).findIndex(n => n?.id === act.jump);
505→                if (to >= 0) {
506→                    this.active.idx = to;
507→                    this._renderStep();
508→                    return;
509→                }
510→            }
511→            if (act.end) {
512→                await this._end(act.onEnd || null);
513→                return;
514→            }
515→            await this._nextInternal();
516→        } finally {
517→            this._busy = false;
518→        }
519→    }
520→
521→    /**
522→     * Advances to the next step in the sequence.
523→     */
524→    async next() {
525→        if (!this.active || this._busy) return;
526→        this._busy = true;
527→        try {
528→            await this._nextInternal();
529→        } finally {
530→            this._busy = false;
531→        }
532→    }
533→
534→    async _nextInternal() {
535→        const step = this.active?.dlg?.sequence?.[this.active?.idx ?? -1];
536→        if (!step) {
537→            await this._end();
538→            return;
539→        }
540→
541→        if (step.onNext) await this._applyOnNodeEnd(step.onNext);
542→
543→        this.active.idx++;
544→        const total = this.active?.dlg?.sequence?.length ?? 0;
545→        if (this.active.idx >= total) {
546→            await this._end(this.active.dlg.onEnd || null);
547→            return;
548→        }
549→        this._renderStep();
550→    }
551→
552→    async _applyOnNodeEnd(act) {
553→        if (act?.setFlags) await this._applyFlags(act.setFlags);
554→    }
555→
556→    async _applyFlags(flags) {
557→        const g = this.game;
558→        let changed = false;
559→        if (Array.isArray(flags)) {
560→            for (const f of flags) if (!g.state.flags[f]) {
561→                g.state.flags[f] = true;
562→                changed = true;
563→            }
564→        } else if (flags && typeof flags === 'object') {
565→            for (const [k, v] of Object.entries(flags)) {
566→                if (!!g.state.flags[k] !== !!v) {
567→                    g.state.flags[k] = !!v;
568→                    changed = true;
569→                }
570→            }
571→        }
572→
573→        if (changed) {
574→            await g._stateChanged();
575→        }
576→    }
577→
578→    /**
579→     * Ends the dialog sequence correctly.
580→     * * CRITICAL ORDER:
581→     * 1. Hide UI (Visual close)
582→     * 2. Apply Logic/Flags (Triggers Engine Events)
583→     * 3. Resolve Promise (Unblock Engine)
584→     */
585→    async _end(onEnd = null) {
586→        const g = this.game;
587→
588→        // 1. Visual close
589→        // We hide the overlay but do NOT resolve the promise yet.
590→        this._hide();
591→        this.active = null;
592→
593→        // 2. Apply logic
594→        if (onEnd) {
595→            if (onEnd.message) g._msg(g._text(onEnd.message));
596→
597→            // Triggers engine events. Since UI is hidden, highlights will be visible.
598→            if (onEnd.setFlags) await this._applyFlags(onEnd.setFlags);
599→
600→            if (onEnd.goTo) await g.goto(onEnd.goTo);
601→        }
602→
603→        // 3. Unblock Engine
604→        // Now we tell the engine "dialog is fully done".
605→        if (this._closeResolver) {
606→            this._closeResolver();
607→            this._closeResolver = null;
608→        }
609→    }
610→}
