      el.style.height = (cfg.rect.h ?? 100) + '%'
    }
  }
}
```

**Token Area Creation** (`puzzles/base.js`, lines 345-375):

```javascript
createTokenArea() {
  const area = document.createElement('div')
  area.className = 'pz-token-area'

  const layoutCfg = this.instanceOptions.layout || this.config.layout || {}
  const mode = layoutCfg.mode || 'auto'

  if (mode === 'manual') {
    // position: relative, flex: 1 1 auto
  } else if (layoutCfg.grid) {
    // display: grid
    // gridTemplateColumns: repeat(cols, 1fr)
    // gap: var(--pz-token-gap)
  } else {
    // Auto flex
    // flexDirection: vertical/horizontal
    // flexWrap: wrap
    // gap: var(--pz-token-gap)
  }

  return area
}
```

---

### 7. VISIBILITY & CONTROL FLOWS

**Visibility Control Patterns**:

| Element | Method | Details |
|---------|--------|---------|
| Dialog Overlay | `.hidden` class toggle | `_show()` / `_hide()` |
| Engine Modal | `.hidden` class toggle | `openModal()` / `_closeModal()` |
| Puzzle Modal | z-index: 8000 + z-index stacking | Auto-overlayed |
| Individual Elements | CSS `visible` property or `display: none` | `applyStyle()`, `applyManualElements()` |

**Element Visibility** (`base.js`, lines 253-262):

```javascript
applyStyle(el, style = {}) {
  // visible (JS API) has priority
  if (style.visible === false) {
    el.style.display = 'none'
  } else if (style.display) {
    el.style.display = style.display
  }
  // Other CSS properties follow...
}
```

**Dialog Input Blocking** (`dialogs.js`, lines 28-32, 181-189):

```javascript
/** Input lock to prevent race conditions during async transitions */
this._busy = false

_handleInput() {
  if (this._busy) return  // Guard against double-click

  if (this._typewriterRunning && this.typewriterConfig.skipOnClick) {
    this._skipTypewriter()
  } else {
    void this.next()
  }
}
```

---

### 8. EVENT HANDLING & LIFECYCLE

**Dialog Step Rendering** (`dialogs.js`, lines 416-491):

```javascript
_renderStep() {
  const step = this.active?.dlg?.sequence?.[this.active?.idx ?? -1]

  if (!step) {
    void this._end()  // Out of bounds
    return
  }

  // 1. Update poses
  if (step.leftPose) this.active.leftPose = step.leftPose
  if (step.rightPose) this.active.rightPose = step.rightPose

  // 2. Apply mirroring logic
  let mirrorLeft = this.active.leftDefaultMirror
  let mirrorRight = this.active.rightDefaultMirror
  if (typeof step.mirror === 'boolean') {
    if (step.speaker === 'left') mirrorLeft = step.mirror
    if (step.speaker === 'right') mirrorRight = step.mirror
  }

  // 3. Set speaker (adds CSS classes)
  this._setSpeaking(sp)

  // 4. Apply portraits
  this._applyPortrait('left', ..., mirrorLeft)
  this._applyPortrait('right', ..., mirrorRight)

  // 5. Render UI elements
  nameEl.textContent = speakerName
  void this._typewriterText(textEl, text)  // Async typewriter

  // 6. Render choice buttons
  choicesEl.innerHTML = ''
  step.choices.forEach(ch => {
    const b = document.createElement('button')
    b.className = 'dlg-choice'
    b.addEventListener('click', async (e) => {
      await this._flashChoice(b)
      await this._applyChoice(step, ch)
    })
    choicesEl.appendChild(b)
  })
}
```

**Choice Handling** (`dialogs.js`, lines 495-519):

```javascript
async _applyChoice(step, ch) {
  if (this._busy) return
  this._busy = true

  try {
    const act = ch?.onChoose || {}
    if (act.setFlags) await this._applyFlags(act.setFlags)

    if (act.jump) {
      // Jump to step with matching id
      const to = (this.active?.dlg?.sequence || []).findIndex(n => n?.id === act.jump)
      if (to >= 0) {
        this.active.idx = to
        this._renderStep()
        return
      }
    }

    if (act.end) {
      await this._end(act.onEnd || null)
      return
    }

    await this._nextInternal()
  } finally {
    this._busy = false
  }
}
```

---

### 9. DIALOG CLOSURE PROTOCOL

**Critical Order** (`dialogs.js`, lines 585-609):

```javascript
async _end(onEnd = null) {
  const g = this.game

  // 1. VISUAL CLOSE (before applying logic!)
  this._hide()
  this.active = null

  // 2. APPLY LOGIC (triggers engine events, highlights visible)
  if (onEnd) {
    if (onEnd.message) g._msg(g._text(onEnd.message))
    if (onEnd.setFlags) await this._applyFlags(onEnd.setFlags)
    if (onEnd.goTo) await g.goto(onEnd.goTo)
  }

  // 3. UNBLOCK ENGINE (tell engine "dialog is fully done")
  if (this._closeResolver) {
    this._closeResolver()
    this._closeResolver = null
  }
}
```

This order is CRITICAL because:
- Visual close happens first (no flashing)
- Logic runs while UI is hidden (prevents race conditions)
- Promise resolution happens last (unblocks engine)

---

### 10. KEY REUSABLE INFRASTRUCTURE FOR CONTENT PANEL

**Immediately Reusable**:

1. **Mount/Unmount Pattern** (`createPuzzleRunner`) - Container creation, positioning, lifecycle guards
2. **Theme System** (`applyTheme`, `applyStyle`) - CSS vars + classes
3. **Layout Infrastructure** (`applyAutoLayout`, `applyManualElements`) - Flex/Grid/Manual positioning
4. **I18n Integration** (`this.t`, `_text()`) - The @key@fallback pattern
5. **Element Visibility** (`visible` property, `display: none`, CSS classes)
6. **Responsive Handlers** (`window.addEventListener('resize', ...)`)

**NOT Reusable** (Dialog-specific):

- Typewriter text effect
- Character portrait system
- Choice branching logic
- Speaker mirroring

**Design Opportunity**:
The puzzle system's modal container (`.pz-container` at z-index 8000) is designed to overlay. A "content panel" could use the same pattern:
- Create panel container at z-index 7999 or 8001 (adjust as needed)
- Mount via `mountInto(this.hotspotLayer)` 
- Use existing `applyStyle()` / `applyTheme()` 
- Use existing `rectToStyle()` for positioning
- Leverage the `@key@fallback` i18n pattern

---

**Summary**: The system is highly modular with clear separation between mounting, rendering, theming, and lifecycle. The puzzle system shows the cleanest example of extensible modal infrastructure—your content panel should follow the same patterns for consistency.

