 517→            this.activeHandle = null;
 518→            this.startPt = {x: ev.clientX, y: ev.clientY};
 519→            this.startRect = {...this.rect};
 520→            return;
 521→        }
 522→        this.dragMode = 'create';
 523→        this.activeHandle = null;
 524→        this.startPt = {x: ev.clientX, y: ev.clientY};
 525→        this.rect = {x: pct.x, y: pct.y, w: 0, h: 0};
 526→        this._renderPersistent();
 527→    }
 528→
 529→    _onPointerMove(ev) {
 530→        if (!this.dragMode || !this.rect) return;
 531→        const box = this._boxRect();
 532→        const dx = (ev.clientX - this.startPt.x) / box.width * 100;
 533→        const dy = (ev.clientY - this.startPt.y) / box.height * 100;
 534→
 535→        if (this.dragMode === 'move') {
 536→            const nx = +(Math.max(0, Math.min(100 - this.rect.w, this.startRect.x + dx))).toFixed(2);
 537→            const ny = +(Math.max(0, Math.min(100 - this.rect.h, this.startRect.y + dy))).toFixed(2);
 538→            this.rect.x = nx;
 539→            this.rect.y = ny;
 540→            Object.assign(this.finalBox.style, {left: this.rect.x + '%', top: this.rect.y + '%'});
 541→            this._updateLabel();
 542→            this._updateJsonPanel();
 543→            return;
 544→        }
 545→
 546→        if (this.dragMode === 'resize' && this.activeHandle) {
 547→            const sr = this.startRect;
 548→            const apply = (nx, ny, nw, nh) => {
 549→                this.rect.x = +(Math.max(0, Math.min(100, nx))).toFixed(2);
 550→                this.rect.y = +(Math.max(0, Math.min(100, ny))).toFixed(2);
 551→                this.rect.w = +(Math.max(0, Math.min(100 - this.rect.x, nw))).toFixed(2);
 552→                this.rect.h = +(Math.max(0, Math.min(100 - this.rect.y, nh))).toFixed(2);
 553→                Object.assign(this.finalBox.style, {
 554→                    left: this.rect.x + '%',
 555→                    top: this.rect.y + '%',
 556→                    width: this.rect.w + '%',
 557→                    height: this.rect.h + '%'
 558→                });
 559→                this._updateLabel();
 560→                this._updateJsonPanel();
 561→            };
 562→            switch (this.activeHandle) {
 563→                case 'nw':
 564→                    apply(sr.x + dx, sr.y + dy, sr.w - dx, sr.h - dy);
 565→                    break;
 566→                case 'n':
 567→                    apply(sr.x, sr.y + dy, sr.w, sr.h - dy);
 568→                    break;
 569→                case 'ne':
 570→                    apply(sr.x, sr.y + dy, sr.w + dx, sr.h - dy);
 571→                    break;
 572→                case 'e':
 573→                    apply(sr.x, sr.y, sr.w + dx, sr.h);
 574→                    break;
 575→                case 'se':
 576→                    apply(sr.x, sr.y, sr.w + dx, sr.h + dy);
 577→                    break;
 578→                case 's':
 579→                    apply(sr.x, sr.y, sr.w, sr.h + dy);
 580→                    break;
 581→                case 'sw':
 582→                    apply(sr.x + dx, sr.y, sr.w - dx, sr.h + dy);
 583→                    break;
 584→                case 'w':
 585→                    apply(sr.x + dx, sr.y, sr.w - dx, sr.h);
 586→                    break;
 587→            }
 588→            return;
 589→        }
 590→
 591→        if (this.dragMode === 'create') {
 592→            const p0 = this._clientToPct({clientX: this.startPt.x, clientY: this.startPt.y});
 593→            const p1 = this._clientToPct(ev);
 594→            const x = Math.min(p0.x, p1.x), y = Math.min(p0.y, p1.y);
 595→            const w = Math.max(0, Math.max(p0.x, p1.x) - x);
 596→            const h = Math.max(0, Math.max(p0.y, p1.y) - y);
 597→            this.rect = {x: +x.toFixed(2), y: +y.toFixed(2), w: +w.toFixed(2), h: +h.toFixed(2)};
 598→            Object.assign(this.finalBox.style, {left: x + '%', top: y + '%', width: w + '%', height: h + '%'});
 599→            this._updateLabel();
 600→            this._updateJsonPanel();
 601→        }
 602→    }
 603→
 604→    _onPointerUp() {
 605→        this.dragMode = null;
 606→        this.activeHandle = null;
 607→        this.startPt = null;
 608→        this.startRect = null;
 609→    }
 610→
 611→    _onKeyDown(e) {
 612→        if (e.key === 'Delete' || e.key === 'Backspace') {
 613→            if (this.rect) {
 614→                this.rect = null;
 615→                this._renderPersistent();
 616→            }
 617→        }
 618→    }
 619→}
