 621→/* ========================================================================== */
 622→/*                               Puzzle editor                                */
 623→
 624→/* ========================================================================== */
 625→
 626→/**
 627→ * Manual and AUTO puzzle layout editor.
 628→ * AUTO: only the yellow window overlay is interactive.
 629→ * MANUAL: window is locked to 0/0/100/100, each [data-id] gets a purple overlay and can be positioned.
 630→ */
 631→class PuzzleEditor {
 632→    /**
 633→     * @param {HTMLElement} puzzleRoot  The .pz root
 634→     * @param {HTMLElement} overlay     Global overlay (used for AUTO mode)
 635→     * @param {HTMLElement} container   Document container (used for hints/toolbars)
 636→     */
 637→    constructor(puzzleRoot, overlay, container) {
 638→        this.puzzleRoot = puzzleRoot;
 639→        this.overlay = overlay;      // Global overlay (AUTO)
 640→        this.container = container;
 641→
 642→        this.windowEl = puzzleRoot.querySelector('.pz__window');
 643→        this.isManualLayout = puzzleRoot.classList.contains('pz--manual');
 644→
 645→        this.localLayer = null;      // MANUAL: overlay anchored inside .pz__window
 646→        this.visualizations = [];
 647→        this.vizById = new Map();    // id -> viz box
 648→        this.components = new Map(); // el -> { id, type, element, _rect, parentId? }
 649→        this.footerEl = null;
 650→
 651→        this.toolbar = null;
 652→        this.jsonPanel = null;
 653→        this.hint = null;
 654→        this.active = null;
 655→
 656→        this._overlayPEBackup = '';
 657→
 658→        this._onMouseDown = this._onMouseDown.bind(this);
 659→        this._onMouseMove = this._onMouseMove.bind(this);
 660→        this._onMouseUp = this._onMouseUp.bind(this);
 661→        this._onKeyDown = this._onKeyDown.bind(this);
 662→    }
 663→
 664→    /** Build UI and interactivity for AUTO or MANUAL based on .pz flags. */
 665→    enable() {
 666→        this._buildHint();
 667→        this._buildToolbar();
 668→
 669→        if (!this.windowEl) {
 670→            console.warn('[ED] .pz__window not found');
 671→            return;
 672→        }
 673→
 674→        if (!this.isManualLayout) {
 675→            // AUTO: yellow window is the only draggable/resizable thing
 676→            this.overlay.style.pointerEvents = 'auto';
 677→            const wRect = this._rectOf(this.windowEl, this.puzzleRoot);
 678→            const winViz = this._makeVizBox(wRect, 'pz-viz-window', 'Work Window', '#ff0', /*locked=*/false);
 679→            winViz.__target = this.windowEl;
 680→            winViz.__relRoot = this.puzzleRoot;
 681→            this.overlay.appendChild(winViz);
 682→            this.visualizations = [winViz];
 683→            this.vizById.clear();
 684→            this.vizById.set('__window__', winViz);
 685→            this._bind();
 686→            this._updateJson();
 687→            console.debug('[ED] AUTO ready', wRect);
 688→            return;
 689→        }
 690→
 691→        // MANUAL
 692→        this._overlayPEBackup = this.overlay.style.pointerEvents || '';
 693→        this.overlay.style.pointerEvents = 'none'; // do not intercept mouse inside the window
 694→
 695→        this._waitWindowReady(() => {
 696→            this._ensureLocalLayer();
 697→            this._lockWindow100();        // force 0/0/100/100
 698→            this._detectComponents();     // includes footer/ok/cancel
 699→            this._freezeInitialRects();   // convert to absolute % + clamp
 700→            this._maybeAutoplace();       // stack vertically if everything is squashed near top-left
 701→            this._createManualVisualizations();
 702→            this._bind();
 703→            this._updateJson();
 704→            console.debug('[ED] MANUAL ready');
 705→        });
 706→    }
 707→
 708→    /** Remove listeners, overlays and restore global overlay pointer-events. */
 709→    destroy() {
 710→        this._unbind();
 711→        this.visualizations.forEach(v => v.remove());
 712→        this.visualizations = [];
 713→        this.vizById.clear();
 714→        if (this.localLayer?.parentNode) this.localLayer.parentNode.removeChild(this.localLayer);
 715→        this.localLayer = null;
 716→        if (this.toolbar?.parentNode) this.toolbar.parentNode.removeChild(this.toolbar);
 717→        if (this.hint?.parentNode) this.hint.parentNode.removeChild(this.hint);
 718→        if (this.jsonPanel?.parentNode) this.jsonPanel.parentNode.removeChild(this.jsonPanel);
 719→        this.toolbar = null;
 720→        this.hint = null;
 721→        this.jsonPanel = null;
 722→        this.components.clear();
 723→        this.footerEl = null;
 724→        if (this.isManualLayout) this.overlay.style.pointerEvents = this._overlayPEBackup;
 725→    }
 726→
 727→    /* ---------- readiness & layers ---------- */
 728→
 729→    /**
 730→     * Wait until .pz__window has a measurable box to avoid 0x0 at initial render.
 731→     * @param {Function} cb
 732→     * @private
 733→     */
 734→    _waitWindowReady(cb) {
 735→        let tries = 0;
 736→        const tick = () => {
 737→            tries++;
 738→            const r = this.windowEl.getBoundingClientRect();
 739→            if (r.width >= 8 && r.height >= 8) return cb();
 740→            if (tries < 30) return requestAnimationFrame(tick);
 741→            cb();
 742→        };
 743→        requestAnimationFrame(tick);
 744→    }
 745→
 746→    /**
 747→     * Ensure the local overlay layer mounted inside .pz__window for MANUAL mode.
 748→     * @private
 749→     */
 750→    _ensureLocalLayer() {
 751→        if (this.localLayer?.isConnected) return;
 752→        const lv = document.createElement('div');
 753→        lv.className = 'pz-viz-layer';
 754→        Object.assign(lv.style, {position: 'absolute', inset: '0', zIndex: '10000', pointerEvents: 'none'});
 755→        if (getComputedStyle(this.windowEl).position === 'static') this.windowEl.style.position = 'relative';
 756→        this.windowEl.appendChild(lv);
 757→        this.localLayer = lv;
 758→    }
 759→
 760→    /**
 761→     * Lock yellow window to 0/0/100/100 relative to the puzzle root (.pz).
 762→     * @private
 763→     */
 764→    _lockWindow100() {
 765→        const root = this.puzzleRoot;
 766→        if (getComputedStyle(root).position === 'static') root.style.position = 'relative';
 767→        Object.assign(this.windowEl.style, {
 768→            position: 'absolute',
 769→            left: '0%', top: '0%',
 770→            width: '100%', height: '100%',
 771→            margin: '0', transform: '', boxSizing: 'border-box'
 772→        });
 773→    }
 774→
 775→    /* ---------- UI ---------- */
 776→
 777→    _buildHint() {
 778→        const hint = document.createElement('div');
 779→        hint.className = 'editor-hint';
 780→        hint.textContent = this.isManualLayout
 781→            ? 'PUZZLE MANUAL: yellow window locked 100% • move purple boxes • Snap 1%'
 782→            : 'PUZZLE AUTO: move the yellow window (drag/resize)';
 783→        Object.assign(hint.style, {
 784→            position: 'absolute',
 785→            left: '10px',
 786→            top: '10px',
 787→            zIndex: '10001',
 788→            pointerEvents: 'none',
 789→            background: 'rgba(0,0,0,0.8)',
 790→            padding: '6px 10px',
 791→            borderRadius: '6px',
 792→            color: '#c9f',
 793→            font: '12px/1.4 sans-serif'
 794→        });
 795→        this.hint = hint;
 796→        this.container.appendChild(hint);
 797→    }
 798→
 799→    _buildToolbar() {
 800→        const tb = document.createElement('div');
 801→        tb.className = 'editor-toolbar puzzle-toolbar';
 802→        Object.assign(tb.style, {
 803→            position: 'absolute',
 804→            right: '10px',
 805→            top: '10px',
 806→            zIndex: '10001',
 807→            pointerEvents: 'auto',
 808→            background: 'rgba(0,0,0,0.85)',
 809→            padding: '6px',
 810→            borderRadius: '8px',
 811→            color: '#fff',
 812→            font: '12px/1.2 system-ui'
 813→        });
 814→        const _btn = (label, onClick) => {
 815→            const b = document.createElement('button');
 816→            b.type = 'button';
 817→            b.textContent = label;
 818→            Object.assign(b.style, {
 819→                margin: '0 4px',
 820→                padding: '4px 8px',
 821→                cursor: 'pointer',
 822→                background: '#222',
 823→                color: '#fff',
 824→                border: '1px solid #666',
 825→                borderRadius: '6px'
 826→            });
 827→            b.addEventListener('click', onClick);
 828→            return b;
 829→        };
 830→        tb.appendChild(_btn('📎 Export', () => this._exportPayload()));
 831→        tb.appendChild(_btn('📋 Show JSON', () => this._toggleJsonPanel()));
 832→        tb.appendChild(_btn('🌳 Dump Tree', () => this._dumpTree()));
 833→        tb.appendChild(_btn('⟳ Refresh', () => this._refreshManual()));
 834→        const snapLabel = document.createElement('label');
 835→        snapLabel.style.marginLeft = '8px';
 836→        snapLabel.style.opacity = '.9';
 837→        const snap = document.createElement('input');
 838→        snap.type = 'checkbox';
 839→        snap.checked = true;
 840→        snap.dataset.act = 'snap';
 841→        snapLabel.appendChild(snap);
 842→        snapLabel.appendChild(document.createTextNode(' Snap 1%'));
 843→        tb.appendChild(snapLabel);
 844→        this.toolbar = tb;
 845→        this.container.appendChild(tb);
 846→    }
 847→
 848→    _toggleJsonPanel() {
 849→        if (this.jsonPanel) {
 850→            this.jsonPanel.remove();
 851→            this.jsonPanel = null;
 852→            return;
 853→        }
 854→        const panel = document.createElement('div');
 855→        panel.className = 'editor-jsonpanel';
 856→        Object.assign(panel.style, {
 857→            position: 'absolute', right: '10px', top: '50px', zIndex: '10002',
 858→            background: 'rgba(0,0,0,.85)', padding: '6px', borderRadius: '6px'
 859→        });
 860→        const ta = document.createElement('textarea');
 861→        Object.assign(ta.style, {
 862→            width: '360px',
 863→            height: '260px',
 864→            color: '#c9f',
 865→            background: '#111',
 866→            font: '12px monospace'
 867→        });
 868→        panel.appendChild(ta);
 869→        const btn = document.createElement('button');
 870→        btn.textContent = 'Copy';
 871→        btn.addEventListener('click', () => {
 872→            ta.select();
 873→            document.execCommand?.('copy');
 874→        });
 875→        Object.assign(btn.style, {margin: '6px 0', padding: '4px 8px'});
 876→        panel.appendChild(btn);
 877→        const host = this.isManualLayout ? this.container : this.overlay;
