 882→
 883→    /** Copy current windowRect and, for MANUAL, the elements map to clipboard. */
 884→    _exportPayload() {
 885→        const payload = {
 886→            windowRect: this._rectOf(this.windowEl || this.puzzleRoot, this.puzzleRoot),
 887→            elements: this.isManualLayout ? this._collectElementsMap() : {}
 888→        };
 889→        const json = JSON.stringify(payload, null, 2);
 890→        try {
 891→            navigator.clipboard?.writeText(json);
 892→        } catch {
 893→            const ta = document.createElement('textarea');
 894→            ta.value = json;
 895→            document.body.appendChild(ta);
 896→            ta.select();
 897→            document.execCommand?.('copy');
 898→            ta.remove();
 899→        }
 900→        this._updateJson();
 901→    }
 902→
 903→    /** Dump detected [data-id] tree to console and clipboard for debugging. */
 904→    _dumpTree() {
 905→        const tree = this._buildTree();
 906→        const json = JSON.stringify(tree, null, 2);
 907→        console.debug('[ED] TREE\n', json);
 908→        if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(json);
 909→    }
 910→
 911→    /* ---------- MANUAL pipeline ---------- */
 912→
 913→    /** Re-scan components and rebuild manual overlays. */
 914→    _refreshManual() {
 915→        if (!this.isManualLayout) return;
 916→        this.visualizations.forEach(v => v.remove());
 917→        this.visualizations = [];
 918→        this.vizById.clear();
 919→        this.components.clear();
 920→        this.footerEl = null;
 921→
 922→        this._lockWindow100();
 923→        this._detectComponents();
 924→        this._freezeInitialRects();
 925→        this._maybeAutoplace();
 926→        this._createManualVisualizations();
 927→        this._bind();
 928→        this._updateJson();
 929→    }
 930→
 931→    /** Detect all [data-id] and footer grouping, record meta. */
 932→    _detectComponents() {
 933→        const els = this.windowEl.querySelectorAll('[data-id]');
 934→        let footer = null;
 935→        els.forEach(el => {
 936→            if (el.getAttribute('data-id') === 'footer') footer = el;
 937→        });
 938→        this.footerEl = footer || null;
 939→
 940→        els.forEach(el => {
 941→            const id = el.getAttribute('data-id');
 942→            if (!id) return;
 943→            const type = el.classList.contains('pz-token') ? 'token' : 'component';
 944→            let parentId = null;
 945→
 946→            // ok/cancel live under footer for relative positioning and debugging
 947→            if (this.footerEl && (id === 'ok' || id === 'cancel')) parentId = 'footer';
 948→
 949→            this.components.set(el, {id, type, element: el, parentId});
 950→        });
 951→    }
 952→
 953→    /** Convert initial geometry to absolute percentages and clamp to parent. */
 954→    _freezeInitialRects() {
 955→        const relWin = this.windowEl;
 956→        if (getComputedStyle(relWin).position === 'static') relWin.style.position = 'relative';
 957→
 958→        for (const [el, meta] of this.components.entries()) {
 959→            const rel = (meta.parentId === 'footer' && this.footerEl) ? this.footerEl : relWin;
 960→            let r = this._rectOf(el, rel);
 961→
 962→            // Clamps and minimal sizes
 963→            if (r.x < 0) {
 964→                r.w = Math.max(0, r.w + r.x);
 965→                r.x = 0;
 966→            }
 967→            if (r.y < 0) {
 968→                r.h = Math.max(0, r.h + r.y);
 969→                r.y = 0;
 970→            }
 971→            if (r.x > 100) r.x = 100;
 972→            if (r.y > 100) r.y = 100;
 973→            if (r.w < 4) r.w = (meta.id === 'ok' || meta.id === 'cancel') ? 10 : 12;
 974→            if (r.h < 3) r.h = (meta.id === 'ok' || meta.id === 'cancel') ? 5 : 6;
 975→            if (r.x + r.w > 100) r.w = 100 - r.x;
 976→            if (r.y + r.h > 100) r.h = 100 - r.y;
 977→
 978→            Object.assign(el.style, {
 979→                position: 'absolute',
 980→                left: r.x + '%', top: r.y + '%',
 981→                width: r.w + '%', height: r.h + '%',
 982→                boxSizing: 'border-box', margin: '', transform: ''
 983→            });
 984→
 985→            meta._rect = this._rectOf(el, rel);
 986→        }
 987→        console.debug('[ED] freeze complete; elements:', this.components.size);
 988→    }
 989→
 990→    /**
 991→     * If elements are squashed near the top-left, arrange them vertically centered,
 992→     * keep footer near bottom, and place ok/cancel inside the footer.
 993→     */
 994→    _maybeAutoplace() {
 995→        const metasTop = Array.from(this.components.values()).filter(m => !m.parentId); // top-level only
 996→        const rects = metasTop.map(m => m._rect);
 997→        const squashed = rects.filter(r => r.y <= 2 || (r.x <= 2 && r.w <= 15)).length;
 998→        if (squashed < Math.ceil(rects.length * 0.6)) {
 999→            this._syncFooterChildrenPositions();
1000→            return;
1001→        }
1002→
1003→        const order = (id) => ({title: 0, prompt: 1, input: 2, footer: 99}[id] ?? 10);
1004→        metasTop.sort((a, b) => order(a.id) - order(b.id) || a.id.localeCompare(b.id));
1005→
1006→        const N = metasTop.length;
1007→        const gap = 4;
1008→        const bottomReserve = metasTop.some(m => m.id === 'footer') ? 10 : 6;
1009→        const Hfree = 100 - bottomReserve - gap * (N + 1);
1010→        const baseH = Math.max(6, Math.floor(Hfree / Math.max(1, N)));
1011→
1012→        let y = gap;
1013→        metasTop.forEach(m => {
1014→            let w = 80;
1015→            if (m.id === 'title' || m.id === 'prompt') w = 70;
1016→            if (m.id === 'footer') {
1017→                w = 50;
1018→                y = 100 - bottomReserve;
1019→            }
1020→
1021→            const x = (100 - w) / 2;
1022→            const h = (m.id === 'footer') ? 6 : baseH;
1023→            const r = {x: +x.toFixed(2), y: +y.toFixed(2), w, h};
1024→
1025→            Object.assign(m.element.style, {
1026→                position: 'absolute',
1027→                left: r.x + '%',
1028→                top: r.y + '%',
1029→                width: r.w + '%',
1030→                height: r.h + '%'
1031→            });
1032→            m._rect = r;
1033→            if (m.id !== 'footer') y += h + gap;
1034→        });
1035→
1036→        // OK and Cancel inside footer: left and right respectively
1037→        if (this.footerEl) {
1038→            const btns = ['cancel', 'ok'];
1039→            btns.forEach((id, i) => {
1040→                const el = this.windowEl.querySelector(`[data-id="${id}"]`);
1041→                if (!el) return;
1042→                const w = 20, h = 6, x = i === 0 ? 4 : 100 - 4 - w, yPct = 50 - h / 2;
1043→                Object.assign(el.style, {
1044→                    position: 'absolute',
1045→                    left: x + '%',
1046→                    top: yPct + '%',
1047→                    width: w + '%',
1048→                    height: h + '%'
1049→                });
1050→            });
1051→        }
1052→        this._syncFooterChildrenPositions();
1053→        console.debug('[ED] autoplace applied');
1054→    }
1055→
1056→    /** Build overlays for manual mode. Yellow window locked, purple boxes for components. */
1057→    _createManualVisualizations() {
1058→        // Yellow locked frame 0/0/100/100 inside .pz__window
1059→        const winViz = this._makeVizBox(
1060→            {x: 0, y: 0, w: 100, h: 100},
1061→            'pz-viz-window',
1062→            'Work Window (locked)',
1063→            '#ff0',
1064→            true
1065→        );
1066→        winViz.__target = this.windowEl;
1067→        winViz.__relRoot = this.windowEl;
1068→        this.localLayer.appendChild(winViz);
1069→        this.visualizations.push(winViz);
1070→        this.vizById.set('__window__', winViz);
1071→
1072→        // Purple for top-level, cyan for ok/cancel
1073→        for (const [el, meta] of this.components.entries()) {
1074→            const isChild = (meta.parentId === 'footer' && this.footerEl);
1075→            const label = meta.id;
1076→            const color = isChild ? '#6bdfff' : '#b450ff';
1077→            const rWin = isChild ? this._rectOf(el, this.windowEl) : meta._rect;
1078→
1079→            const viz = this._makeVizBox(rWin, isChild ? 'pz-viz-child' : 'pz-viz-component', label, color, false);
1080→            viz.__target = el;
1081→            viz.__meta = meta;
1082→            viz.__relRoot = isChild ? this.footerEl : this.windowEl; // movement in % relative to parent
1083→            this.localLayer.appendChild(viz);
1084→            this.visualizations.push(viz);
1085→            this.vizById.set(meta.id, viz);
1086→        }
1087→    }
1088→
1089→    /** Keep ok/cancel overlays in sync when the footer moves. */
1090→    _syncFooterChildrenPositions() {
1091→        if (!this.footerEl) return;
1092→        const kids = ['ok', 'cancel'];
1093→        kids.forEach(id => {
1094→            const el = this.windowEl.querySelector(`[data-id="${id}"]`);
1095→            const viz = this.vizById.get(id);
1096→            if (!el || !viz) return;
1097→            const rWin = this._rectOf(el, this.windowEl);
1098→            Object.assign(viz.style, {
1099→                left: rWin.x + '%',
1100→                top: rWin.y + '%',
1101→                width: rWin.w + '%',
1102→                height: rWin.h + '%'
1103→            });
1104→            const lab = viz.querySelector('.pz-viz-label');
1105→            if (lab) {
1106→                const p = lab.__prefix || lab.textContent.split('x:')[0].trim();
1107→                lab.__prefix = p;
1108→                lab.textContent = `${p}  x:${rWin.x} y:${rWin.y} w:${rWin.w} h:${rWin.h}`;
1109→            }
1110→        });
1111→    }
1112→
1113→    /* ---------- visualization + interactions ---------- */
1114→
1115→    /**
1116→     * Create a draggable/resizable overlay box.
1117→     * For component boxes there is no visible text label to avoid covering small targets.
1118→     * @param {{x:number,y:number,w:number,h:number}} rect
1119→     * @param {string} cls
1120→     * @param {string} label
1121→     * @param {string} color
1122→     * @param {boolean} locked
1123→     * @returns {HTMLDivElement}
1124→     * @private
1125→     */
1126→    _makeVizBox(rect, cls, label, color, locked) {
1127→        const box = document.createElement('div');
1128→        box.className = 'pz-viz ' + cls;
1129→        Object.assign(box.style, {
1130→            position: 'absolute',
1131→            left: rect.x + '%', top: rect.y + '%', width: rect.w + '%', height: rect.h + '%',
1132→            border: `2px solid ${color}`,
1133→            background: cls === 'pz-viz-window' ? 'transparent' : 'rgba(180,80,255,0.08)',
1134→            boxShadow: '0 0 0 1px rgba(0,0,0,0.2) inset',
1135→            borderRadius: '6px',
1136→            zIndex: '9998', cursor: locked ? 'default' : 'move', userSelect: 'none',
1137→            pointerEvents: 'auto'
1138→        });
1139→
1140→        // Visible label only for yellow window; not for component overlays
1141→        if (cls === 'pz-viz-window') {
1142→            const lab = document.createElement('div');
1143→            lab.className = 'pz-viz-label';
1144→            lab.textContent = `${label}  x:${rect.x} y:${rect.y} w:${rect.w} h:${rect.h}`;
1145→            Object.assign(lab.style, {
1146→                position: 'absolute', left: '0', top: '-18px',
1147→                background: 'rgba(0,0,0,.85)', color: '#e6d6ff',
1148→                font: '11px ui-monospace, Menlo, Consolas, monospace',
1149→                padding: '2px 6px', pointerEvents: 'none'
1150→            });
1151→            box.appendChild(lab);
1152→        } else {
1153→            box.title = label; // unobtrusive hint only
1154→        }
1155→
1156→        if (!locked) {
1157→            ['nw', 'n', 'ne', 'e', 'se', 's', 'sw', 'w'].forEach(h => {
1158→                const dot = document.createElement('div');
1159→                dot.dataset.handle = h;
1160→                Object.assign(dot.style, {
1161→                    position: 'absolute', width: '10px', height: '10px',
1162→                    background: color, border: '2px solid #fff', borderRadius: '50%', boxSizing: 'border-box'
1163→                });
1164→                const pos = (x, y) => {
1165→                    dot.style.left = x;
1166→                    dot.style.top = y;
1167→                };
1168→                switch (h) {
1169→                    case 'nw':
1170→                        pos('-6px', '-6px');
1171→                        break;
1172→                    case 'n':
1173→                        pos('calc(50% - 5px)', '-6px');
1174→                        break;
1175→                    case 'ne':
1176→                        pos('calc(100% - 6px)', '-6px');
1177→                        break;
1178→                    case 'e':
1179→                        pos('calc(100% - 6px)', 'calc(50% - 5px)');
1180→                        break;
1181→                    case 'se':
1182→                        pos('calc(100% - 6px)', 'calc(100% - 6px)');
1183→                        break;
1184→                    case 's':
1185→                        pos('calc(50% - 5px)', 'calc(100% - 6px)');
1186→                        break;
1187→                    case 'sw':
1188→                        pos('-6px', 'calc(100% - 6px)');
1189→                        break;
1190→                    case 'w':
1191→                        pos('-6px', 'calc(50% - 5px)');
1192→                        break;
1193→                }
1194→                box.appendChild(dot);
1195→            });
1196→        }
1197→        return box;
1198→    }
