1200→    /** Attach mouse handlers. AUTO: only window. MANUAL: all except locked window. */
1201→    _bind() {
1202→        this.visualizations.forEach(v => {
1203→            if (!this.isManualLayout && v.classList.contains('pz-viz-window')) {
1204→                v.addEventListener('mousedown', this._onMouseDown);
1205→            } else if (this.isManualLayout && !v.classList.contains('pz-viz-window')) {
1206→                v.addEventListener('mousedown', this._onMouseDown);
1207→            }
1208→        });
1209→        window.addEventListener('mousemove', this._onMouseMove);
1210→        window.addEventListener('mouseup', this._onMouseUp);
1211→        window.addEventListener('keydown', this._onKeyDown);
1212→    }
1213→
1214→    /** Detach mouse handlers. */
1215→    _unbind() {
1216→        this.visualizations.forEach(v => v.removeEventListener('mousedown', this._onMouseDown));
1217→        window.removeEventListener('mousemove', this._onMouseMove);
1218→        window.removeEventListener('mouseup', this._onMouseUp);
1219→        window.removeEventListener('keydown', this._onKeyDown);
1220→    }
1221→
1222→    _onMouseDown(e) {
1223→        e.preventDefault();
1224→        e.stopPropagation();
1225→        const viz = e.currentTarget;
1226→        const handle = e.target?.dataset?.handle;
1227→
1228→        if (e.button === 1) {
1229→            viz.__deleted = true;
1230→            viz.remove();
1231→            this.visualizations = this.visualizations.filter(v => v !== viz);
1232→            this.vizById.forEach((vv, k) => {
1233→                if (vv === viz) this.vizById.delete(k);
1234→            });
1235→            this._updateJson();
1236→            return;
1237→        }
1238→
1239→        const startMouse = {x: e.clientX, y: e.clientY};
1240→        const isWindow = viz.classList.contains('pz-viz-window');
1241→        const relRoot = isWindow ? (this.isManualLayout ? this.windowEl : this.puzzleRoot)
1242→            : (viz.__relRoot || this.windowEl);
1243→        const startElRect = this._rectOf(viz.__target, relRoot);
1244→
1245→        this.active = {
1246→            type: handle ? 'resize' : 'move',
1247→            viz,
1248→            handle,
1249→            startMouse,
1250→            startElRect,
1251→            targetEl: viz.__target,
1252→            relRoot,
1253→            isWindow
1254→        };
1255→    }
1256→
1257→    _onMouseMove(e) {
1258→        if (!this.active) return;
1259→        const A = this.active;
1260→        const box = A.relRoot.getBoundingClientRect();
1261→        const dx = (e.clientX - A.startMouse.x) / box.width * 100;
1262→        const dy = (e.clientY - A.startMouse.y) / box.height * 100;
1263→        const snap = !!this.toolbar?.querySelector('input[data-act="snap"]')?.checked;
1264→
1265→        const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
1266→        const emit = (nx, ny, nw, nh) => {
1267→            nx = clamp(nx, 0, 100);
1268→            ny = clamp(ny, 0, 100);
1269→            nw = clamp(nw, 0, 100 - nx);
1270→            nh = clamp(nh, 0, 100 - ny);
1271→            if (snap) {
1272→                nx = Math.round(nx);
1273→                ny = Math.round(ny);
1274→                nw = Math.round(nw);
1275→                nh = Math.round(nh);
1276→            } else {
1277→                nx = +nx.toFixed(2);
1278→                ny = +ny.toFixed(2);
1279→                nw = +nw.toFixed(2);
1280→                nh = +nh.toFixed(2);
1281→            }
1282→
1283→            // A) Apply to the element (percentages relative to relRoot)
1284→            this._applyRectToEl(A.targetEl, {x: nx, y: ny, w: nw, h: nh});
1285→
1286→            // B) Recompute viz box position
1287→            let rForViz;
1288→            if (A.relRoot === this.footerEl) {
1289→                rForViz = this._rectOf(A.targetEl, this.windowEl); // viz is in localLayer (relative to window)
1290→            } else if (!this.isManualLayout && A.isWindow) {
1291→                rForViz = this._rectOf(A.targetEl, this.puzzleRoot); // AUTO: viz is in the global overlay
1292→            } else {
1293→                rForViz = (A.relRoot === this.windowEl)
1294→                    ? this._rectOf(A.targetEl, this.windowEl)
1295→                    : {x: nx, y: ny, w: nw, h: nh};
1296→            }
1297→            Object.assign(A.viz.style, {
1298→                left: rForViz.x + '%',
1299→                top: rForViz.y + '%',
1300→                width: rForViz.w + '%',
1301→                height: rForViz.h + '%'
1302→            });
1303→
1304→            const lab = A.viz.querySelector('.pz-viz-label');
1305→            if (lab) {
1306→                const p = lab.__prefix || lab.textContent.split('x:')[0].trim();
1307→                lab.__prefix = p;
1308→                lab.textContent = `${p}  x:${rForViz.x} y:${rForViz.y} w:${rForViz.w} h:${rForViz.h}`;
1309→            }
1310→
1311→            // When moving the footer, keep child visualizations in sync
1312→            if (A.targetEl === this.footerEl) this._syncFooterChildrenPositions();
1313→
1314→            this._updateJson();
1315→        };
1316→
1317→        const sr = A.startElRect;
1318→        if (A.type === 'move') {
1319→            emit(sr.x + dx, sr.y + dy, sr.w, sr.h);
1320→            return;
1321→        }
1322→        switch (A.handle) {
1323→            case 'nw':
1324→                emit(sr.x + dx, sr.y + dy, sr.w - dx, sr.h - dy);
1325→                break;
1326→            case 'n':
1327→                emit(sr.x, sr.y + dy, sr.w, sr.h - dy);
1328→                break;
1329→            case 'ne':
1330→                emit(sr.x, sr.y + dy, sr.w + dx, sr.h - dy);
1331→                break;
1332→            case 'e':
1333→                emit(sr.x, sr.y, sr.w + dx, sr.h);
1334→                break;
1335→            case 'se':
1336→                emit(sr.x, sr.y, sr.w + dx, sr.h + dy);
1337→                break;
1338→            case 's':
1339→                emit(sr.x, sr.y, sr.w, sr.h + dy);
1340→                break;
1341→            case 'sw':
1342→                emit(sr.x + dx, sr.y, sr.w - dx, sr.h + dy);
1343→                break;
1344→            case 'w':
1345→                emit(sr.x + dx, sr.y, sr.w - dx, sr.h);
1346→                break;
1347→        }
1348→    }
1349→
1350→    _onMouseUp() {
1351→        this.active = null;
1352→    }
1353→
1354→    _onKeyDown(e) { /* optional key bindings can go here */
1355→    }
1356→
1357→    /* ---------- data / JSON / tree ---------- */
1358→
1359→    /** Collect element rects relative to their base (footer for ok/cancel, window for others). */
1360→    _collectElementsMap() {
1361→        const out = {};
1362→        const rel = this.windowEl || this.puzzleRoot;
1363→        for (const [el, meta] of this.components.entries()) {
1364→            if (!el.isConnected) continue;
1365→            const base = (meta.parentId === 'footer' && this.footerEl) ? this.footerEl : rel;
1366→            out[meta.id] = {rect: this._rectOf(el, base)};
1367→        }
1368→        return out;
1369→    }
1370→
1371→    /** Build a flat tree of [data-id] nodes with parent relations. */
1372→    _buildTree() {
1373→        const nodes = [];
1374→        const idOf = el => el.getAttribute('data-id');
1375→        const root = this.windowEl || this.puzzleRoot;
1376→        const all = Array.from(root.querySelectorAll('[data-id]'));
1377→        all.forEach(el => {
1378→            const id = idOf(el);
1379→            if (!id) return;
1380→            const parent = el.parentElement?.closest('[data-id]');
1381→            const parentId = parent ? idOf(parent) : null;
1382→            nodes.push({id, kind: el.classList.contains('pz-token') ? 'token' : 'component', parentId, children: []});
1383→        });
1384→        const byId = new Map(nodes.map(n => [n.id, n]));
1385→        nodes.forEach(n => {
1386→            if (n.parentId && byId.has(n.parentId)) byId.get(n.parentId).children.push(n.id);
1387→        });
1388→        return nodes;
1389→    }
1390→
1391→    /** JSON reflecting current state for the panel. */
1392→    _currentJson() {
1393→        return JSON.stringify({
1394→            windowRect: this._rectOf(this.windowEl || this.puzzleRoot, this.puzzleRoot),
1395→            elements: this.isManualLayout ? this._collectElementsMap() : {}
1396→        }, null, 2);
1397→    }
1398→
1399→    _updateJson() {
1400→        if (!this.jsonPanel) return;
1401→        this.jsonPanel.querySelector('textarea').value = this._currentJson();
1402→    }
1403→
1404→    /* ---------- geometry ---------- */
1405→
1406→    /**
1407→     * Get a rect of an element relative to a reference element and convert to percentages.
1408→     * @param {HTMLElement} el
1409→     * @param {HTMLElement} relTo
1410→     * @returns {{x:number,y:number,w:number,h:number}}
1411→     * @private
1412→     */
1413→    _rectOf(el, relTo) {
1414→        const pr = relTo.getBoundingClientRect();
1415→        const er = el.getBoundingClientRect();
1416→        const pct = (v, total) => +(v / total * 100).toFixed(2);
1417→        return {
1418→            x: pct(er.left - pr.left, pr.width),
1419→            y: pct(er.top - pr.top, pr.height),
1420→            w: pct(er.width, pr.width),
1421→            h: pct(er.height, pr.height)
1422→        };
1423→    }
1424→
1425→    /**
1426→     * Apply percentage rect to element as absolute positioning.
1427→     * @param {HTMLElement} el
1428→     * @param {{x:number,y:number,w:number,h:number}} rect
1429→     * @private
1430→     */
1431→    _applyRectToEl(el, rect) {
1432→        Object.assign(el.style, {
1433→            position: 'absolute',
1434→            left: rect.x + '%',
1435→            top: rect.y + '%',
1436→            width: rect.w + '%',
1437→            height: rect.h + '%'
1438→        });
1439→    }
1440→}
