 12→<body>
 13→<!-- Top bar -->
 14→<header class="topbar">
 15→    <div class="title">Úniková hra</div>
 16→    <div class="controls">
 17→        <button id="btnRestart" title="Restart">↺ Restart</button>
 18→        <button id="btnEditor" title="Přepnout editor">✎ Edit</button>
 19→    </div>
 20→</header>
 21→
 22→<!-- Game root -->
 23→<main id="gameRoot">
 24→    <div id="sceneContainer">
 25→        <img id="sceneImage" alt="scene">
 26→        <div id="hotspotLayer"></div>
 27→        <div id="editorOverlay" class="hidden"></div>
 28→    </div>
 29→
 30→    <section id="uiBar">
 31→        <div id="inventory"></div>
 32→        <div id="msg"></div>
 33→    </section>
 34→</main>
 35→
 36→<!-- Modal -->
 37→<div id="modal" class="hidden">
 38→    <div class="modal-content">
 39→        <div id="modalTitle" class="modal-title"></div>
 40→        <div id="modalBody" class="modal-body"></div>
 41→        <div class="modal-actions">
 42→            <button id="modalCancel">Zrušit</button>
 43→            <button id="modalOk">OK</button>
 44→        </div>
 45→    </div>
 46→</div>
 47→
 48→<script type="module">
 49→    // Core imports
 50→    import {Game} from './engine/engine.js';
 51→    import {Editor} from './engine/editor.js';
 52→    import {ENGINE_I18N} from './engine/i18n.js';
 53→
 54→    // --- Query params --------------------------------------------------------
 55→    const params = new URLSearchParams(location.search);
 56→    const gameId = params.get('game') || 'leeuwenhoek';
 57→    const lang = (params.get('lang') || 'cs').toLowerCase();
 58→    const baseUrl = `./games/${gameId}/`;
 59→
 60→    // Per-game CSS (overrides fonty, barvy, tvary…). Stačí soubor přidat do /games/<gameId>/game.css
 61→    (function attachPerGameCss() {
 62→        const link = document.createElement('link');
 63→        link.rel = 'stylesheet';
 64→        link.href = `${baseUrl}game.css`;
 65→        // Když soubor neexistuje, prohlížeč to jen zapíše do konzole; funkčně nevadí.
 66→        document.head.appendChild(link);
 67→    })();
 68→
 69→    // --- Helpers -------------------------------------------------------------
 70→    async function fetchJsonSafe(url) {
 71→        try {
 72→            const r = await fetch(url, {cache: 'no-cache'});
 73→            if (!r.ok) throw new Error(r.statusText);
 74→            return await r.json();
 75→        } catch {
 76→            return {};
 77→        }
 78→    }
 79→
 80→    // --- Boot ---------------------------------------------------------------
 81→    (async () => {
 82→        // Optional per-game i18n
 83→        const gameI18n = await fetchJsonSafe(`${baseUrl}i18n/${lang}.json`);
 84→
 85→        // Instantiate engine
 86→        const game = new Game({
 87→            baseUrl,
 88→            scenesUrl: `${baseUrl}scenes.json`,
 89→            dialogsUrl: `${baseUrl}dialogs.json`,
 90→            lang,
 91→            i18n: {
 92→                engine: ENGINE_I18N?.[lang] || ENGINE_I18N?.cs || {},
 93→                game: gameI18n || {},
 94→            },
 95→            // DOM refs
 96→            sceneImage: document.getElementById('sceneImage'),
 97→            hotspotLayer: document.getElementById('hotspotLayer'),
 98→            inventoryRoot: document.getElementById('inventory'),
 99→            messageBox: document.getElementById('msg'),
100→            modalRoot: document.getElementById('modal'),
101→            modalTitle: document.getElementById('modalTitle'),
102→            modalBody: document.getElementById('modalBody'),
103→            modalCancel: document.getElementById('modalCancel'),
104→            modalOk: document.getElementById('modalOk'),
105→        });
106→
107→        // Editor (draw hotspots)
108→        const editor = new Editor({
109→            game,
110→            overlay: document.getElementById('editorOverlay'),
111→            hotspotLayer: document.getElementById('hotspotLayer'),
112→        });
113→
114→        // Expose for quick debugging (toasts etc.)
115→        window.__game = game;
116→
117→        // UI actions
118→        document.getElementById('btnRestart').addEventListener('click', () => game.restart());
119→        document.getElementById('btnEditor').addEventListener('click', () => editor.toggle());
120→
121→        // Optional PWA (activated only with ?pwa=1)
122→        if ('serviceWorker' in navigator && params.get('pwa') === '1') {
123→            navigator.serviceWorker.register('./service-worker.js').catch(console.error);
124→        }
125→
126→        // Init engine (loads scenes, renders first scene, runs enterScene events)
127→        await game.init();
128→
129→        // Maintain consistent scene aspect (warn on drift)
130→        (function setSceneAspectWatcher() {
131→            const sceneImg = document.getElementById('sceneImage');
132→            let baselineAspect = null; // h/w
133→
134→            function setAspectFrom(img) {
135→                const iw = img.naturalWidth || 16;
136→                const ih = img.naturalHeight || 9;
137→                document.documentElement.style.setProperty('--scene-aspect', `${iw} / ${ih}`);
138→                baselineAspect = ih / iw;
139→            }
140→
141→            function checkDrift(img) {
142→                if (!baselineAspect) return;
143→                const iw = img.naturalWidth || 16;
144→                const ih = img.naturalHeight || 9;
145→                const a = ih / iw;
146→                const drift = Math.abs(a - baselineAspect) / baselineAspect;
147→                if (drift > 0.02) {
148→                    window.__game?.toast?.('Pozor: tento obrázek má jiný poměr stran než baseline. Doporučeno sjednotit.', 5000);
149→                }
150→            }
151→
152→            sceneImg.addEventListener('load', () => {
153→                if (!baselineAspect) setAspectFrom(sceneImg);
154→                checkDrift(sceneImg);
155→            });
156→        })();
157→    })();
158→</script>
159→</body>
