 408→/* Stage holds two portrait anchors that sit on the panel's top edge */
 409→.dlg-stage {
 410→    position: relative;
 411→    min-height: 0;
 412→    overflow: hidden;
 413→    pointer-events: none; /* Transparent for portraits */
 414→    z-index: 1100;
 415→}
