 519→/* ==========================================================================
 520→   Dialog choices – unified with puzzle buttons
 521→   - Scoped to .dlg-overlay to prevent global leaks
 522→   - Pill buttons around text (no 100% width)
 523→   - Green hover/confirm to match OK/correct visuals
 524→   ========================================================================== */
 525→
 526→.dlg-overlay {
 527→    /* Stable dialog-scoped tokens (optionally reading from puzzles.css) */
 528→    --dlg-choice-bg: rgba(255, 255, 255, 0.10);
 529→    --dlg-choice-border: rgba(255, 255, 255, 0.35);
 530→    --dlg-choice-text: rgba(255, 255, 255, 0.95);
