 533→    /* Green look aligned with OK/correct - EXPLICIT VALUES */
 534→    --dlg-choice-hover-bg: rgba(80, 200, 120, 0.25);
 535→    --dlg-choice-hover-border: rgba(80, 200, 120, 0.65);
 536→    --dlg-choice-selected-bg: rgba(80, 200, 120, 0.30);
 537→    --dlg-choice-selected-border: rgba(80, 200, 120, 0.75);
 538→
 539→    --dlg-t: 250ms ease;
 540→}
