 767→    box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.12);
 768→}
 769→
 770→#modal .btn:active {
 771→    transform: translateY(1px);
 772→}
 773→
 774→/* Use button: neutral by default; turns blue on hover/focus */
 775→#modal .btn--action {
 776→    /* inherit base neutral styles from #modal .btn */
 777→    /* intentionally no custom background/border here */
 778→}
 779→
 780→#modal .btn--action:hover,
 781→#modal .btn--action:focus-visible {
 782→    background: #2a3b6a;
 783→    border-color: #2d72ff;
