 795→
 796→/* ==========================================================================
 797→   HOTSPOT STATES SYSTEM
 798→   ========================================================================== */
 799→
 800→/* Content container inside hotspot (text, icon) - Centered by default */
 801→.hotspot .hs-content {
 802→    position: absolute;
 803→    left: 50%;
 804→    top: 50%;
 805→    transform: translate(-50%, -50%);
 806→    pointer-events: none;
 807→    font-weight: 700;
 808→    font-size: 2.2rem;
 809→    text-shadow: 0 2px 8px rgba(0,0,0,0.9);
 810→    z-index: 10;
 811→    white-space: nowrap;
