 813→
 814→/* Image overlay inside hotspot - Fills the area */
 815→.hotspot .hs-image {
 816→    width: 100%;
 817→    height: 100%;
 818→    object-fit: contain;
 819→    display: block;
 820→    pointer-events: none;
 821→    z-index: 5;
 822→}
 823→
 824→/* --- STATE: SUCCESS ---
 825→   Generic style for completed tasks/slots.
 826→*/
 827→#hotspotLayer .hotspot.state-success {
 828→    border: 2px solid rgba(88, 197, 154, 0.9) !important;
 829→    background: rgba(88, 197, 154, 0.25) !important;
 830→    box-shadow: 0 0 20px rgba(88, 197, 154, 0.6), inset 0 0 15px rgba(88, 197, 154, 0.3) !important;
 831→    transition: all 0.6s cubic-bezier(0.22, 1, 0.36, 1);
 832→
 833→    cursor: default !important;
 834→    opacity: 1 !important;
 835→}
 836→
 837→.hotspot.state-success .hs-content {
 838→    color: #58c59a;
