 840→}
 841→
 842→@keyframes hs-pop-success {
 843→    0% {
 844→        opacity: 0;
 845→        transform: translate(-50%, -50%) scale(0.5);
 846→    }
 847→    100% {
 848→        opacity: 1;
 849→        transform: translate(-50%, -50%) scale(1);
 850→    }
 851→}
 852→
 853→/* --- STATE: LOCKED --- */
