 858→
 859→/* ==========================================================================
 860→   VIDEO PLAYER OVERLAY
 861→   ========================================================================== */
 862→
 863→.video-overlay {
 864→    position: absolute;
 865→    z-index: 9500; /* Above dialogs (1100) and highlights (9000) */
 866→    background: #000;
