 924→
 925→/* ==========================================================================
 926→   ITEM DRAG & DROP SYSTEM
 927→   ========================================================================== */
 928→
 929→/* Item being dragged */
 930→.item.is-dragging {
 931→    opacity: 0.5;
 932→    transform: scale(0.95);
 933→    box-shadow: none !important;
 934→}
 935→
 936→/* Body state when dragging an item */
 937→body.item-dragging {
 938→    cursor: grabbing;
 939→}
 940→
 941→body.item-dragging .hotspot {
 942→    /* Make hotspots more visible during drag */
 943→    transition: all 0.2s ease;
 944→}
 945→
 946→/* Hotspot that can accept the dragged item */
 947→#hotspotLayer .hotspot.accepts-drop {
 948→    border: 2px dashed rgba(88, 197, 154, 0.7) !important;
 949→    background: rgba(88, 197, 154, 0.15) !important;
 950→    animation: pulse-accept 1.2s ease-in-out infinite;
 951→}
 952→
 953→@keyframes pulse-accept {
 954→    0%, 100% {
 955→        box-shadow: 0 0 10px rgba(88, 197, 154, 0.3);
 956→    }
 957→    50% {
 958→        box-shadow: 0 0 20px rgba(88, 197, 154, 0.6);
 959→    }
 960→}
 961→
 962→/* Hotspot currently under the drag cursor */
 963→#hotspotLayer .hotspot.drop-target {
 964→    border: 3px solid rgba(88, 197, 154, 1) !important;
 965→    background: rgba(88, 197, 154, 0.35) !important;
 966→    box-shadow: 0 0 30px rgba(88, 197, 154, 0.8), inset 0 0 15px rgba(88, 197, 154, 0.4) !important;
 967→    transform: scale(1.02);
 968→}
 969→
 970→/* Touch drag ghost element */
 971→.item-drag-ghost {
 972→    position: fixed;
 973→    z-index: 10000;
 974→    pointer-events: none;
 975→    display: flex;
 976→    align-items: center;
 977→    gap: 8px;
 978→    background: rgba(20, 22, 28, 0.95);
 979→    border: 2px solid rgba(88, 197, 154, 0.8);
 980→    border-radius: 10px;
 981→    padding: 8px 12px;
 982→    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.5), 0 0 20px rgba(88, 197, 154, 0.4);
 983→    max-width: 200px;
 984→    animation: ghost-appear 0.15s ease-out;
 985→}
 986→
 987→@keyframes ghost-appear {
 988→    from {
 989→        opacity: 0;
 990→        transform: scale(0.8);
 991→    }
 992→    to {
 993→        opacity: 1;
 994→        transform: scale(1);
 995→    }
 996→}
 997→
 998→.item-drag-ghost img {
 999→    width: 36px;
1000→    height: 36px;
1001→    object-fit: contain;
1002→    border-radius: 4px;
1003→}
1004→
1005→.item-drag-ghost span {
1006→    font-size: 14px;
1007→    color: #f5f5f5;
1008→    white-space: nowrap;
1009→    overflow: hidden;
1010→    text-overflow: ellipsis;
1011→}
1012→
1013→/* Prevent text selection and default touch actions during drag */
1014→body.item-dragging * {
1015→    user-select: none !important;
1016→    -webkit-user-select: none !important;
1017→}
1018→
1019→/* Touch device specific: prevent accidental scrolling during item drag */
1020→@media (hover: none) and (pointer: coarse) {
1021→    .item {
1022→        touch-action: manipulation;
1023→    }
1024→
1025→    body.item-dragging {
1026→        overflow: hidden;
1027→        touch-action: none;
1028→    }
1029→}

  1→/* ============================================================================
  2→   PUZZLES 2.0 - Universal CSS Framework
  3→   - Semi-transparent colors (NEVER fully opaque - background must show)
  4→   - Hierarchical theming: engine → game → puzzle → token
  5→   - Smooth animations for all state changes
  6→   - Responsive layout (auto vertical/horizontal/grid + manual)
  7→   ============================================================================ */
  8→
  9→.pz {
 10→    /* === TYPOGRAPHY === */
 11→    --pz-font-family: inherit;
 12→    --pz-font-size-base: 1rem;
 13→    --pz-font-size-title: 1.3em;
 14→    --pz-font-size-prompt: 1.05em;
 15→
 16→    /* === COLORS (semi-transparent) === */
 17→    --pz-text-color: rgba(255, 255, 255, 0.92);
 18→    --pz-token-text-color: rgba(255, 255, 255, 0.92); /* NEW: token-specific text color */
 19→
 20→    /* Tokens */
 21→    --pz-token-bg: rgba(255, 255, 255, 0.12);
 22→    --pz-token-border: rgba(255, 255, 255, 0.35);
 23→    --pz-token-radius: 14px;
 24→    --pz-token-pad-v: 0.9vh;
 25→    --pz-token-pad-h: 1.2vw;
 26→    --pz-token-gap: 1.2vh;
 27→
 28→    /* Buttons */
 29→    --pz-btn-bg: rgba(255, 255, 255, 0.10);
 30→    --pz-btn-border: rgba(255, 255, 255, 0.35);
 31→    --pz-btn-radius: 12px;
 32→    --pz-btn-text: rgba(255, 255, 255, 0.95);
 33→
 34→    /* States */
 35→    --pz-selected-bg: rgba(90, 160, 255, 0.22);
 36→    --pz-selected-border: rgba(90, 160, 255, 0.5);
 37→
 38→    --pz-correct-bg: rgba(20, 220, 90, 0.22);
 39→    --pz-correct-border: rgba(20, 220, 90, 0.65);
 40→
 41→    --pz-wrong-bg: rgba(220, 40, 40, 0.22);
 42→    --pz-wrong-border: rgba(220, 40, 40, 0.65);
 43→
 44→    --pz-hint-border: rgba(255, 200, 80, 0.5);
 45→
 46→    /* Effects */
 47→    --pz-outline-glow: 0 0 0 3px rgba(255, 255, 255, 0.18);
 48→    --pz-hover-boost: 0 0 0 3px rgba(255, 255, 255, 0.10);
 49→    --pz-transition-fast: 160ms ease;
 50→    --pz-transition-normal: 250ms ease;
 51→    --pz-transition-slow: 350ms ease;
 52→
 53→    /* === BASE STYLES === */
 54→    font-family: var(--pz-font-family);
 55→    font-size: var(--pz-font-size-base);
 56→    color: var(--pz-text-color);
 57→    position: absolute;
 58→    box-sizing: border-box;
 59→    pointer-events: auto;
 60→    user-select: none;
 61→}
 62→
 63→.pz * {
 64→    box-sizing: border-box;
 65→}
 66→
 67→/* ============================================================================
 68→   STRUCTURE: Root → Window → Flow
 69→   ============================================================================ */
 70→
 71→/* Pracovní okno - pozicované v procentech uvnitř rootu */
 72→.pz__window {
 73→    position: absolute;
 74→    /* pozice se nastaví inline přes workRect */
 75→    overflow: hidden;
 76→    /* DEBUG - odkomentuj pro vizualizaci */
 77→    /* border: 2px dashed rgba(255, 0, 0, 0.5); */
 78→    /* background: rgba(255, 255, 0, 0.1); */
 79→}
 80→
 81→/* ============================================================================
 82→   LAYOUT: Auto (vertical/horizontal/grid) + Manual
 83→   ============================================================================ */
 84→
 85→/* AUTO flow */
 86→.pz--auto .pz__flow {
 87→    position: absolute;
 88→    inset: 0;
 89→    display: flex;
 90→    flex-wrap: nowrap;
 91→    gap: var(--pz-token-gap);
 92→    padding: 2vh 2vw;
 93→    align-items: stretch;
 94→    box-sizing: border-box;
 95→}
 96→
 97→.pz--auto.pz--vertical .pz__flow {
 98→    flex-direction: column;
 99→    justify-content: space-between;
100→}
101→
102→.pz--auto.pz--horizontal .pz__flow {
103→    flex-direction: row;
104→    flex-wrap: wrap;
105→    justify-content: center; /* CRITICAL: center content horizontally */
106→    align-items: center;
107→    align-content: center; /* CRITICAL: center wrapped rows vertically */
108→}
109→
110→/* ============================================================================
111→   HORIZONTAL MODE - General rules (for all kinds except phrase/code)
112→   ============================================================================ */
113→
114→/* Header (title + prompt) stays at top, centered */
115→.pz--horizontal .pz-header-group {
116→    width: 100%;
117→    text-align: center;
118→    flex: 0 0 auto;
119→}
120→
121→/* Token area wraps horizontally, centered */
122→.pz--horizontal .pz-token-area {
123→    width: 100%;
124→    display: flex;
125→    flex-direction: row;
126→    flex-wrap: wrap;
127→    justify-content: center; /* CRITICAL: center tokens */
128→    gap: var(--pz-token-gap);
129→}
130→
131→/* Footer (buttons) centered at bottom */
132→.pz--horizontal .pz-footer {
133→    width: 100%;
134→    display: flex;
135→    justify-content: center; /* CRITICAL: center buttons, not right */
136→    gap: var(--pz-token-gap);
137→    flex: 0 0 auto;
138→}
139→
140→/* ============================================================================
141→   HORIZONTAL MODE - phrase/code exceptions (input + buttons on same row)
142→   ============================================================================ */
143→
144→/* phrase/code: special layout override */
145→.pz--horizontal.pz--kind-phrase .pz__flow,
146→.pz--horizontal.pz--kind-code .pz__flow {
147→    justify-content: center;
148→    align-items: center;
149→    align-content: center;
150→}
151→
152→.pz--horizontal.pz--kind-phrase .pz-header-group,
153→.pz--horizontal.pz--kind-code .pz-header-group {
154→    width: 100%;
155→    text-align: center;
156→}
157→
158→/* Input + buttons row */
159→.pz--horizontal.pz--kind-phrase .pz-input-wrap,
160→.pz--horizontal.pz--kind-code .pz-input-wrap {
161→    flex: 0 1 auto; /* don't grow excessively */
162→    max-width: 600px;
163→    min-width: 300px;
164→}
165→
166→.pz--horizontal.pz--kind-phrase .pz-footer,
167→.pz--horizontal.pz--kind-code .pz-footer {
168→    flex: 0 0 auto;
169→    width: auto; /* CRITICAL: don't take full width */
170→    justify-content: flex-start; /* align with input */
171→    margin-left: 0; /* no auto margin */
172→}
173→
174→/* ============================================================================
175→   HORIZONTAL MODE - order kind (two rows: shuffled + ordered)
176→   ============================================================================ */
177→
178→.pz--horizontal.pz--kind-order .pz-order-container {
179→    grid-template-columns: 1fr !important;
180→    grid-template-rows: 1fr 1fr !important;
181→}
182→
183→.pz--horizontal.pz--kind-order .pz-area {
184→    flex-direction: row !important;
185→    flex-wrap: wrap !important;
186→    justify-content: center !important; /* center tokens in area */
187→}
188→
189→/* ============================================================================
190→   HORIZONTAL MODE - match kind (two rows: left + right)
191→   ============================================================================ */
192→
193→.pz--horizontal.pz--kind-match .pz-match-columns {
194→    grid-template-columns: 1fr !important;
195→    grid-template-rows: 1fr 1fr !important;
196→}
197→
198→.pz--horizontal.pz--kind-match .pz-match-column {
199→    flex-direction: row !important;
200→    flex-wrap: wrap !important;
201→    justify-content: center !important; /* center tokens in column */
202→}
203→
204→/* ============================================================================
205→   HORIZONTAL MODE - group kind (grid: rows first, then columns)
206→   ============================================================================ */
207→
208→.pz--horizontal.pz--kind-group .pz-group-board {
209→    justify-items: center; /* center groups in grid cells */
210→}
211→
212→/* GRID layout */
213→.pz--grid .pz__flow {
214→    position: absolute;
215→    inset: 0;
216→    display: grid;
217→    grid-auto-rows: min-content;
218→    gap: var(--pz-token-gap);
219→    padding: 2vh 2vw;
220→}
221→
222→.pz--grid .pz__flow[data-cols="2"] {
223→    grid-template-columns: repeat(2, 1fr);
224→}
225→
226→.pz--grid .pz__flow[data-cols="3"] {
227→    grid-template-columns: repeat(3, 1fr);
228→}
229→
230→.pz--grid .pz__flow[data-cols="4"] {
231→    grid-template-columns: repeat(4, 1fr);
232→}
233→
234→/* MANUAL layout - žádné auto positioning */
235→.pz--manual .pz__flow {
236→    position: absolute;
237→    inset: 0;
238→    padding: 2vh 2vw;
239→}
240→
241→/* ============================================================================
242→   HEADER GROUP (Title + Prompt)
243→   ============================================================================ */
244→
245→.pz-header-group {
246→    flex: 0 0 auto;
247→    display: flex;
248→    flex-direction: column;
249→    gap: 0.8vh;
250→}
251→
252→.pz-title {
253→    font-weight: 700;
254→    font-size: var(--pz-font-size-title);
255→    margin-bottom: 0;
256→    flex: 0 0 auto;
257→    text-align: center;
258→}
259→
260→.pz-prompt {
261→    opacity: 0.9;
262→    font-size: var(--pz-font-size-prompt);
263→    margin-bottom: 0;
264→    flex: 0 0 auto;
265→    text-align: center;
266→}
267→
268→/* ============================================================================
269→   TOKEN AREA - kontejner pro tokens (auto/grid/manual)
270→   ============================================================================ */
271→
272→.pz-token-area {
273→    flex: 1 1 auto; /* roste a zabírá volné místo */
274→    min-height: 0; /* umožňuje scroll pokud je potřeba */
275→    display: flex;
276→    flex-direction: column;
277→    gap: var(--pz-token-gap);
278→}
279→
280→/* ============================================================================
281→   TOKENS - jednotné stylování pro všechny puzzle kinds
282→   ============================================================================ */
283→
284→.pz-token {
285→    background: var(--pz-token-bg);
286→    border: 1px solid var(--pz-token-border);
287→    border-radius: var(--pz-token-radius);
288→    padding: var(--pz-token-pad-v) var(--pz-token-pad-h);
289→    color: var(--pz-token-text-color); /* Use CSS variable for easy override */
290→    cursor: pointer;
291→    display: flex;
292→    align-items: center;
293→    justify-content: center;
294→    gap: 0.6em;
295→    text-align: center;
296→    transition: background var(--pz-transition-normal),
297→    border-color var(--pz-transition-normal),
298→    box-shadow var(--pz-transition-fast),
299→    transform 80ms ease;
300→    backdrop-filter: saturate(110%) blur(1px);
301→}
302→
303→/* Hover effect - only on devices with actual hover capability (not touch) */
304→@media (hover: hover) {
305→    .pz-token:hover {
306→        box-shadow: var(--pz-hover-boost);
307→    }
308→}
309→
310→/* MATCH only — disable :hover on touch devices to avoid sticky hover overlaying pair color */
311→@media (hover: none), (pointer: coarse) {
312→    .pz--kind-match .pz-token:hover,
313→    .pz-kind-match .pz-token:hover {
314→        background: inherit !important;
315→        border-color: inherit !important;
316→        box-shadow: none !important;
317→        transform: none !important;
318→    }
319→}
320→
321→.pz.is-touch.pz--kind-match .pz-token:hover,
322→.pz.is-touch.pz-kind-match .pz-token:hover {
323→    background: inherit !important;
324→    border-color: inherit !important;
325→    box-shadow: none !important;
326→    transform: none !important;
327→}
328→
329→.pz--kind-match .pz-token,
330→.pz-kind-match .pz-token {
331→    -webkit-tap-highlight-color: transparent;
332→    touch-action: manipulation;
333→}
334→
335→.pz-token:active {
336→    transform: translateY(1px);
337→}
338→
339→/* Token states - animated */
340→.pz-token.is-selected,
341→.pz-token.selected {
342→    background: var(--pz-selected-bg);
343→    border-color: var(--pz-selected-border);
344→    box-shadow: var(--pz-outline-glow);
345→}
346→
347→.pz-token.is-correct,
348→.pz-token.correct {
349→    background: var(--pz-correct-bg);
350→    border-color: var(--pz-correct-border);
351→    animation: token-pulse-correct 0.4s ease;
352→}
353→
354→.pz-token.is-wrong,
355→.pz-token.wrong {
356→    background: var(--pz-wrong-bg);
357→    border-color: var(--pz-wrong-border);
358→    animation: token-shake 0.4s ease;
359→}
