669→    overflow-wrap: break-word;
670→    display: flow-root; /* Better than inline for wrapping with inline-block gaps */
671→}
672→
673→/* Gap - empty slot for token (inline-block for proper text flow) */
674→.pz-cloze-gap {
675→    display: inline-block;
676→    min-width: 80px;
677→    height: 1.6em;
678→    margin: 0 4px;
679→    padding: 2px 8px;
680→    background: rgba(255, 255, 255, 0.08);
