697→/* Gap with token inside */
698→.pz-cloze-gap.filled {
699→    border-style: solid;
700→    border-color: transparent;
701→    background: transparent;
702→    padding: 0;
703→    min-width: auto;
704→    height: auto;
705→    line-height: inherit; /* Použij line-height z parent elementu */
706→}
707→
708→/* Token inside gap - compact style */
709→.pz-cloze-gap.filled .pz-token {
710→    margin: 0;
711→    display: inline-block;
712→    height: auto;
713→    padding: 0.2em 0.8em;
