807→/* ============================================================================
808→   MATCH - Side Differentiation (dragdrop mode)
809→   ============================================================================ */
810→
811→/* Left side tokens - blue tint with left border accent (only when NOT paired) */
812→.pz-match--dragdrop .pz-match-token--left:not([data-pair-index]) {
813→    background: rgba(100, 150, 255, 0.15);
814→    border-left: 4px solid rgba(100, 150, 255, 0.6);
815→}
816→
817→/* Right side tokens - green/teal tint with right border accent (only when NOT paired) */
818→.pz-match--dragdrop .pz-match-token--right:not([data-pair-index]) {
819→    background: rgba(100, 255, 150, 0.15);
820→    border-right: 4px solid rgba(100, 255, 150, 0.6);
821→}
822→
823→/* Hover effects for sides (only on hover-capable devices and NOT paired) */
824→@media (hover: hover) {
825→    .pz-match--dragdrop .pz-match-token--left:not([data-pair-index]):hover {
826→        background: rgba(100, 150, 255, 0.25);
827→        box-shadow: 0 0 8px rgba(100, 150, 255, 0.4);
828→    }
829→
830→    .pz-match--dragdrop .pz-match-token--right:not([data-pair-index]):hover {
831→        background: rgba(100, 255, 150, 0.25);
832→        box-shadow: 0 0 8px rgba(100, 255, 150, 0.4);
833→    }
834→}
835→
836→/* When tokens are paired in dragdrop, reset border to normal and allow inline background */
837→.pz-match--dragdrop .pz-match-token--left[data-pair-index],
838→.pz-match--dragdrop .pz-match-token--right[data-pair-index] {
839→    /* Reset borders to normal token border */
840→    border-left: 1px solid var(--pz-token-border);
841→    border-right: 1px solid var(--pz-token-border);
842→    /* Background is set via inline style (pair color) */
843→}
844→
845→/* ============================================================================
846→   MATCH - Shake Animation for Wrong Pairs
847→   ============================================================================ */
848→
849→@keyframes shake {
850→    0%, 100% { transform: translate(-50%, -50%) translateX(0); }
851→    10%, 30%, 50%, 70%, 90% { transform: translate(-50%, -50%) translateX(-10px); }
852→    20%, 40%, 60%, 80% { transform: translate(-50%, -50%) translateX(10px); }
853→}
854→
855→.pz-match-token.is-wrong {
856→    animation: shake 0.5s ease-in-out;
857→}
858→
859→/* Columns mode wrong pairs - shake animation */
860→.pz-match--columns .pz-token.is-wrong {
861→    animation: shake-static 0.5s ease-in-out;
862→}
863→
864→@keyframes shake-static {
865→    0%, 100% { transform: translateX(0); }
866→    10%, 30%, 50%, 70%, 90% { transform: translateX(-8px); }
867→    20%, 40%, 60%, 80% { transform: translateX(8px); }
868→}

