 1→// games/tests/setup.localstorage.js
 2→// Simple in-memory localStorage polyfill for Vitest (Node) runs.
 3→// Some environments expose a stub without methods; we ensure a real implementation exists.
 4→
 5→class MemoryStorage {
 6→  constructor() { this._m = new Map(); }
 7→  get length() { return this._m.size; }
 8→  key(n) { return Array.from(this._m.keys())[n] ?? null; }
 9→  getItem(k) { k = String(k); return this._m.has(k) ? this._m.get(k) : null; }
10→  setItem(k, v) { this._m.set(String(k), String(v)); }
11→  removeItem(k) { this._m.delete(String(k)); }
12→  clear() { this._m.clear(); }
13→}
14→
15→const ensureStorage = () => {
16→  const store = new MemoryStorage();
17→  // attach to global and window (if present)
18→  globalThis.localStorage = store;
19→  if (globalThis.window) {
20→    globalThis.window.localStorage = store;
21→  } else {
22→    // minimal window shim for code paths that check window.localStorage
23→    globalThis.window = { localStorage: store };
24→  }
25→};
26→
27→ensureStorage();
28→
29→// Optional: silence unhandled pointer events in JSDOM <-> Node
30→if (!globalThis.PointerEvent) {
31→  globalThis.PointerEvent = class extends Event {
32→    constructor(type, opts = {}) { super(type, opts); Object.assign(this, opts); }
33→  };
34→}
