}

/* ------------------------------------------------------------------ */
/*  Block rendering                                                   */
/* ------------------------------------------------------------------ */

/**
 * Render an array of block tokens into an HTML string.
 *
 * @param {Block[]} blocks - Tokenised block array.
 * @returns {string} Complete HTML output.
