          "onApply": { "setFlags": ["slot_rel_ok"], "message": "Relativistická synchronizace v toleranci." },
          "states": [ { "requireFlags": ["slot_rel_ok"], "cssClass": "state-success", "content": "✓", "clickable": false } ]
        }
      ]
    },
    {
      "id": "exit",
      "title": "Let k hvězdám",
      "image": "assets/scenes/warp-flight.jpg",
      "end": true,
      "hotspots": []
    }
  ],

  "events": [
    {
      "id": "dlg-intro-start",
