   1→// engine/engine.js
   2→// Game engine core: scenes, i18n, dialogs, hero profile, inventory, puzzles, events, content panels.
   3→
   4→import {createPuzzleRunner, openListModal} from './puzzles/index.js';
   5→import {DialogUI} from './dialogs.js';
   6→import {ContentPanel} from './content.js';
   7→
   8→export class Game {
   9→    constructor(opts) {
  10→        // DOM refs
  11→        this.sceneImage = opts.sceneImage;
  12→        this.hotspotLayer = opts.hotspotLayer;
  13→        this.inventoryRoot = opts.inventoryRoot;
  14→        this.messageBox = opts.messageBox;
  15→        this.modalRoot = opts.modalRoot;
  16→        this.modalTitle = opts.modalTitle;
  17→        this.modalBody = opts.modalBody;
  18→        this.modalCancel = opts.modalCancel;
  19→        this.modalOk = opts.modalOk;
  20→
  21→        // Data sources
  22→        this.baseUrl = opts.baseUrl || './';
  23→        this.scenesUrl = opts.scenesUrl;          // already prefixed by caller
  24→        this.dialogsUrl = opts.dialogsUrl || null; // ./games/<id>/dialogs.json (optional)
  25→        this.lang = (opts.lang || 'cs').toLowerCase();
  26→        this.i18n = opts.i18n || {engine: {}, game: {}};
  27→
  28→        // State
  29→        this.data = null;
  30→        this.meta = {};
  31→        this.dialogsData = null;
  32→        this.state = null;
  33→        this.currentScene = null;
  34→        this._modalResolve = null;
  35→        this._pendingHighlights = {};
  36→
  37→        // Toast container
  38→        this.toastRoot = document.createElement('div');
  39→        this.toastRoot.className = 'toast-container';
  40→        document.body.appendChild(this.toastRoot);
  41→
  42→        // Dialog UI
  43→        this.dialogUI = new DialogUI(this);
  44→
  45→        // Content Panel UI
  46→        this.contentPanel = new ContentPanel(this);
  47→
  48→        // Modal events
  49→        this.modalCancel.addEventListener('click', () => this._closeModal(false));
  50→        this.modalOk.addEventListener('click', () => this._closeModal(true));
  51→
  52→        // ESC = exit use-mode
  53→        document.addEventListener('keydown', (e) => {
  54→            if (e.key === 'Escape' && this.state?.useItemId) {
  55→                this.exitUseMode();
  56→                e.preventDefault();
  57→            }
  58→        });
  59→    }
  60→
  61→    // --- debug toggles ----------------------------------------------------------
  62→
  63→    _debugOn() {
  64→        try {
  65→            return new URLSearchParams(location.search).get('debug') === '1';
  66→        } catch {
  67→            return false;
  68→        }
  69→    }
  70→
  71→    _dbg(...args) {
  72→        if (this._debugOn()) console.debug('[GAME]', ...args);
  73→    }
  74→
  75→    // --- version signature for safe restore ------------------------------------
  76→
  77→    _signature() {
  78→        const gid = this.meta?.id || 'unknown';
  79→        const gver = this.meta?.version || '0';
  80→        const lang = this.lang || 'cs';
  81→        return `${gid}|${gver}|${lang}`;
  82→    }
  83→
  84→    // --- i18n helpers -----------------------------------------------------------
  85→
  86→    _fmt(str, params) {
  87→        if (!params) return str;
  88→        return String(str).replace(/\{(\w+)}/g, (_, k) => (params[k] ?? `{${k}}`));
  89→    }
  90→
  91→    _t(key, fallback = '', params = null) {
  92→        const g = this.i18n?.game?.[key];
  93→        const e = this.i18n?.engine?.[key];
  94→        const raw = (g != null ? g : (e != null ? e : fallback));
  95→        return this._fmt(raw, params);
  96→    }
  97→
  98→    /**
  99→     * Resolve string | {key} | "@key@fallback".
 100→     */
 101→    _text(val, fallback = '') {
 102→        if (val && typeof val === 'object' && val.key) {
 103→            return this._t(String(val.key), fallback);
 104→        }
 105→        if (typeof val === 'string') {
 106→            const m = val.match(/^@([^@]+)@(.*)$/s);
 107→            if (m) return this._t(m[1].trim(), m[2]);
 108→            return val;
 109→        }
 110→        return (val != null ? String(val) : String(fallback));
 111→    }
 112→
 113→    /** Prefix relative paths with baseUrl. */
 114→    _resolveAsset(path) {
 115→        if (!path) return path;
 116→        const s = String(path);
 117→        if (/^(?:https?:)?\/\//i.test(s)) return s;           // absolute URL
 118→        if (s.startsWith('./') || s.startsWith('/')) return s; // already rooted
 119→        return this.baseUrl.replace(/\/+$/, '/') + s.replace(/^\/+/, '');
 120→    }
 121→
 122→    // --- lifecycle --------------------------------------------------------------
 123→
 124→    async init() {
 125→        this.data = await fetch(this.scenesUrl, {cache: 'no-cache'}).then(r => r.json());
 126→        this.modalRoot.classList.add('hidden');
 127→
 128→        this.meta = this.data?.meta || {};
 129→
 130→        // Query flags
 131→        let forceReset = false;
 132→        let urlHero = null;
 133→        try {
 134→            const p = new URLSearchParams(location.search);
 135→            forceReset = p.get('reset') === '1';
 136→            urlHero = p.get('hero'); // may be null
 137→        } catch { /* noop */
 138→        }
 139→
 140→        const saved = forceReset ? null : this._loadState();
 141→        const okSaved = !!saved && saved.signature === this._signature();
 142→
 143→        // fresh state if signature changed or reset requested
 144→        this.state = okSaved ? saved : {
 145→            signature: this._signature(),
 146→            inventory: [],
 147→            solved: {},
 148→            flags: {},
 149→            visited: {},
 150→            eventsFired: {},
 151→            scene: this.data.startScene || this.data.scenes[0]?.id,
 152→            useItemId: null,
 153→            hero: null,
 154→            puzzleResults: [], // aggregateOnly results bucket
 155→            contentShown: {}  // tracks "once" content panels
 156→        };
 157→
 158→        // initialize hero (default → then URL override if present)
 159→        if (!this.state.hero) {
 160→            const defId = this.data?.defaultHero || Object.keys(this.data?.heroes || {})[0] || 'adam';
 161→            this._setHeroInternal(defId);
 162→        }
 163→        if (urlHero) {
 164→            // URL always wins (do not nuke progress)
 165→            this._setHeroInternal(urlHero);
 166→            this._dbg('[HERO] overridden from URL →', urlHero, this.state.hero);
 167→        }
 168→
 169→        await this.goto(this.state.scene, {noSave: true});
 170→        this._renderInventory();
 171→    }
 172→
 173→    restart() {
 174→        localStorage.removeItem('leeuwenhoek_escape_state');
 175→        location.reload();
 176→    }
 177→
 178→    async goto(sceneId, opts = {}) {
 179→        const scene = this.data.scenes.find(s => s.id === sceneId);
 180→        if (!scene) return this._msg(this._t('engine.sceneNotFound', 'Scéna nebyla nalezena: {id}', {id: sceneId}));
 181→
 182→        this.currentScene = scene;
 183→        this.state.scene = sceneId;
 184→        this.state.visited[sceneId] = true;
 185→        if (!opts.noSave) this._saveState();
 186→
 187→        this.sceneImage.src = this._resolveAsset(scene.image);
 188→        await new Promise(res => {
 189→            if (this.sceneImage.complete && this.sceneImage.naturalWidth) res();
 190→            else this.sceneImage.onload = () => res();
 191→        });
 192→
 193→        this._renderHotspots();
 194→        this._msg(this._text(scene.title) || '');
 195→
 196→        // queued highlights for this scene
 197→        this._drainHighlightsForScene(sceneId);
 198→        // events: enterScene
 199→        await this._processEvents({on: 'enterScene', scene: sceneId});
 200→
 201→        // scene-level auto content panel
 202→        if (scene.content?.ref) {
 203→            const trigger = scene.content.trigger || 'enter';
 204→            if (trigger === 'enter') {
 205→                const cId = scene.content.ref;
 206→                const cOnce = scene.content.once ?? true;
 207→                if (!cOnce || !this.state.contentShown?.[cId]) {
 208→                    await this.contentPanel.open(cId);
 209→                }
 210→            }
 211→        }
 212→
 213→        if (scene.end) this._msg(this._t('engine.endCongrats', '🎉 Gratulujeme! Našel si cestu ven!'));
 214→    }
 215→
 216→    // --- hero profile -----------------------------------------------------------
 217→
 218→    _getHeroProfileById(id) {
 219→        const map = this.data?.heroes || {};
 220→        return map[id] || null;
 221→    }
 222→
 223→    _setHeroInternal(id) {
 224→        const prof = this._getHeroProfileById(id) || {
 225→            id: 'adam',
 226→            gender: 'm',
 227→            name: 'Adam',
 228→            assetsBase: 'assets/npc/adam/'
 229→        };
 230→        this.state.hero = {
 231→            id: prof.id,
 232→            gender: prof.gender || 'm',
 233→            name: this._text(prof.name) || prof.name || 'Hero',
 234→            assetsBase: prof.assetsBase || 'assets/npc/adam/'
 235→        };
 236→        this._saveState();
 237→    }
 238→
 239→    setHero(id) {
 240→        this._setHeroInternal(id);
 241→    }
 242→
 243→    getHero() {
 244→        return this.state?.hero || this._getHeroProfileById(this.data?.defaultHero) || {
 245→            id: 'adam',
 246→            gender: 'm',
 247→            name: 'Adam',
 248→            assetsBase: 'assets/npc/adam/'
 249→        };
 250→    }
 251→
 252→    getHeroId() {
 253→        return this.getHero().id;
 254→    }
 255→
 256→    getHeroGender() {
 257→        return this.getHero().gender;
 258→    }
 259→
 260→    // --- use mode ---------------------------------------------------------------
 261→
 262→    enterUseMode(itemId) {
 263→        if (!itemId) return;
 264→        this.state.useItemId = itemId;
 265→        document.body.classList.add('use-on');
 266→        this._renderInventory();
 267→        const name = this._itemLabel(itemId);
 268→        this.toast(this._t('engine.use.selected', 'Vybráno k použití: {name}. Klepni na cíl.', {name}), 800);
 269→    }
 270→
 271→    exitUseMode() {
 272→        if (!this.state.useItemId) return;
 273→        this.state.useItemId = null;
 274→        document.body.classList.remove('use-on');
 275→        this._renderInventory();
 276→    }
 277→
 278→    _removeItemFromInventory(id) {
 279→        const i = this.state.inventory.indexOf(id);
 280→        if (i >= 0) {
 281→            this.state.inventory.splice(i, 1);
 282→            this._renderInventory();
 283→        }
 284→    }
 285→
 286→    _getUseGuardPolicy() {
 287→        const s = this.currentScene?.settings?.useGuard
 288→            ?? this.data?.settings?.accessibility?.useGuard
 289→            ?? this.data?.settings?.useGuard; // fallback
 290→        if (s === true) return 'hide';
 291→        return (s === 'hide' || s === 'disable') ? s : 'off';
 292→    }
 293→
 294→    /**
 295→     * Checks if an item can be used in the current scene.
 296→     * @param {string} itemId - The item ID to check.
 297→     * @returns {boolean|null} - true if usable, false if not usable, null if cannot determine (fail-safe).
 298→     */
 299→    _isItemApplicableHere(itemId) {
 300→        // Fail-safe: if currentScene is not loaded, return null to indicate uncertainty
 301→        if (!this.currentScene) {
 302→            this._dbg('[GUARD] _isItemApplicableHere: currentScene is null/undefined, returning null (fail-safe)');
 303→            return null;
 304→        }
 305→
 306→        const hs = this.currentScene.hotspots || [];
 307→
 308→        // If scene has no hotspots at all, we can definitively say item is not usable here
 309→        if (hs.length === 0) {
 310→            return false;
 311→        }
 312→
 313→        return hs.some(h => {
 314→            if (!h || !Array.isArray(h.acceptItems)) return false;
 315→
 316→            const accepts = h.acceptItems.map(x => typeof x === 'string' ? { id: x } : x);
 317→            if (!accepts.some(a => a?.id === itemId)) return false;
 318→
 319→            if (h.requireItems && !this._hasAll(h.requireItems)) return false;
 320→            if (h.requireFlags && !this._hasAllFlags(h.requireFlags)) return false;
 321→
 322→            return true;
 323→        });
 324→    }
 325→
 326→    // --- renderers --------------------------------------------------------------
 327→
 328→    _renderHotspots() {
 329→        this.hotspotLayer.innerHTML = '';
 330→        const hotspots = this.currentScene.hotspots || [];
 331→
 332→        hotspots.forEach((h, idx) => {
 333→            const el = document.createElement('button');
 334→            el.className = 'hotspot';
 335→
 336→            // Default render rectangle (can be overridden by state)
 337→            let visualRect = h.rect;
 338→
 339→            // STATE LOGIC: Find the first matching state (Priority List)
 340→            // The engine checks states from top to bottom. The first one with satisfied requireFlags wins.
 341→            let activeState = null;
 342→            if (h.states && Array.isArray(h.states)) {
 343→                activeState = h.states.find(s => {
 344→                    // If no flags required, it's a default/fallback state
 345→                    if (!s.requireFlags) return true;
 346→                    // Otherwise check if all flags are present
 347→                    return this._hasAllFlags(s.requireFlags);
 348→                });
 349→            }
 350→
 351→            // APPLY ACTIVE STATE
 352→            if (activeState) {
 353→                // 1. CSS Class (e.g., "state-success", "state-locked")
 354→                if (activeState.cssClass) {
 355→                    el.classList.add(activeState.cssClass);
 356→                }
 357→
 358→                // 2. Content (text label, icon, symbol)
 359→                if (activeState.content) {
 360→                    const span = document.createElement('span');
 361→                    span.className = 'hs-content';
 362→                    span.textContent = this._text(activeState.content);
 363→                    el.appendChild(span);
 364→                }
 365→
 366→                // 3. Image Overlay (e.g., specific item graphic)
 367→                if (activeState.image) {
 368→                    const img = document.createElement('img');
 369→                    img.src = this._resolveAsset(activeState.image);
 370→                    img.className = 'hs-image';
 371→                    el.appendChild(img);
 372→                }
 373→
 374→                // 4. Rect Override (if the visual state has different dimensions than the hit area)
 375→                if (activeState.rect) {
 376→                    visualRect = activeState.rect;
 377→                }
 378→
 379→                // 5. Interactivity (disable clicking if the state is final/passive)
 380→                if (activeState.clickable === false) {
 381→                    el.style.pointerEvents = 'none';
 382→                    el.tabIndex = -1;
 383→                }
 384→            }
 385→
 386→            // Apply calculated geometry
 387→            el.style.left = visualRect.x + '%';
 388→            el.style.top = visualRect.y + '%';
 389→            el.style.width = visualRect.w + '%';
 390→            el.style.height = visualRect.h + '%';
 391→
 392→            // Bind interactions (only if not disabled by state)
 393→            if (!activeState || activeState.clickable !== false) {
 394→                el.setAttribute('data-index', String(idx));
 395→
 396→                // Tooltip: prefer state label, fallback to hotspot label
 397→                const label = (activeState && activeState.label) || h.label;
 398→                if (label) el.title = this._text(label);
 399→
 400→                el.addEventListener('click', (e) => {
 401→                    // Editor guard
 402→                    if (document.body.classList.contains('editor-on')) {
 403→                        e.preventDefault(); e.stopPropagation(); return;
 404→                    }
 405→                    e.preventDefault();
 406→                    this._activateHotspot(h).catch(err => this._msg(String(err)));
 407→                });
 408→
 409→                // --- Drop handling for item drag & drop ---
 410→                if (h.acceptItems && Array.isArray(h.acceptItems)) {
 411→                    this._setupHotspotDropHandlers(el, h, idx);
 412→                }
 413→            }
 414→
 415→            this.hotspotLayer.appendChild(el);
 416→        });
 417→    }
 418→
 419→    /**
 420→     * Sets up drag & drop handlers for a hotspot that accepts items.
 421→     * @param {HTMLElement} el - The hotspot element.
 422→     * @param {object} hs - The hotspot configuration.
 423→     * @param {number} idx - The hotspot index.
 424→     */
 425→    _setupHotspotDropHandlers(el, hs, idx) {
 426→        // HTML5 Drag API - dragover is required to allow drop
 427→        el.addEventListener('dragover', (e) => {
 428→            const itemId = e.dataTransfer.types.includes('text/plain') ? 'pending' : null;
 429→            if (itemId) {
 430→                e.preventDefault();
 431→                e.dataTransfer.dropEffect = 'move';
 432→                el.classList.add('drop-target');
 433→            }
 434→        });
 435→
 436→        el.addEventListener('dragleave', (e) => {
 437→            el.classList.remove('drop-target');
 438→        });
 439→
 440→        el.addEventListener('drop', async (e) => {
 441→            e.preventDefault();
 442→            el.classList.remove('drop-target');
 443→
 444→            const itemId = e.dataTransfer.getData('text/plain');
 445→            if (!itemId) return;
 446→
 447→            this._dbg('[DROP] Item dropped on hotspot:', itemId, hs);
 448→            await this._handleItemDropOnHotspot(itemId, hs);
 449→        });
 450→    }
 451→
 452→    async _activateHotspot(h) {
 453→        console.log('[HOTSPOT] Activation triggered:', h.type, h);
 454→
 455→        // 1. Use-mode guard (pokud držíme předmět a hotspot ho neumí přijmout)
 456→        // Pokud hráč drží předmět, ale klikne na něco, co předměty nebere -> chyba.
 457→        if (this.state.useItemId && !h.acceptItems) {
 458→            this.toast(this._t('engine.use.notApplicable', 'Tento předmět tady nelze použít.'), 2500);
 459→            this.exitUseMode();
 460→            return;
 461→        }
 462→
 463→        // 2. Requirements check (Prerekvizity)
 464→        // Kontrola, zda má hráč potřebné předměty v inventáři (pokud jsou vyžadovány)
 465→        if (h.requireItems && !this._hasAll(h.requireItems)) {
 466→            this._msg(this._t('engine.missingItems', 'Něco ti chybí…'));
 467→            return;
 468→        }
 469→        // Kontrola, zda jsou splněny herní flagy (např. odemčeno)
 470→        if (h.requireFlags && !this._hasAllFlags(h.requireFlags)) {
 471→            this._msg(this._t('engine.needUnlock', 'Nejprve musíš něco odemknout…'));
 472→            return;
 473→        }
 474→
 475→        // 3. Item Usage (Accept items) - Pokud hotspot přijímá předměty
 476→        if (h.acceptItems && Array.isArray(h.acceptItems)) {
 477→            const selected = this.state.useItemId;
 478→            // Normalizace acceptItems (může to být string nebo objekt)
 479→            const accepts = h.acceptItems.map(x => (typeof x === 'string' ? {id: x, consume: false} : x));
 480→
 481→            // Zkusíme najít, zda vybraný předmět je v seznamu povolených
 482→            const match = selected ? accepts.find(a => a.id === selected) : null;
 483→
 484→            if (!match) {
 485→                // Hráč drží předmět, ale ten sem nepatří
 486→                if (selected) {
 487→                    this.toast(this._t('engine.use.notApplicable', 'Tento předmět tady nelze použít.'), 2500);
 488→                    this.exitUseMode();
 489→                    return;
 490→                }
 491→                // Hráč nic nedrží, ale hotspot vyžaduje předmět -> zobrazíme hint?
 492→                const allowHint = (h.showNeedHint !== false) && (this.data?.settings?.hints?.acceptNeed !== false);
 493→                if (allowHint) {
 494→                    const need = accepts.map(a => this._itemLabel(a.id)).filter(Boolean).join(', ');
 495→                    this.toast(this._t('engine.use.needItem', 'Potřebuješ použít: {need}.', {need}), 3500);
 496→                }
 497→                return;
 498→            }
 499→
 500→            // SHODA: Hráč použil správný předmět
 501→            if (match.consume) this._removeItemFromInventory(match.id);
 502→            this.exitUseMode();
 503→
 504→            if (h.onApply) await this._applyActions(h.onApply);
 505→            else this.toast(this._t('engine.use.applied', 'Předmět byl použit.'), 2200);
 506→            return;
 507→        }
 508→
 509→        // 4. Specific Actions (Rozcestník typů hotspotů)
 510→
 511→        // --- NOVÁ ČÁST: Obecná akce Apply (bez předmětu) ---
 512→        // Toto je to, co potřebujeme pro spuštění videa kliknutím na šipku
 513→        if (h.type === 'apply') {
 514→            console.log('[HOTSPOT] Executing Apply actions:', h.onApply);
 515→            if (h.onApply) {
 516→                await this._applyActions(h.onApply);
 517→            }
 518→            return;
 519→        }
 520→        // ---------------------------------------------------
 521→
 522→        if (h.type === 'goTo') {
 523→            await this.goto(h.target);
 524→            return;
 525→        }
 526→
 527→        if (h.type === 'pickup') {
 528→            if (!this.state.inventory.includes(h.itemId)) {
 529→                this.state.inventory.push(h.itemId);
 530→                this._renderInventory();
 531→                this._msg(this._t('engine.pickedUp', 'Sebráno: {name}', {name: this._itemLabel(h.itemId)}));
 532→                await this._stateChanged();
 533→            } else {
 534→                this._msg(this._t('engine.alreadyHave', 'Už máš: {name}', {name: this._itemLabel(h.itemId)}));
 535→            }
 536→            return;
 537→        }
 538→
 539→        if (h.type === 'puzzle') {
 540→            const ref = h.puzzleRef || h.puzzle?.ref;
 541→            if (!ref) {
 542→                console.error('Puzzle hotspot missing puzzleRef');
 543→                return;
 544→            }
 545→
 546→            const options = h.options || h.puzzle?.options || {};
 547→            const background = h.puzzleBackground || h.puzzle?.background || null;
 548→            const solvedKey = 'solved:pz:' + ref;
 549→
 550→            if (this.state.solved[solvedKey]) {
 551→                await this._applyActions(h.onSuccess);
 552→                return;
 553→            }
 554→
 555→            const res = await this._openPuzzleByRef({
 556→                ref,
 557→                rect: h.rect || {x: 0, y: 0, w: 100, h: 100},
 558→                options,
 559→                background
 560→            });
 561→
 562→            if (options.aggregateOnly) {
 563→                this._appendPuzzleResult({ref, ok: !!res?.ok, detail: res?.detail || null});
 564→                if (res?.ok && h.onSuccess) await this._applyActions(h.onSuccess);
 565→                if (!res?.ok && h.onFail) await this._applyActions(h.onFail);
 566→                return;
 567→            }
 568→
 569→            if (res?.ok) {
 570→                this._msg(this._t('engine.solved', 'Vyřešeno!'));
 571→                this.state.solved[solvedKey] = true;
 572→                this._saveState();
 573→                await this._applyActions(h.onSuccess);
 574→            } else {
 575→                if (h.onFail) await this._applyActions(h.onFail);
 576→                else this._msg(this._t('engine.puzzleFailed', 'Puzzle nevyřešeno.'));
 577→            }
 578→            return;
 579→        }
 580→
 581→        if (h.type === 'puzzleList') {
 582→            const ok = await openListModal(this, {
 583→                items: h.items || h.puzzleList?.items || [],
 584→                rect: h.rect || {x: 0, y: 0, w: 100, h: 100},
 585→                background: h.puzzleList?.background || h.background,
 586→                aggregateOnly: !!(h.options?.aggregateOnly),
 587→                blockUntilSolved: !!(h.options?.blockUntilSolved),
 588→                puzzlesById: this.data.puzzles
 589→            });
 590→            if (ok) {
 591→                if (h.onSuccess) await this._applyActions(h.onSuccess);
 592→            } else {
 593→                if (h.onFail) await this._applyActions(h.onFail);
 594→            }
 595→            return;
 596→        }
 597→
 598→        if (h.type === 'dialog') {
 599→            await this.openDialog(h.dialogId);
 600→            return;
 601→        }
 602→
 603→        if (h.type === 'content') {
 604→            await this.contentPanel.open(h.contentRef);
 605→            return;
 606→        }
 607→
 608→        // Fallback pro neznámé typy
 609→        this._msg('Unknown hotspot type: ' + h.type);
 610→        console.warn('Unknown hotspot type:', h);
 611→    }
