 613→    // --- puzzles 2.0 helpers ----------------------------------------------------
 614→
 615→    async _ensurePuzzlesLoaded() {
 616→        // pokud už jsou v this.data.puzzles ve formátu mapy, hotovo
 617→        if (this.data?.puzzles && typeof this.data.puzzles === 'object' && !Array.isArray(this.data.puzzles)) {
 618→            return;
 619→        }
 620→
 621→        const url = this._resolveAsset('puzzles.json');
 622→        let json = {};
 623→        try {
 624→            const r = await fetch(url, {cache: 'no-cache'});
 625→            if (r.ok) json = await r.json();
 626→        } catch {
 627→            // ignore
 628→        }
 629→
 630→        // 1) { byId: { ... } }
 631→        if (json && typeof json === 'object' && json.byId && typeof json.byId === 'object') {
 632→            this.data.puzzles = json.byId;
 633→            return;
 634→        }
 635→        // 2) [ { id, kind, ... }, ... ]
 636→        if (Array.isArray(json)) {
 637→            this.data.puzzles = Object.fromEntries(json.filter(p => p?.id).map(p => [p.id, p]));
 638→            return;
 639→        }
 640→        // 3) { id1:{...}, id2:{...} }
 641→        if (json && typeof json === 'object') {
 642→            this.data.puzzles = json;
 643→            return;
 644→        }
 645→
 646→        // fallback, empty map
 647→        this.data.puzzles = {};
 648→    }
 649→
 650→    async _openPuzzleByRef({ref, rect, options = {}, background = null}) {
 651→        await this._ensurePuzzlesLoaded();
 652→
 653→        // If background not provided in hotspot, try to get it from puzzle config
 654→        if (!background) {
 655→            const puzzleCfg = this.data.puzzles?.[ref];
 656→            if (puzzleCfg?.background) {
 657→                background = puzzleCfg.background;
 658→            }
 659→        }
 660→
 661→        return await new Promise((resolve) => {
 662→            const runner = createPuzzleRunner({
 663→                ref,
 664→                rect,
 665→                background: background ? this._resolveAsset(background) : null,
 666→                instanceOptions: options,
 667→                puzzlesById: this.data.puzzles || {},
 668→                i18n: (k) => this._t(k, k),
 669→                engine: this,
 670→                onResolve: (result) => {
 671→                    try {
 672→                        runner?.unmount?.();
 673→                    } catch (_) {
 674→                    }
 675→                    resolve(result || {ok: false});
 676→                }
 677→            });
 678→
 679→            runner.mountInto(this.hotspotLayer);
 680→        });
 681→    }
