 809→    _renderInventory() {
 810→        this.inventoryRoot.innerHTML = '';
 811→        (this.state.inventory || []).forEach(id => {
 812→            const item = this._itemById(id);
 813→            if (!item) return;
 814→
 815→            const wrap = document.createElement('button');
 816→            wrap.type = 'button';
 817→            wrap.className = 'item';
 818→            wrap.draggable = true; // Enable HTML5 drag
 819→            wrap.dataset.itemId = id;
 820→            if (this.state.useItemId === id) wrap.classList.add('selected');
 821→            wrap.title = this._t('engine.item.hint', 'Klikni pro náhled, táhni pro použití');
 822→
 823→            if (item.icon) {
 824→                const img = document.createElement('img');
 825→                img.src = this._resolveAsset(item.icon);
 826→                img.alt = this._text(item.label) || id;
 827→                img.draggable = false; // Prevent image from being dragged separately
 828→                wrap.appendChild(img);
 829→            }
 830→            const span = document.createElement('span');
 831→            span.textContent = this._text(item.label) || id;
 832→            wrap.appendChild(span);
 833→
 834→            // --- Drag & Drop handlers ---
 835→            this._setupItemDragDrop(wrap, item);
 836→
 837→            // --- Click handler (for preview) ---
 838→            // Using pointerup with tracking to differentiate from drag
 839→            let pointerDownTime = 0;
 840→            let pointerMoved = false;
 841→
 842→            wrap.addEventListener('pointerdown', (e) => {
 843→                pointerDownTime = Date.now();
 844→                pointerMoved = false;
 845→            });
 846→
 847→            wrap.addEventListener('pointermove', () => {
 848→                pointerMoved = true;
 849→            });
 850→
 851→            wrap.addEventListener('pointerup', (e) => {
 852→                // Ignore if this was a drag operation
 853→                if (pointerMoved && Date.now() - pointerDownTime > 150) return;
 854→
 855→                // Toggle use mode if already selected
 856→                if (this.state.useItemId === id) {
 857→                    this.exitUseMode();
 858→                    return;
 859→                }
 860→                this._inspectItem(item);
 861→            });
 862→
 863→            // Prevent default click to avoid double-firing
 864→            wrap.addEventListener('click', (e) => {
 865→                e.preventDefault();
 866→            });
 867→
 868→            this.inventoryRoot.appendChild(wrap);
 869→        });
 870→    }
