 872→    /**
 873→     * Sets up drag & drop handlers for an inventory item element.
 874→     * @param {HTMLElement} el - The item button element.
 875→     * @param {object} item - The item data object.
 876→     */
 877→    _setupItemDragDrop(el, item) {
 878→        // HTML5 Drag API
 879→        el.addEventListener('dragstart', (e) => {
 880→            e.dataTransfer.setData('text/plain', item.id);
 881→            e.dataTransfer.effectAllowed = 'move';
 882→            el.classList.add('is-dragging');
 883→            document.body.classList.add('item-dragging');
 884→
 885→            // Create custom drag image
 886→            if (item.icon) {
 887→                const dragImg = new Image();
 888→                dragImg.src = this._resolveAsset(item.icon);
 889→                // Use small offset so cursor is on the image
 890→                e.dataTransfer.setDragImage(dragImg, 24, 24);
 891→            }
 892→
 893→            this._dbg('[DRAG] Started dragging item:', item.id);
 894→        });
 895→
 896→        el.addEventListener('dragend', (e) => {
 897→            el.classList.remove('is-dragging');
 898→            document.body.classList.remove('item-dragging');
 899→            this._clearHotspotDropHighlights();
 900→            this._dbg('[DRAG] Ended dragging item:', item.id);
 901→        });
 902→
 903→        // Touch-based drag for mobile (pointer events fallback)
 904→        this._setupTouchDrag(el, item);
 905→    }
 906→
 907→    /**
 908→     * Sets up touch-based drag for mobile devices where HTML5 drag doesn't work well.
 909→     * @param {HTMLElement} el - The item element.
 910→     * @param {object} item - The item data object.
 911→     */
 912→    _setupTouchDrag(el, item) {
 913→        let touchStartTime = 0;
 914→        let touchStartX = 0;
 915→        let touchStartY = 0;
 916→        let ghost = null;
 917→        let isDragging = false;
 918→        const DRAG_THRESHOLD = 10; // pixels
 919→        const HOLD_TIME = 200; // ms to distinguish from tap
 920→
 921→        const createGhost = () => {
 922→            ghost = document.createElement('div');
 923→            ghost.className = 'item-drag-ghost';
 924→            if (item.icon) {
 925→                const img = document.createElement('img');
 926→                img.src = this._resolveAsset(item.icon);
 927→                ghost.appendChild(img);
 928→            }
 929→            const label = document.createElement('span');
 930→            label.textContent = this._text(item.label) || item.id;
 931→            ghost.appendChild(label);
 932→            document.body.appendChild(ghost);
 933→        };
 934→
 935→        const moveGhost = (x, y) => {
 936→            if (!ghost) return;
 937→            ghost.style.left = (x - 30) + 'px';
 938→            ghost.style.top = (y - 30) + 'px';
 939→        };
 940→
 941→        const removeGhost = () => {
 942→            if (ghost && ghost.parentNode) {
 943→                ghost.parentNode.removeChild(ghost);
 944→            }
 945→            ghost = null;
 946→        };
 947→
 948→        const getHotspotUnderPoint = (x, y) => {
 949→            const elements = document.elementsFromPoint(x, y);
 950→            for (const elem of elements) {
 951→                if (elem.classList.contains('hotspot') && elem.dataset.acceptsItems) {
 952→                    return elem;
 953→                }
 954→            }
 955→            return null;
 956→        };
 957→
 958→        el.addEventListener('touchstart', (e) => {
 959→            touchStartTime = Date.now();
 960→            const touch = e.touches[0];
 961→            touchStartX = touch.clientX;
 962→            touchStartY = touch.clientY;
 963→            isDragging = false;
 964→        }, { passive: true });
 965→
 966→        el.addEventListener('touchmove', (e) => {
 967→            const touch = e.touches[0];
 968→            const dx = touch.clientX - touchStartX;
 969→            const dy = touch.clientY - touchStartY;
 970→            const distance = Math.sqrt(dx * dx + dy * dy);
 971→            const elapsed = Date.now() - touchStartTime;
 972→
 973→            // Start drag if moved enough or held long enough while moving
 974→            if (!isDragging && (distance > DRAG_THRESHOLD || (elapsed > HOLD_TIME && distance > 5))) {
 975→                isDragging = true;
 976→                createGhost();
 977→                el.classList.add('is-dragging');
 978→                document.body.classList.add('item-dragging');
 979→                this._highlightAcceptingHotspots(item.id);
 980→            }
 981→
 982→            if (isDragging) {
 983→                e.preventDefault(); // Prevent scroll while dragging
 984→                moveGhost(touch.clientX, touch.clientY);
 985→
 986→                // Highlight hotspot under touch
 987→                const hotspot = getHotspotUnderPoint(touch.clientX, touch.clientY);
 988→                this._updateHotspotDropHighlight(hotspot);
 989→            }
 990→        }, { passive: false });
 991→
 992→        el.addEventListener('touchend', (e) => {
 993→            if (isDragging) {
 994→                const touch = e.changedTouches[0];
 995→                const hotspot = getHotspotUnderPoint(touch.clientX, touch.clientY);
 996→
 997→                if (hotspot) {
 998→                    const hotspotIndex = parseInt(hotspot.dataset.index, 10);
 999→                    const hs = this.currentScene?.hotspots?.[hotspotIndex];
1000→                    if (hs) {
1001→                        this._handleItemDropOnHotspot(item.id, hs);
1002→                    }
1003→                }
1004→
1005→                removeGhost();
1006→                el.classList.remove('is-dragging');
1007→                document.body.classList.remove('item-dragging');
1008→                this._clearHotspotDropHighlights();
1009→                isDragging = false;
1010→            }
1011→        });
1012→
1013→        el.addEventListener('touchcancel', () => {
1014→            if (isDragging) {
1015→                removeGhost();
1016→                el.classList.remove('is-dragging');
1017→                document.body.classList.remove('item-dragging');
1018→                this._clearHotspotDropHighlights();
1019→                isDragging = false;
1020→            }
1021→        });
1022→    }
1023→
1024→    /**
1025→     * Highlights hotspots that accept the given item.
1026→     * @param {string} itemId - The item ID being dragged.
1027→     */
1028→    _highlightAcceptingHotspots(itemId) {
1029→        const hotspots = this.hotspotLayer.querySelectorAll('.hotspot');
1030→        hotspots.forEach(el => {
1031→            const idx = parseInt(el.dataset.index, 10);
1032→            const hs = this.currentScene?.hotspots?.[idx];
1033→            if (hs && this._hotspotAcceptsItem(hs, itemId)) {
1034→                el.classList.add('accepts-drop');
1035→                el.dataset.acceptsItems = 'true';
1036→            }
1037→        });
1038→    }
1039→
1040→    /**
1041→     * Updates the visual highlight for the hotspot currently under the drag cursor.
1042→     * @param {HTMLElement|null} hotspotEl - The hotspot element or null.
1043→     */
1044→    _updateHotspotDropHighlight(hotspotEl) {
1045→        const hotspots = this.hotspotLayer.querySelectorAll('.hotspot');
1046→        hotspots.forEach(el => {
