1348→    /**
1349→     * Process game events based on a trigger.
1350→     * @param {{on: string, scene?: string}} trigger - The event trigger context.
1351→     */
1352→    async _processEvents(trigger) {
1353→        const events = this.data.events || [];
1354→        for (const ev of events) {
1355→            if (!ev || !ev.id) continue;
1356→
1357→            // 1. Check if already fired (for one-time events)
1358→            if (ev.once && this.state.eventsFired?.[ev.id]) continue;
1359→
1360→            const w = ev.when || {};
1361→
1362→            // 2. Check Conditions
1363→            // a) Trigger type match
1364→            if (w.on && w.on !== trigger.on) continue;
1365→
1366→            // b) Scene match (current scene or specified scene)
1367→            if (w.scene && w.scene !== (trigger.scene || this.state.scene)) continue;
1368→
1369→            // c) Inventory requirements
1370→            if (w.requireItems && !this._hasAll(w.requireItems)) continue;
1371→
1372→            // d) Flag requirements
1373→            if (w.requireFlags && !this._hasAllFlags(w.requireFlags)) continue;
1374→
1375→            // e) Missing items check
1376→            if (w.missingItems && (w.missingItems.some(x => this.state.inventory.includes(x)))) continue;
1377→
1378→            // --- MATCH FOUND ---
1379→
1380→            // Mark event as fired IMMEDIATELY before executing actions.
1381→            // This prevents recursion loops if an action (like a dialog) triggers
1382→            // a state change that would otherwise re-evaluate and re-trigger this
1383→            // same event while it is still pending/awaiting.
1384→            if (ev.once) {
1385→                this.state.eventsFired = this.state.eventsFired || {};
1386→                this.state.eventsFired[ev.id] = true;
1387→                this._saveState();
1388→            }
1389→
1390→            const act = ev.then || {};
1391→
1392→            // 3. Execute Actions
1393→
1394→            // Show Toast
1395→            if (act.toast?.text) {
1396→                this.toast(this._text(act.toast.text), act.toast.ms ?? 5000);
1397→            }
1398→
1399→            // Change Scene Image
1400→            if (act.setSceneImage?.sceneId && act.setSceneImage?.image) {
1401→                const sc = this.data.scenes.find(s => s.id === act.setSceneImage.sceneId);
1402→                if (sc) {
1403→                    sc.image = this._resolveAsset(act.setSceneImage.image);
1404→                    // If we are currently in this scene, update the DOM immediately
1405→                    if (this.currentScene?.id === sc.id) {
1406→                        this.sceneImage.src = sc.image;
1407→                        await new Promise(res => {
1408→                            if (this.sceneImage.complete && this.sceneImage.naturalWidth) res();
1409→                            else this.sceneImage.onload = () => res();
1410→                        });
1411→                    }
1412→                }
1413→            }
1414→
1415→            // Open Dialog (Blocking)
1416→            // The engine waits here until the dialog is fully closed by the user.
1417→            if (act.openDialog) {
1418→                await this.openDialog(act.openDialog);
1419→            }
1420→
1421→            // Highlight Hotspot
1422→            // Executed after the dialog closes (if any).
1423→            if (act.highlightHotspot?.rect) {
1424→                const h = act.highlightHotspot;
1425→                this._enqueueOrShowHighlight({
1426→                    sceneId: h.sceneId || (w.scene || this.state.scene),
1427→                    rect: h.rect,
1428→                    ms: h.ms ?? 3500,
1429→                    outline: !!h.outline
1430→                });
1431→            }
1432→
1433→            // Play Video (Blocking)
1434→            // Engine waits until the video ends or is skipped
1435→            if (act.playVideo?.src) {
1436→                await this._playVideo(act.playVideo);
1437→                if (act.playVideo.onEnd) {
1438→                    await this._applyActions(act.playVideo.onEnd);
1439→                }
1440→            }
1441→
1442→            // Open Puzzle
1443→            if (act.openPuzzle) {
1444→                const ap = act.openPuzzle;
1445→                const res = await this._openPuzzleByRef({
1446→                    ref: ap.ref,
1447→                    rect: ap.rect || {x: 0, y: 0, w: 100, h: 100},
1448→                    options: ap.options || {},
1449→                    background: ap.background || null
1450→                });
1451→
1452→                if (ap.options?.aggregateOnly) {
1453→                    this._appendPuzzleResult({ref: ap.ref, ok: !!res?.ok, detail: res?.detail || null});
1454→                } else {
1455→                    if (res?.ok) {
1456→                        if (ap.onSuccess) await this._applyActions(ap.onSuccess);
1457→                    } else {
1458→                        if (ap.onFail) await this._applyActions(ap.onFail);
1459→                    }
1460→                }
1461→            }
1462→
1463→            // Open Puzzle List
1464→            if (act.openPuzzleList) {
1465→                const apl = act.openPuzzleList;
1466→                const ok = await openListModal(this, {
1467→                    items: apl.items || [],
1468→                    rect: apl.rect || {x: 0, y: 0, w: 100, h: 100},
1469→                    background: apl.background || null,
1470→                    aggregateOnly: !!apl.aggregateOnly,
1471→                    blockUntilSolved: !!apl.blockUntilSolved,
1472→                    puzzlesById: this.data.puzzles
1473→                });
1474→                if (ok) {
1475→                    if (apl.onSuccess) await this._applyActions(apl.onSuccess);
1476→                } else {
1477→                    if (apl.onFail) await this._applyActions(apl.onFail);
1478→                }
1479→            }
1480→
1481→            // Set Flags
1482→            if (act.setFlags) {
1483→                let changed = false;
1484→                if (Array.isArray(act.setFlags)) {
1485→                    for (const f of act.setFlags) {
1486→                        if (!this.state.flags[f]) {
1487→                            this.state.flags[f] = true;
1488→                            changed = true;
1489→                        }
1490→                    }
1491→                } else {
1492→                    for (const [k, v] of Object.entries(act.setFlags)) {
1493→                        if (!!this.state.flags[k] !== !!v) {
1494→                            this.state.flags[k] = !!v;
1495→                            changed = true;
1496→                        }
1497→                    }
1498→                }
1499→                if (changed) this._saveState();
1500→            }
1501→        }
1502→    }
