1506→    /**
1507→     * Plays a video overlay or embedded video.
1508→     * Returns a Promise that resolves when the video ends or is skipped.
1509→     * @param {object} cfg - { src, mode, rect, delay, allowSkip, onEnd }
1510→     */
1511→    async _playVideo(cfg) {
1512→        const src = this._resolveAsset(cfg.src);
1513→
1514→        // 1. Delay logic (optional wait before showing video)
1515→        if (cfg.delay && cfg.delay > 0) {
1516→            await new Promise(resolve => setTimeout(resolve, cfg.delay));
1517→        }
1518→
1519→        return new Promise((resolve) => {
1520→            // Container setup
1521→            const wrapper = document.createElement('div');
1522→            wrapper.className = 'video-overlay';
1523→
1524→            // Mode handling (fullscreen vs rect)
1525→            if (cfg.mode === 'rect' && cfg.rect) {
1526→                wrapper.classList.add('mode-rect');
1527→                Object.assign(wrapper.style, {
1528→                    left: cfg.rect.x + '%',
1529→                    top: cfg.rect.y + '%',
1530→                    width: cfg.rect.w + '%',
1531→                    height: cfg.rect.h + '%'
1532→                });
1533→            } else {
1534→                wrapper.classList.add('mode-fullscreen');
1535→            }
1536→
1537→            // Video element
1538→            const video = document.createElement('video');
1539→            video.src = src;
1540→            video.autoplay = true;
1541→            video.playsInline = true; // Critical for iOS/Tablets to prevent native fullscreen force
1542→            video.controls = false;   // We handle interaction manually
1543→
1544→            wrapper.appendChild(video);
1545→
1546→            // Skip button (optional)
1547→            if (cfg.allowSkip !== false) {
1548→                const skipBtn = document.createElement('button');
1549→                skipBtn.className = 'video-skip';
1550→                skipBtn.innerHTML = '&times;'; // Close icon
1551→                skipBtn.title = 'Skip Video';
1552→
1553→                // Skip handler
1554→                skipBtn.addEventListener('click', (e) => {
1555→                    e.stopPropagation();
1556→                    finish();
1557→                });
1558→                wrapper.appendChild(skipBtn);
1559→
1560→                // Allow clicking outside/on wrapper to skip (only in fullscreen mode)
1561→                if (cfg.mode !== 'rect') {
1562→                    wrapper.addEventListener('click', finish);
1563→                }
1564→            }
1565→
1566→            // Mount to DOM (highest layer)
1567→            document.body.appendChild(wrapper);
1568→
1569→            // Lifecycle end handler
1570→            let finished = false;
1571→            function finish() {
1572→                if (finished) return;
1573→                finished = true;
1574→
1575→                video.pause();
1576→                if (wrapper.parentNode) wrapper.parentNode.removeChild(wrapper);
1577→
1578→                // Execute follow-up actions (onEnd) if defined
1579→                // Note: We resolve first to unblock the engine, logic happens outside
1580→                resolve();
1581→            }
1582→
1583→            // Event listeners
1584→            video.addEventListener('ended', finish);
1585→
1586→            video.addEventListener('error', (e) => {
1587→                console.error('[VIDEO] Error playing:', src, e);
1588→                finish(); // Don't block the game on error
1589→            });
1590→
1591→            // Start playback with error handling (autoplay policy)
1592→            video.play().catch(err => {
1593→                console.warn('[VIDEO] Autoplay blocked or failed:', err);
1594→                // If autoplay is blocked, we might need a "Click to Play" UI here.
1595→                // For now, we assume user interaction has already happened (dialog click).
1596→            });
1597→        });
1598→    }
