1616→    async openDialog(arg) {
1617→        const id = (typeof arg === 'string') ? arg : (arg && arg.id);
1618→        this._dbg('openDialog() begin →', {id});
1619→        if (!id) {
1620→            console.warn('[GAME] openDialog() called without id');
