  1→/**
  2→ * @fileoverview Content Panel system for the escape-game-engine.
  3→ *
  4→ * Renders rich narrative content (Markdown / HTML / plain text) inside
  5→ * styled, semi-transparent overlay panels displayed over scene backgrounds.
  6→ *
  7→ * Content panels are the engine's primary mechanism for room descriptions,
  8→ * mission briefings, story text, and any translatable narrative content.
  9→ *
 10→ * Integration points:
 11→ * - Event action:   `{ "openContent": "content-id" }`
 12→ * - Hotspot type:   `{ "type": "content", "contentRef": "content-id" }`
 13→ * - Scene property: `{ "content": { "ref": "id", "trigger": "enter" } }`
 14→ *
 15→ * @module content
 16→ */
 17→
 18→import { renderContent } from './content-renderer.js';
 19→
 20→/* ------------------------------------------------------------------ */
 21→/*  Default configuration                                             */
 22→/* ------------------------------------------------------------------ */
 23→
 24→/** @type {import('./content').PanelDefaults} */
 25→const DEFAULTS = {
 26→  rect:       { x: 3, y: 3, w: 45, h: 94 },
 27→  theme:      'glass',
 28→  backdrop:   'dim',
 29→  scrollable: true,
 30→  animation:  'fade-slide',
 31→  format:     'markdown',
 32→  once:       false,
 33→  buttons: {
 34→    ok: { visible: true, label: '@btn.continue@Pokračovat' },
 35→  },
 36→};
 37→
 38→/** Z-index for the content panel container (below puzzles, above dialogs). */
 39→const Z_INDEX = 7500;
 40→
 41→/** Duration (ms) of the show / hide CSS transitions. */
 42→const ANIM_MS = 300;
 43→
 44→/* ------------------------------------------------------------------ */
 45→/*  ContentPanel class                                                */
 46→/* ------------------------------------------------------------------ */
 47→
 48→/**
 49→ * @typedef {Object} ContentDef
 50→ * @property {string}  id                        - Unique identifier.
 51→ * @property {string}  [title]                   - Panel heading (supports i18n `@key@fallback`).
 52→ * @property {'markdown'|'html'|'text'} [format] - Body content format.
 53→ * @property {string}  body                      - Body content (supports i18n).
 54→ * @property {Object}  [panel]                   - Visual / layout options.
 55→ * @property {Object}  [panel.rect]              - Position `{x,y,w,h}` in viewport %.
 56→ * @property {string}  [panel.theme]             - Theme name: `glass` | `solid` | `minimal`.
 57→ * @property {string}  [panel.backdrop]          - Backdrop style: `blur` | `dim` | `none`.
 58→ * @property {boolean} [panel.scrollable]        - Allow vertical scrolling.
 59→ * @property {string}  [panel.animation]         - Animation type: `fade` | `fade-slide` | `none`.
 60→ * @property {Object}  [buttons]                 - Button config `{ ok: { visible, label } }`.
 61→ * @property {boolean} [once]                    - Show only once per session.
 62→ */
 63→
 64→/**
 65→ * Manages opening, rendering, and closing content overlay panels.
 66→ *
 67→ * Usage inside the engine:
 68→ * ```js
 69→ * this.contentPanel = new ContentPanel(this);
 70→ * await this.contentPanel.open('intro-briefing');
 71→ * ```
 72→ */
 73→export class ContentPanel {
 74→
 75→  /**
 76→   * @param {import('./engine').Game} game - Reference to the parent Game instance.
 77→   */
 78→  constructor(game) {
 79→    /** @type {import('./engine').Game} */
 80→    this.game = game;
 81→
 82→    /**
 83→     * Currently visible container element, or `null` when closed.
 84→     * @type {HTMLElement|null}
 85→     */
 86→    this._container = null;
 87→
 88→    /**
 89→     * Promise resolve callback for the current `open()` call.
 90→     * @type {Function|null}
 91→     */
 92→    this._resolve = null;
 93→
 94→    /* Bind keyboard handler once so we can remove it later. */
 95→    this._onKeyDown = this._onKeyDown.bind(this);
 96→  }
 97→
 98→  /* ---------------------------------------------------------------- */
 99→  /*  Public API                                                      */
100→  /* ---------------------------------------------------------------- */
101→
102→  /**
103→   * Open a content panel by its definition ID.
104→   *
105→   * Reads the definition from `game.data.content[contentId]`, resolves
106→   * i18n values, renders the Markdown / HTML body, and displays the
107→   * panel with the configured animation.
108→   *
109→   * The returned promise resolves when the user dismisses the panel.
110→   *
111→   * @param {string} contentId   - Key in the `content` map of scenes.json.
112→   * @param {Object} [overrides] - Runtime overrides merged on top of the definition.
113→   * @returns {Promise<void>}
114→   */
115→  async open(contentId, overrides = {}) {
116→    const contentMap = this.game.data?.content || {};
117→    const def = contentMap[contentId];
118→    if (!def) {
119→      console.warn(`[ContentPanel] definition not found: "${contentId}"`);
120→      return;
121→    }
122→
123→    // Respect "once" flag
124→    if (def.once && this.game.state.contentShown?.[contentId]) return;
125→
126→    // Close any panel that is already open
127→    if (this._container) this._closeImmediate();
128→
129→    const merged = this._mergeDefaults(def, overrides);
130→
131→    return new Promise(resolve => {
132→      this._resolve = resolve;
133→      this._render(contentId, merged);
134→    });
135→  }
136→
137→  /**
138→   * Close the currently open panel (if any), triggering the exit animation.
139→   */
140→  close() {
141→    if (!this._container) return;
142→    this._animateOut();
143→  }
144→
145→  /**
146→   * Whether a content panel is currently visible.
147→   * @type {boolean}
148→   */
149→  get isOpen() {
150→    return !!this._container;
151→  }
152→
153→  /* ---------------------------------------------------------------- */
154→  /*  Merge & resolve helpers                                         */
155→  /* ---------------------------------------------------------------- */
156→
157→  /**
158→   * Deep-merge a content definition with defaults and runtime overrides.
159→   *
160→   * @param {ContentDef} def       - Source definition from JSON.
161→   * @param {Object}     overrides - Runtime overrides.
162→   * @returns {ContentDef} Merged definition.
163→   * @private
164→   */
165→  _mergeDefaults(def, overrides) {
166→    const panel = {
167→      ...DEFAULTS,
168→      ...(def.panel || {}),
169→      ...(overrides.panel || {}),
170→      rect: {
171→        ...DEFAULTS.rect,
172→        ...(def.panel?.rect || {}),
173→        ...(overrides.panel?.rect || {}),
174→      },
175→    };
176→
177→    const buttons = {
178→      ok: {
179→        ...DEFAULTS.buttons.ok,
180→        ...(def.buttons?.ok || {}),
181→        ...(overrides.buttons?.ok || {}),
182→      },
183→    };
184→
185→    return {
186→      ...def,
187→      ...overrides,
188→      panel,
189→      buttons,
190→      format: overrides.format || def.format || DEFAULTS.format,
191→      once: overrides.once ?? def.once ?? DEFAULTS.once,
192→    };
193→  }
194→
195→  /**
196→   * Resolve an i18n-capable string through the engine's `_text()` helper.
197→   *
198→   * @param {string} val      - Raw value (may contain `@key@fallback`).
199→   * @param {string} [fb=''] - Fallback if val is falsy.
200→   * @returns {string}
201→   * @private
202→   */
203→  _t(val, fb = '') {
204→    return this.game._text(val, fb);
205→  }
206→
207→  /* ---------------------------------------------------------------- */
208→  /*  DOM construction                                                */
209→  /* ---------------------------------------------------------------- */
210→
211→  /**
212→   * Build and mount the complete panel DOM tree.
213→   *
214→   * @param {string}     contentId - Definition ID (used for state tracking).
215→   * @param {ContentDef} def       - Merged definition.
216→   * @private
217→   */
218→  _render(contentId, def) {
219→    const { panel, buttons, format } = def;
220→
221→    // ── Container ──
222→    const container = document.createElement('div');
223→    container.className = 'cp-container';
224→    container.style.zIndex = Z_INDEX;
225→    container.setAttribute('role', 'dialog');
226→    container.setAttribute('aria-modal', 'true');
227→    container.dataset.contentId = contentId;
228→
229→    // ── Backdrop ──
230→    const backdrop = document.createElement('div');
231→    backdrop.className = `cp-backdrop cp-backdrop--${panel.backdrop}`;
232→    backdrop.addEventListener('click', () => this.close());
233→    container.appendChild(backdrop);
234→
235→    // ── Panel ──
236→    const panelEl = document.createElement('div');
237→    panelEl.className = `cp-panel cp-panel--${panel.theme}`;
238→    Object.assign(panelEl.style, {
239→      left:   `${panel.rect.x}%`,
240→      top:    `${panel.rect.y}%`,
241→      width:  `${panel.rect.w}%`,
242→      height: `${panel.rect.h}%`,
243→    });
244→    container.appendChild(panelEl);
245→
246→    // ── Header ──
247→    const title = this._t(def.title);
248→    if (title) {
249→      const header = document.createElement('div');
250→      header.className = 'cp-header';
251→      header.setAttribute('data-id', 'header');
252→
253→      const h2 = document.createElement('h2');
254→      h2.className = 'cp-title';
255→      h2.id = `cp-title-${contentId}`;
256→      h2.textContent = title;
257→      container.setAttribute('aria-labelledby', h2.id);
258→      header.appendChild(h2);
259→      panelEl.appendChild(header);
260→    }
261→
262→    // ── Body ──
263→    const body = document.createElement('div');
264→    body.className = 'cp-body';
265→    body.setAttribute('data-id', 'body');
266→    body.tabIndex = 0;
267→    if (panel.scrollable) body.classList.add('cp-body--scrollable');
268→
269→    const content = document.createElement('div');
270→    content.className = 'cp-content';
271→
272→    const rawBody = this._t(def.body);
273→    content.innerHTML = renderContent(rawBody, format);
274→
275→    // Resolve relative image paths within rendered content
276→    content.querySelectorAll('img').forEach(img => {
277→      const src = img.getAttribute('src');
278→      if (src && !src.startsWith('http') && !src.startsWith('data:')) {
279→        img.src = this.game._resolveAsset(src);
280→      }
281→    });
282→
283→    body.appendChild(content);
284→    panelEl.appendChild(body);
285→
286→    // ── Footer ──
287→    if (buttons.ok?.visible !== false) {
288→      const footer = document.createElement('div');
289→      footer.className = 'cp-footer';
290→      footer.setAttribute('data-id', 'footer');
291→
292→      const okBtn = document.createElement('button');
293→      okBtn.className = 'cp-btn cp-btn--ok';
294→      okBtn.type = 'button';
295→      okBtn.textContent = this._t(buttons.ok.label, 'OK');
296→      okBtn.addEventListener('click', () => this.close());
297→      footer.appendChild(okBtn);
298→
299→      panelEl.appendChild(footer);
300→    }
301→
302→    // ── Mount ──
303→    this._container = container;
304→    this._contentId = contentId;
305→    this._def = def;
306→
307→    (this.game.hotspotLayer || document.body).appendChild(container);
308→
309→    document.addEventListener('keydown', this._onKeyDown);
310→
311→    // Trigger enter animation on next frame
312→    requestAnimationFrame(() => {
313→      panelEl.classList.add('cp-panel--visible');
314→      backdrop.classList.add('cp-backdrop--visible');
315→    });
316→  }
317→
318→  /* ---------------------------------------------------------------- */
319→  /*  Animation & teardown                                            */
320→  /* ---------------------------------------------------------------- */
321→
322→  /**
323→   * Animate the panel out, then remove from DOM and resolve the promise.
324→   * @private
325→   */
326→  _animateOut() {
327→    if (!this._container) return;
328→
329→    const panel = this._container.querySelector('.cp-panel');
330→    const backdrop = this._container.querySelector('.cp-backdrop');
331→
332→    if (panel)    panel.classList.remove('cp-panel--visible');
333→    if (backdrop) backdrop.classList.remove('cp-backdrop--visible');
334→
335→    const cleanup = () => this._closeImmediate();
336→
337→    // Wait for CSS transition to finish, with a safety timeout
338→    if (this._def?.panel?.animation === 'none') {
339→      cleanup();
340→    } else {
341→      setTimeout(cleanup, ANIM_MS + 50);
342→    }
343→  }
344→
345→  /**
346→   * Immediately remove the panel from DOM and resolve the open() promise.
347→   * @private
348→   */
349→  _closeImmediate() {
350→    if (!this._container) return;
351→
352→    document.removeEventListener('keydown', this._onKeyDown);
353→
354→    this._container.remove();
355→
356→    // Track "once" in game state
357→    if (this._def?.once && this._contentId) {
358→      if (!this.game.state.contentShown) this.game.state.contentShown = {};
359→      this.game.state.contentShown[this._contentId] = true;
360→      this.game._saveState();
361→    }
362→
363→    this._container = null;
364→    this._contentId = null;
365→    this._def = null;
366→
367→    if (this._resolve) {
368→      const r = this._resolve;
369→      this._resolve = null;
370→      r();
371→    }
372→  }
373→
374→  /* ---------------------------------------------------------------- */
375→  /*  Keyboard handling                                               */
376→  /* ---------------------------------------------------------------- */
377→
378→  /**
379→   * Handle keyboard events while panel is open.
380→   *
381→   * - **Escape** closes the panel.
382→   * - **Tab** is trapped within the panel for accessibility.
383→   *
384→   * @param {KeyboardEvent} e
385→   * @private
386→   */
387→  _onKeyDown(e) {
388→    if (!this._container) return;
389→
390→    if (e.key === 'Escape') {
391→      e.preventDefault();
392→      e.stopPropagation();
393→      this.close();
394→      return;
395→    }
396→
397→    // Trap focus within the panel
398→    if (e.key === 'Tab') {
399→      const focusable = this._container.querySelectorAll(
400→        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
401→      );
402→      if (focusable.length === 0) return;
403→
404→      const first = focusable[0];
405→      const last  = focusable[focusable.length - 1];
406→
407→      if (e.shiftKey && document.activeElement === first) {
408→        e.preventDefault();
409→        last.focus();
410→      } else if (!e.shiftKey && document.activeElement === last) {
411→        e.preventDefault();
412→        first.focus();
413→      }
414→    }
415→  }
416→}
