input.content:
/* ==========================================================================
   HEAT ESCAPE — GAME.CSS
   Theme: Dark Sci-Fi / Orange Heat & Cyan Cold
   Dependencies: base/style.css, puzzles.css, content.css
   ========================================================================== */

/* --- 1. PALETTE & VARIABLES --- */

:root {
  /* Heat theme palette */
  --he-bg:            #1a1a2e;
  --he-surface:       #1e2030;
  --he-panel:         rgba(30, 32, 48, 0.95);
  --he-text:          #ece9e0;
  --he-muted:         #b0aaa0;
  --he-accent:        #e8652e;
  --he-accent-light:  #ff6b35;
  --he-accent-glow:   rgba(232, 101, 46, 0.4);
  --he-secondary:     #3ecbf0;
  --he-secondary-glow: rgba(62, 203, 240, 0.3);
  --he-success:       #58c59a;
  --he-danger:        #ff6b6b;
  --he-shadow:        rgba(0, 0, 0, 0.6);

  /* Puzzle system overrides */
  --pz-text-color:    var(--he-text);
  --pz-token-bg:      rgba(39, 42, 60, 0.85);
  --pz-token-border:  rgba(232, 101, 46, 0.3);
  --pz-selected-bg:   rgba(62, 203, 240, 0.1);
  --pz-selected-border: var(--he-secondary);
  --pz-wrong-bg:      rgba(220, 40, 40, 0.4);
  --pz-wrong-border:  rgba(220, 40, 40, 0.8);

  /* Content panel overrides */
  --cp-text:          var(--he-text);
  --cp-heading:       var(--he-accent-light);
  --cp-accent:        var(--he-accent);
  --cp-btn-bg:        var(--he-accent);
  --cp-btn-hover:     var(--he-accent-light);
  --cp-scrollbar:     var(--he-accent);
}

/* --- 2. GLOBAL LAYOUT --- */

html {
  overflow-y: auto;
  height: 100%;
  overscroll-behavior-y: none;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  background-color: var(--he-bg);
  color: var(--he-text);
  margin: 0;
  min-height: 100%;
  overflow-y: auto;
  -webkit-tap-highlight-color: transparent;
}

#gameRoot {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* --- 3. TOP BAR --- */

.topbar {
  background: linear-gradient(180deg, rgba(30, 32, 48, 0.98), rgba(26, 26, 46, 0.95));
  border-bottom: 1px solid rgba(232, 101, 46, 0.3);
}

.topbar .title {
  font-size: 1.4em;
  font-weight: 700;
  color: var(--he-accent-light);
  letter-spacing: 0.5px;
  text-transform: uppercase;
  text-shadow: 0 2px 4px var(--he-shadow);
}

/* --- 4. BUTTONS --- */

.btn, button, .ui-button, .pz-btn {
  background: linear-gradient(180deg, #2b2f42, #232738);
  color: var(--he-text);
  border: 1px solid rgba(232, 101, 46, 0.3);
  border-radius: 8px;
  padding: 8px 16px;
  font-family: inherit;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
}

.btn:hover, button:hover, .pz-btn:hover {
  border-color: var(--he-accent);
  box-shadow: 0 0 10px var(--he-accent-glow);
  transform: translateY(-1px);
}

.btn:active, button:active {
  transform: translateY(1px);
}

/* --- 5. PUZZLE SYSTEM OVERRIDES --- */

.pz-title {
  font-size: 1.4em;
  font-weight: 700;
  color: var(--he-accent-light);
  margin-bottom: 0.5em;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.pz__window {
  background: rgba(26, 26, 46, 0.88);
  border: 1px solid var(--he-accent);
  border-radius: 12px;
  box-shadow: 0 0 30px rgba(0, 0, 0, 0.8);
  backdrop-filter: blur(5px);
}

/* Tokens (quiz, group, order, match) */
.pz-kind-group .pz-token,
.pz-kind-order .pz-token,
.pz-kind-match .pz-token {
  background: var(--pz-token-bg) !important;
  border: 1px solid var(--pz-token-border) !important;
  color: var(--he-text) !important;
  backdrop-filter: blur(4px);
  font-weight: 500;
  transition: background 0.2s, transform 0.1s;
}

.pz-kind-group .pz-token:hover,
.pz-kind-order .pz-token:hover,
.pz-kind-match .pz-token:hover {
  background: rgba(39, 42, 60, 1) !important;
  border-color: var(--he-secondary) !important;
  box-shadow: 0 0 8px var(--he-secondary-glow) !important;
  transform: translateY(-1px);
}

/* Error state */
.pz-kind-group .pz-token.wrong,
.pz-kind-group .pz-token.is-wrong,
.pz-kind-order .pz-token.wrong,
.pz-kind-order .pz-token.is-wrong,
.pz-kind-match .pz-token.wrong,
.pz-kind-match .pz-token.is-wrong {
  background: var(--pz-wrong-bg) !important;
  border-color: var(--pz-wrong-border) !important;
  box-shadow: 0 0 15px rgba(255, 60, 60, 0.4) !important;
  animation: he-shake 0.4s ease-in-out;
}

/* Selection state */
.pz-kind-match .pz-token.is-selected,
.pz-kind-match .pz-token.selected {
  background: rgba(62, 203, 240, 0.05) !important;
  border-color: var(--he-secondary) !important;
  box-shadow: 0 0 0 1px var(--he-secondary), 0 0 15px var(--he-secondary-glow) !important;
  z-index: 5;
  transform: scale(1.02);
}

/* Group buckets & order slots */
.pz-group-bucket,
.pz-order-slot {
  background: rgba(26, 26, 46, 0.8);
  border: 1px dashed rgba(232, 101, 46, 0.4);
  border-radius: 10px;
}

.pz-group-label {
  color: var(--he-accent-light);
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

/* --- 6. CLOZE PUZZLE --- */

.pz-cloze-tokens-area .pz-token,
.pz-cloze-gap .pz-token {
  touch-action: none;
  user-select: none;
  cursor: grab;
  background: var(--pz-token-bg);
  border: 1px solid var(--pz-token-border);
  padding: 6px 12px;
  border-radius: 6px;
  color: var(--he-text);
  font-weight: 500;
}

.pz-cloze-ghost {
  pointer-events: none !important;
  z-index: 9999;
  box-shadow: 0 15px 30px rgba(0, 0, 0, 0.6);
  opacity: 0.95;
  transform: scale(1.1);
  border-color: var(--he-accent);
}

.pz-cloze-gap {
  background: rgba(0, 0, 0, 0.3);
  border: 1px dashed rgba(232, 101, 46, 0.5);
  border-radius: 4px;
  min-width: 80px;
  display: inline-block;
  vertical-align: middle;
  margin: 0 4px;
  transition: all 0.2s;
}

.pz-cloze-gap.drag-over {
  background: rgba(62, 203, 240, 0.2);
  border-color: var(--he-secondary);
  box-shadow: 0 0 10px var(--he-secondary-glow);
}

.pz-cloze-gap.filled {
  border: none;
  background: transparent;
}

/* --- 7. CONTENT PANEL OVERRIDES --- */

.cp-panel--glass {
  background: rgba(26, 26, 46, 0.85) !important;
  border: 1px solid rgba(232, 101, 46, 0.3) !important;
}

.cp-title {
  color: var(--he-accent-light) !important;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.cp-btn--ok {
  background: linear-gradient(180deg, var(--he-accent), #c4541f) !important;
  border: none !important;
  color: #fff !important;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.cp-btn--ok:hover {
  background: linear-gradient(180deg, var(--he-accent-light), var(--he-accent)) !important;
  box-shadow: 0 0 15px var(--he-accent-glow) !important;
}

.cp-content h2 {
  color: var(--he-accent-light) !important;
}

.cp-content strong {
  color: var(--he-secondary) !important;
}

/* --- 8. HOTSPOT STATES --- */

/* Success state (green check after puzzle solved) */
.hotspot.state-success {
  border: 2px solid var(--he-success) !important;
  background: rgba(88, 197, 154, 0.15) !important;
  border-radius: 8px;
}

.hotspot.state-success .hs-content {
  color: var(--he-success);
  font-size: 1.5em;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
}

/* Highlight glow (pulse animation when arrow unlocked) */
.hs-glow {
  position: absolute !important;
  z-index: 9000 !important;
  pointer-events: none;
  background: radial-gradient(
    ellipse at center,
    rgba(88, 197, 154, 0.0) 0%,
    rgba(88, 197, 154, 0.3) 60%,
    transparent 80%
  );
  border: 3px solid rgba(88, 197, 154, 0.9);
  box-shadow:
    0 0 40px rgba(88, 197, 154, 0.8),
    inset 0 0 20px rgba(88, 197, 154, 0.5);
  border-radius: 12px;
  opacity: 0.6;
  animation: he-glow-pulse 1.8s infinite ease-in-out;
}

/* --- 9. TOASTS --- */

.toast {
  background: var(--he-panel);
  border: 1px solid var(--he-accent);
  color: var(--he-text);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.8);
  font-family: inherit;
}

/* --- 10. INVENTORY (hidden for this game) --- */

.inventory {
  background: linear-gradient(180deg, rgba(30, 32, 48, 0.95), rgba(26, 26, 46, 0.98));
  border-top: 1px solid var(--he-accent);
  backdrop-filter: blur(4px);
}

/* --- 11. ANIMATIONS --- */

@keyframes he-shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-5px); }
  75% { transform: translateX(5px); }
}

@keyframes he-glow-pulse {
  0%   { transform: scale(0.95); opacity: 0.6; border-color: rgba(88, 197, 154, 0.7); }
  50%  { transform: scale(1.05); opacity: 1.0; border-color: rgba(88, 197, 154, 1.0);
         box-shadow: 0 0 60px rgba(88, 197, 154, 1); }
  100% { transform: scale(0.95); opacity: 0.6; border-color: rgba(88, 197, 154, 0.7); }
}

/* --- 12. TABLET & MOBILE FIXES --- */

@media (max-width: 1024px) {
  .topbar .title {
    font-size: 1.2em;
  }
}

@media (max-width: 720px) {
  .topbar .title {
    font-size: 1em;
  }
}

/* Touch device optimisations */
@media (hover: none) and (pointer: coarse) {
  .hotspot {
    touch-action: manipulation;
    -webkit-user-select: none;
    user-select: none;
  }

  .btn, button, .pz-btn {
    min-height: 44px;
    min-width: 44px;
  }
}

/* Safari-specific fixes */
@supports (-webkit-touch-callout: none) {
  .pz__window {
    -webkit-backdrop-filter: blur(5px);
  }

  .cp-panel--glass {
    -webkit-backdrop-filter: blur(12px) !important;
  }
}

