  1→// engine/puzzles/kinds/list.js
  2→// Kind: list – sequential puzzle execution with aggregation and summary
  3→
  4→import {BasePuzzle} from '../base.js';
  5→import {createPuzzleRunner} from '../index.js';
  6→
  7→const DBG = () => (typeof window !== 'undefined' && /\bdebug=1\b/.test(window.location.search));
  8→
  9→export default class ListPuzzle extends BasePuzzle {
 10→    constructor(args) {
 11→        super(args);
 12→        this._results = [];
 13→        this._currentIdx = 0;
 14→        this._running = false;
 15→        this._bgOverlay = null;
 16→    }
 17→
 18→    mount(container, workRect, backgroundUrl) {
 19→        // List doesn't use standard BasePuzzle mount - it manages its own sequence
 20→        this.container = container;
 21→        this.workRect = workRect;
 22→        this.backgroundUrl = backgroundUrl;
 23→
 24→        // Shared background for entire list
 25→        if (backgroundUrl) {
 26→            this._bgOverlay = document.createElement('div');
 27→            Object.assign(this._bgOverlay.style, {
 28→                position: 'absolute',
 29→                inset: '0',
 30→                backgroundImage: `url("${backgroundUrl}")`,
 31→                backgroundSize: 'cover',
 32→                backgroundPosition: 'center',
 33→                pointerEvents: 'none',
 34→                zIndex: '7999'
 35→            });
 36→            container.appendChild(this._bgOverlay);
 37→        }
 38→
 39→        if (DBG()) {
 40→            console.debug('[PZ.list] mounted', {
 41→                steps: this.config.steps?.length || 0,
 42→                aggregateOnly: this.instanceOptions.aggregateOnly,
 43→                blockUntilSolved: this.instanceOptions.blockUntilSolved
 44→            });
 45→        }
 46→    }
 47→
 48→    render() {
 49→        if (this._running) return;
 50→        this._running = true;
 51→
 52→        const steps = this.config.steps || this.config.items || [];
 53→
 54→        if (DBG()) {
 55→            console.debug('[PZ.list] starting sequence', {stepCount: steps.length});
 56→        }
 57→
 58→        this._runSequence(steps);
 59→    }
 60→
 61→    _runSequence(steps) {
 62→        if (this._currentIdx >= steps.length) {
 63→            // All done - show summary
 64→            this._showSummary();
 65→            return;
 66→        }
 67→
 68→        const step = steps[this._currentIdx];
 69→        const instOpts = {
 70→            aggregateOnly: this.instanceOptions.aggregateOnly ?? false,
 71→            blockUntilSolved: this.instanceOptions.blockUntilSolved ?? false,
 72→            ...(step.options || {})
 73→        };
 74→
 75→        if (DBG()) {
 76→            console.debug('[PZ.list] starting step', {
 77→                idx: this._currentIdx,
 78→                ref: step.ref,
 79→                options: instOpts
 80→            });
 81→        }
 82→
 83→        // IMPORTANT: Use step.rect if defined, otherwise use full screen (not this.workRect)
 84→        // this.workRect is for the list container itself, not for individual puzzles
 85→        const puzzleRect = step.rect || {x: 0, y: 0, w: 100, h: 100};
 86→
 87→        const runner = createPuzzleRunner({
 88→            ref: step.ref,
 89→            config: step.config,
 90→            rect: puzzleRect,
 91→            background: step.background || undefined,
 92→            instanceOptions: instOpts,
 93→            puzzlesById: this.engine.data?.puzzles || {},
 94→            i18n: (k, def) => this.tKey(k, def),
 95→            engine: this.engine,
 96→            onResolve: (result) => {
 97→                this._results.push({
 98→                    index: this._currentIdx,
 99→                    ref: step.ref || step.config?.id || `#${this._currentIdx}`,
100→                    ok: !!result.ok,
101→                    detail: result.detail
102→                });
103→
104→                if (DBG()) {
105→                    console.debug('[PZ.list] step resolved', {
106→                        idx: this._currentIdx,
107→                        ok: result.ok,
108→                        blockUntilSolved: instOpts.blockUntilSolved
109→                    });
110→                }
111→
112→                // blockUntilSolved takes precedence
113→                if (instOpts.blockUntilSolved && !result.ok) {
114→                    if (DBG()) {
115→                        console.debug('[PZ.list] blocked - must solve correctly');
116→                    }
117→                    return; // Stay on this step
118→                }
119→
120→                // Progress to next
121→                runner.unmount();
122→                this._currentIdx++;
123→                this._runSequence(steps);
124→            }
125→        });
126→
127→        runner.mountInto(this.container);
128→    }
129→
130→    _showSummary() {
131→        const total = this._results.length;
132→        const ok = this._results.filter(r => r.ok).length;
133→        const allOk = ok === total;
134→
135→        if (DBG()) {
136→            console.debug('[PZ.list] summary', {total, ok, allOk});
137→        }
138→
139→        const summary = this.config.summary || {};
140→
141→        if (summary.show === false) {
142→            // No summary - resolve immediately
143→            this._finish(allOk);
144→            return;
145→        }
146→
147→        // Create summary overlay (use CSS classes, minimal inline styles)
148→        const host = document.createElement('div');
149→        host.className = 'pz-list-summary';
150→        Object.assign(host.style, {
151→            left: (this.workRect?.x ?? 10) + '%',
152→            top: (this.workRect?.y ?? 10) + '%',
153→            width: (this.workRect?.w ?? 80) + '%',
154→            height: (this.workRect?.h ?? 80) + '%'
155→        });
156→
157→        // Title
158→        const title = document.createElement('div');
159→        title.textContent = this.t(summary.title || '@list.summary.title@Výsledek série', 'Výsledek série');
160→        Object.assign(title.style, {
161→            fontSize: '1.4em',
162→            fontWeight: '700',
163→            textAlign: 'center',
164→            color: 'rgba(255, 255, 255, 0.95)'
165→        });
166→        host.appendChild(title);
167→
168→        // Score (if enabled)
169→        if (summary.showScore !== false) {
170→            const score = document.createElement('div');
171→            score.textContent = `${ok} / ${total}`;
172→            Object.assign(score.style, {
173→                fontSize: '2.5em',
174→                fontWeight: '700',
175→                color: allOk ? 'rgba(20, 220, 90, 0.9)' : 'rgba(255, 160, 90, 0.9)'
176→            });
177→            host.appendChild(score);
178→        }
179→
180→        // Message
181→        const message = document.createElement('div');
182→        const msgKey = allOk ? 'messageOk' : 'messageFail';
183→        const msgDefault = allOk ? 'Skvělé! Série splněna.' : 'Něco se nepovedlo.';
184→        message.textContent = this.t(summary[msgKey] || msgDefault, msgDefault);
185→        Object.assign(message.style, {
186→            fontSize: '1.1em',
187→            textAlign: 'center',
188→            opacity: '0.9',
189→            color: 'rgba(255, 255, 255, 0.9)',
190→            maxWidth: '80%'
191→        });
192→        host.appendChild(message);
193→
194→        // OK button - MUST use only CSS classes, NO inline background/border styles
195→        const btn = document.createElement('button');
196→        btn.type = 'button';
197→        btn.className = 'pz-btn pz-btn--ok';
198→        btn.textContent = this.t('@engine.modal.ok@OK', 'OK');
199→
200→        // Only layout styles inline, NO background/border (CSS handles those)
201→        Object.assign(btn.style, {
202→            marginTop: '2vh',
203→            minWidth: '120px'
204→        });
205→
206→        btn.addEventListener('click', () => {
207→            if (host.parentNode) {
208→                host.parentNode.removeChild(host);
209→            }
210→            this._finish(allOk);
211→        });
212→        host.appendChild(btn);
213→
214→        this.container.appendChild(host);
215→    }
216→
217→    _finish(allOk) {
218→        if (DBG()) {
219→            console.debug('[PZ.list] finished', {allOk, results: this._results});
220→        }
221→
222→        if (allOk) {
223→            this.resolveOk?.({results: this._results});
224→        } else {
225→            this.resolveFail?.('incomplete', {results: this._results});
226→        }
227→    }
228→
229→    unmount() {
230→        if (this._bgOverlay?.parentNode) {
231→            this._bgOverlay.parentNode.removeChild(this._bgOverlay);
232→        }
233→        this._running = false;
234→
235→        if (DBG()) {
236→            console.debug('[PZ.list] unmount');
237→        }
238→    }
239→
240→    onOk() {
241→        // List manages its own flow - no manual OK
242→        return {hold: true};
243→    }
244→
245→    onCancel() {
246→        this.resolveFail?.('cancel');
247→        this.onRequestClose?.({reason: 'cancel'});
248→    }
249→}

   1→// engine/engine.js
   2→// Game engine core: scenes, i18n, dialogs, hero profile, inventory, puzzles, events, content panels.
   3→
   4→import {createPuzzleRunner, openListModal} from './puzzles/index.js';
   5→import {DialogUI} from './dialogs.js';
   6→import {ContentPanel} from './content.js';
   7→
   8→export class Game {
   9→    constructor(opts) {
  10→        // DOM refs
  11→        this.sceneImage = opts.sceneImage;
  12→        this.hotspotLayer = opts.hotspotLayer;
  13→        this.inventoryRoot = opts.inventoryRoot;
  14→        this.messageBox = opts.messageBox;
  15→        this.modalRoot = opts.modalRoot;
  16→        this.modalTitle = opts.modalTitle;
  17→        this.modalBody = opts.modalBody;
  18→        this.modalCancel = opts.modalCancel;
  19→        this.modalOk = opts.modalOk;
  20→
  21→        // Data sources
  22→        this.baseUrl = opts.baseUrl || './';
  23→        this.scenesUrl = opts.scenesUrl;          // already prefixed by caller
  24→        this.dialogsUrl = opts.dialogsUrl || null; // ./games/<id>/dialogs.json (optional)
  25→        this.lang = (opts.lang || 'cs').toLowerCase();
  26→        this.i18n = opts.i18n || {engine: {}, game: {}};
  27→
  28→        // State
  29→        this.data = null;
  30→        this.meta = {};
  31→        this.dialogsData = null;
  32→        this.state = null;
  33→        this.currentScene = null;
  34→        this._modalResolve = null;
  35→        this._pendingHighlights = {};
  36→
  37→        // Toast container
  38→        this.toastRoot = document.createElement('div');
  39→        this.toastRoot.className = 'toast-container';
  40→        document.body.appendChild(this.toastRoot);
  41→
  42→        // Dialog UI
  43→        this.dialogUI = new DialogUI(this);
  44→
  45→        // Content Panel UI
  46→        this.contentPanel = new ContentPanel(this);
  47→
  48→        // Modal events
  49→        this.modalCancel.addEventListener('click', () => this._closeModal(false));
  50→        this.modalOk.addEventListener('click', () => this._closeModal(true));
  51→
  52→        // ESC = exit use-mode
  53→        document.addEventListener('keydown', (e) => {
  54→            if (e.key === 'Escape' && this.state?.useItemId) {
  55→                this.exitUseMode();
  56→                e.preventDefault();
  57→            }
  58→        });
  59→    }
  60→
  61→    // --- debug toggles ----------------------------------------------------------
  62→
  63→    _debugOn() {
  64→        try {
  65→            return new URLSearchParams(location.search).get('debug') === '1';
  66→        } catch {
  67→            return false;
  68→        }
  69→    }
  70→
  71→    _dbg(...args) {
  72→        if (this._debugOn()) console.debug('[GAME]', ...args);
  73→    }
  74→
  75→    // --- version signature for safe restore ------------------------------------
  76→
  77→    _signature() {
  78→        const gid = this.meta?.id || 'unknown';
  79→        const gver = this.meta?.version || '0';
  80→        const lang = this.lang || 'cs';
  81→        return `${gid}|${gver}|${lang}`;
  82→    }
  83→
  84→    // --- i18n helpers -----------------------------------------------------------
  85→
  86→    _fmt(str, params) {
  87→        if (!params) return str;
  88→        return String(str).replace(/\{(\w+)}/g, (_, k) => (params[k] ?? `{${k}}`));
  89→    }
  90→
  91→    _t(key, fallback = '', params = null) {
  92→        const g = this.i18n?.game?.[key];
  93→        const e = this.i18n?.engine?.[key];
  94→        const raw = (g != null ? g : (e != null ? e : fallback));
  95→        return this._fmt(raw, params);
  96→    }
  97→
  98→    /**
  99→     * Resolve string | {key} | "@key@fallback".
 100→     */
 101→    _text(val, fallback = '') {
 102→        if (val && typeof val === 'object' && val.key) {
 103→            return this._t(String(val.key), fallback);
 104→        }
 105→        if (typeof val === 'string') {
 106→            const m = val.match(/^@([^@]+)@(.*)$/s);
 107→            if (m) return this._t(m[1].trim(), m[2]);
 108→            return val;
 109→        }
 110→        return (val != null ? String(val) : String(fallback));
 111→    }
 112→
 113→    /** Prefix relative paths with baseUrl. */
 114→    _resolveAsset(path) {
 115→        if (!path) return path;
 116→        const s = String(path);
 117→        if (/^(?:https?:)?\/\//i.test(s)) return s;           // absolute URL
 118→        if (s.startsWith('./') || s.startsWith('/')) return s; // already rooted
 119→        return this.baseUrl.replace(/\/+$/, '/') + s.replace(/^\/+/, '');
 120→    }
 121→
 122→    // --- lifecycle --------------------------------------------------------------
 123→
 124→    async init() {
 125→        this.data = await fetch(this.scenesUrl, {cache: 'no-cache'}).then(r => r.json());
 126→        this.modalRoot.classList.add('hidden');
 127→
 128→        this.meta = this.data?.meta || {};
 129→
 130→        // Query flags
 131→        let forceReset = false;
 132→        let urlHero = null;
 133→        try {
 134→            const p = new URLSearchParams(location.search);
 135→            forceReset = p.get('reset') === '1';
 136→            urlHero = p.get('hero'); // may be null
 137→        } catch { /* noop */
 138→        }
 139→
 140→        const saved = forceReset ? null : this._loadState();
 141→        const okSaved = !!saved && saved.signature === this._signature();
 142→
 143→        // fresh state if signature changed or reset requested
 144→        this.state = okSaved ? saved : {
 145→            signature: this._signature(),
 146→            inventory: [],
 147→            solved: {},
 148→            flags: {},
 149→            visited: {},
 150→            eventsFired: {},
 151→            scene: this.data.startScene || this.data.scenes[0]?.id,
 152→            useItemId: null,
 153→            hero: null,
 154→            puzzleResults: [], // aggregateOnly results bucket
 155→            contentShown: {}  // tracks "once" content panels
 156→        };
 157→
 158→        // initialize hero (default → then URL override if present)
 159→        if (!this.state.hero) {
 160→            const defId = this.data?.defaultHero || Object.keys(this.data?.heroes || {})[0] || 'adam';
 161→            this._setHeroInternal(defId);
 162→        }
 163→        if (urlHero) {
 164→            // URL always wins (do not nuke progress)
 165→            this._setHeroInternal(urlHero);
 166→            this._dbg('[HERO] overridden from URL →', urlHero, this.state.hero);
 167→        }
 168→
 169→        await this.goto(this.state.scene, {noSave: true});
 170→        this._renderInventory();
 171→    }
 172→
 173→    restart() {
 174→        localStorage.removeItem('leeuwenhoek_escape_state');
 175→        location.reload();
 176→    }
 177→
 178→    async goto(sceneId, opts = {}) {
 179→        const scene = this.data.scenes.find(s => s.id === sceneId);
 180→        if (!scene) return this._msg(this._t('engine.sceneNotFound', 'Scéna nebyla nalezena: {id}', {id: sceneId}));
 181→
 182→        this.currentScene = scene;
 183→        this.state.scene = sceneId;
 184→        this.state.visited[sceneId] = true;
 185→        if (!opts.noSave) this._saveState();
 186→
 187→        this.sceneImage.src = this._resolveAsset(scene.image);
 188→        await new Promise(res => {
 189→            if (this.sceneImage.complete && this.sceneImage.naturalWidth) res();
 190→            else this.sceneImage.onload = () => res();
 191→        });
 192→
 193→        this._renderHotspots();
 194→        this._msg(this._text(scene.title) || '');
 195→
 196→        // queued highlights for this scene
 197→        this._drainHighlightsForScene(sceneId);
 198→        // events: enterScene
 199→        await this._processEvents({on: 'enterScene', scene: sceneId});
 200→
 201→        // scene-level auto content panel
 202→        if (scene.content?.ref) {
 203→            const trigger = scene.content.trigger || 'enter';
 204→            if (trigger === 'enter') {
 205→                const cId = scene.content.ref;
 206→                const cOnce = scene.content.once ?? true;
 207→                if (!cOnce || !this.state.contentShown?.[cId]) {
 208→                    await this.contentPanel.open(cId);
 209→                }
 210→            }
 211→        }
