 419→    /**
 420→     * Sets up drag & drop handlers for a hotspot that accepts items.
 421→     * @param {HTMLElement} el - The hotspot element.
 422→     * @param {object} hs - The hotspot configuration.
 423→     * @param {number} idx - The hotspot index.
 424→     */
 425→    _setupHotspotDropHandlers(el, hs, idx) {
 426→        // HTML5 Drag API - dragover is required to allow drop
 427→        el.addEventListener('dragover', (e) => {
 428→            const itemId = e.dataTransfer.types.includes('text/plain') ? 'pending' : null;
 429→            if (itemId) {
 430→                e.preventDefault();
 431→                e.dataTransfer.dropEffect = 'move';
 432→                el.classList.add('drop-target');
 433→            }
 434→        });
 435→
 436→        el.addEventListener('dragleave', (e) => {
 437→            el.classList.remove('drop-target');
 438→        });
 439→
 440→        el.addEventListener('drop', async (e) => {
 441→            e.preventDefault();
 442→            el.classList.remove('drop-target');
 443→
 444→            const itemId = e.dataTransfer.getData('text/plain');
 445→            if (!itemId) return;
 446→
 447→            this._dbg('[DROP] Item dropped on hotspot:', itemId, hs);
 448→            await this._handleItemDropOnHotspot(itemId, hs);
 449→        });
 450→    }
