 452→    async _activateHotspot(h) {
 453→        console.log('[HOTSPOT] Activation triggered:', h.type, h);
 454→
 455→        // 1. Use-mode guard (pokud držíme předmět a hotspot ho neumí přijmout)
 456→        // Pokud hráč drží předmět, ale klikne na něco, co předměty nebere -> chyba.
 457→        if (this.state.useItemId && !h.acceptItems) {
 458→            this.toast(this._t('engine.use.notApplicable', 'Tento předmět tady nelze použít.'), 2500);
 459→            this.exitUseMode();
 460→            return;
 461→        }
 462→
 463→        // 2. Requirements check (Prerekvizity)
 464→        // Kontrola, zda má hráč potřebné předměty v inventáři (pokud jsou vyžadovány)
 465→        if (h.requireItems && !this._hasAll(h.requireItems)) {
 466→            this._msg(this._t('engine.missingItems', 'Něco ti chybí…'));
 467→            return;
 468→        }
 469→        // Kontrola, zda jsou splněny herní flagy (např. odemčeno)
 470→        if (h.requireFlags && !this._hasAllFlags(h.requireFlags)) {
 471→            this._msg(this._t('engine.needUnlock', 'Nejprve musíš něco odemknout…'));
 472→            return;
 473→        }
 474→
 475→        // 3. Item Usage (Accept items) - Pokud hotspot přijímá předměty
 476→        if (h.acceptItems && Array.isArray(h.acceptItems)) {
 477→            const selected = this.state.useItemId;
 478→            // Normalizace acceptItems (může to být string nebo objekt)
 479→            const accepts = h.acceptItems.map(x => (typeof x === 'string' ? {id: x, consume: false} : x));
 480→
 481→            // Zkusíme najít, zda vybraný předmět je v seznamu povolených
 482→            const match = selected ? accepts.find(a => a.id === selected) : null;
 483→
 484→            if (!match) {
 485→                // Hráč drží předmět, ale ten sem nepatří
 486→                if (selected) {
 487→                    this.toast(this._t('engine.use.notApplicable', 'Tento předmět tady nelze použít.'), 2500);
 488→                    this.exitUseMode();
 489→                    return;
 490→                }
 491→                // Hráč nic nedrží, ale hotspot vyžaduje předmět -> zobrazíme hint?
 492→                const allowHint = (h.showNeedHint !== false) && (this.data?.settings?.hints?.acceptNeed !== false);
 493→                if (allowHint) {
 494→                    const need = accepts.map(a => this._itemLabel(a.id)).filter(Boolean).join(', ');
 495→                    this.toast(this._t('engine.use.needItem', 'Potřebuješ použít: {need}.', {need}), 3500);
 496→                }
 497→                return;
 498→            }
 499→
 500→            // SHODA: Hráč použil správný předmět
 501→            if (match.consume) this._removeItemFromInventory(match.id);
 502→            this.exitUseMode();
 503→
 504→            if (h.onApply) await this._applyActions(h.onApply);
 505→            else this.toast(this._t('engine.use.applied', 'Předmět byl použit.'), 2200);
 506→            return;
 507→        }
 508→
 509→        // 4. Specific Actions (Rozcestník typů hotspotů)
 510→
 511→        // --- NOVÁ ČÁST: Obecná akce Apply (bez předmětu) ---
 512→        // Toto je to, co potřebujeme pro spuštění videa kliknutím na šipku
 513→        if (h.type === 'apply') {
 514→            console.log('[HOTSPOT] Executing Apply actions:', h.onApply);
 515→            if (h.onApply) {
 516→                await this._applyActions(h.onApply);
 517→            }
 518→            return;
 519→        }
 520→        // ---------------------------------------------------
 521→
 522→        if (h.type === 'goTo') {
 523→            await this.goto(h.target);
 524→            return;
 525→        }
 526→
 527→        if (h.type === 'pickup') {
 528→            if (!this.state.inventory.includes(h.itemId)) {
 529→                this.state.inventory.push(h.itemId);
 530→                this._renderInventory();
 531→                this._msg(this._t('engine.pickedUp', 'Sebráno: {name}', {name: this._itemLabel(h.itemId)}));
 532→                await this._stateChanged();
 533→            } else {
 534→                this._msg(this._t('engine.alreadyHave', 'Už máš: {name}', {name: this._itemLabel(h.itemId)}));
 535→            }
 536→            return;
 537→        }
 538→
 539→        if (h.type === 'puzzle') {
 540→            const ref = h.puzzleRef || h.puzzle?.ref;
 541→            if (!ref) {
 542→                console.error('Puzzle hotspot missing puzzleRef');
 543→                return;
 544→            }
 545→
 546→            const options = h.options || h.puzzle?.options || {};
 547→            const background = h.puzzleBackground || h.puzzle?.background || null;
 548→            const solvedKey = 'solved:pz:' + ref;
 549→
 550→            if (this.state.solved[solvedKey]) {
 551→                await this._applyActions(h.onSuccess);
 552→                return;
 553→            }
 554→
 555→            const res = await this._openPuzzleByRef({
 556→                ref,
 557→                rect: h.rect || {x: 0, y: 0, w: 100, h: 100},
 558→                options,
 559→                background
 560→            });
 561→
 562→            if (options.aggregateOnly) {
 563→                this._appendPuzzleResult({ref, ok: !!res?.ok, detail: res?.detail || null});
 564→                if (res?.ok && h.onSuccess) await this._applyActions(h.onSuccess);
 565→                if (!res?.ok && h.onFail) await this._applyActions(h.onFail);
 566→                return;
 567→            }
 568→
 569→            if (res?.ok) {
 570→                this._msg(this._t('engine.solved', 'Vyřešeno!'));
 571→                this.state.solved[solvedKey] = true;
 572→                this._saveState();
 573→                await this._applyActions(h.onSuccess);
 574→            } else {
 575→                if (h.onFail) await this._applyActions(h.onFail);
 576→                else this._msg(this._t('engine.puzzleFailed', 'Puzzle nevyřešeno.'));
 577→            }
 578→            return;
 579→        }
 580→
 581→        if (h.type === 'puzzleList') {
 582→            const ok = await openListModal(this, {
 583→                items: h.items || h.puzzleList?.items || [],
 584→                rect: h.rect || {x: 0, y: 0, w: 100, h: 100},
 585→                background: h.puzzleList?.background || h.background,
 586→                aggregateOnly: !!(h.options?.aggregateOnly),
 587→                blockUntilSolved: !!(h.options?.blockUntilSolved),
 588→                puzzlesById: this.data.puzzles
 589→            });
 590→            if (ok) {
 591→                if (h.onSuccess) await this._applyActions(h.onSuccess);
 592→            } else {
 593→                if (h.onFail) await this._applyActions(h.onFail);
 594→            }
 595→            return;
 596→        }
 597→
 598→        if (h.type === 'dialog') {
 599→            await this.openDialog(h.dialogId);
 600→            return;
 601→        }
 602→
 603→        if (h.type === 'content') {
 604→            await this.contentPanel.open(h.contentRef);
 605→            return;
 606→        }
 607→
 608→        // Fallback pro neznámé typy
 609→        this._msg('Unknown hotspot type: ' + h.type);
 610→        console.warn('Unknown hotspot type:', h);
 611→    }
