 683→    _appendPuzzleResult(obj) {
 684→        this.state.puzzleResults.push(obj);
 685→        if (this.state.puzzleResults.length > 500) {
 686→            this.state.puzzleResults.splice(0, this.state.puzzleResults.length - 500);
 687→        }
 688→        this._saveState();
 689→    }
