 691→    // --- apply action bundles (success/fail/shared) -----------------------------
 692→
 693→    /**
 694→     * Executes a bundle of actions (used by Hotspots, Puzzles onSuccess/onFail, Video onEnd).
 695→     * Supports: toast, message, openDialog, openContent, highlightHotspot, playVideo, giveItem, setFlags, clearFlags, goTo.
 696→     */
 697→    async _applyActions(actions) {
 698→        if (!actions) return;
 699→
 700→        // 1. Visual Feedback
 701→        if (actions.toast?.text) {
 702→            this.toast(this._text(actions.toast.text), actions.toast.ms ?? 5000);
 703→        }
 704→        if (actions.message) {
 705→            this._msg(this._text(actions.message));
 706→        }
 707→
 708→        // 2. Dialogs (Blocking)
 709→        if (actions.openDialog) {
 710→            await this.openDialog(actions.openDialog);
 711→        }
 712→
 713→        // 2b. Content Panels (Blocking)
 714→        if (actions.openContent) {
 715→            await this.contentPanel.open(actions.openContent);
 716→        }
 717→
 718→        // 3. Highlight Hotspot
 719→        if (actions.highlightHotspot?.rect) {
 720→            const h = actions.highlightHotspot;
 721→            this._enqueueOrShowHighlight({
 722→                sceneId: h.sceneId || this.currentScene?.id,
 723→                rect: h.rect,
 724→                ms: h.ms ?? 3500,
 725→                outline: !!h.outline
 726→            });
 727→        }
 728→
 729→        // 4. Play Video (Blocking)
 730→        if (actions.playVideo?.src) {
 731→            await this._playVideo(actions.playVideo);
 732→
 733→            if (actions.playVideo.onEnd) {
 734→                await this._applyActions(actions.playVideo.onEnd);
 735→            }
 736→        }
 737→
 738→        // 5. Logic (Items / Flags)
 739→        let changed = false;
 740→
 741→        if (actions.giveItem) {
 742→            const give = Array.isArray(actions.giveItem) ? actions.giveItem : [actions.giveItem];
 743→            let added = 0;
 744→            for (const id of give) {
 745→                if (!this.state.inventory.includes(id)) {
 746→                    this.state.inventory.push(id);
 747→                    added++;
 748→                    changed = true;
 749→                }
 750→            }
 751→            if (added) this._renderInventory();
 752→        }
 753→
 754→        if (actions.setFlags) {
 755→            if (Array.isArray(actions.setFlags)) {
 756→                for (const f of actions.setFlags) {
 757→                    if (!this.state.flags[f]) {
 758→                        this.state.flags[f] = true;
 759→                        changed = true;
 760→                    }
 761→                }
 762→            } else {
 763→                for (const [k, v] of Object.entries(actions.setFlags)) {
 764→                    if (!!this.state.flags[k] !== !!v) {
 765→                        this.state.flags[k] = !!v;
 766→                        changed = true;
 767→                    }
 768→                }
 769→            }
 770→        }
 771→
 772→        if (actions.clearFlags && Array.isArray(actions.clearFlags)) {
 773→            for (const f of actions.clearFlags) {
 774→                if (this.state.flags[f]) {
 775→                    delete this.state.flags[f];
 776→                    changed = true;
 777→                }
 778→            }
 779→        }
 780→
 781→        // 6. State & Navigation
 782→        if (changed) {
 783→            this._renderHotspots();
 784→            await this._stateChanged();
 785→            if (this.currentScene) {
 786→                this._drainHighlightsForScene(this.currentScene.id);
 787→            }
 788→        }
 789→
 790→        if (actions.goTo) {
 791→            await this.goto(actions.goTo);
 792→        }
 793→    }
 794→
 795→    // backward compatibility
 796→    async _applyOnSuccess(actions) {
 797→        return this._applyActions(actions);
 798→    }
