1062→    /**
1063→     * Checks if a hotspot accepts a specific item.
1064→     * @param {object} hs - The hotspot configuration.
1065→     * @param {string} itemId - The item ID to check.
1066→     * @returns {boolean}
1067→     */
1068→    _hotspotAcceptsItem(hs, itemId) {
1069→        if (!hs || !Array.isArray(hs.acceptItems)) return false;
1070→        const accepts = hs.acceptItems.map(x => typeof x === 'string' ? { id: x } : x);
1071→        if (!accepts.some(a => a?.id === itemId)) return false;
1072→        if (hs.requireItems && !this._hasAll(hs.requireItems)) return false;
1073→        if (hs.requireFlags && !this._hasAllFlags(hs.requireFlags)) return false;
1074→        return true;
1075→    }
