1077→    /**
1078→     * Handles dropping an item on a hotspot.
1079→     * @param {string} itemId - The dropped item ID.
1080→     * @param {object} hs - The target hotspot configuration.
1081→     */
1082→    async _handleItemDropOnHotspot(itemId, hs) {
1083→        if (!this._hotspotAcceptsItem(hs, itemId)) {
1084→            this.toast(this._t('engine.use.notApplicable', 'Tento předmět tady nelze použít.'), 2500);
1085→            return;
1086→        }
1087→
1088→        const accepts = hs.acceptItems.map(x => typeof x === 'string' ? { id: x, consume: false } : x);
1089→        const match = accepts.find(a => a.id === itemId);
1090→
1091→        if (match) {
1092→            if (match.consume) this._removeItemFromInventory(itemId);
1093→
1094→            if (hs.onApply) {
1095→                await this._applyActions(hs.onApply);
1096→            } else {
1097→                this.toast(this._t('engine.use.applied', 'Předmět byl použit.'), 2200);
1098→            }
1099→        }
1100→    }
