1102→    /**
1103→     * Open the "Inspect Item" modal.
1104→     * Final UX:
1105→     * - No OK/Cancel footer at all.
1106→     * - A top-right close (×) icon that reddens on hover.
1107→     * - Inside body: single blue "Use" button (adventure style).
1108→     * - Title/word/description are localized via _text/_t.
1109→     *
1110→     * No global modal API changes required — we defensively hide any footer if present.
1111→     *
1112→     * @param {{id:string, icon?:string, label?:string|object, meta?:{word?:string|object, description?:string|object}}} item
1113→     * @returns {Promise<void>}
1114→     */
1115→    async _inspectItem(item) {
1116→        // Build modal body
1117→        const body = document.createElement('div');
1118→        body.className = 'modal-body item-inspect';
1119→
1120→        if (item.icon) {
1121→            const img = document.createElement('img');
1122→            img.src = this._resolveAsset(item.icon);
1123→            img.alt = this._text(item.label) || item.id;
1124→            img.className = 'modal-img';
1125→            body.appendChild(img);
1126→        }
1127→
1128→        if (item.meta?.word) {
1129→            const w = document.createElement('div');
1130→            w.className = 'modal-word';
1131→            const wordValue = this._text(item.meta.word);
1132→            w.textContent = (wordValue && String(wordValue)) || String(item.meta.word);
1133→            body.appendChild(w);
1134→        }
1135→
1136→        if (item.meta?.description) {
1137→            const d = document.createElement('div');
1138→            d.className = 'modal-desc';
1139→            const descValue = this._text(item.meta.description);
1140→            d.textContent = (descValue && String(descValue)) || String(item.meta.description);
1141→            body.appendChild(d);
1142→        }
1143→
1144→        // Inline action dock (only "Use")
1145→        const ops = document.createElement('div');
1146→        ops.className = 'item-ops';
1147→
1148→        const btnUse = document.createElement('button');
1149→        btnUse.type = 'button';
1150→        btnUse.className = 'btn btn--action';
1151→        btnUse.textContent = this._t('engine.use.button', 'Použít');
1152→
1153→        const policy = this._getUseGuardPolicy();
1154→        if (policy !== 'off') {
1155→            const allowed = this._isItemApplicableHere(item.id);
1156→            // FAIL-SAFE: If allowed is null (cannot determine), show the button anyway
1157→            // This prevents edge cases where button disappears due to race conditions
1158→            const shouldHide = policy === 'hide' && allowed === false;
1159→            const shouldDisable = policy === 'disable' && allowed === false;
1160→
1161→            if (shouldHide) {
1162→                // Button is intentionally not placed in the panel
1163→                this._dbg('[ITEM] Use button hidden: policy=hide, allowed=false');
1164→            } else {
1165→                if (shouldDisable) {
1166→                    btnUse.disabled = true;
1167→                    btnUse.title = this._t('engine.use.disabledHere', 'Na této scéně teď nemáš kde použít.');
1168→                    btnUse.classList.add('is-disabled');
1169→                }
1170→                btnUse.addEventListener('click', () => {
1171→                    if (btnUse.disabled) return;
1172→                    this.enterUseMode(item.id);
1173→                    this._closeModal(true);
1174→                });
1175→                ops.appendChild(btnUse);
1176→            }
1177→        } else {
1178→            btnUse.addEventListener('click', () => {
1179→                this.enterUseMode(item.id);
1180→                this._closeModal(true);
1181→            });
1182→            ops.appendChild(btnUse);
1183→        }
1184→
1185→        body.appendChild(ops);
1186→
1187→        // Open modal WITHOUT footer labels (try to suppress buttons).
1188→        // If the modal implementation still renders a footer, we hide it below.
1189→        const p = this.openModal({
1190→            title: this._text(item.label) || item.id,
1191→            body,
1192→            okLabel: '',          // suppress OK
1193→            cancelLabel: ''       // suppress Cancel
1194→        });
1195→
1196→        // Tune modal DOM after it mounts: add header close icon; hide any footer.
1197→        const tune = () => {
1198→            const overlay = document.getElementById('modal');
1199→            if (!overlay) return;
1200→            const content = overlay.querySelector('.modal-content');
1201→            if (!content) return;
1202→
1203→            content.classList.add('modal--item');
1204→
1205→            // Header with title + close icon (×)
1206→            let header = content.querySelector('.modal-header');
1207→            if (!header) {
1208→                header = document.createElement('div');
1209→                header.className = 'modal-header';
1210→
1211→                const titleEl = document.createElement('div');
1212→                titleEl.className = 'modal-title';
1213→                titleEl.textContent = this._text(item.label) || item.id;
1214→
1215→                const closeBtn = document.createElement('button');
1216→                closeBtn.type = 'button';
1217→                closeBtn.className = 'modal-close';
1218→                closeBtn.setAttribute('aria-label', this._t('engine.modal.close', 'Close'));
1219→                closeBtn.innerHTML = '&times;'; // ×
1220→                closeBtn.addEventListener('click', () => this._closeModal(false));
1221→
1222→                header.appendChild(titleEl);
1223→                header.appendChild(closeBtn);
1224→
1225→                // Remove any plain .modal-title block if present and insert header at the top
1226→                const oldTitle = content.querySelector('.modal-title');
1227→                if (oldTitle && oldTitle.parentElement === content) oldTitle.remove();
1228→                content.insertBefore(header, content.firstChild);
1229→            }
1230→
1231→            // Hide any footer/actions row defensively (if openModal created it)
1232→            const candidates = Array.from(content.children).slice(-3); // last few blocks
1233→            candidates.forEach(node => {
1234→                if (node.classList.contains('item-ops')) return; // keep our Use dock
1235→                const btns = node.querySelectorAll('button');
1236→                if (btns.length && (node === content.lastElementChild || /ok|cancel|zavř|close/i.test(node.textContent || ''))) {
1237→                    node.style.display = 'none';
1238→                    node.classList.add('modal-footer-hidden');
1239→                }
1240→            });
1241→        };
1242→
1243→        // Run after layout tick to ensure modal DOM exists
1244→        setTimeout(tune, 0);
1245→
1246→        await p;
1247→    }
