1348→    /**
1349→     * Process game events based on a trigger.
1350→     * @param {{on: string, scene?: string}} trigger - The event trigger context.
1351→     */
1352→    async _processEvents(trigger) {
1353→        const events = this.data.events || [];
1354→        for (const ev of events) {
1355→            if (!ev || !ev.id) continue;
1356→
1357→            // 1. Check if already fired (for one-time events)
1358→            if (ev.once && this.state.eventsFired?.[ev.id]) continue;
1359→
1360→            const w = ev.when || {};
1361→
1362→            // 2. Check Conditions
1363→            // a) Trigger type match
1364→            if (w.on && w.on !== trigger.on) continue;
1365→
1366→            // b) Scene match (current scene or specified scene)
1367→            if (w.scene && w.scene !== (trigger.scene || this.state.scene)) continue;
1368→
1369→            // c) Inventory requirements
1370→            if (w.requireItems && !this._hasAll(w.requireItems)) continue;
1371→
1372→            // d) Flag requirements
1373→            if (w.requireFlags && !this._hasAllFlags(w.requireFlags)) continue;
1374→
1375→            // e) Missing items check
1376→            if (w.missingItems && (w.missingItems.some(x => this.state.inventory.includes(x)))) continue;
1377→
1378→            // --- MATCH FOUND ---
1379→
1380→            // Mark event as fired IMMEDIATELY before executing actions.
1381→            // This prevents recursion loops if an action (like a dialog) triggers
1382→            // a state change that would otherwise re-evaluate and re-trigger this
1383→            // same event while it is still pending/awaiting.
1384→            if (ev.once) {
1385→                this.state.eventsFired = this.state.eventsFired || {};
1386→                this.state.eventsFired[ev.id] = true;
1387→                this._saveState();
1388→            }
1389→
1390→            const act = ev.then || {};
1391→
1392→            // 3. Execute Actions
1393→
1394→            // Show Toast
1395→            if (act.toast?.text) {
1396→                this.toast(this._text(act.toast.text), act.toast.ms ?? 5000);
1397→            }
1398→
1399→            // Change Scene Image
1400→            if (act.setSceneImage?.sceneId && act.setSceneImage?.image) {
1401→                const sc = this.data.scenes.find(s => s.id === act.setSceneImage.sceneId);
1402→                if (sc) {
1403→                    sc.image = this._resolveAsset(act.setSceneImage.image);
1404→                    // If we are currently in this scene, update the DOM immediately
1405→                    if (this.currentScene?.id === sc.id) {
1406→                        this.sceneImage.src = sc.image;
1407→                        await new Promise(res => {
1408→                            if (this.sceneImage.complete && this.sceneImage.naturalWidth) res();
1409→                            else this.sceneImage.onload = () => res();
1410→                        });
1411→                    }
1412→                }
1413→            }
1414→
1415→            // Open Dialog (Blocking)
1416→            // The engine waits here until the dialog is fully closed by the user.
1417→            if (act.openDialog) {
1418→                await this.openDialog(act.openDialog);
1419→            }
1420→
1421→            // Open Content Panel (Blocking)
1422→            if (act.openContent) {
1423→                await this.contentPanel.open(act.openContent);
1424→            }
1425→
1426→            // Highlight Hotspot
1427→            // Executed after the dialog closes (if any).
1428→            if (act.highlightHotspot?.rect) {
1429→                const h = act.highlightHotspot;
1430→                this._enqueueOrShowHighlight({
1431→                    sceneId: h.sceneId || (w.scene || this.state.scene),
1432→                    rect: h.rect,
1433→                    ms: h.ms ?? 3500,
1434→                    outline: !!h.outline
1435→                });
1436→            }
1437→
1438→            // Play Video (Blocking)
1439→            // Engine waits until the video ends or is skipped
1440→            if (act.playVideo?.src) {
1441→                await this._playVideo(act.playVideo);
1442→                if (act.playVideo.onEnd) {
1443→                    await this._applyActions(act.playVideo.onEnd);
1444→                }
1445→            }
1446→
1447→            // Open Puzzle
1448→            if (act.openPuzzle) {
1449→                const ap = act.openPuzzle;
1450→                const res = await this._openPuzzleByRef({
1451→                    ref: ap.ref,
1452→                    rect: ap.rect || {x: 0, y: 0, w: 100, h: 100},
1453→                    options: ap.options || {},
1454→                    background: ap.background || null
1455→                });
1456→
1457→                if (ap.options?.aggregateOnly) {
1458→                    this._appendPuzzleResult({ref: ap.ref, ok: !!res?.ok, detail: res?.detail || null});
1459→                } else {
1460→                    if (res?.ok) {
1461→                        if (ap.onSuccess) await this._applyActions(ap.onSuccess);
1462→                    } else {
1463→                        if (ap.onFail) await this._applyActions(ap.onFail);
1464→                    }
1465→                }
1466→            }
1467→
1468→            // Open Puzzle List
1469→            if (act.openPuzzleList) {
1470→                const apl = act.openPuzzleList;
1471→                const ok = await openListModal(this, {
1472→                    items: apl.items || [],
1473→                    rect: apl.rect || {x: 0, y: 0, w: 100, h: 100},
1474→                    background: apl.background || null,
1475→                    aggregateOnly: !!apl.aggregateOnly,
1476→                    blockUntilSolved: !!apl.blockUntilSolved,
1477→                    puzzlesById: this.data.puzzles
1478→                });
1479→                if (ok) {
1480→                    if (apl.onSuccess) await this._applyActions(apl.onSuccess);
1481→                } else {
1482→                    if (apl.onFail) await this._applyActions(apl.onFail);
1483→                }
1484→            }
1485→
1486→            // Set Flags
1487→            if (act.setFlags) {
1488→                let changed = false;
1489→                if (Array.isArray(act.setFlags)) {
1490→                    for (const f of act.setFlags) {
1491→                        if (!this.state.flags[f]) {
1492→                            this.state.flags[f] = true;
1493→                            changed = true;
1494→                        }
1495→                    }
1496→                } else {
1497→                    for (const [k, v] of Object.entries(act.setFlags)) {
1498→                        if (!!this.state.flags[k] !== !!v) {
1499→                            this.state.flags[k] = !!v;
1500→                            changed = true;
1501→                        }
1502→                    }
1503→                }
1504→                if (changed) this._saveState();
1505→            }
1506→        }
1507→    }
