1509→    // --- video ---------------------------------------------------------------
1510→
1511→    /**
1512→     * Plays a video overlay or embedded video.
1513→     * Returns a Promise that resolves when the video ends or is skipped.
1514→     * @param {object} cfg - { src, mode, rect, delay, allowSkip, onEnd }
1515→     */
1516→    async _playVideo(cfg) {
1517→        const src = this._resolveAsset(cfg.src);
1518→
1519→        // 1. Delay logic (optional wait before showing video)
1520→        if (cfg.delay && cfg.delay > 0) {
1521→            await new Promise(resolve => setTimeout(resolve, cfg.delay));
1522→        }
1523→
1524→        return new Promise((resolve) => {
1525→            // Container setup
1526→            const wrapper = document.createElement('div');
1527→            wrapper.className = 'video-overlay';
1528→
1529→            // Mode handling (fullscreen vs rect)
1530→            if (cfg.mode === 'rect' && cfg.rect) {
1531→                wrapper.classList.add('mode-rect');
1532→                Object.assign(wrapper.style, {
1533→                    left: cfg.rect.x + '%',
1534→                    top: cfg.rect.y + '%',
1535→                    width: cfg.rect.w + '%',
1536→                    height: cfg.rect.h + '%'
1537→                });
1538→            } else {
1539→                wrapper.classList.add('mode-fullscreen');
1540→            }
1541→
1542→            // Video element
1543→            const video = document.createElement('video');
1544→            video.src = src;
1545→            video.autoplay = true;
1546→            video.playsInline = true; // Critical for iOS/Tablets to prevent native fullscreen force
1547→            video.controls = false;   // We handle interaction manually
1548→
1549→            wrapper.appendChild(video);
1550→
1551→            // Skip button (optional)
1552→            if (cfg.allowSkip !== false) {
1553→                const skipBtn = document.createElement('button');
1554→                skipBtn.className = 'video-skip';
1555→                skipBtn.innerHTML = '&times;'; // Close icon
1556→                skipBtn.title = 'Skip Video';
1557→
1558→                // Skip handler
1559→                skipBtn.addEventListener('click', (e) => {
1560→                    e.stopPropagation();
1561→                    finish();
1562→                });
1563→                wrapper.appendChild(skipBtn);
1564→
1565→                // Allow clicking outside/on wrapper to skip (only in fullscreen mode)
1566→                if (cfg.mode !== 'rect') {
1567→                    wrapper.addEventListener('click', finish);
1568→                }
1569→            }
1570→
1571→            // Mount to DOM (highest layer)
1572→            document.body.appendChild(wrapper);
1573→
1574→            // Lifecycle end handler
1575→            let finished = false;
1576→            function finish() {
1577→                if (finished) return;
1578→                finished = true;
1579→
1580→                video.pause();
1581→                if (wrapper.parentNode) wrapper.parentNode.removeChild(wrapper);
1582→
1583→                // Execute follow-up actions (onEnd) if defined
1584→                // Note: We resolve first to unblock the engine, logic happens outside
1585→                resolve();
1586→            }
1587→
1588→            // Event listeners
1589→            video.addEventListener('ended', finish);
1590→
1591→            video.addEventListener('error', (e) => {
1592→                console.error('[VIDEO] Error playing:', src, e);
1593→                finish(); // Don't block the game on error
1594→            });
1595→
1596→            // Start playback with error handling (autoplay policy)
1597→            video.play().catch(err => {
1598→                console.warn('[VIDEO] Autoplay blocked or failed:', err);
1599→                // If autoplay is blocked, we might need a "Click to Play" UI here.
1600→                // For now, we assume user interaction has already happened (dialog click).
1601→            });
1602→        });
1603→    }
1604→
1605→    // --- dialogs ---------------------------------------------------------------
1606→
1607→    async _ensureDialogsLoaded() {
1608→        if (this.dialogsData || !this.dialogsUrl) return;
1609→        try {
1610→            this._dbg('_ensureDialogsLoaded(): fetching', this.dialogsUrl);
1611→            const r = await fetch(this.dialogsUrl, {cache: 'no-cache'});
1612→            const json = await r.json();
1613→            this.dialogsData = json || {dialogs: [], characters: []};
1614→            this._dbg('_ensureDialogsLoaded(): fetched OK', {dialogs: this.dialogsData.dialogs?.length ?? 0});
1615→        } catch (err) {
1616→            console.error('[GAME] _ensureDialogsLoaded() failed:', err);
1617→            this.dialogsData = {dialogs: [], characters: []};
1618→        }
1619→    }
1620→
1621→    async openDialog(arg) {
1622→        const id = (typeof arg === 'string') ? arg : (arg && arg.id);
1623→        this._dbg('openDialog() begin →', {id});
1624→        if (!id) {
1625→            console.warn('[GAME] openDialog() called without id');
1626→            return;
1627→        }
1628→        await this._ensureDialogsLoaded();
1629→        if (!this.dialogsData) {
1630→            this._msg('Dialogy nejsou k dispozici.');
1631→            return;
1632→        }
1633→        return await this.dialogUI.open(id);
1634→    }
1635→
1636→    // --- persistence ------------------------------------------------------------
1637→
1638→    _saveState() {
1639→        this.state.signature = this._signature();
1640→        localStorage.setItem('leeuwenhoek_escape_state', JSON.stringify(this.state));
1641→    }
1642→
1643→    _loadState() {
1644→        try {
1645→            const raw = localStorage.getItem('leeuwenhoek_escape_state');
1646→            return raw ? JSON.parse(raw) : null;
1647→        } catch {
1648→            return null;
1649→        }
1650→    }
1651→}
